INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90304','fiesta','Fiestas en honor a María Santísima de la Asunción y San Jerónimo','Patronal y Etnográfica. Se celebra en Agosto. Celebración de arraigo local sustentada por la emigración estival, caracterizada por la procesión litúrgica tradicional hacia la iglesia parroquial y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90322','fiesta','Fiestas Patronales del Santísimo Cristo de la Misericordia','Patronal y Romería. Se celebra en Pentecostés (Mayo / Junio). Festejo comarcal menor con gran devoción al Santo Cristo, destacando el canto de mayos, la subasta de andas y el reparto de caridad o pan bendito.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14001','fiesta','Fiestas del Santo Cristo de la Fe y de la Virgen de la Orden','Patronal, Taurina y Recreación Histórica. Se celebra en Septiembre. Festividad de relevancia comarcal e hito medieval. Destaca por la procesión solemne por el recinto amurallado, encierros de reses bravas y una notable ambientación histórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90305','fiesta','Fiestas de San Cristóbal y la Virgen del Rosario','Patronal y Romería. Se celebra en Julio y Octubre. Celebración tradicional de carácter local orientada al retorno de emigrantes en verano, combinada con actos religiosos e invitaciones populares a base de zurra manchego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90306','fiesta','Fiestas de San Blas y la Virgen del Rosario','Patronal, Etnográfica y Enológica. Se celebra en Febrero y Septiembre. Hito etnográfico en la Alcarria conquense; sobresale por la bendición de los tradicionales rollos de San Blas, los pasacalles de la tía Pepa y la apertura de sus centenarias cuevas de vino.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90307','fiesta','Fiestas en honor a San Antonio de Padua y la Virgen de la Vega','Patronal y Romería. Se celebra en Junio y Septiembre. Festividad local marcada por la romería a la ermita de Nuestra Señora de la Vega, los tradicionales juegos populares y verbenas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90826','fiesta','Fiestas de la Santa Cruz y la Virgen de la Piedad','Patronal, Taurina y Romería. Se celebra en Mayo y Septiembre. Festejo de gran calado comarcal en la Mancha Alta; incluye la traída y llevada de la Virgen desde su ermita, devotas procesiones nocturnas y encierros taurinos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90827','fiesta','Fiestas de la Virgen del Remedio','Patronal y Etnográfica. Se celebra en Septiembre. Festejo de la Serranía Baja centrado en los actos litúrgicos, la almoneda de objetos donados a la Virgen y cenas populares basadas en cordero serrano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90308','fiesta','Fiestas en honor a San Martín Obispo','Patronal y Romería. Se celebra en Agosto (traslado estival). Verbena y procesión adaptadas al regreso estival de la comunidad local, complementadas con comidas vecinales en el entorno natural del río Guadiela.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90309','fiesta','Fiestas de Santiago Apóstol y la Virgen de la Vega','Patronal y Romería. Se celebra en Julio y Septiembre. Romería tradicional de arraigo vecinal a la ermita, acompañada por la puja de palos para portar las imágenes religiosas y campeonatos de juegos autóctonos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90310','fiesta','Fiestas de Nuestro Padre Jesús Nazareno','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad de marcado carácter familiar en un entorno rural de baja demografía, sustentada por una procesión solemne y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90311','fiesta','Romería de la Virgen de la Muela','Romería y Etnográfica. Se celebra en Mayo. Festividad de gran relevancia etnográfica provincial. Destaca la espectacular subida de la Virgen al cerro de la Muela y la ancestral danza de paloteo interpretada por los danzantes vestidos con indumentaria tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90312','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración típica de la Serranía que congrega a los antiguos residentes en torno a la procesión del santo protector contra la peste y calderetas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90828','fiesta','Fiestas de San Antonio de Padua y la Virgen de los Dolores','Patronal, Taurina y Etnográfica. Se celebra en Junio y Agosto. Hito festivo de la comarca de la Serranía Baja, relevante por sus tradicionales encierros y festejos taurinos, pasacalles de peñas y gran arraigo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90829','fiesta','Fiestas en honor a Nuestra Señora de la Asunción y San Bartolomé','Patronal y Etnográfica. Se celebra en Agosto. Fiestas mayores locales con procesión solemne, certámenes de pintura o poesía locales, competiciones de caliche y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90313','fiesta','Fiestas de San Vicente Mártir y la Virgen de las Nieves','Patronal, Taurina y Etnográfica. Se celebra en Enero y Agosto. Celebración con arraigo por sus tradicionales encierros por las calles de la villa, las solemnes procesiones y las populares verbenas en la plaza de la Constitución.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90314','fiesta','La Endiablada (en honor a San Blas y la Virgen de la Candelaria)','Etnográfica y Religiosa. Se celebra en Febrero. Fiesta de Interés Turístico Regional. Posee un valor etnográfico excepcional en España. Los hombres del pueblo se visten con trajes de colores extravagantes y grandes cencerros colgados a la espalda, danzando y saltando de forma ritual ante las imágenes sagradas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90315','fiesta','Fiestas de la Virgen de la Torre','Patronal y Romería. Se celebra en Septiembre. Celebración religiosa local centrada en la subasta de andas, procesión litúrgica por las calles del pueblo y juegos infantiles tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90316','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festejo de marcado carácter vecinal en el municipio con menor población de la provincia, dinamizado por el retorno estival, comidas de hermandad y música popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16905','fiesta','Fiestas del Santo Rostro y de la Virgen del Amparo','Patronal y Romería. Se celebra en Mayo y Septiembre. Celebración con gran afluencia por su cercanía a la capital; destaca la procesión del Santo Rostro, las verbenas masivas y los tradicionales torneos de juegos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90830','fiesta','Fiestas en honor al Santo Cristo de la Vera Cruz','Patronal y Etnográfica. Se celebra en Septiembre. Festividad local de la Serranía de Cuenca centrada en la tradición religiosa, subasta de joyas del Cristo y meriendas comunitarias a base de caldereta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90321','fiesta','Fiestas de la Virgen del Rosario y San Roque','Patronal y Etnográfica. Se celebra en Septiembre. Festejo de arraigo comarcal que incluye pasacalles musicales, paelladas gigantes para los vecinos, competiciones deportivas locales y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90317','fiesta','Fiestas de San Lorenzo y la Virgen de las Nieves','Patronal y Etnográfica. Se celebra en Agosto. Celebración de la Serranía Baja sustentada por la comunidad estival, caracterizada por la procesión litúrgica, campeonatos de cartas y bailes en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90318','fiesta','Fiestas del Santo Cristo de la Agonía','Patronal y Enológica. Se celebra en Agosto. Festividad de la Alcarria conquense marcada por los actos religiosos, la música de charanga y la tradicional reunión de peñas en sus cuevas de vino excavadas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90319','fiesta','Fiestas en honor a la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Septiembre. Celebración local típicamente manchega con solemnes misas, el canto de la salve, pólvora pirotécnica y juegos infantiles en la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90320','fiesta','Fiestas de la Virgen de la Vega','Patronal, Taurina y Romería. Se celebra en Septiembre. Festejo de relevancia comarcal que destaca por la emotiva traída de la Virgen desde su ermita, los encierros taurinos por las calles y los concursos de carrozas elaboradas por las peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16029','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Tradición local enfocada en la procesión del santo, la puja de varas para portar las andas, campeonatos de petanca y caliche, y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16030','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Celebración rural y familiar de baja demografía, vertebrada por la misa solemne, el parque infantil y las orquestas que reúnen a los veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16031','fiesta','Fiestas de San Antonio de Padua','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Festejo serrano adaptado al retorno vacacional, con el tradicional reparto de caridad, campeonatos de bolos conquenses y cenas vecinales al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16032','fiesta','Fiestas del Santísimo Cristo de la Alborada','Patronal y Etnográfica. Se celebra en Mayo. Festividad de gran raigambre tradicional; sobresale por el emotivo canto de los Mayos a la medianoche del 30 de abril y las danzas rituales delante del Cristo procesional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16033','fiesta','Fiestas de la Virgen de la Gracia y San Bartolomé','Patronal, Taurina y Recreación Histórica. Se celebra en Septiembre. Festejo de gran empaque comarcal e hito monumental. Destaca por el desfile de gigantes y cabezudos, sus encierros, corridas de toros y los eventos internacionales de combate medieval en su castillo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16034','fiesta','Fiestas de San Isidro Labrador y la Virgen de la Paz','Patronal y Romería. Se celebra en Mayo y Agosto. Celebración de arraigo puramente local con bendición de campos, subastas benéficas para la parroquia y verbenas musicales de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16035','fiesta','Fiestas de la Virgen de la Rosa','Patronal y Etnográfica. Se celebra en Septiembre. Hito festivo de la Serranía Alta; destaca por el antiquísimo cántico de la "Loa a la Virgen", el tradicional baile de la bandera por las calles de la villa y su arraigo histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16036','fiesta','Fiestas de la Virgen del Pilar y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festejo de la Serranía Baja caracterizado por la procesión mariana, competiciones de juegos tradicionales de madera y calderetas elaboradas con carne de caza comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16038','fiesta','Fiestas de San Pedro de Alcántara','Patronal y Etnográfica. Se celebra en Octubre. Micro-festividad de marcado carácter familiar en un entorno rural alcarreño, complementada con un almuerzo popular para los escasos residentes fijos y visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16040','fiesta','Fiestas de la Virgen de la Estrella','Patronal y Romería. Se celebra en Septiembre. Celebración local centrada en la romería hacia la ermita de la Estrella, las exhibiciones de corta de troncos y comidas populares serranas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16039','fiesta','Fiestas de la Virgen de la Estrella','Patronal, Taurina y Romería. Se celebra en Septiembre. Festividad con notable arrastre en la comarca de la Manchuela Conquense, famosa por su procesión de antorchas, encierros y la degustación de zurra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16041','fiesta','Fiestas de la Virgen de la Alcarria','Patronal y Romería. Se celebra en Mayo y Septiembre. Festejo relevante marcado por la masiva romería al sitio del Humilladero a orillas del embalse, cantos alcarreños tradicionales y animadas verbenas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16042','fiesta','Fiestas de la Virgen de la Loma','Patronal y Taurina. Se celebra en Septiembre. Celebración de gran arraigo provincial; sobresale por la multitudinaria procesión de la patrona, la gran feria taurina en su plaza tradicional y los desfiles de carrozas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16043','fiesta','Fiestas de San Juan Bautista y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festejo serrano adaptado al verano con procesiones solemnes, concursos gastronómicos de tortillas y gachas manchegas, y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16044','fiesta','Fiestas del Santo Cristo de la Agonía','Patronal y Etnográfica. Se celebra en Agosto. Pequeña festividad local que congrega a los antiguos residentes en torno a los cultos religiosos, juegos de cartas tradicionales y música de orquesta nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16045','fiesta','Fiestas de San Mamés y la Virgen de la Carrodilla','Patronal y Etnográfica. Se celebra en Agosto. Festejo típico de la Alcarria Alta conquense enfocado en el retorno vacacional, con pasacalles de dulzaineros, procesión y meriendas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16046','fiesta','Fiestas de la Virgen de la Milagrosa y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración local dinamizada por las visitas turísticas a sus famosas torcas; incluye subasta de andas, campeonatos de fútbol sala y bailes de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16047','fiesta','Fiestas de San Antonio de Padua','*. Patronal y Etnográfica. *. Se celebra en Junio. *. Tradición local manchega fundamentada en el culto al santo, la bendición de los panes de San Antonio y verbenas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16048','fiesta','Fiestas de la Virgen de la Dehesa','Patronal, Etnográfica y Taurina. Se celebra en Agosto. Festejo de gran atractivo en el valle del Escabas; destaca por sus tradicionales sueltas de reses bravas en recinto, actividades en el río y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16049','fiesta','Fiestas de la Virgen de la Trasierra','Patronal y Romería. Se celebra en Septiembre. Celebración religiosa local estructurada en torno a la bajada de la Virgen desde el cerro de la ermita, misas solemnes y pólvora nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16050','fiesta','Fiestas del Santo Cristo del Amparo','Patronal y Etnográfica. Se celebra en Septiembre. Celebración tradicional alcarreña que cuenta con una arraigada procesión nocturna, concursos de cocina local como morteruelo, y un activo ambiente de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16051','fiesta','Fiestas de la Virgen de la Paz','Patronal y Romería. Se celebra en Agosto (traslado estival). Festejo local muy vinculado al yacimiento arqueológico de Ercávica; incluye la tradicional procesión mariana, actividades culturales y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16053','fiesta','Fiestas de la Virgen de la Serna y San Roque','Patronal, Etnográfica y Taurina. Se celebra en Agosto. Festejo tradicional de la Serranía Alta; destaca por sus arraigadas sueltas de vacas en la plaza del pueblo, la procesión de la patrona y las comidas vecinales con carnes de caza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16056','fiesta','Fiestas en honor a la Virgen de la Asunción y San Roque','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Hito festivo en la Serranía Baja. Sobresale por la gran animación de sus peñas locales, sus encierros tradicionales de reses bravas y las solemnes procesiones litúrgicas por el casco histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16057','fiesta','Fiestas del Santo Cristo de la Agonía','Patronal y Etnográfica. Se celebra en Agosto. Celebración de la comarca minera y serrana sustentada por los emigrantes que retornan en verano; incluye procesión litúrgica, campeonatos de bolos serranos y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16058','fiesta','Fiestas en honor a San Bartolomé Apóstol','Patronal y Etnográfica. Se celebra en Agosto. Festejo netamente local y de carácter familiar en la Mancha Alta, caracterizado por los cultos al patrón, la invitación popular a base de zurra y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16060','fiesta','Fiestas de la Virgen de la Estrella y San Antonio','Patronal, Enológica y Romería. Se celebra en Mayo y Agosto. Festejo de la ribera del Júcar con notable arraigo comarcal; destaca por la romería a la ermita, los desfiles de peñas y la degustación de los reconocidos vinos de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16061','fiesta','Fiestas en honor al Santísimo Cristo de la Fe','Patronal y Etnográfica. Se celebra en Agosto. Celebración manchega popularmente conocida como "Teatinos"; resalta por su masivo desfile de carrozas, las procesiones de gran fervor religioso y las verbenas con orquestas de nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16062','fiesta','Fiestas de San Juan Bautista y la Virgen del Carmen','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Micro-festividad en uno de los municipios con menor censo de la Serranía Baja, articulada en torno a comidas comunitarias y música popular para reunir a los descendientes de la localidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16063','fiesta','Fiestas del Dulce Nombre de Jesús','Patronal y Etnográfica. Se celebra en Mayo. Festividad local de la comarca de la Manchuela marcada por la procesión solemne, los juegos autóctonos de lanzamiento de reja y las comidas populares en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16064','fiesta','Fiestas de la Virgen de la Asunción y San Julián','Patronal y Enológica. Se celebra en Agosto. Festejo de arraigo local célebre por su vinculación a la cultura del vino y el cultivo del azafrán; incluye pasacalles de la banda de música, coronación de reinas y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16065','fiesta','Fiestas en honor a Nuestra Señora del Pilar','Patronal y Etnográfica. Se celebra en Octubre. Celebración manchega tradicional que reúne a la comarca en torno a la procesión mariana, tiradas de traca pirotécnica y las tradicionales gachas y migas colectivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16066','fiesta','Fiestas de San Juan Evangelista y la Virgen de la Nieve','Patronal y Etnográfica. Se celebra en Agosto. Gran festividad en la Manchuela, conocida por su tradición en la fabricación de guitarras; destaca por el gran ambiente de sus peñas, certámenes folclóricos, conciertos y verbenas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16067','fiesta','Fiestas en honor a San Blas y la Virgen de la Caridad','Patronal y Etnográfica. Se celebra en Febrero y Agosto (fiesta del emigrante). Tradición alcarreña que combina las misas y bendición de rollos en invierno con verbenas y competiciones deportivas de gran concurrencia en la época estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16068','fiesta','Fiestas de San Agustín y la Virgen de la Fuente','Patronal y Romería. Se celebra en Agosto. Festejo marcado por el reencuentro veraniego; destaca la emotiva bajada de la Virgen a su ermita, los concursos de habilidad con tractores y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16070','fiesta','Fiestas del Santo Cristo de la Salud','Patronal y Etnográfica. Se celebra en Agosto. Pequeña celebración vecinal de la Serranía de Cuenca centrada en la subasta de banzos de la imagen religiosa, meriendas de hermandad y música de charanga.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16072','fiesta','Fiestas de Nuestra Señora de las Angustias','Patronal, Etnográfica y Recreación Histórica. Se celebra en Septiembre. Festejo de gran valor históricocultural por su patrimonio medieval; sobresale por la recreación de las "Embajadas de Moros y Cristianos", las solemnes procesiones y los cantos tradicionales de la salve.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16071','fiesta','Fiestas de San Ignacio de Loyola','Patronal y Etnográfica. Se celebra en Julio. Festividad local alcarreña de carácter familiar en un núcleo de baja demografía, vertebrada por la misa solemne, aperitivos populares y bailes en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16073','fiesta','Fiestas del Santísimo Cristo de la Salud','Patronal y Etnográfica. Se celebra en Agosto. Celebración tradicional con procesión de antorchas, campeonatos de juegos de mesa y de caliche, junto a animadas verbenas nocturnas que congregan a los pueblos limítrofes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16074','fiesta','Fiestas del Santo Cristo de la Salud y San Mamés','Patronal y Etnográfica. Se celebra en Agosto. Festejo serrano adaptado al retorno vacacional, caracterizado por la subasta de andas, comidas populares basadas en caldereta de cordero y concursos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','fiesta','Fiestas de San Mateo','Taurina, Histórica y Etnográfica. Se celebra en Septiembre. Fiesta declarada de Interés Turístico Regional con enorme proyección nacional. Conmemora la conquista de la ciudad por Alfonso VIII; destaca por la suelta de vaquinas enmaromadas por el casco histórico, los multitudinarios desfiles de peñas y la degustación masiva de zurra y morteruelo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16079','fiesta','Fiestas en honor a San Pedro y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festejo de la Serranía Alta muy ligado a su pasado minero, dinamizado por el turismo estival con misas solemnes, campeonatos de bolos serranos y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16082','fiesta','Fiestas del Santo Cristo de la Losa y San Roque','Patronal, Etnográfica y Recreación Histórica. Se celebra en Mayo y Agosto. Festejo de gran atractivo en el valle del Cabriel; destaca por su gran animación de peñas en verano y la célebre fiesta celta "Keltiberia" que recrea el patrimonio arqueológico local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16083','fiesta','Fiestas de San Bartolomé Apóstol','Patronal y Etnográfica. Se celebra en Agosto. Celebración típicamente familiar y vecinal adaptada al retorno estival, caracterizada por la procesión del santo, rifas parroquiales y bailes en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16084','fiesta','Fiestas de San Miguel Arcángel y la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Septiembre. Festejo tradicional de la Serranía Alta con subasta de banzos, comidas vecinales basadas en caldereta de cordero serrano y competiciones de juegos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16086','fiesta','Fiestas en honor a Nuestra Señora de la Soledad','Patronal y Taurina. Se celebra en Septiembre. Festejo de gran relevancia comarcal e intensa devoción mariana; sobresale por su espectacular "pólvora" pirotécnica, los concurridos encierros camperos y las grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16087','fiesta','Fiestas del Santísimo Cristo de la Misericordia','Patronal y Etnográfica. Se celebra en Septiembre. Celebración de la Mancha Alta con solemne procesión, competiciones tradicionales de lanzamiento de reja, juegos populares manchegos y bailes de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16088','fiesta','Fiestas de San Roque y la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Festejo de la Serranía Baja sustentado por la emigración estival, caracterizado por la procesión litúrgica, concursos gastronómicos de gachas y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16904','fiesta','Fiestas de la Virgen de la Antigua (en Jábaga)','Patronal y Romería. Se celebra en Mayo. Celebración de gran concurrencia dada su proximidad a la capital; destaca por la romería a la ermita, los cantos litúrgicos y las degustaciones de repostería local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16089','fiesta','Fiestas de la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Octubre. Festividad de arraigo comarcal famosa por las leyendas de su entorno; incluye procesión, el canto tradicional de salves y un gran ambiente de peñas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16093','fiesta','Romería de la Virgen de Tejeda','Romería, Etnográfica y Religiosa. Se celebra en Septiembre. Fiesta de Interés Turístico Regional. Es una de las romerías más masivas y antiguas de la provincia que atrae a miles de peregrinos de Cuenca, Valencia y Teruel; destaca el baile ritual de los Danzantes de Tejeda.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16094','fiesta','Fiestas de la Virgen de la Natividad','Patronal y Etnográfica. Se celebra en Septiembre. Hito alcarreño donde se conserva el canto tradicional de "La Caridad", reparto de pan bendito, pasacalles nocturnos con antorchas y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16095','fiesta','Fiestas de San Sebastián','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Micro-festividad familiar en la Serranía Baja centrada en misas mayores, la tradicional subasta de rollos del santo y bailes al aire libre para los veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16096','fiesta','Fiestas de San Jorge y la Virgen de la Fuente','Patronal y Taurina. Se celebra en Abril y Agosto. Festejo de la Manchuela con notable afluencia por sus sueltas de reses en recintos portátiles, comidas vecinales y desfiles de carrozas elaboradas por las peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16097','fiesta','Fiestas de la Virgen de la Salud y San Roque','Patronal, Etnográfica y Taurina. Se celebra en Agosto. Celebración serrana tradicional que conserva encierros de vaquillas, solemnes misas procesionales y concursos gastronómicos de platos típicos de caza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16098','fiesta','Fiestas en honor a San Julián y la Virgen de la Estrella','Patronal, Enológica y Etnográfica. Se celebra en Enero y Agosto. Festividad con gran tirón en la Manchuela, muy ligada a sus cooperativas vitivinícolas; destaca por sus multitudinarias verbenas, la tradicional pisada de uva y la ofrenda floral.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16099','fiesta','Fiestas del Santo Cristo de la Columna','Patronal y Etnográfica. Se celebra en Agosto. Celebración típicamente manchega y familiar sustentada por el retorno estival, caracterizada por la procesión litúrgica, la puja de andas y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16100','fiesta','Fiestas de la Virgen de la Morenita y San Bernabé','Patronal, Taurina y Etnográfica. Se celebra en Junio y Septiembre. Gran festividad en la Mancha Alta que destaca por la histórica rivalidad festiva y folclórica entre sus dos barrios tradicionales, encierros taurinos y procesiones masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16101','fiesta','Fiestas de la Virgen de la Encarnación','Patronal y Romería. Se celebra en Marzo y Agosto. Festejo local vinculado a su entorno de reserva natural; incluye el tradicional canto de mayos manchegos, procesión mariana y calderetas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16102','fiesta','Fiestas Patronales del Santo Cristo de la Agonía','Patronal, Taurina y Feria Comercial. Se celebra en Septiembre. Festejo de gran relevancia provincial; sobresale por la multitudinaria procesión nocturna del Cristo, su potente feria taurina con encierros camperos y un recinto ferial muy activo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16110','fiesta','Fiestas del Santo Niño y San Miguel','Patronal y Etnográfica. Se celebra en Septiembre. Celebración vecinal menor estructurada en torno a la procesión por el casco rural, la subasta de banzos y meriendas de hermandad en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16106','fiesta','El Vitore (en honor a la Inmaculada Concepción)','Etnográfica, Ecuestre y Religiosa. Se celebra en Noviembre / Diciembre. Fiesta declarada de Interés Turístico Regional con un fervor único. Es considerada la procesión más larga de la cristiandad; los caballeros vitores aclaman el estandarte de la Virgen a caballo durante más de 24 horas ininterrumpidas entre una multitud fervorosa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16107','fiesta','Fiestas de la Virgen del Rosario y San Roque','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Tradición en el corazón de la Serranía Alta; destaca por sus encierros de reses bravas en un singular recinto natural amurallado, el canto de las "loas" y la tipicidad de sus peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16108','fiesta','Fiestas del Santo Cristo de la Agonía','Patronal y Etnográfica. Se celebra en Agosto. Festividad local alcarreña dinamizada por el turismo de veraneo, caracterizada por la misa solemne, campeonatos de juegos de cartas y cenas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16109','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Pequeño festejo rural de la Serranía Baja basado en cultos religiosos tradicionales, rifas benéficas para la iglesia parroquial y música de charanga.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16111','fiesta','Fiestas en honor a la Virgen del Pozo','Patronal, Romería y Etnográfica. Se celebra en Agosto. Festejo serrano de gran belleza natural; destaca por la romería, las tradicionales exhibiciones de oficios forestales como la corta de troncos y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16112','fiesta','Fiestas de San Juan Evangelista y Santa Quiteria','Etnográfica, Histórica y Rivalidad Vecinal. Se celebra en Mayo. Festividad de gran empaque comarcal e hito etnográfico en la Alcarria conquense. Se define por la histórica y apasionada rivalidad entre los barrios de San Juan y Santa Quiteria, con espectaculares desfiles de galeras, bailes de danzantes con paloteos y loas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16113','fiesta','Feria y Fiestas de la Virgen de la Consolación','Patronal, Taurina y Feria Comercial. Se celebra en Agosto. Festejo de gran relevancia en la comarca de la Manchuela. Cuenta con una gran procesión de bajada de la patrona, corridas de toros de nivel, encierros, un gran desfile de carrozas y multitudinarias verbenas nocturnas). ¿Puedo continuar con el siguiente bloque de la provincia de Cuenca (avanzando hacia los municipios que empiezan por la letra L.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16115','fiesta','Fiestas de San Bartolomé Apóstol','Patronal y Etnográfica. Se celebra en Agosto. Celebración en plena Serranía Alta apoyada en el retorno estival; incluye la procesión tradicional por el pueblo, juegos populares infantiles y calderetas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16116','fiesta','Fiestas en honor a San Juan Bautista','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Celebración de la Serranía Alta orientada a las familias de antiguos residentes, dinamizada con misas solemnes, gachas comunitarias y música de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16117','fiesta','Fiestas de San Roque y la Virgen de la Fuenmaría','Patronal, Taurina y Romería. Se celebra en Agosto y Septiembre. Hito festivo de la Serranía Baja. Sobresale por sus animados encierros de vaquillas por el casco urbano, desfile de peñas locales, verbenas masivas y la devota romería a la ermita.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16118','fiesta','Fiestas de San Roque','Patronal, Taurina y Enológica. Se celebra en Agosto. Celebración de la Manchuela con gran afluencia; resalta por sus tradicionales festejos taurinos en plaza portátil, la degustación de vinos cooperativos locales y grandes verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16119','fiesta','Fiestas de la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Septiembre. Festividad local de la Alcarria con procesiones tradicionales, cantos marianos, campeonatos de juegos populares de cartas y bailes con orquesta en el centro de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16121','fiesta','Fiestas del Santo Cristo de la Redención','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festejo en plena Serranía Alta muy concurrido por su atractivo natural; destaca por la suelta de reses bravas en recinto cerrado, procesión solemne y degustación de patatas con carne de toro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16123','fiesta','Fiestas de la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Celebración serrana familiar enfocada en reunir a la comunidad emigrada con misas, campeonatos de cartas tradicionales, tiro de barra y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16124','fiesta','Fiestas en honor al Santo Niño de la Bola','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Festejo de gran relevancia en la Mancha Alta conquense. Sobresale por la masiva procesión del Santo Niño, sus encierros tradicionales de reses bravas y un gran recinto ferial con peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16125','fiesta','Fiestas del Santo Cristo de la Salud','Patronal, Taurina y Feria. Se celebra en Septiembre. Hito festivo de la comarca limítrofe con Valencia; destaca por la masiva bajada del Cristo, encierros tradicionales, corridas de toros de nivel y un recinto ferial muy dinámico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16128','fiesta','Fiestas de la Virgen de la Asunción y San Pedro','Patronal y Etnográfica. Se celebra en Agosto. Festejo típicamente manchego centrado en el reencuentro estival, caracterizado por la procesión litúrgica, la invitación vecinal al zurra y juegos de caliche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16129','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Festejo típicamente vecinal adaptado a la afluencia estival, caracterizado por la procesión mariana, competiciones de caliche y cenas populares en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16130','fiesta','Fiestas de Jesús Nazareno','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festejo con notable arraigo comarcal que incluye solemnes procesiones del Nazareno, sueltas de vaquillas por las calles, concursos de disfraces y animadas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16131','fiesta','Fiestas de la Virgen de la O','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Celebración de carácter familiar ligada a su pasado salinero; cuenta con misas litúrgicas, reparto de pan bendito, juegos infantiles y bailes en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16133','fiesta','Fiesta de la Virgen de Manjavacas','Romería, Etnográfica y Ecuestre. Se celebra en Agosto. Fiesta declarada de Interés Turístico Regional. Destaca por la espectacular e histórica "Carrera de la Virgen", donde los andarines llevan a la patrona corriendo a pie desde su ermita a lo largo de kilómetros, acompañados por jinetes a caballo y una multitud enfervorecida.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16134','fiesta','Feria y Fiestas de San Gil Abad','Patronal, Taurina y Feria Comercial. Se celebra en Septiembre. Gran feria industrial y festiva de la Manchuela conquense. Cuenta con un extenso y activo real de la feria, importantes corridas de toros, encierros urbanos, desfiles de carrozas y conciertos masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16137','fiesta','Fiestas en honor a San Miguel Arcángel','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Festividad menor serrana estructurada en torno a la procesión por el casco antiguo, subasta de rollos tradicionales y meriendas vecinales a base de cordero serrano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16139','fiesta','Fiestas del Santo Niño','Patronal, Histórica y Etnográfica. Se celebra en Agosto. Festejo tradicional a orillas del embalse de Alarcón; sobresale por la colorida y antigua representación de los "Moros y Cristianos", con dichos populares, desfiles y salvas de pólvora.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16140','fiesta','Fiestas de San Mamés','Patronal y Etnográfica. Se celebra en Agosto. Festejo alcarreño en un municipio conocido por sus iniciativas contra la despoblación; cuenta con misas solemnes, aperitivos comunitarios y actividades culturales populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16141','fiesta','Fiestas de la Virgen de las Nieves y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración de arraigo local sustentada por la emigración veraniega; se caracteriza por procesiones con cánticos tradicionales, subasta de rollos y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16142','fiesta','Fiestas del Santo Cristo de la Salud','Patronal y Etnográfica. Se celebra en Agosto. Festividad local manchega articulada en torno a la devota procesión del Cristo, subasta de andas, concursos culinarios locales y música de orquesta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16143','fiesta','Fiestas de San Juan Bautista','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Micro-festividad alcarreña de carácter marcadamente familiar en un entorno rural de baja demografía, con procesión, aperitivo vecinal y baile de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16145','fiesta','Fiestas del Santo Cristo de los Milagros','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festejo con gran arraigo en la Mancha Alta; destaca por la devoción procesional al Cristo, sus encierros tradicionales por las calles de la villa y el ambiente festivo de sus peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16146','fiesta','Fiestas de los Santos Inocentes y San Pedro','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Celebración en la Serranía Baja centrada en los ritos litúrgicos, comidas comunales de caldereta de cordero serrano y competiciones de juegos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16147','fiesta','Fiestas de la Virgen de la Purificación','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Pequeño festejo rural de baja demografía estructurado en torno a misas mayores, juegos infantiles tradicionales y orquestas que reúnen a los veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16148','fiesta','Fiestas del Santísimo Cristo de la Salud','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festividad manchega con notable arrastre comarcal; sobresale por sus tradicionales encierros y festejos taurinos en plaza portátil y las solemnes procesiones nocturnas del Cristo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16149','fiesta','Fiestas en honor a San Justo y San Pastor','Patronal y Etnográfica. Se celebra en Agosto. Festividad de gran concurrencia por su cercanía a las hoces de la capital; incluye procesión litúrgica tradicional, actividades en el río Huécar y animadas verbenas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16150','fiesta','Fiestas en honor a la Virgen de la Gracia y San Roque','Patronal y Taurina. Se celebra en Agosto. Festejo de la Serranía Baja que congrega a la comarca por sus espectaculares sueltas de reses bravas en su monumental y rectangular plaza, además de actos religiosos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16151','fiesta','Fiestas de la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Celebración local típicamente manchega con solemnes misas, subasta de banzos, competiciones de juegos populares como el caliche y bailes de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16156','fiesta','Fiestas de San Blas y la Virgen del Monte','Patronal y Etnográfica. Se celebra en Febrero y Septiembre. Tradición alcarreña de relevancia comarcal; destaca por la procesión y subida a la ermita del cerro, cantos tradicionales y una multitudinaria comida de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16158','fiesta','Fiestas de la Virgen de la Consolación','Patronal, Etnográfica y Deportiva. Se celebra en Julio y Agosto. Festejo de la ribera del Júcar con gran animación estival; destaca por sus actividades y competiciones náuticas en el río, desfiles de peñas y verbenas populares masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16159','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Celebración manchega tradicional que reúne a la comarca con procesiones solemnes, sueltas de vaquillas en su plaza de toros tradicional y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16160','fiesta','Fiestas en honor a San Vicente Mártir','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Festejo local alcarreño fundamentado en la vuelta de antiguos residentes en verano, con misas solemnes, campeonatos de bolos y música popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16161','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Festividad local de corte tradicional centrada en la procesión litúrgica por su fisonomía de origen medieval, rifas parroquiales y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16162','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festejo alcarreño sustentado por la emigración estival, caracterizado por las misas tradicionales, campeonatos de juegos autóctonos y cenas populares al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16167','fiesta','Fiestas de la Virgen de la Soledad y San Gregorio','Patronal, Taurina y Etnográfica. Se celebra en Mayo y Agosto. Festividad manchega con arraigo; destaca por el emotivo canto de los mayos, las procesiones solemnes, sus encierros urbanos de reses y el activo ambiente de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16169','fiesta','Fiestas en honor a San Julián','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Micro-festividad de la Serranía Alta adaptada a la demografía estival, caracterizada por comidas vecinales de caldereta serrana y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16908','fiesta','Fiestas del Santo Cristo de la Agonía (en Rubielos bajos)','Patronal y Etnográfica. Se celebra en Agosto. Celebración unificada de sus núcleos rurales; incluye campeonatos de caliche y petanca, procesiones de fe, tracas pirotécnicas y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16170','fiesta','Fiestas de la Virgen de la Torre y del Santo Cristo de la Caridad','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Hito festivo en la Alcarria conquense; sobresale por sus espectaculares encierros tradicionales por el casco histórico, la bajada de la Virgen de la Torre y la exhibición de su artesanía local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16171','fiesta','Fiestas del Santo Niño del Remedio y la Virgen del Rosario','Patronal, Taurina y del Cómic. Se celebra en Agosto. Festividad manchega de gran repercusión cultural. Combina las tradicionales verbenas, procesiones multitudinarias y encierros taurinos con su célebre Feria Internacional del Cómic, atrayendo a miles de visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16172','fiesta','Fiestas de la Virgen de la Misericordia','Patronal, Romería y Etnográfica. Se celebra en Septiembre. *. Celebración manchega tradicional a los pies de su castillo medieval; destaca por la bajada en romería de la patrona, la subasta de andas y el gran ambiente de sus peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16174','fiesta','Fiestas del Santo Salvador','Patronal y Etnográfica. Se celebra en Agosto. Festejo de la Manchuela centrado en las reuniones familiares y vecinales de verano, con procesiones religiosas solemnes, concursos de gachas manchegas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16175','fiesta','Fiestas de la Virgen del Rosario y San Marcos','Patronal, Taurina y Feria Comercial. Se celebra en Agosto. Gran festividad y motor económico de la Manchuela. Cuenta con una potentísima feria taurina, multitudinario desfile de carrozas elaboradas por las peñas, conciertos de primer nivel y un animado recinto ferial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16126','fiesta','Fiestas en honor a la Virgen de la Piedad','Patronal, Romería y Etnográfica. Se celebra en Agosto. Festejo de la Serranía Baja con gran afluencia; resalta por la tradicional bajada de la patrona desde su ermita, pasacalles de peñas y la quema de una monumental traca pirotécnica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16132','fiesta','Fiestas de San Lorenzo','Patronal y Etnográfica. Se celebra en Agosto. Pequeña festividad local de baja demografía centrada en cultos religiosos tradicionales, campeonatos de juegos de mesa y música popular para los veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16152','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad rural enfocada en las familias de antiguos residentes retornados, caracterizada por misas mayores, rifas benéficas y música popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16153','fiesta','Fiestas de la Virgen de la Buena Leche y Nuestro Padre Jesús Nazareno','Patronal, Taurina y Etnográfica. Se celebra en Julio y Septiembre. Festejo de la Mancha Alta con notable raigambre; destaca por las solemnes procesiones religiosas, sus tradicionales encierros de reses bravas y un animado concurso de carrozas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16154','fiesta','Fiestas de la Virgen de la Asunción y San Roque / Feria del Ajo','Patronal, Gastronómica y Feria Comercial. Se celebra en Julio y Agosto. Fiesta de Interés Turístico Regional la Feria Internacional del Ajo. Posee un inmenso impacto comercial y gastronómico de nivel nacional, complementado con las fiestas patronales, grandes conciertos, corridas de toros y actividades culinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16155','fiesta','Fiestas en honor a la Virgen de la Consolación','Patronal, Taurina y Romería. Se celebra en Agosto. Celebración de la Manchuela con notable arraigo; destaca por la emotiva bajada de la patrona desde su ermita, encierros tradicionales por el casco urbano y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16163','fiesta','Fiestas de la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Septiembre. Festejo a las puertas de la Serranía centrado en la tradición litúrgica, la puja de varas, competiciones deportivas locales y bailes populares de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16165','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Celebración en un bellísimo entorno monumental de la Serranía Alta; incluye procesión litúrgica tradicional, campeonatos de bolos serranos y verbenas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16166','fiesta','Fiestas de la Virgen del Rosario y la Santísima Trinidad','*. Patronal y Enológica. *. Se celebra en Agosto. *. Festejo de la Mancha Alta muy vinculado a su tradición vitivinícola; destaca por el gran desfile de carrozas, pasacalles de la banda de música y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16176','fiesta','Fiestas del Santo Cristo de la Luz','Patronal y Etnográfica. Se celebra en Septiembre. Celebración de la Mancha Alta con baja demografía; se centra en la liturgia eclesiástica, la subasta de banzos de la imagen y cenas populares de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16177','fiesta','Fiestas de la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Festejo de la Serranía Media que congrega a los antiguos residentes en torno a procesiones solemnes, campeonatos de bolos conquenses y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16181','fiesta','Fiestas del Santo Cristo de la Agonía','Patronal y Etnográfica. Se celebra en Agosto. Celebración local alcarreña dinamizada por el veraneo, articulada en torno a la procesión del Cristo, competiciones tradicionales de lanzamiento de reja y bailes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16185','fiesta','Fiestas de la Virgen de la Altura','Patronal y Romería. Se celebra en Mayo y Agosto. Celebración de la Alcarria meridional estructurada en torno a la procesión litúrgica mariana, juegos infantiles y tradicionales meriendas a base de caldereta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16186','fiesta','Fiestas en honor a la Virgen de los Remedios','Patronal, Taurina y Romería. Se celebra en Mayo y Septiembre. Festejo con fuerte proyección comarcal debido a su cercanía al Parque Arqueológico de Segóbriga; destaca por la romería a la ermita, encierros y la degustación de gachas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16187','fiesta','Fiestas de San Roque y la Virgen de la Natividad','Patronal y Etnográfica. Se celebra en Agosto y Septiembre. Celebración en la Serranía Alta orientada al reencuentro de la comunidad emigrante, caracterizada por la procesión del santo protector y comidas populares en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16188','fiesta','Fiestas en honor a la Virgen del Rosario (en Salmeroncillos de Abajo)','Patronal y Etnográfica. Se celebra en Agosto. Festejo típico de la Alcarria conquense con pasacalles de charangas, bendición de rollos, juegos de naipes tradicionales y bailes nocturnos al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16189','fiesta','Fiestas de la Virgen de la Carrodilla y San Roque','Patronal, Romería y Etnográfica. Se celebra en Agosto y Septiembre. Hito festivo de la Serranía Alta fronterizo con Aragón; sobresale por la romería a la ermita, los cantos tradicionales de jotas serranas y comidas de hermandad con cordero lechal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16190','fiesta','Venida y Romería de la Virgen de Rus','Romería, Etnográfica y Religiosa. Se celebra en Domingo de Resurrección y Lunes de Pentecostés. Fiesta declarada de Interés Turístico Regional con un arraigo multitudinario. Destaca por las frenéticas carreras que dan los portadores llevando a hombros la imagen de la Virgen de Rus y la Virgen del Remedio en un ambiente de fervor masivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16191','fiesta','Fiestas en honor a San Lorenzo Mártir','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Celebración de gran relevancia en la comarca de la Mancha Alta; cuenta con una consolidada feria taurina con encierros tradicionales, desfiles de carrozas y pasacalles de peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16192','fiesta','Fiestas de San Martín Obispo','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Pequeña festividad serrana adaptada al regreso vacacional, caracterizada por la subasta de andas religiosos, torneos de bolos serranos y cenas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16193','fiesta','Fiestas de San Pedro Apóstol y la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Junio y Agosto. Tradición alcarreña de carácter vecinal; incluye procesiones solemnes, tiradas de traca pirotécnica, concursos gastronómicos y verbenas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16194','fiesta','Fiestas de la Virgen de la Preciosa Sangre','Patronal y Etnográfica. Se celebra en Septiembre. Festejo de la Serranía Baja con gran identidad histórica; destaca por los pasacalles de su banda de música local, certámenes de folclore y comidas colectivas basadas en el morteruelo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16196','fiesta','Fiestas en honor al Santísimo Cristo de la Salud','Patronal y Etnográfica. Se celebra en Agosto. Celebración de la Mancha Baja con gran fervor popular; incluye una populosa procesión nocturna de antorchas, competiciones de caliche y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16195','fiesta','Fiestas de la Virgen del Amparo','Patronal y Etnográfica. Se celebra en Septiembre. Festejo en la cuna histórica de Jorge Manrique; destaca por sus tradicionales solemnidades litúrgicas, galas culturales en la plaza, pasacalles de gigantes y cabezudos y animadas verbenas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16197','fiesta','Fiestas de la Virgen del Val y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad de la Serranía Alta en un entorno natural privilegiado, sustentada por comidas vecinales de hermandad y música tradicional para los veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16199','fiesta','Fiestas de San Sebastián','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Celebración serrana menor centrada en el retorno de la comunidad, con misas solemnes, campeonatos de cartas tradicionales y bailes populares en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16909','fiesta','Fiestas del Santo Niño (en Ribatajada)','Patronal y Etnográfica. Se celebra en Agosto. Festividad del municipio que agrupa varias pedanías; incluye pasacalles intermunicipales, degustaciones colectivas de gachas manchegas y verbenas que congregan a toda la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16202','fiesta','Fiestas de San Antonio de Padua y la Virgen de la Asunción','Patronal, Taurina y Etnográfica. Se celebra en Junio y Agosto. Festejo de la Serranía Baja con gran afluencia de las provincias vecinas; destaca por sus arraigadas sueltas de vaquillas en plaza portátil, competiciones de tiro al plato y verbenas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16204','fiesta','Fiestas de la Virgen de la Cabeza y San Roque','Patronal y Romería. Se celebra en Agosto. Celebración de la Mancha Alta con procesión mariana, subasta de banzos y joyas donadas a la virgen, competiciones de caliche y verbenas nocturnas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16205','fiesta','Fiestas de San Pedro y San Roque','Patronal y Etnográfica. Se celebra en Agosto. *. Micro-celebración vecinal de la Serranía Alta articulada en torno a comidas comunitarias a base de caldereta serrana y orquestas de plaza para reunir a los descendientes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16206','fiesta','Fiestas de la Virgen de la Paz','Patronal y Enológica. Se celebra en Agosto (traslado estival). Festividad alcarreña caracterizada por la animación de sus peñas dentro de las bodegas tradicionales excavadas en roca, pasacalles musicales y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16209','fiesta','Fiestas de la Virgen de las Nieves','Patronal y Etnográfica. Se celebra en Agosto. Festejo tradicional alcarreño que mantiene viva la procesión de la patrona, la tirada de fuegos artificiales y comidas colectivas basadas en cordero serrano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16211','fiesta','Fiestas de la Virgen de la Urbanidad','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Celebración comarcal que cuenta con encierros tradicionales por el casco urbano, concursos de disfraces infantiles y un activo ambiente nocturno de peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16212','fiesta','Fiestas de la Virgen del Valle','Patronal y Etnográfica. Se celebra en Septiembre. Celebración típicamente manchega caracterizada por las solemnidades religiosas, certámenes populares de cocina local y juegos tradicionales de madera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16213','fiesta','Fiestas de San Sebastián','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Pequeña festividad familiar en un núcleo de baja demografía, vertebrada por la misa solemne de campaña, aperitivos comunitarios y música popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16216','fiesta','Fiestas en honor a la Virgen de la Atalaya','Patronal y Romería. Se celebra en Mayo. Tradición local manchega con romería hacia la ermita de la Atalaya, el emotivo canto de los mayos, comidas en el campo y verbenas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16217','fiesta','Fiestas de la Virgen de Santa Ana','Patronal y Etnográfica. Se celebra en Julio. Celebración manchega de carácter vecinal orientada al turismo de fin de semana, con procesiones tradicionales, reparto de caridad parroquial y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16218','fiesta','Fiestas de la Virgen de las Angustias','Patronal, Recreación Histórica y Etnográfica. Se celebra en Agosto. Festejo de gran relevancia histórico-cultural apoyado en el imponente marco de su Monasterio; destaca por los desfiles con trajes tradicionales, procesiones e hitos musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16219','fiesta','Fiestas de la Virgen de la Laguna','Patronal y Etnográfica. Se celebra en Septiembre. Celebración en el entorno natural de la Serranía Alta; incluye procesiones solemnes, concursos de pesca tradicional en la laguna, cucañas y calderetas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16906','fiesta','Fiestas de la Virgen del Rosario (en Valdecolmenas de Abajo)','Patronal y Etnográfica. Se celebra en Agosto. Festividad local de la Alcarria centrada en el retorno de la emigración, caracterizada por pasacalles de música tradicional, tiradas de traca y cenas colectivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16224','fiesta','Fiestas de la Virgen de la Gracia','Patronal y Etnográfica. Se celebra en Agosto. Festejo serrano dinamizado por sus famosas esculturas costumbristas de metal; incluye procesiones litúrgicas, exhibiciones de oficios tradicionales forestales y bailes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16225','fiesta','Fiestas del Santo Cristo de la Redención','Patronal y Etnográfica. Se celebra en Agosto. Celebración vecinal menor de la Serranía Media con subasta de banzos de la imagen, campeonatos de cartas tradicionales de baraja española y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16227','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festejo serrano tradicional caracterizado por el reparto de panes benditos caritativos del santo, competiciones de bolos conquenses y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16228','fiesta','Fiestas del Santo Cristo de la Salud','Patronal y Enológica. Se celebra en Agosto. Festividad de la Alcarria Alta famosa por su patrimonio de olivares y vides; sobresale por la apertura de las peñas en cuevas centenarias, el desfile de carrozas y procesiones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16902','fiesta','Fiestas de la Virgen de la Trinidad (en Valdeganga de Cuenca)','Patronal y Romería. Se celebra en Junio. Festejo a orillas del río Júcar con romería a la ermita de la Trinidad, concursos de pesca fluvial, degustación de morteruelo comarcal y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16903','fiesta','Fiestas de Moros y Cristianos (en Valera de Abajo)','Histórica, Etnográfica y Tradicional. Se celebra en Enero. Festividad de gran empaque etnográfico provincial. Se trata de una de las recreaciones de Moros y Cristianos más antiguas de la provincia de Cuenca, destacando por sus solemnes "dichos" o embajadas y sus vistosas vestimentas históricas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16231','fiesta','Fiestas de San Juan Bautista y la Virgen de la Estrella','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Micro-festividad de carácter netamente familiar en la Manchuela, sustentada por los cultos tradicionales al santo patrón y cenas al aire libre para los residentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16173','fiesta','Fiestas de la Inmaculada Concepción (en Garcinarro)','Patronal, Romería y Etnográfica. Se celebra en Agosto (traslado estival). Festejo alcarreño dinamizado por el turismo arqueológico local; incluye romería al cerro de la ermita, pasacalles con bandas de música locales y un animado ambiente vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16234','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Celebración de la Serranía Alta en un municipio de mínima demografía, sustentada por reuniones comunitarias en torno a calderetas cocinadas al fuego de leña y orquestas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16236','fiesta','Fiestas de Moros y Cristianos (en honor al Santo Niño)','Histórica, Etnográfica y Militar. Se celebra en Enero. Fiesta declarada de Interés Turístico Regional. Posee un valor etnográfico monumental; se caracteriza por las ruidosas e imponentes descargas de arcabucería de las compañías mora y cristiana, las tradicionales "guerrillas" a caballo y los solemnes dichos históricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16237','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festejo local manchego dinamizado por el regreso vacacional de antiguos vecinos, vertebrado por la procesión litúrgica mariana y bailes en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16238','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Celebración tradicional en la Mancha Alta; resalta por sus tradicionales sueltas de vaquillas en recinto urbano, desfile de peñas populares y variadas degustaciones gastronómicas manchegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16239','fiesta','Belén Viviente y Fiestas de Nuestra Señora de la Natividad','Etnográfica, Recreación y Patronal. Se celebra en Diciembre (Belén) y Septiembre. Hito etnográfico de la Serranía Alta por su célebre Belén Viviente escenificado en la gruta natural de la roca de la cueva, atrayendo a numeroso público provincial, junto a sus fiestas tradicionales serranas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16240','fiesta','Fiestas de Nuestra Señora del Carmen','Patronal y Etnográfica. Se celebra en Julio y Agosto. Festividad de la Alcarria conquense caracterizada por la procesión solemne, el canto de las salves de madrugada, competiciones de caliche y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16242','fiesta','Fiestas de San Juan Bautista y la Virgen de Albalate','Patronal, Etnográfica y Enológica. Se celebra en Junio y Agosto. Festejo tradicional alcarreño famoso por sus cuevas vinícolas excavadas en el barranco; destaca por las reuniones de peñas, pasacalles de dulzainas y procesiones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16243','fiesta','Fiestas del Santo Cristo de la Expiración','Patronal, Histórica y Etnográfica. Se celebra en Septiembre. Festejo de hito monumental en la Mancha Alta; incluye solemnes procesiones por su bien conservado entramado señorial, certámenes poéticos y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16244','fiesta','Fiestas de la Virgen del Rosario y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración en la llanura manchega con una intensa participación vecinal, destacando el desfile de carrozas elaboradas por peñas y las tradicionales gachas y migas colectivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16245','fiesta','Fiestas de la Virgen de la Natividad','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Puerta de acceso a la Serranía Alta; destaca por sus encierros tradicionales por el casco urbano, actividades de animación en el río Júcar y verbenas populares masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16246','fiesta','Fiestas de Nuestra Señora de los Portales','Patronal, Romería y Etnográfica. Se celebra en Septiembre. Festejo alcarreño cercano al embalse de Buendía; destaca por el emotivo traslado de la virgen, desfiles de comparsas musicales y un gran ambiente festivo de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16247','fiesta','Fiestas de San Bartolomé Apóstol','Patronal y Etnográfica. Se celebra en Agosto. Celebración típicamente local de la Mancha Alta, fundamentada en los ritos litúrgicos, la subasta vecinal de andas y bailes nocturnos para la comunidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16248','fiesta','Fiestas en honor a San Pedro Apóstol y la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Julio y Octubre. Festividad de la Manchuela Conquense con gran arraigo en la recolección de la almendra; destaca su procesión mariana, el pasacalles de carrozas locales y las cenas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16249','fiesta','Fiestas en honor de la Virgen de Magaceda','Patronal, Romería y Taurina. Se celebra en Mayo y Septiembre. Festejo de gran relevancia comarcal e hito de la Orden de Santiago; destaca por la masiva romería a la ermita, la subasta de andas y capotes, y sus tradicionales encierros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16251','fiesta','Feria y Fiestas de la Virgen de las Nieves','Patronal, Taurina y Gastronómica. Se celebra en Agosto. Gran celebración en la Manchuela ligada a la cultura del champiñón; destaca por sus procesiones solemnes, corridas de toros de gran nivel y la alta participación de peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16253','fiesta','Fiestas de la Virgen de la Cabeza','Patronal y Romería. Se celebra en Septiembre. Celebración tradicional con procesión de antorchas, el canto popular de la Salve, campeonatos de juegos de mesa manchegos y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16254','fiesta','Fiestas del Santísimo Cristo de la Resurrección','Patronal y Etnográfica. Se celebra en Agosto. Celebración de la Alcarria vinculada al turismo que visita la villa romana de Noheda; incluye misa mayor, bailes de plaza y meriendas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16255','fiesta','Fiestas de San Roque y la Virgen del Carmen','Patronal y Etnográfica. Se celebra en Agosto. Festejo de carácter estrictamente vecinal sustentado por los emigrantes que retornan en verano; cuenta con procesiones litúrgicas, campeonatos de naipes y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16263','fiesta','Fiestas de la Virgen de la Cabeza','Patronal y Romería. Se celebra en Septiembre. Festejo muy concurrido por su cercanía a la capital; destaca por su emotiva romería al paraje de las balsas, actividades para peñas y grandes orquestas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16258','fiesta','Fiestas en honor a San Roque y la Virgen de la Asunción','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Hito festivo de la Serranía Baja rodeado de arte rupestre; sobresale por sus tradicionales sueltas de vacas por las calles, las calderetas de toro y las dianas floreadas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16259','fiesta','Fiestas del Santo Cristo de la Victoria','Patronal y Etnográfica. Se celebra en Agosto. Pequeña festividad familiar alcarreña en un entorno rural de baja demografía, vertebrada por la misa solemne, aperitivos populares y bailes en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16910','fiesta','Fiestas de San Antonio de Padua','Patronal y Etnográfica. Se celebra en Junio. Micro-festividad vecinal adaptada al censo local, articulada en torno al reparto de la caridad del santo y reuniones gastronómicas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16264','fiesta','Fiestas de Nuestra Señora de Fuentes','Patronal y Romería. Se celebra en Septiembre. Celebración de la Mancha Alta con solemne procesión hacia la ermita de Fuentes, tradicionales subastas de banzos y concursos de arada y habilidad con tractor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16265','fiesta','Fiestas de San Bartolomé Apóstol','Patronal y Etnográfica. Se celebra en Agosto. Festejo netamente local y de carácter muy familiar, caracterizado por los cultos al patrón, juegos infantiles y una orquesta nocturna para los veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16266','fiesta','Fiestas de San Jorge y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración tradicional marcada por el reencuentro estival; incluye la procesión litúrgica por las calles del casco rural, rifas benéficas y cenas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16269','fiesta','Fiestas de Jesús Nazareno y la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Septiembre. Festejo de gran raigambre en la comarca; destaca por la solemne y emotiva subida del Nazareno, tracas pirotécnicas masivas y un activo ambiente de peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16270','fiesta','Fiestas en honor a la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Septiembre. Festejo local manchego con competiciones tradicionales de lanzamiento de reja, juegos populares para niños y bailes de orquesta en la pista municipal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16271','fiesta','Fiestas en honor a la Virgen de la Consolación','Patronal y Romería. Se celebra en Agosto. Festividad de la Manchuela Conquense con romería tradicional, competiciones deportivas locales, comidas vecinales basadas en cordero serrano y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16272','fiesta','Fiestas de la Virgen de la Merced','Patronal y Etnográfica. Se celebra en Septiembre. Festejo tradicional alcarreño que aglutina la identidad de sus pedanías; incluye procesión, el canto tradicional de salves y degustación de gachas manchegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16273','fiesta','Fiestas del Santísimo Cristo de la Almorada','Patronal y Etnográfica. Se celebra en Mayo. Celebración local centrada en la tradición religiosa manchega de los mayos, la subasta de andas y el reparto de pan bendito entre los hermanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16275','fiesta','Fiestas de San Felipe y Santiago','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Micro-festividad en la frontera de la Alcarria con Guadalajara; se sostiene gracias al retorno estival con comidas vecinales e hiladas de música popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16276','fiesta','Fiestas de Nuestra Señora de los Ángeles y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festejo serrano adaptado a la baja demografía invernal, caracterizado por una misa mayor muy emotiva, campeonatos de naipes y veladas musicales al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16277','fiesta','Fiestas de la Virgen del Carmen','Patronal y Romería. Se celebra en Julio. Celebración de la Mancha Alta con su procesión por las empinadas calles de la villa histórica, tiradas de fuegos artificiales y verbenas populares). Con este bloque cerramos oficialmente la provincia de Cuenca en estricto orden alfabético. ¿Deseas que continuemos el proyecto con la provincia de Guadalajara empezando por sus primeros municipios (Abánades, Ablanque, Adobes, Alaminos, Alarilla, Albalate de Zorita, etc.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90163','fiesta','Fiestas en honor a San Pedro Apóstol y la Virgen de la Merced','Patronal, Etnográfica y Recreación Histórica. Se celebra en Agosto. Celebración en el valle del Tajuña marcada por el retorno estival. Destaca por sus procesiones religiosas tradicionales y las jornadas de recreación histórica sobre la Guerra Civil en su entorno fortificado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90164','fiesta','Fiestas del Santo Cristo del Buen Camino','Patronal y Etnográfica. Se celebra en Agosto. Festejo tradicional del Alto Tajo sostenido por la comunidad veraneante; cuenta con pasacalles de peñas locales, comidas populares a base de caldereta y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90165','fiesta','Fiestas de San Cristóbal y la Virgen de la Oliva','Patronal y Etnográfica. Se celebra en Agosto. Pequeña celebración vecinal en el Señorío de Molina de Aragón; se estructura en torno a los cultos religiosos, juegos de cartas tradicionales y música de orquesta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90166','fiesta','Fiestas en honor a Santiago Apóstol','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Micro-festividad de carácter familiar en la Alcarria alta; se dinamiza con juegos infantiles tradicionales, meriendas de hermandad en la plaza y música local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90167','fiesta','Cabalgata de Reyes Magos de Alarilla','Etnográfica, Deportiva y Religiosa. Se celebra en Enero. Festejo de gran singularidad provincial y proyección mediática. Los Reyes Magos y sus pajes descienden volando en ala delta y parapente iluminados desde el cerro de la Muela ante miles de asistentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90168','fiesta','Fiestas en honor a la Santa Cruz y San Blas','Patronal, Taurina y Romería. Se celebra en Febrero y Septiembre. Festejo alcarreño de gran tradición; destaca por la bajada de la Santa Cruz, sus encierros de reses bravas por el casco urbano, calderetas populares y la apertura de las peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90169','fiesta','Fiestas de San Antonio de Padua y la Virgen de la Vega','Patronal, Etnográfica y Taurina. Se celebra en Junio y Agosto. Celebración de la Alcarria Baja con notable animación popular; incluye sueltas de vaquillas en plaza portátil, competiciones de juegos autóctonos como la tanguilla y verbenas de nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90831','fiesta','Fiestas de Santa Coloma','Patronal y Romería. Se celebra en Julio. Festividad local de la Sierra Norte que congrega a los devotos en la joya románica de la ermita de Santa Coloma, caracterizada por la bendición de alimentos y comidas camperas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90170','fiesta','Fiestas de Nuestra Señora del Espinar','Patronal, Romería y Taurina. Se celebra en Agosto y Septiembre. Festejo de gran arraigo en la Hoya de Infantado; destaca por la procesión mariana junto a la majestuosa iglesia parroquial denominada "La Catedral de la Alcarria", encierros y la tradicional bueyada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90171','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración familiar menor condicionada por la baja demografía invernal; se sustenta con la misa mayor, procesión del santo protector y bailes populares nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90172','fiesta','Fiestas del Santo Cristo de la Misericordia y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festejo comarcal relevante por su posición de paso; incluye la tradicional procesión litúrgica, pasacalles animados por charangas locales, torneos deportivos y activas verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90173','fiesta','Fiestas de San Timoteo y la Virgen de la Antigua','Patronal, Etnográfica y Taurina. Se celebra en Agosto. Festividad de gran identidad en la Sierra de Molina; sobresale por el canto tradicional de la "Loa a San Timoteo", la suelta de novillos y el reparto comunal de carne en caldereta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90174','fiesta','Fiestas del Santo Cristo de la Fe','Patronal y Etnográfica. Se celebra en Septiembre. Festividad de arraigo estrictamente local centrada en la procesión del Cristo, la tradicional subasta de banzos y concursos de cocina tradicional alcarreña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90175','fiesta','Fiestas de San Roque y la Virgen de los Dolores','Patronal y Etnográfica. Se celebra en Agosto. Festejo vecinal en el valle del río Mesa dinamizado por el regreso estival, con solemnes misas, subastas parroquiales, torneos de naipes y bailes en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90832','fiesta','Fiestas del Santo Cristo del Calvario','Patronal y Etnográfica. Se celebra en Agosto. Celebración tradicional con procesión religiosa, campeonatos de bolos y juegos tradicionales de madera, acompañados por las clásicas cenas de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90176','fiesta','Fiestas de San Juan Bautista y San Roque','Patronal y Etnográfica. Se celebra en Junio y Agosto. Celebración de la Alcarria Alta con tradicionales pasacalles, fuegos artificiales, concursos de gachas y migas, y concurridas verbenas en la plaza de la Olivera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90177','fiesta','Fiestas de San Juan Bautista','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Micro-festividad de carácter netamente familiar adaptada a su baja demografía, vertebrada por la misa litúrgica y un almuerzo colectivo para residentes y familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90178','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Pequeña celebración tradicional que reúne a los descendientes de la villa en torno a los actos litúrgicos, rifas benéficas y música popular al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90179','fiesta','Fiestas en honor al Santísimo Cristo de las Injurias','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festejo de gran relevancia en la Alcarria Baja; destaca por sus multitudinarios y arraigados encierros, tanto por el campo como por sus empinadas calles, y un gran ambiente de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90180','fiesta','Fiestas de la Virgen de la Luz','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festividad de gran solera histórica; sobresale por la procesión de la patrona acompañada de dulzaineros, sus tradicionales encierros urbanos y la caldereta popular de toro en el coso medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90181','fiesta','Fiestas del Santo Cristo del Amparo','Patronal y Etnográfica. Se celebra en Septiembre. Celebración tradicional con procesión ante el balcón de la Alcarria, competiciones de juegos populares, catas de vino local y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90182','fiesta','Fiestas de la Virgen de la Paz','Patronal, Taurina y Feria Comercial. Se celebra en Septiembre. Celebración de gran concurrencia en el Corredor del Henares; destaca por sus multitudinarios encierros urbanos, desfiles de peñas locales, eventos deportivos y grandes conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90183','fiesta','Fiestas en honor a la Virgen del Pilar y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festividad de la Sierra de Albarracín de gran valor etnográfico; sobresale por la conservación del baile de la bandera, pasacalles tradicionales y el asado comunal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19031','fiesta','Fiestas de San Sebastián','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Micro-festividad de carácter netamente familiar sustentada por el regreso de los emigrantes, dinamizada con procesiones religiosas sencillas y cenas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19032','fiesta','Fiestas de la Virgen de la Lastra y San Vicente','Patronal y Etnográfica. Se celebra en Agosto. Festejo en la comarca de Sigüenza marcado por los cultos en su singular iglesia fortificada, campeonatos de juegos autóctonos de madera y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19033','fiesta','Fiestas de San Martín Obispo','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Pequeña festividad vecinal de baja demografía invernal, centrada en la subasta de andas para la procesión, meriendas populares y campeonatos de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19034','fiesta','Fiestas de San Martín','Patronal y Etnográfica. Se celebra en Agosto. Celebración local típicamente rural en el Señorío de Molina, articulada en torno a la misa mayor, juegos infantiles y música popular en la plaza del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19036','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal, Etnográfica y Taurina. Se celebra en Agosto. Festejo en la Alcarria Baja con notable animación; incluye pasacalles con charangas, sueltas de vaquillas en recinto portátil, y comidas populares basadas en caldereta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19037','fiesta','Fiestas de San Roque y Fiesta de la Botarga','Etnográfica y Patronal. Se celebra en Enero (Botarga) y Agosto (Patronales). Destaca a nivel provincial por su ancestral Botarga de invierno, figura satírica con máscara y cencerros. En agosto celebran encierros tradicionales e importantes certámenes folclóricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19038','fiesta','Fiestas de la Virgen de la Asunción y San Mamés','Patronal y Etnográfica. Se celebra en Agosto. Celebración en el entorno del Alto Tajo caracterizada por la procesión litúrgica, campeonatos de bolos castellanos, tiradas de traca y cenas colectivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19039','fiesta','Fiestas de San Bartolomé','Patronal y Etnográfica. Se celebra en Agosto. Festejo tradicional alcarreño sustentado por el turismo familiar estival, con solemne misa, la tradicional puja de banzos y bailes populares de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19040','fiesta','Fiestas en honor a la Virgen de la Leche','Patronal y Etnográfica. Se celebra en Agosto. Micro-celebración vecinal adaptada al retorno estival con procesión mariana, torneos tradicionales de naipes y comidas populares en la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19041','fiesta','Fiestas del Santo Cristo de la Clemencia','Patronal y Etnográfica. Se celebra en Septiembre. Festividad local del valle del Tajuña con misa solemne, certámenes de pintura infantil, competiciones de tanguilla y animadas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19043','fiesta','Fiestas del Santo Cristo de la Cárcel y San Agustín','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Festividad alcarreña dinamizada por un activo asociacionismo local; destaca por sus encierros de reses bravas por las calles y el tradicional reparto de migas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19044','fiesta','La Caballada de Atienza','Etnográfica, Ecuestre y Recreación Histórica. Se celebra en Pentecostés (Mayo / Junio). Fiesta declarada de Interés Turístico Nacional. Conmemora desde el año 1162 la salvación del rey Alfonso VIII por los arrieros atencinos; los cofrades visten capas castellanas y sombreros de copa, realizando carreras de caballos y ritos medievales estrictos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19045','fiesta','Fiestas de la Virgen del Madroñal','Patronal, Romería y Etnográfica. Se celebra en Septiembre. Festejo de gran raigambre en la baja Alcarria; incluye la bajada en procesión de la Virgen desde su ermita en el cerro, cantos de mayos tradicionales y festejos taurinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19046','fiesta','Fiestas en honor a la Virgen de la Soledad','Patronal, Taurina y Feria Comercial. Se celebra en Septiembre. Fiesta declarada de Interés Turístico Regional. Destaca por el espectacular Desfile de Carrozas, realizado de forma artesanal por las peñas públicas, junto a una potente feria taurina y macroconciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19047','fiesta','Fiestas de la Virgen de los S समु de la Soledad','Patronal y Etnográfica. Se celebra en Agosto. Celebración de tradición ferroviaria en el valle del Henares, articulada en torno a la procesión litúrgica, campeonatos de bolos y comidas de hermandad en el río Bornova.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19049','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festejo vecinal menor de baja demografía invernal, sostenido por la llegada estival de familiares con misas solemnes, rifas parroquiales y música de charanga.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19050','fiesta','Fiestas de Nuestra Señora de los Remedios','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad alcarreña de carácter estrictamente familiar, basada en la procesión tradicional de la Virgen, juegos infantiles de madera y veladas musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19051','fiesta','Fiestas de la Virgen de la Collada','Patronal y Romería. द्री. Se celebra en Agosto. Tradición local alcarreña en la que se realiza la procesión a la ermita, acompañada por la subasta de banzos, competiciones de tanguilla y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19052','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festejo típicamente serrano enfocado en el reencuentro estival; cuenta con misas solemnes, el canto de las tradicionales coplas de San Roque y cenas de caldereta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19053','fiesta','Fiestas de la Virgen de la Peña y Tradicional Encierro del 16 de Agosto','Taurina, Patronal y Etnográfica. Se celebra en Agosto. Fiesta declarada de Interés Turístico Regional. Su encierro del 16 de agosto por el campo es uno de los más antiguos e importantes de España, atrayendo a decenas de miles de aficionados para ver bajar las reses desde el monte de la Alcarria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19054','fiesta','Fiestas del Santo Cristo de la Esperanza y Los Soldadescos','Patronal, Etnográfica y Taurina. Se celebra en Septiembre. Hito etnográfico en el corazón de la Alcarria; destaca por la comitiva de "Los Soldadescos" vestidos con uniformes antiguos escoltando los actos religiosos, además de sus encierros urbanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19057','fiesta','Fiestas de San Roque y Fiesta de las Mechas','Patronal y Etnográfica. Se celebra en Agosto. Festejo serrano en las faldas del Alto Rey que conserva las tradicionales rondas autóctonas, campeonatos de bolos castellanos y degustación de patatas con costillas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19086','fiesta','Fiestas de los Cristos y de San Salvador','Patronal, Taurina y Feria Comercial. Se celebra en Septiembre. Festejo de gran relevancia comarcal. Destaca por sus históricos encierros de reses bravas por el campo, sus ferias medievales de muestras agrícolas y el desfile de sus numerosas peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19058','fiesta','Fiestas del Santo Cristo de la Expiración','Patronal, Taurina y Feria Comercial. Se celebra en Julio. Celebración de gran concurrencia urbana; sobresale por los encierros por las calles del municipio, los multitudinarios desfiles de peñas y un programa musical masivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19059','fiesta','Fiestas de la Virgen de la Antigua','Patronal y Etnográfica. Se celebra en Agosto. Celebración del Señorío de Molina vinculada al histórico Castillo de Zafra; incluye procesiones solemnes, tiradas de traca pirotécnica y meriendas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19060','fiesta','Fiestas en honor a la Virgen del Rosario','Patronal y Etnográfica (Arquitectura Negra). Se celebra en Agosto. Festejo de gran atractivo turístico en los Pueblos Negros; destaca por sus pasacalles con gaitas y dulzainas, bailes tradicionales en sus plazas de pizarra y gran afluencia regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19061','fiesta','Fiestas de Santa María Magdalena','Patronal y Romería. Se celebra en Julio. Festividad local de la Sierra Norte; los devotos se congregan en torno a la monumental iglesia románica de San Bartolomé y su célebre mensario, compartiendo migas serranas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19064','fiesta','Fiestas de San Juan Bautista y la Virgen de la Merced','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Celebración tradicional alcarreña adaptada al verano con subasta de banzos, concursos de gachas y verbenas populares que congregan a los pueblos limítrofes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19065','fiesta','Feria de Ganado de Cantalojas','Feria Comercial y Etnográfica. Se celebra en Octubre. Es una de las ferias de ganado tradicional más importantes e históricas del Sistema Central, cita ineludible del sector ganadero con exhibiciones de oficios, maquinaria y gastronomía serrana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19066','fiesta','Fiestas del Santo Cristo de la Santa Cruz','Patronal y Etnográfica. Se celebra en Mayo. Celebración de la Campiña de Guadalajara que conserva el canto de los mayos, el adorno floral de las calles y competiciones tradicionales de caliche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19071','fiesta','Fiestas en honor a la Virgen de la Antigua y Fiesta de las Candelas','Patronal, Taurina y Etnográfica. Se celebra en Febrero (Candelas) y Septiembre (Patronales). Destaca por su fiesta invernal de las Candelas con la lectura de los "dichos" por los mayordomos a caballo. En septiembre celebra encierros tradicionales por el campo de gran fama comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19078','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Pequeño festejo rural de la comarca de la Alcarria centrado en actos litúrgicos tradicionales, torneos de naipes y cenas vecinales en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19079','fiesta','Fiestas del Santo Cristo de la Vega','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad del Señorío de Molina basada en una procesión solemne, aperitivos populares costeados por el ayuntamiento y bailes al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19103','fiesta','Fiestas de San Bartolomé y San Roque','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Hito festivo de la Serranía de Molina; destaca por su singular plaza de toros circular de madera, sus encierros a caballo tradicionales y el canto solemne del Miserere.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19104','fiesta','Fiestas de San Juan Bautista','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Espectacular festejo por su ubicación entre formaciones de arenisca roja; los encierros tradicionales de vaquillas se realizan usando las propias rocas naturales como toriles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19105','fiesta','Fiestas de la Virgen de la Solidaridad','Patronal, Taurina y Feria Comercial. Se celebra en Septiembre. Celebración de la Campiña muy concurrida; destaca por sus activos desfiles de peñas en carrozas, sus tradicionales encierros urbanos de toros y verbenas musicales masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19106','fiesta','Fiestas en honor a San Roque y la Virgen de los Huertos','Patronal y Etnográfica. Se celebra en Agosto. Celebración alcarreña a orillas de Entrepeñas; incluye subasta de banzos de la patrona, campeonatos de tanguilla y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19092','fiesta','Fiesta de Santa Águeda y Fiestas de la Virgen de los Remedios','Etnográfica, Histórica y Patronal. Se celebra en Febrero (Santa Águeda) y Agosto (Patronales). Su fiesta de Santa Águeda es declarada de Interés Turístico Regional, donde las mujeres toman el mando del pueblo luciendo el espectacular traje tradicional alcarreño ante el Palacio Ducal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19096','fiesta','Fiestas del Santo Cristo de la Buena Muerte y Los Danzantes de Condemios','Etnográfica y Patronal. Se celebra en Agosto. Hito folclórico de la Sierra Norte; destaca por la ancestral danza de paloteo interpretada por los danzantes masculinos tradicionales con trajes rituales blancos y cintas de colores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19095','fiesta','Fiestas de San Vicente Mártir','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Festejo de carácter familiar que reúne a la comunidad en torno a procesiones religiosas sencillas, comidas vecinales de caldereta y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19099','fiesta','Fiestas de San Roque y de la Virgen del Buen Fuente','Patronal, Romería y Etnográfica. Se celebra en Agosto. Festejo en las puertas del Parque Natural del Alto Tajo; sobresale por su romería al Santuario de la Virgen de la Hoz, encierros de vaquillas y un dinámico programa de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19107','fiesta','Fiestas de la Virgen de la Muela','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festividad vinculada al entorno de la antigua ciudad romana de Caraca; incluye encierros tradicionales por el casco urbano, concursos gastronómicos de migas y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19108','fiesta','Fiestas del Santo Cristo de las Injurias y la Virgen de la Esperanza','Patronal y Etnográfica. Se celebra en Agosto. Celebración alcarreña que conserva el canto de la Salve tradicional en la plaza, pasacalles de cabezudos acompañados por dulzaineros y degustación de dulces locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19109','fiesta','Fiestas en honor a San Roque','Patronal y Etnográfica. Se celebra en Agosto. Pequeña celebración en el Señorío de Molina presidida por su esbelto castillo; cuenta con misas solemnes, campeonatos de naipes de guiote y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19110','fiesta','Fiestas de la Virgen de la Esperanza','Patronal y Etnográfica. Se celebra en Agosto. Celebración bajo la silueta de su monumental torre barroca "Giralda de la Alcarria"; incluye procesiones tradicionales, reparto de caridad y verbenas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19111','fiesta','Fiestas de la Virgen de los Desamparados','Patronal y Taurina. Se celebra en Agosto. Festejo tradicional alcarreño con una concurrida procesión nocturna, suelta de vaquillas en su plaza de toros tradicional portátil y concurso de calderetas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19113','fiesta','Fiesta de Santa Águeda y Fiestas de la Virgen de la Asunción','Etnográfica y Patronal. Se celebra en Febrero (Santa Águeda) y Agosto (Patronales). Destaca por su tradicional celebración de las Águedas, donde las mujeres asumen los cargos institucionales por un día luciendo los trajes regionales de la campiña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19114','fiesta','Fiestas de la Virgen de la Fuente','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad local de baja demografía invernal, articulada en torno a los cultos parroquiales tradicionales y meriendas populares de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19117','fiesta','Fiestas en honor a la Virgen de la Antigua','Patronal, Taurina y Feria Comercial. Se celebra en Agosto. Festejo de la Campiña con gran arrastre comarcal; es famoso por sus encierros camperos de toros por los llanos del Henares, masivos desfiles de peñas y conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19118','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración típicamente rural e íntima adaptada al retorno estival con procesión del santo protector, campeonatos de juegos de cartas y música de orquesta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19119','fiesta','Fiestas de San Juan Bautista','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Festividad local de la campiña baja centrada en la subasta de banzos para portar las andas religiosas, concursos infantiles de pintura y bailes de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19120','fiesta','Fiestas de la Virgen de la Antigua y La Borricá','Etnográfica y Patronal. Se celebra en Enero (La Borricá) y Septiembre (Patronales). Posee una joya etnográfica el fin de semana de Reyes conocida como "La Borricá", donde los cofrades recorren el pueblo a caballo portando la bandera e insignias rituales históricas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19121','fiesta','Fiestas de San Agustín y Fiesta del Mayo','Patronal, Etnográfica y Taurina. Se celebra en Mayo (Mayo) y Agosto (Patronales). Festejo alcarreño de gran tradición histórica; destaca por la plantada del árbol del mayo en la plaza y sus arraigados encierros urbanos de toros por el casco medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19124','fiesta','Fiestas de la Virgen de los Perpetuos Socorros y Los Mayos','Patronal y Etnográfica. Se celebra en Mayo. Destaca por el tradicional e ininterrumpido canto de los Mayos al pie de su monumental picota barroca del siglo XVI, complementado con verbenas y pasacalles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19125','fiesta','Fiestas del Santo Niño y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración vecinal menor estructurada en torno a la procesión por el casco rural, la subasta de andas religiosas y meriendas de hermandad en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19126','fiesta','Fiestas de la Virgen del Campo','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Festividad campiñera de notable afluencia por sus tradicionales encierros taurinos por las calles de la villa, pasacalles de charangas y animados concursos de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19127','fiesta','Fiestas de la Virgen del Pinar y Los Danzantes de Galve','Etnográfica y Patronal. Se celebra en Agosto. Hito del folclore provincial en la Sierra Norte; destaca por la ancestral danza del paloteo y el "Zarragón", personaje con látigo que dirige los movimientos rituales del grupo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19130','fiesta','Ferias y Fiestas de la Virgen de la Antigua','Feria Comercial, Taurina y Etnográfica. Se celebra en Septiembre. Fiestas grandes de la capital de la provincia de enorme empaque. Cuenta con multitudinarios e históricos encierros urbanos, desfiles de peñas monumentales, una gran feria taurina y un real ferial muy activo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19132','fiesta','Fiesta de San Bartolomé y la Fiesta de la Matanza','*. Gastronómica, Etnográfica y Patronal. *. Se celebra en Agosto (Patrón) y Diciembre (Matanza). *. Destaca por la conservación de la matanza del cerdo tradicional alcarreña en invierno, que atrae a gran cantidad de visitantes para degustar el picadillo y las migas de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19133','fiesta','Fiestas de San Juan Bautista','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Festejo de la vega del Henares adaptado al turismo estival con procesión del santo patrón, comidas populares a base de paella y campeonatos tradicionales de naipes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19134','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad del Señorío de Molina de marcado carácter vecinal y familiar, caracterizada por la misa mayor, rifas populares y bailes en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19135','fiesta','Pasión Viviente de Hiendelaencina','Etnográfica, Teatro Popular y Religiosa. Se celebra en Semana Santa (Viernes Santo). Fiesta declarada de Interés Turístico Regional. Todo el pueblo se convierte en escenario viviente para representar la Pasión de Cristo con un realismo y emotividad excepcionales que atraen a miles de visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19138','fiesta','Festival Medieval de Hita','Recreación Histórica, Literaria y Etnográfica. Se celebra en Julio. Fiesta declarada de Interés Turístico Nacional. Es el festival medieval más antiguo de España; el pueblo revive el "Libro de Buen Amor" del Arcipreste con torneos caballerescos auténticos, desfiles de botargas y teatro en la calle.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19139','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración tradicional del Señorío de Molina en las inmediaciones del Monasterio de la Buenafuente; incluye procesión, subasta de banzos y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19143','fiesta','Fiestas de la Virgen de la Soledad y Fiesta del Vino','Patronal, Taurina y Enológica. Se celebra en Abril (Vino) y Septiembre (Patronales). Hito alcarreño de gran empaque; destaca en abril por el concurso del vino en sus bodegas subterráneas medievales y en septiembre por sus multitudinarios encierros camperos y urbanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19145','fiesta','Fiestas de San Julián','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Pequeña festividad vecinal sustentada por el regreso vacacional con procesiones litúrgicas íntimas, tradicionales concursos gastronómicos de tortillas y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19146','fiesta','Fiestas de San Sebastián','Patronal y Etnográfica (Arquitectura Negra). Se celebra en Agosto (traslado estival). Festejo serrano adaptado a las pedanías de la Arquitectura Negra; incluye pasacalles con charangas, misas solemnes y calderetas colectivas para los residentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19147','fiesta','Fiestas del Santo Cristo de la Salud','Patronal y Etnográfica. Se celebra en Agosto. Celebración familiar de baja demografía invernal en el valle del Salado, vertebrada por la misa litúrgica, la subasta de joyas del Cristo y bailes en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19148','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festejo en la comarca del Alto Tajo caracterizado por la procesión litúrgica, los tradicionales campeonatos de juegos autóctonos de cartas y música nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19150','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración alcarreña que conserva el canto de los mayos, pasacalles tradicionales con charangas y degustación popular de caldereta en su entorno monumental.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19151','fiesta','Fiestas de la Virgen de la Peñahora','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festejo de gran raigambre en el valle del Sorbe; sobresale por la multitudinaria procesión del "Fuego" iluminada con antorchas, sus encierros urbanos de toros y el desfile de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19152','fiesta','Fiestas en honor de la Virgen del Socorro','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festividad de la Alcarria Baja con notable arrastre; destaca por sus arraigados encierros de toros por el campo y por las calles, además del tradicional concurso de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19153','fiesta','Fiestas de San Pedro Apóstol','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Celebración íntima y familiar en el municipio con menor población del Señorío de Molina, articulada en torno a comidas vecinales y música tradicional en la plaza). Con este bloque cerramos la letra I de la provincia de Guadalajara. ¿Deseas que continuemos el proyecto con el siguiente bloque (avanzando hacia los municipios que empiezan por la letra J como Jadraque.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19156','fiesta','Fiestas Patronales del Santísimo Cristo de la Cruz Acuestas y Fiesta de las Migas','Patronal, Taurina y Gastronómica. Se celebra en Septiembre (Patronales) y Diciembre (Migas). Festejo de gran calado comarcal bajo el "Castillo del Cid". Destacan sus tradicionales encierros y novilladas en septiembre, y el masivo concurso nacional de migas en diciembre, hito gastronómico provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19157','fiesta','Fiestas de San Bartolomé','Patronal y Etnográfica. Se celebra en Agosto. Festejo local del valle del Bornova condicionado por la baja demografía, sustentado por el retorno vacacional con misas, campeonatos de cartas y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19159','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración tradicional alcarreña en el valle del Badiel con subasta de banzos, concursos de gachas manchegas y verbenas que reúnen a los núcleos pedáneos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19160','fiesta','Fiestas en honor a la Virgen de la Soledad','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festividad de arraigo en el Tajuña; destaca por sus encierros urbanos, pasacalles de la banda de música, carrozas elaboradas por las peñas y verbenas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19161','fiesta','Fiestas de San Bartolomé','Patronal, Etnográfica y Taurina. Se celebra en Agosto. Festejo muy cercano a la capital provincial, al pie de la cuna de la Orden de San Jerónimo; incluye sueltas de reses, tradicionales calderetas y animadas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19162','fiesta','Fiestas de la Virgen de la Quinta Angustia','Patronal y Etnográfica. Se celebra en Agosto. Celebración de la comarca de Sigüenza ligada a su pasado celtíbero; incluye procesiones solemnes, subasta de banzos y juegos tradicionales de bolos serranos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19163','fiesta','Carnaval de Luzón (Los Diablos de Luzón)','Etnográfica y Carnaval Tradicional. Se celebra en Febrero. Fiesta de Interés Turístico Regional. Hito etnográfico de valor excepcional; los "diablos" desfilan con la piel tiznada de hollín y aceite, grandes cuernos de toro en la cabeza y ruidosos cencerros a la cintura, persiguiendo a los asistentes junto a las "mascaritas".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19165','fiesta','Fiesta del Santo Niño y Fiesta de los Danzantes de Majaelrayo','Etnográfica y Patronal (Arquitectura Negra). Se celebra en Septiembre. Fiesta de Interés Turístico Regional. Celebrada en el corazón de los Pueblos Negros; destaca por la ancestral danza de paloteo y castañuelas ejecutada por ocho danzantes masculinos ataviados con indumentarias rituales de gran vistosidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19166','fiesta','Fiestas de la Virgen de la Antigua','Patronal y Etnográfica. Se celebra en Septiembre. Celebración de la Campiña marcada por la procesión litúrgica, el tradicional canto de salves, competiciones de tanguilla y comidas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19167','fiesta','Fiestas de Nuestra Señora del Valle','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festejo campiñero con notable concurrencia vecinal; incluye sus tradicionales encierros por las calles del casco urbano, concursos de cocina y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19170','fiesta','Fiestas de la Virgen de los Olmos','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Histórica festividad vinculada a los antiguos tratantes de ganado; sobresale por sus festejos taurinos en su plaza de toros de piedra de 1912, pasacalles de peñas y solemnes cultos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19171','fiesta','Fiestas Patronales del Santo Cristo de la Gallardo y de la Virgen de la Soledad','Patronal, Taurina y Feria Comercial. Se celebra en Mayo y Agosto. Festejo urbano de gran relevancia en el Corredor del Henares. Sus encierros de toros, suelta de reses y el masivo ambiente de peñas en el parque de ferias atraen a miles de personas de toda la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19172','fiesta','Fiestas de la Virgen del Sagrario','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad del alto valle del Tajuña adaptada al reencuentro estival, con procesión tradicional del santo, campeonatos de guiote y cenas populares de caldereta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19176','fiesta','Fiesta de la Soldadesca (en honor a la Virgen de la Paz)','Etnográfica, Histórica y Religiosa. Se celebra en Enero. Fiesta de Interés Turístico Regional. Conmemora la Batalla de Lepanto; los mozos visten uniformes militares de época y desfilan escoltando a la Virgen, destacando la exhibición del "bandereo" ante la imagen mariana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19177','fiesta','Fiestas de la Virgen de los Remedios','Patronal y Etnográfica. Se celebra en Agosto. Pequeña celebración serrana vertebrada por la misa mayor, la tradicional subasta de roscas de pan bendito, competiciones infantiles y música popular en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19179','fiesta','Fiestas del Santo Cristo de la Agonía','Patronal y Etnográfica. Se celebra en Agosto. Festejo tradicional en el valle del Bornova; cuenta con procesión solemne, campeonatos locales de bolos castellanos y calderetas comunitarias elaboradas en el parque.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19181','fiesta','Fiestas del Santo Cristo de la Agonía','Patronal y Etnográfica. Se celebra en Agosto. Festejo de la Sierra Norte en la Ruta del Cid; destaca por sus tradicionales pasacalles con dulzaineros, la subasta de andas parroquiales y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19184','fiesta','Fiestas de San Sebastián y la Virgen de la Fuensanta','Patronal y Romería. Se celebra en Agosto. Celebración alcarreña en la Hoya de Infantado centrada en la romería hacia la ermita mariana, comidas populares campestres y bailes de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19186','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Festejo vecinal menor dinamizado por la comunidad estival; incluye misa solemne, campeonatos tradicionales de cartas y música de charanga en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19187','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Micro-celebración familiar en la comarca de la Alcarria alta centrada en actos litúrgicos, rifas vecinales y bailes al aire libre para los veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19188','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad en el valle del río Mesa adaptada a su baja demografía invernal, articulada en torno a comidas vecinales y música tradicional en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19189','fiesta','Fiestas de la Virgen de la Luz y Fiesta del Mayo','Patronal y Etnográfica. Se celebra en Mayo. Festejo campiñero que conserva la plantada del árbol del mayo por los mozos en la plaza de la villa, acompañado por cantos litúrgicos y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19190','fiesta','Fiestas del Santo Cristo de las Victorias y Fiestas de la Virgen del Carmen','Patronal, Militar-Religiosa y Taurina. Se celebra en Julio (Carmen) y Septiembre (Cristo). *. Fiesta de la Virgen del Carmen declarada de Interés Turístico Regional. Destaca por el desfile de la antiquísima Cofradía Militar del Carmen con uniformes de época y escolta armada, además de potentes ferias taurinas en septiembre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19192','fiesta','Fiestas del Santísimo Cristo del Calvario','Patronal, Enológica y Taurina. Se celebra en Septiembre. Gran festividad alcarreña célebre por su cultura vinícola con Denominación de Origen; destaca por la solemne procesión de los portadores del Cristo, sus importantes encierros taurinos urbanos y de campo, y catas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19193','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Micro-celebración vecinal campiñera de baja demografía, articulada en torno a los cultos parroquiales y meriendas populares de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19194','fiesta','Fiestas de la Virgen de la Alcarria y Los Mayos','Patronal y Etnográfica. Se celebra en Mayo y Agosto. Festejo tradicional alcarreño que mantiene el canto de los mayos en su singular rollo jurisdiccional del siglo XVI, complementado con procesiones y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19195','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festejo del Señorío de Molina sustentado por el regreso vacacional con procesiones litúrgicas íntimas, tradicionales concursos de naipes de guiote y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19196','fiesta','Fiestas de San Diego y San Roque','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Celebración en el valle del Badiel dinamizada por el retorno veraniego, caracterizada por la procesión litúrgica, campeonatos de tanguilla y bailes de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19154','fiesta','Fiestas de la Virgen de la Acordanza','Patronal y Etnográfica. Se celebra en Septiembre. Celebración serrana tradicional con subasta de banzos de la patrona, comidas vecinales basadas en caldereta de cordero serrano y juegos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19199','fiesta','Fiestas en honor a San Juan Bautista','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Festejo menor en el Parque Natural del Alto Tajo enfocado en el reencuentro estival; cuenta con misas solemnes, rifas parroquiales y música de orquesta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19201','fiesta','Romería de la Virgen de la Buenafuente y San Jorge','Romería y Etnográfica. Se celebra en Junio y Agosto. Celebración vinculada al histórico Monasterio de Buenafuente del Sistal; congrega a los devotos del ducado en procesiones tradicionales, cantos religiosos y comidas camperas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19202','fiesta','Fiestas de San Mateo','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Pequeña celebración rural del valle del Salado centrada en actos litúrgicos tradicionales, torneos familiares de naipes y veladas musicales al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19204','fiesta','Fiestas de San Juan Bautista y la Virgen de la Asunción','Patronal y Etnográfica (Forestal). Se celebra en Agosto. Hito festivo de la Sierra de Molina en el municipio más alto de la región; destaca por la procesión tradicional de la Virgen, las exhibiciones forestales de corta de troncos y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19208','fiesta','Fiestas de la Virgen de la Presa y Triatlón de Pálmaces','Deportiva, Patronal y Romería. Se celebra en Julio y Agosto. Destaca a nivel nacional por su célebre triatlón de larga trayectoria que revoluciona el municipio. En agosto celebran las procesiones tradicionales a orillas del embalse del río Cañamares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19209','fiesta','Fiestas de San Lorenzo','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad en un núcleo con censo invernal crítico en el Señorío de Molina, articulada en torno a una misa solemne y comidas comunitarias de hermandad para los descendientes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19210','fiesta','Fiestas del Santo Niño','Patronal y Etnográfica. Se celebra en Agosto. Festividad local del valle del Salado centrada en la procesión tradicional por el casco rural, la subasta de andas y meriendas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19211','fiesta','Fiestas en honor de la Virgen de los Remedios y Feria Medieval','Patronal, Taurina e Histórica. Se celebra en Mayo (Feria) y Septiembre (Patronales). Festejo alcarreño de relieve junto a Entrepeñas; destaca por su gran feria medieval en primavera y por sus tradicionales encierros urbanos de toros y bueyadas en septiembre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19212','fiesta','Festival Ducal de Pastrana y Fiestas de la Virgen de la Alcarria','Recreación Histórica, Literaria y Patronal. Se celebra en Julio (Festival Ducal) y Septiembre (Patronales). El Festival Ducal es Fiesta de Interés Turístico Regional. La Villa Ducal recrea el Siglo de Oro y la historia de la Princesa de Éboli con majestuosos desfiles con trajes de época cortesana, teatro barroco y conciertos monumentales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19216','fiesta','Fiestas de la Virgen de Ribagorda y Festival Blues de la Alcarria/Alto Tajo','Romería, Musical y Etnográfica. Se celebra en Julio (Blues) y Septiembre (Romería). Destaca por su masivo festival de música Blues que congrega a miles de seguidores en pleno Parque Natural, complementado con su romería tradicional de honda devoción serrana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19217','fiesta','Fiestas de la Virgen de los Remedios','Patronal y Etnográfica. Se celebra en Agosto. Celebración alcarreña dinamizada por el turismo estival, caracterizada por la procesión litúrgica, campeonatos de tanguilla y cenas vecinales al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19219','fiesta','Fiestas de San Juan Bautista','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Pequeña celebración rural en el Señorío de Molina centrada en actos litúrgicos, la subasta de rollos del santo y bailes populares en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19220','fiesta','Fiestas en honor a San Donato y la Virgen de la Alcarria','Patronal, Taurina y Feria Comercial. Se celebra en Agosto. Festejo de notable crecimiento demográfico; sobresale por los encierros tradicionales por las calles de la villa, pasacalles de peñas locales y verbenas de gran formato.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19221','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad de carácter netamente familiar en la Sierra de Molina, vertebrada por la misa solemne, campeonatos de naipes de guiote y música local de charanga.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19222','fiesta','Fiestas de la Virgen del Campo y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festejo comarcal del Señorío de Molina con pasacalles musicales, paelladas gigantes para los vecinos, competiciones de juegos tradicionales de madera y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19223','fiesta','Fiestas de la Virgen de los Remedios y Fiesta de los Gancheros','Etnográfica, Patronal y Oficios Tradicionales. Se celebra en Agosto (Patronales) y Septiembre (Gancheros). La Fiesta de los Gancheros del Alto Tajo es Fiesta de Interés Turístico Regional. Recrea de forma rotativa el oficio tradicional de la maderada, donde los gancheros guían los troncos flotando por el río Tajo vestidos de época.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19224','fiesta','Fiestas de San Martín Obispo','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Celebración alcarreña orientada al retorno de emigrantes en verano, combinada con actos religiosos, subastas parroquiales y verbenas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19225','fiesta','Fiestas del Santísimo Cristo de la Agonía','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festividad de la Alcarria Alta con notable animación; incluye pasacalles de peñas, encierros de reses bravas por el casco urbano y tradicionales concursos gastronómicos de migas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19227','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración típica de la Sierra de Molina que congrega a los antiguos residentes en torno a la procesión del santo protector y calderetas comunitarias vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19226','fiesta','Fiestas de la Virgen de la Natividad','Patronal y Etnográfica. Se celebra en Septiembre. Micro-festividad de marcado carácter familiar en la Sierra Norte de baja demografía, sustentada por una procesión solemne y comidas populares de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19233','fiesta','Fiestas de la Virgen de la Dicha','Patronal y Etnográfica. Se celebra en Septiembre. Festividad local del valle del llano alcarreño marcada por la procesión solemne, competiciones tradicionales de caliche y comidas populares en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19234','fiesta','Fiestas de la Virgen de los Enebrales y Fiesta de la Botarga','Etnográfica y Patronal. Se celebra en Febrero (Botarga) y Agosto (Patronales). Hito etnográfico de la Sierra Norte; destaca por su tradicional botarga invernal con máscara ritual y cencerros que interactúa con la vecindad ante las ruinas del Monasterio de Bonaval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19235','fiesta','Fiestas de la Virgen de Armallones','Patronal y Etnográfica. Se celebra en Agosto. Festejo vinculado al entorno de la Cueva de los Casares; incluye la procesión mariana tradicional, campeonatos de bolos serranos y cenas vecinales a base de caldereta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19237','fiesta','Fiestas del Santo Cristo de la Clemencia','Patronal y Etnográfica. Se celebra en Agosto. Celebración tradicional del Señorío de Molina con procesión religiosa, la puja de varas de la imagen, torneos de guiote y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19242','fiesta','Fiestas en honor de la Virgen de la Asunción y San Roque','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Festejo alcarreño en el valle del San Andrés; destaca por sus arraigadas sueltas de vacas en recinto portátil, pasacalles con charangas y verbenas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19245','fiesta','Fiestas de la Santa Cara de Dios y la Virgen del Socorro','Patronal, Taurina y Ecuestre. Se celebra en Agosto y Septiembre. Festejo de gran relevancia comarcal a orillas del "Mar de Castilla"; sobresale por la solemne procesión de la Santa Cara, sus concurridos encierros urbanos y camperos, y las actividades náuticas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19246','fiesta','Fiestas de San Benito','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Celebración vinculada al histórico entorno de sus salinas tradicionales; incluye misa litúrgica solemne, campeonatos de cartas y almuerzos populares vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19247','fiesta','Fiestas en honor a la Virgen del Puerto y San Roque','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Festejo tradicional alcarreño en el límite con Cuenca; destaca por sus procesiones religiosas, los encierros urbanos de vaquillas en su plaza Mayor porticada y la animada reunión de peñas en las bodegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19248','fiesta','Fiestas de San Andrés Apóstol','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Celebración de carácter familiar junto al embalse de Alcorlo; centrada en la procesión de andas, campeonatos de cartas tradicionales de guiote y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19249','fiesta','Fiestas del Santo Cristo de la Columna','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad alcarreña sustentada por el retorno estival de emigrantes, vertebrada por la misa solemne, aperitivos comunitarios en la plaza y música popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19250','fiesta','Fiestas de los Santos Justo y Pastor','Patronal y Etnográfica. Se celebra en Agosto. Pequeña celebración rural e íntima en un núcleo de muy baja demografía, basada en los cultos parroquiales, juegos infantiles y cenas de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19251','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Festividad local de la comarca de Sigüenza; los devotos se congregan en su singular iglesia románica porticada, acompañando los actos de bailes populares y tanguilla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19252','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración tradicional de la Alcarria Baja con pasacalles de cabezudos y charangas, concursos gastronómicos de gachas manchegas y animadas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19254','fiesta','Fiestas de la Virgen de la Minerva','Patronal y Etnográfica. Se celebra en Agosto. Festejo del Señorío de Molina condicionado por la altitud y la despoblación invernal; se activa en verano con torneos de naipes, subasta de banzos y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19901','fiesta','Fiestas de San Juan Bautista','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Micro-festividad de la Sierra Norte de marcado carácter vecinal, articulada en torno a comidas comunitarias a base de caldereta serrana y música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19255','fiesta','Fiesta del Santo Niño y Fiestas de la Virgen de la Serna','Etnográfica y Patronal. Se celebra en Diciembre (Santo Niño) y Agosto (Patronales). Destaca por su fiesta tradicional de invierno del Santo Niño con la comparsa del "Diablo" y los "Danzantes", hito de la comarca minera de Molina que atrae gran interés patrimonial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19256','fiesta','Fiestas de Santa Eulalia','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Celebración vecinal menor estructurada en torno a la procesión por el casco rural, la subasta de andas religiosas y meriendas de hermandad en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','fiesta','Fiestas de San Roque y la Virgen de la Mayor y Jornadas Medievales','Patronal, Recreación Histórica y Taurina. Se celebra en Julio (Medievales) y Agosto (Patronales). Fiestas de gran empaque provincial e hito monumental nacional. Destacan sus famosas Jornadas Medievales con el asalto al Castillo, la procesión de los faroles de la Virgen de la Mayor y su feria taurina tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19258','fiesta','Fiestas en honor a la Virgen de la Soledad','Patronal y Etnográfica. Se celebra en Agosto. Festejo de la Alcarria Alta dinamizado por la comunidad veraneante; incluye subastas parroquiales, campeonatos de bolos castellanos y calderetas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19259','fiesta','Fiestas del Santo Cristo de la Redención','Patronal y Etnográfica. Se celebra en Agosto. Celebración junto a la Laguna de Somolinos en la Sierra Norte, caracterizada por la procesión litúrgica, concursos infantiles de pintura y bailes de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19260','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad de la comarca alcarreña de carácter estrictamente familiar, basada en los cultos tradicionales al santo protector y cenas vecinales al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19261','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Pequeño festejo rural centrado en actos litúrgicos tradicionales, tiradas de traca pirotécnica, torneos de naipes de guiote y veladas musicales de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19262','fiesta','Fiestas de la Virgen de los Enebrales','Patronal, Romería y Feria Comercial. Se celebra en Septiembre. Hito festivo de la Sierra Norte y puerta de los Pueblos Negros; destaca por la romería a la ermita en el paraje de la Ciudad Encantada y su concurrido Mercado Medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19263','fiesta','Fiestas de San Miguel Arcángel','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Festejo de la vega del Henares adaptado al turismo estival con procesión del santo patrón, comidas populares a base de paella y campeonatos de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19264','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración en el corazón del Parque Natural del Alto Tajo; incluye pasacalles con charangas, misas solemnes con subasta de banzos y concursos de jotas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19265','fiesta','Fiestas de San Bartolomé','Patronal y Etnográfica. Se celebra en Agosto. Festividad local del Señorío de Molina articulada en torno a los cultos parroquiales, juegos infantiles tradicionales de madera y meriendas colectivas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19266','fiesta','Feria de San Matías de Tendilla y Fiestas de la Virgen de la Salceda','Feria Comercial, Gastronómica y Patronal. Se celebra en Febrero (San Matías) y Septiembre (Patronales). Su histórica feria ganadera y de muestras de San Matías está declarada de Interés Turístico Regional, atrayendo a miles de visitantes bajo sus soportales medievales para degustar migas y torreznos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19267','fiesta','Fiestas de la Virgen del Amor Hermoso','Patronal y Etnográfica. Se celebra en Agosto. Pequeña celebración en la Sierra de Molina caracterizada por la procesión litúrgica tradicional, rifas parroquiales benéficas y música de orquesta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19268','fiesta','Fiestas de San Juan Bautista y de las Salinas de Armallá','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Festejo rural del Señorío de Molina vinculado a su patrimonio salinero histórico; incluye misa solemne, campeonatos de guiote y cenas vecinales en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19269','fiesta','Fiestas de la Virgen de los Remedios','Patronal y Etnográfica. Se celebra en Septiembre. Celebración tradicional serrana en el entorno del Bornova con solemne procesión mariana, competiciones de tanguilla y bailes de orquesta en la pista municipal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19271','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad local en el Señorío de Molina adaptada al censo estival, articulada en torno a comidas colectivas y música popular para reunir a los descendientes de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19270','fiesta','Fiestas de San Pedro Apóstol','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). *. Micro-celebración vecinal menor de marcado carácter familiar en un núcleo de baja demografía, sustentada por una procesión solemne y orquestas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19272','fiesta','Fiestas de San Bartolomé y de la Virgen de los Dolores','Patronal y Etnográfica. Se celebra en Agosto. Festejo de arraigo local en la frontera con Aragón; incluye pasacalles musicales, paelladas gigantes para los vecinos, campeonatos de cartas y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19274','fiesta','Fiestas en honor a la Virgen del Amparo y Certamen de Rondas Tradicionales','Patronal, Etnográfica y Taurina. Se celebra en Septiembre (Patronales) y Diciembre (Rondas). Su Certamen de Rondas Navideñas está declarado de Interés Turístico Regional, reuniendo a grupos folclóricos de toda la provincia ante su imponente castillo medieval. En septiembre celebran encierros tradicionales por el campo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19279','fiesta','Fiestas de San Miguel Arcángel','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Celebración en el valle del Badiel condicionada por su evolución demográfica singular; centrada en actos litúrgicos tradicionales, juegos infantiles y música de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19277','fiesta','Fiestas del Santo Niño','Patronal y Etnográfica. Se celebra en Agosto. Festejo vecinal menor de la comarca molinesa sustentada por la comunidad estival, caracterizado por la procesión, la tradicional puja de banzos y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19278','fiesta','Fiestas de San Juan Bautista','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Micro-festividad familiar de la Alcarria alta centrada en misas mayores, la tradicional subasta de rollos del santo y bailes al aire libre para los veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19280','fiesta','Fiestas de la Virgen de la Corona y Fiesta de las Candelas','Patronal, Taurina y Etnográfica. Se celebra en Febrero (Candelas) y Septiembre (Patronales). Celebración de la Campiña muy concurrida; destaca por su tradición invernal de las Candelas con la carrera del "Zorra" y en septiembre por sus multitudinarios encierros urbanos de toros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19281','fiesta','Fiestas de San Miguel','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Pequeña festividad familiar alcarreña de carácter íntimo en un núcleo de baja demografía, vertebrada por la misa solemne, aperitivos populares y bailes en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19282','fiesta','Fiestas del Santo Cristo de la Buena Dicha','Patronal y Etnográfica. Se celebra en Agosto. Festejo tradicional alcarreño junto a la autovía A-2; incluye pasacalles de peñas locales, comidas populares a base de caldereta y verbenas de nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19283','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración del Señorío de Molina en sus extensos pinares; centrada en la procesión de las andas del santo, campeonatos de naipes de guiote y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19284','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad íntima y de carácter muy familiar adaptada a su baja demografía, basada en la procesión tradicional, juegos infantiles de madera y veladas musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19285','fiesta','Fiestas de San Miguel Arcángel','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Pequeña celebración vecinal del Señorío de Molina sustentada por los antiguos residentes que retornan en verano, caracterizada por la misa litúrgica y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19286','fiesta','Fiestas de la Virgen de la Llaná','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festejo campiñero con notable animación popular por su cercanía a la capital; incluye tradicionales encierros de toros por las calles de la villa, pasacalles de peñas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19287','fiesta','Fiestas de San Bartolomé y de la Virgen de los Remedios','Patronal y Etnográfica. Se celebra en Agosto. Celebración tradicional de la comarca de Molina; destaca por sus solemnes procesiones, las tradicionales subastas de banzos y un activo ambiente de peñas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19288','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Festejo serrano adaptado al retorno estival en el valle del Jarama, caracterizado por la procesión litúrgica, concursos de cocina local y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19289','fiesta','Fiestas de San Roque y de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Celebración de la Sierra de Molina dinamizada por los veraneantes; incluye subasta de andas para la procesión, tradicionales meriendas de caldereta y campeonatos de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19290','fiesta','Fiestas de la Virgen de la Soledad','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festejo alcarreño en el balcón de la Alcarria; destaca por sus tradicionales encierros de reses bravas por las calles, concursos de gachas y migas, y un activo desfile de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19291','fiesta','Fiestas de la Virgen del Campo y las Vacas por el Tajo','Taurina, Patronal y Etnográfica. Se celebra en Junio (Vacas al Tajo) y Septiembre (Patronales). Festejo declarado de Interés Turístico Regional. Su célebre suelta de "Vacas por el Tajo" en junio congrega a miles de personas en el cauce del río, constituyendo un hito taurino y etnográfico único en España.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19293','fiesta','Fiestas de la Virgen de la Varga','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Festividad de gran raigambre en la frontera con Madrid; destaca por sus arraigados encierros de toros por el campo y por las calles de su conjunto histórico, y un potente desfile de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19294','fiesta','Fiestas de San Juan Ante Portam Latinam','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Micro-festividad serrana de carácter familiar en un entorno rural de baja demografía, vertebrada por una procesión solemne, aperitivos populares y música de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19297','fiesta','Fiestas de San José y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Pequeña celebración alcarreña de carácter íntimo en un núcleo de baja demografía, basada en los cultos tradicionales al santo, juegos infantiles y música popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19298','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festividad local del valle del Henares dinamizada por el regreso estival; incluye la tradicional procesión mariana, campeonatos de cartas tradicionales de guiote y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19299','fiesta','Fiestas en honor a Santa María Magdalena','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Festejo de la Alcarria Alta sustentado por la emigración estival, caracterizado por la procesión litúrgica tradicional, subasta de roscas y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19300','fiesta','Fiestas del Santísimo Cristo de la Resurrección','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Festividad campiñera muy concurrida por su cercanía a la capital; destaca por sus encierros urbanos de reses bravas, pasacalles de peñas locales y grandes orquestas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19301','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración tradicional alcarreña en el valle del Tajuña orientada al retorno de emigrantes en verano, combinada con actos religiosos e invitaciones populares a base de zurra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19302','fiesta','Fiestas del Santo Cristo del Amparo','Patronal y Etnográfica. Se celebra en Septiembre. Festejo de arraigo estrictamente local centrado en los actos litúrgicos, la almoneda de banzos y cenas populares basadas en asados tradicionales alcarreños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19303','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad de marcado carácter familiar en un entorno rural de baja demografía, sustentada por una procesión solemne, campeonatos de guiote y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19305','fiesta','Fiestas del Santo Cristo de la Agonía','Patronal y Etnográfica. Se celebra en Agosto. Festejo tradicional de la Sierra Norte con procesión, canto de jotas serranas por las calles de la villa y tradicionales calderetas colectivas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19306','fiesta','Fiestas en honor a San Roque','Patronal y Etnográfica. Se celebra en Agosto. Pequeña festividad vecinal en el valle del Tajuña basada en cultos religiosos tradicionales, rifas benéficas para la iglesia parroquial y música de charanga.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19307','fiesta','Fiestas de San Pedro Apóstol y Fiesta de los Descamisados','Etnográfica y Patronal. Se celebra en Agosto. Hito etnográfico en la Sierra de Ayllón; destaca por la pervivencia de antiquísimas coplas locales, rondas tradicionales con instrumentos autóctonos y la típica hospitalidad serrana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19308','fiesta','Fiestas del Santo Cristo de la Agonía','Patronal y Etnográfica. Se celebra en Agosto. Celebración en la Alcarria Alta marcada por las procesiones litúrgicas, la tradicional subasta de banzos, competiciones de tanguilla y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19310','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad de carácter familiar en el parque natural del Alto Tajo, dinamizada con juegos infantiles tradicionales, meriendas de hermandad en la plaza y música local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19311','fiesta','Fiestas del Santísimo Sacramento y Danzas del Octavo de Corpus','Etnográfica y Religiosa. Se celebra en Junio. Fiesta declarada de Interés Turístico Regional con un valor etnográfico excepcional. Es una de las joyas folclóricas de los Pueblos Negros; los danzantes visten espectaculares indumentarias con sombreros de flores multicolores y realizan danzas rituales de paloteo al son de la dulzaina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19317','fiesta','Fiestas de San Roque y la Virgen de la Asunción','Patronal, Etnográfica y Tradición Resinera. Se celebra en Agosto. Festejo de gran identidad en el Alto Tajo; sobresale por las exhibiciones tradicionales de la corta de troncos, pasacalles de peñas y reparto comunal de caldereta de cordero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19318','fiesta','Fiestas de San Blas','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Micro-celebración vecinal adaptada al retorno estival con procesión del santo protector, torneos tradicionales de naipes y comidas populares en la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19319','fiesta','Fiestas de la Virgen del Amor Hermoso','Patronal, Taurina y Feria Comercial. Se celebra en Junio. Celebración de gran concurrencia urbana en el Corredor del Henares; destaca por sus multitudinarios encierros por las calles, desfiles de peñas locales, macro-verbenas y eventos deportivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19323','fiesta','Fiestas de la Virgen de la Angustias','Patronal y Etnográfica. Se celebra en Septiembre. Festividad local de la campiña alta centrada en la subasta de banzos para portar las andas religiosas, concursos infantiles de dibujo y bailes de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19322','fiesta','Fiestas de San Blas','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Pequeña festividad vecinal de baja demografía invernal, centrada en la subasta de andas para la procesión, meriendas populares y campeonatos de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19324','fiesta','Fiestas de Jesús Nazareno','Patronal y Etnográfica. Se celebra en Septiembre. Celebración tradicional en el valle del río Mesa con solemne procesión, competiciones de tanguilla, fuegos artificiales y animadas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19325','fiesta','Fiestas en honor a la Virgen de la Antigua','Patronal y Etnográfica. Se celebra en Agosto. Celebración de la Campiña de Guadalajara que conserva el canto de los mayos, el adorno floral de las calles y competiciones tradicionales de caliche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19326','fiesta','Fiestas de San Bartolomé Apóstol','Patronal, Etnográfica y Taurina. Se celebra en Agosto. Festividad de gran crecimiento urbano debido al núcleo de Valdeluz; incluye encierros tradicionales por el casco urbano, concursos gastronómicos de migas y orquestas de nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19327','fiesta','Fiestas en honor a la Virgen de la Soledad','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festejo alcarreño de gran tradición; destaca por la procesión mariana, sus encierros de reses bravas por las calles y el campo, calderetas populares y la apertura de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19330','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración tradicional con procesión religiosa en el valle del San Andrés, campeonatos de bolos castellanos y tradicionales cenas de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19329','fiesta','Fiestas de la Virgen de la Pastora','Patronal y Etnográfica. Se celebra en Agosto. Festejo vecinal menor de baja demografía winter, sostenido por la llegada estival de familiares con misas solemnes, rifas parroquiales y música de charanga.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19331','fiesta','Fiestas de la Virgen de la Granja','Patronal, Taurina y Feria Comercial. Se celebra en Septiembre. Festejo de gran relevancia provincial y raigambre taurina. Destaca por sus históricos encierros de toros por el campo por los llanos del Henares, multitudinarios desfiles de peñas y potentes ferias de muestras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19333','fiesta','Fiestas de la Virgen de la Asunción y San Roque','*. Patronal y Etnográfica. *. Se celebra en Agosto. *. Hito festivo de la comarca del Alto Tajo; destaca por el gran ambiente de su comunidad estival, pasacalles de dulzaineros, competiciones de corta de troncos y calderetas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19335','fiesta','Fiestas de la Virgen de la Asunción','Patronal, Histórica y Etnográfica. Se celebra en Agosto. Festejo de gran valor históricocultural por su patrimonio medieval y arqueológico ligado a Recópolis; sobresale por sus procesiones solemnes, comidas populares a orillas del Tajo y actividades culturales). Hemos cerrado de forma completa y rigurosa la provincia de Guadalajara. ¿Deseas que continuemos el proyecto con la provincia de Toledo (comenzando por Ajofrín, Alameda de la Sagra, Albarreal de Tajo, Alcabón, Alcaudete de la Jara, Alcañizo, Alcolea de Tajo, etc.) para terminar definitivamente la Comunidad Autónoma de Castilla-La Mancha?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90291','fiesta','Fiestas en honor a la Virgen de Gracia y San Bartolomé','Patronal y Etnográfica. Se celebra en Agosto y Septiembre. Festividad de arraigo en la comarca de la Sisla; destaca por su gran tradición musical con pasacalles de bandas, la solemne procesión mariana y la degustación de dulces tradicionales como los mantecados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90292','fiesta','Fiestas de la Virgen del Carmen','Patronal y Taurina. Se celebra en Julio. Festejo de la comarca de la Sagra con gran poder de convocatoria; destaca por sus arraigados encierros urbanos de reses bravas y las procesiones religiosas solemnes escoltadas por las peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90833','fiesta','Fiestas del Santísimo Cristo de la Esperanza y San Agustín','Patronal y Etnográfica. Se celebra en Agosto. Celebración tradicional en la ribera del Tajo enfocada en el reencuentro estival, caracterizada por la puja de banzos, competiciones de juegos populares manchegos y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90834','fiesta','Fiestas de Santo Tomás de Cantórbery y la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Septiembre y Octubre. Festejo local de raíces agrícolas; sobresale por la bendición comunal de alimentos, juegos infantiles tradicionales en la plaza mayor y orquestas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90293','fiesta','Fiestas en honor a la Virgen del Castillo','Patronal, Romería y Taurina. Se celebra en Mayo y Septiembre. Festejo con gran empaque en la comarca de la Jara; destaca por la bajada de la Virgen desde su ermita, los encierros camperos tradicionales y un animado concurso gastronómico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90294','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Celebración ribereña con notable arraigo por sus sueltas de vaquillas en recinto portátil, pasacalles de gigantes y cabezudos y animadas verbenas de peñas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90295','fiesta','Fiestas del Santo Cristo de la Buena Dicha','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad familiar y vecinal en una zona de baja demografía, dinamizada por la llegada veraniega con misas solemnes, rifas parroquiales y orquestas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90296','fiesta','Fiestas de la Virgen de la Espina y San Santiago','Patronal y Romería. Se celebra en Mayo y Agosto. Festejo vinculado a la Vía Verde de la Jara; sobresale por su vistosa romería campestre, las competiciones de caliche y las tradicionales parrilladas de carne locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90297','fiesta','Fiestas en honor a San Bartolomé Apóstol','Patronal y Etnográfica. Se celebra en Agosto. Celebración popular conocida localmente como "Aldeanovita" centrada en la procesión del santo, la puja de varas, espectáculos de pólvora pirotécnica y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90298','fiesta','Fiestas del Santísimo Cristo de la Sangre','Patronal y Etnográfica. Se celebra en Agosto. Festividad de la Sierra de San Vicente; incluye pasacalles acompañados por dulzaineros, procesión nocturna de antorchas y la tradicional degustación de patatas al caldero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90299','fiesta','Fiestas del Santísimo Cristo de la Misericordia','Patronal y Etnográfica. Se celebra en Agosto y Septiembre. Celebración bajo la silueta de su castillo medieval; incluye solemnes procesiones del Cristo, subastas parroquiales benéficas y animadas verbenas en el paseo principal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90300','fiesta','Fiestas de la Virgen de la Piedad, San Roque y los Carnavales','Patronal, Taurina y Etnográfica. Se celebra en Febrero (Carnaval) y Agosto (Patronales). Destaca por su ancestral Carnaval de las Ánimas con el "Baile de la Bandera". En agosto celebran encierros tradicionales por el campo y calles que atraen a gran cantidad de aficionados de Madrid y Toledo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90301','fiesta','Fiestas de Santa Ana','Patronal, Taurina y Feria Comercial. Se celebra en Julio. Festejo de gran relevancia en la Sagra; sobresale por su feria taurina de gran prestigio comarcal, encierros matutinos urbanos, desfiles masivos de peñas y desfiles de carrozas artísticas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90835','fiesta','Fiestas de la Virgen de la Visitación y San Roque','Patronal y Etnográfica. Se celebra en Julio y Agosto. Festejo tradicional de raíces agrícolas centrado en los cultos religiosos, carreras de cintas a caballo, juegos populares para niños y veladas musicales nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90302','fiesta','Fiestas de la Virgen de la Antigua y San Juan Bautista','Patronal, Taurina y Feria Comercial. Se celebra en Junio y Agosto. Festividad con gran tirón por su cercanía inmediata a la capital toledana; incluye multitudinarios encierros por las calles, actividades culturales y grandes conciertos en la plaza de la Constitución.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90303','fiesta','Fiestas de San Pablo y la Virgen de la Milagrosa','Patronal y Etnográfica. Se celebra en Enero y Agosto. Micro-festividad de carácter familiar ligada a su entorno arqueológico y megalítico, vertebrada por la misa solemne, aperitivos populares y música popular al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45018','fiesta','Fiestas del Santo Cristo de la Agonía','Patronal y Etnográfica. Se celebra en Septiembre. Festejo tradicional marcado por la procesión del Cristo al pie de su histórico castillo con la enseña del león; cuenta con juegos infantiles de madera y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45019','fiesta','Fiestas del Santísimo Cristo de la Sala','Etnográfica, Patronal y Religiosa. Se celebra en Septiembre. Fiesta declarada de Interés Turístico Regional. Destaca por la espectacular Procesión de los trajes típicos bargueños, donde las mujeres desfilan luciendo mantones de Manila históricos, suntuosos aderezos de oro y peinados tradicionales solemnes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45020','fiesta','Fiestas de San Sebastián y la Virgen de la Zarza','Patronal y Etnográfica. Se celebra en Enero y Agosto. Hito festivo de la Jara baja; incluye el encendido de luminarias tradicionales en invierno y grandes procesiones con subastas de banzos y verbenas multitudinarias en verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45021','fiesta','Fiestas de Nuestra Señora de la Salud','Patronal y Taurina. Se celebra en Agosto. Celebración de la Sagra alta con gran fervor taurino; destaca por sus tradicionales encierros y novilladas en su emblemática plaza de toros rectangular e integrada en el casco histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45022','fiesta','Fiestas de San Buenaventura','Patronal y Etnográfica. Se celebra en Julio. Celebración en el límite con el valle del Tiétar; se caracteriza por los cultos tradicionales, campeonatos de caliche y cenas comunitarias basadas en carnes de caza de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45023','fiesta','Fiestas del Santo Cristo de la Fe','Patronal y Etnográfica. Se celebra en Septiembre. Festejo tradicional con procesiones solemnes, concursos gastronómicos de migas y gachas manchegas, campeonatos de pádel y animadas verbenas que atraen a la juventud comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45024','fiesta','Fiestas de San Pantaleón y la Virgen de la Candelaria','Patronal y Etnográfica. *. Se celebra en Febrero y Julio. *. Celebración dinamizada por el turismo que visita las famosas Barrancas de Burujón; incluye pasacalles con charangas, misas mayores solemnes y el tradicional refresco popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45025','fiesta','Fiestas de Nuestra Señora del Socorro','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Festividad campiñera que cuenta con encierros urbanos tradicionales, concursos de peñas locales, verbenas multitudinarias en la plaza del ayuntamiento y campeonatos de mus.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45026','fiesta','Fiestas del Santísimo Cristo del Socorro','Patronal y Etnográfica. Se celebra en Agosto. Pequeño festejo rural de la Mesa de Ocaña de marcado carácter vecinal y familiar, caracterizado por la misa mayor con coro, la subasta de andas y música al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45027','fiesta','Fiestas de la Virgen del Castillo y San Nazario','Patronal y Etnográfica. Se celebra en Julio. Celebración manchega tradicional que reúne a los emigrantes locales en torno a la procesión mariana, tiradas de traca pirotécnica y las clásicas gachas colectivas en el campo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45028','fiesta','Fiestas en honor al Santísimo Cristo de Chozas','Patronal, Taurina y Gastronómica. Se celebra en Septiembre. Festejo de gran relevancia en el eje del Tajo-Talavera; destaca por sus tradicionales encierros urbanos de toros, la degustación masiva de su tradicional guiso de toro y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45029','fiesta','Fiestas de la Virgen de la Consolación y San Blas','Patronal y Etnográfica. Se celebra en Febrero y Septiembre. Festejo local de la Campana de Oropesa centrado en la tradición religiosa, la bendición de rollos de pan del santo, campeonatos de naipes de guiote y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45030','fiesta','Fiestas del Santísimo Cristo de las Misericordias','Patronal y Etnográfica. Se celebra en Septiembre. Celebración tradicional entre antiguos conventos y casonas señoriales; incluye procesiones nocturnas solemnes, exposiciones de artesanía textil comarcal y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45031','fiesta','Fiestas de la Virgen de la Caridad y San Juan Bautista','Patronal, Enológica y Taurina. Se celebra en Agosto. Hito festivo de la comarca de Torrijos ligado a la cultura del vino con D.O. Méntrida; sobresale por su ofrenda floral, sus encierros camperos y urbanos, y cata de caldos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45032','fiesta','Fiestas de la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Agosto. Festejo vecinal menor sustentado por el regreso vacacional estival, caracterizado por la procesión parroquial por el casco histórico, juegos infantiles y música popular en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45033','fiesta','Fiestas en honor a la Virgen de la Costa y San Blas','Patronal y Romería. Se celebra en Febrero y Agosto. Romería tradicional serrana que congrega a los vecinos en parajes naturales de la Jara alta, combinando comidas comunitarias, cantos religiosos y competiciones de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45034','fiesta','Pecados y Danzantes de Camuñas (Fiesta del Corpus Christi)','Etnográfica, Ritual y Religiosa. Se celebra en Mayo / Junio (Corpus). Fiesta declarada de Interés Turístico Nacional de incalculable valor etnográfico. Recrea la lucha mística entre el Bien y el Mal a través de los Pecados (caretas imponentes y gritos guturales) y los Danzantes (indumentaria blanca y ritmo rítmico con porras y cascabeles) en un ceremonial único en España.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45035','fiesta','Fiestas de la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Festejo serrano adaptado al retorno vacacional en el valle del Alberche, caracterizado por la subasta de banzos de la patrona, comidas populares basadas en caldereta y bailes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45036','fiesta','Fiestas de la Virgen de la Asunción y la Fiesta del Santo Niño','Patronal y Etnográfica. Se celebra en Agosto y Septiembre. Celebración tradicional toledana con procesión, la subasta de andas religiosas, campeonatos de caliche y tiro al plato, y animadas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45037','fiesta','Fiestas de Santiago Apóstol y las Fiestas de las Carreras de Caballos','Etnográfica, Ecuestre y Patronal. Se celebra en Julio. Fiesta de Interés Turístico Regional. Famosa por sus ancestrales e intrépidas carreras de caballos de origen medieval, donde los jinetes emparejados galopan por la plaza mayor a gran velocidad para descabezar un ganso colgado de una cuerda de forma ritual.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45038','fiesta','Fiestas en honor al Santo Cristo de la Fe','Patronal, Taurina e Histórica. Se celebra en Septiembre. Festejo muy ligado al turismo que acude a su Parque Arqueológico de villas romanas; incluye tradicionales encierros y festejos taurinos, desfiles de carrozas de peñas y conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45039','fiesta','Fiestas de la Virgen de la Encina y San Isidro','Patronal y Etnográfica. Se celebra en Mayo y Agosto. Tradición local de arraigo vecinal enfocada en el culto mariano, la procesión de la patrona con tracas, meriendas populares en la plaza y juegos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45041','fiesta','Fiestas en honor a Nuestra Señora de la Gracia','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festejo de gran solera en el norte de la provincia; sobresale por sus concurridos encierros urbanos de toros, grandes espectáculos pirotécnicos junto a la iglesia mudéjar y verbenas de nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45042','fiesta','Fiestas del Santo Cristo de la Salud','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad familiar en la comarca de la Sisla de baja demografía invernal, vertebrada por la misa litúrgica, campeonatos de cartas tradicionales y música de orquesta nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45043','fiesta','Fiestas de la Virgen del Castillo y de San Andrés','Patronal y Etnográfica. Se celebra en Agosto y Noviembre. Festejo de la Sierra de San Vicente; destaca por la emotiva bajada de la Virgen iluminada por antorchas, degustaciones de migas camperas y un activo ambiente de peñas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45045','fiesta','Fiestas de la Virgen del Rosario y San Vicente','Patronal, Etnográfica y Naútica. Se celebra en Agosto y Octubre. Celebración dinamizada por las actividades veraniegas de su embalse sobre el Alberche; incluye pasacalles tradicionales con charangas, subasta de andas y bailes de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45046','fiesta','Fiestas de la Virgen de la Antigua y San Joaquín','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festejo de gran raigambre en la ribera del Tajo; destaca por sus encierros urbanos de reses bravas por las empinadas calles, desfiles de peñas en carrozas y pólvora pirotécnica final.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45047','fiesta','Fiestas de la Virgen de la Natividad y San Antonio','Patronal, Taurina y Feria Comercial. Se celebra en Junio y Septiembre. Festejo de la Sagra alta muy concurrido; destaca por sus activos desfiles de peñas en carrozas, sus tradicionales encierros urbanos de toros por el casco histórico y verbenas musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45049','fiesta','Fiestas de San Roque y la Virgen del Rosario','Patronal, Etnográfica y Artesanal. Se celebra en Agosto y Octubre. Celebración tradicional comarcal que cuenta con una arraigada procesión nocturna, exhibiciones de artesanía de cuero locales, concursos de cocina local y un activo ambiente festivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45056','fiesta','Fiestas de la Virgen de la Misericordia y el Santísimo Cristo de la Piedad','*. Patronal y Taurina. *. Se celebra en Mayo y Septiembre. *. Festividad de la comarca de la Sagra de gran concurrencia; sobresale por los encierros urbanos de reses bravas por el municipio, los desfiles de disfraces de las peñas y conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45057','fiesta','Fiestas de la Virgen de los Remedios','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Micro-festividad vecinal adaptada al censo local, articulada en torno al culto litúrgico de la patrona, tradicionales aperitivos populares pagados por el ayuntamiento y bailes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45050','fiesta','Fiestas en honor a Nuestra Señora de la Natividad','Patronal y Etnográfica. Se celebra en Septiembre. Celebración tradicional de la Mesa de Ocaña con solemne procesión mariana, competiciones tradicionales de lanzamiento de reja y juegos populares manchegos en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45051','fiesta','Fiestas de la Virgen del Carmen','Patronal, Taurina y Feria Comercial. Se celebra en Septiembre. Festividad con gran relevancia en la comarca cerámica de la Sagra; incluye encierros tradicionales por el casco urbano, concursos gastronómicos de migas y orquestas populares masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45052','fiesta','Fiestas de Nuestra Señora de las Angustias','Patronal y Etnográfica. Se celebra en Junio. Celebración residencial con enorme afluencia juvenil por su cercanía a Toledo; destaca por su emotiva ofrenda floral, actividades culturales para peñas y grandes orquestas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45053','fiesta','Fiesta de la Rosa del Azafrán','Gastronómica, Etnográfica y Recreación Histórica. Se celebra en Octubre. Fiesta declarada de Interés Turístico Regional de enorme proyección nacional. Se celebra al pie de sus icónicos molinos de viento manchegos y su castillo; destaca por el certamen folclórico nacional de coros y danzas, la molienda tradicional en el molino "Sancho" y el concurso de mondado de la flor del azafrán.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45054','fiesta','Fiestas de la Virgen de la Muela y San Isidro','Patronal, Enológica y Romería. Se celebra en Mayo. Gran festividad en la Mancha Alta toledana; destaca por la masiva romería al santuario de la patrona, los desfiles de peñas locales y catas populares organizadas por sus prestigiosas bodegas vitivinícolas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45055','fiesta','Fiestas de la Virgen del Remedio y San Bartolomé','Patronal, Etnográfica y Artesanal. Se celebra en Septiembre. Festejo tradicional de los Montes de Toledo célebre por su vinculación a la artesanía de la forja y la alfarería; incluye pasacalles de la banda de música, solemnes misas y degustación de tostones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45058','fiesta','Fiestas de la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Agosto. Celebración tradicional con procesión de antorchas, campeonatos de juegos de mesa castellanos y naipes, acompañados por las clásicas cenas de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45059','fiesta','Fiestas de la Virgen del Rosario y San Isidro','Patronal y Etnográfica. Se celebra en Mayo y Septiembre. Festejo de la Mesa de Ocaña con notable arraigo; destaca por los cánticos tradicionales de la salve a la medianoche, certámenes de pintura local y bailes populares con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45060','fiesta','Fiestas de la Virgen de la Esclavitud','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Pequeña celebración vecinal de la comarca de Torrijos centrada en la subasta de banzos de la imagen religiosa, meriendas de hermandad en la plaza del ayuntamiento y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45061','fiesta','Fiestas en honor a San Roque y la Virgen de la Asunción','Patronal, Taurina e Histórica. Se celebra en Agosto. Festejo de gran relevancia comarcal e hito monumental a orillas del Alberche. Destaca por sus históricos encierros taurinos por las calles del recinto amurallado, el desfile de peñas masivo y festivales culturales en su castillo palacio medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45062','fiesta','Fiestas del Santo Cristo de la Cruz a Cuestas','Patronal y Taurina. Se celebra en Septiembre. Celebración tradicional de raíces agrícolas con gran animación de peñas; incluye sueltas de vaquillas en su plaza de toros tradicional, procesiones multitudinarias de gran fervor y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45063','fiesta','Fiestas de Santiago Apóstol y la Virgen de los Remedios','Patronal y Etnográfica. Se celebra en Julio y Agosto. Festejo en los Montes de Toledo serranos marcado por el reencuentro veraniego; destaca por las tradicionales rondas de música locales, competiciones de caliche y calderetas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45064','fiesta','Fiestas de la Virgen de la Leche y Jornadas Cervantinas','Patronal, Histórico-Literaria y Taurina. Se celebra en Agosto (Patronales) y Diciembre (Cervantinas). Hito cultural indiscutible. En diciembre celebran recreaciones históricas solemnes sobre el matrimonio de Miguel de Cervantes en la localidad. En agosto destacan sus tradicionales encierros y novilladas de gran fama comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45065','fiesta','Fiestas de la Virgen de los Remedios','Patronal y Romería. Se celebra en Agosto. Celebración de la comarca de la Jara basada en cultos religiosos tradicionales de arraigo local, rifas benéficas para la parroquia de San Andrés y música de orquesta nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45066','fiesta','Fiestas del Santo Cristo del Olvido y la Virgen de la Soledad','Patronal, Taurina y Feria Comercial. Se celebra en Septiembre. Festejo de enorme empaque en la comarca del calzado; sobresale por su potente feria taurina con corridas de toros y encierros urbanos, desfiles de carrozas de gran nivel artesanal y macroverbenas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45067','fiesta','Fiestas de San Agustín y San Bartolomé','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Festividad de gran raigambre en los Montes de Toledo; destaca por sus célebres encierros de toros por las calles de la villa, sus activos concursos de charangas de peñas locales y las calderetas comunales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45068','fiesta','Fiestas en honor a María Santísima de la Antigua y San Andrés Apóstol','Patronal y Etnográfica. Se celebra en Agosto y Noviembre. Festejo de la comarca de Torrijos sustentado por el retorno estival; incluye procesión religiosa con subasta de banzos y las tradicionales migas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45069','fiesta','Fiestas de la Virgen del Rosario y San Mateo','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Celebración de notable arraigo comarcal; destaca por sus encierros urbanos, la masiva ofrenda floral a la patrona y el gran concurso local de gachas manchegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45070','fiesta','Fiestas de la Virgen de la Natividad','Patronal, Recreación Histórica y Romería. Se celebra en Septiembre. Hito festivo e histórico muy vinculado a su famoso castillo medieval; sobresale por la procesión portando réplicas del tesoro visigodo de Guarrazar y sus jornadas históricas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45071','fiesta','Fiestas del Santo Niño de La Guardia','Patronal y Etnográfica. Se celebra en Septiembre. Festejo de gran raigambre e intensa devoción popular; incluye la espectacular bajada del Santo Niño a su ermita excavada en la roca y vistosos castillos de fuegos artificiales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45072','fiesta','Fiestas del Santísimo Cristo de la Veracruz','Patronal y Etnográfica. Se celebra en Septiembre. Celebración tradicional de la comarca de Talavera junto al río Tajo, caracterizada por la procesión litúrgica, campeonatos de caliche y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45073','fiesta','Fiestas en honor a San Ildefonso y la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Agosto (festa estival) y Octubre. Festejo tradicional de la Campana de Oropesa que conserva las rondas de guitarras de la zona, subasta de roscas y tradicionales calderetas de cordero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45074','fiesta','Fiestas en honor al Santísimo Cristo de la Agonía','Patronal, Etnográfica y Taurina. Se celebra en Agosto. Celebración en la Sierra de San Vicente con alta afluencia estival; incluye la subasta de banzos de la imagen, encierros tradicionales de vaquillas y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45075','fiesta','Fiestas de San Miguel Arcángel','Patronal y Etnográfica. Se celebra en Septiembre. Micro-festividad de la comarca de los Montes de Toledo adaptada a la baja demografía, vertebrada por la misa solemne y degustación de carnes de caza de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45076','fiesta','Fiestas de la Virgen de la Higuera','Patronal y Romería. Se celebra en Mayo y Agosto. Festividad local marcada por la romería, el canto tradicional de los mayos manchegos y competiciones de juegos autóctonos de lanzamiento de reja.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45077','fiesta','Fiestas de San Juan Bautista y la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Junio y Agosto. Celebración de arraigo estrictamente local centrada en las misas mayores, pasacalles animados por charangas y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45078','fiesta','Fiestas de la Virgen del Rosario','Patronal y Romería. Se celebra en Agosto. Festejo de la Mesa de Ocaña con notable afluencia; destaca por la romería y bajada de la patrona desde su singular ermita modernista, y comidas populares de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45081','fiesta','Fiestas de la Virgen de la Caridad','Patronal, Taurina y Feria Comercial. Se celebra en Agosto / Septiembre. Fiesta de Interés Turístico Regional. Destaca por su importantísima feria taurina en el coso cubierto, sus solemnes procesiones marianas, desfiles gigantescos de peñas y macro-conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90836','fiesta','Fiestas en honor de la Virgen de la Oliva','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festejo del Valle del Tiétar toledano; incluye la tradicional procesión de la patrona, sueltas de vaquillas en plaza portátil y animadas verbenas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45080','fiesta','Fiestas de San Juan Bautista','Patronal y Etnográfica. Se celebra en Junio. Micro-festividad simbólica de marcado carácter familiar en el municipio con menor población censada de España, sustentada en un almuerzo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45082','fiesta','Corpus Christi de Lagartera','Etnográfica, Textil y Religiosa. Se celebra en Junio (Corpus Christi). Fiesta declarada de Interés Turístico Regional de enorme valor etnográfico nacional. Las calles se adornan con altares tradicionales y los vecinos lucen sus espectaculares y valiosísimos trajes típicos bordados a mano de origen renacentista.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45083','fiesta','Fiestas del Santo Cristo del Buen Camino','Patronal y Etnográfica. Se celebra en Septiembre. Celebración vecinal menor estructurada en torno a la procesión por el casco rural, la subasta de andas y el tradicional convite a base de zurra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45084','fiesta','Fiestas en honor al Santísimo Cristo de las Injurias','Patronal, Taurina y Feria Comercial. Se celebra en Mayo y Septiembre. Celebración manchega tradicional que cuenta con una arraigada procesión nocturna, encierros por el casco urbano y competiciones de arada y habilidad con tractor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45085','fiesta','Fiestas de la Virgen de la Oliva','Patronal y Taurina. Se celebra en Mayo y Septiembre. Festejo de la comarca de La Sagra con encierros tradicionales por las calles, pasacalles de la banda de música local y fuegos artificiales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45087','fiesta','Fiestas del Santísimo Cristo del Prado y Jornadas del Azafrán','Patronal, Feria Comercial y Gastronómica. Se celebra en Septiembre (Cristo) y Octubre (Azafrán). Festejo de gran empaque en la Mancha toledana. Destaca por sus procesiones masivas y, muy especialmente, por sus jornadas dedicadas a la monda del azafrán con concursos folclóricos y demostraciones etnográficas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45088','fiesta','Fiestas en honor a la Virgen del Carmen','Patronal, Taurina y Etnográfica. Se celebra en Julio. Festejo de La Sagra con gran animación de peñas; incluye sueltas de reses bravas en recinto urbano, macro-verbenas y desfiles de carrozas elaboradas por vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45089','fiesta','Fiestas de la Virgen de las Nieves','Patronal, Taurina y Romería. Se celebra en Agosto. Festejo riberano de gran tradición bajo su histórico castillo; sobresale por la procesión por las calles con tracas pirotécnicas, encierros y la degustación de vinos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45090','fiesta','Fiestas de Nuestro Padre Jesús Nazareno','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Festividad local manchega con solemne procesión bajo la torre del castillo, puja de banzos e invitaciones populares costeadas por la hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45091','fiesta','Fiestas de la Virgen de los Dados','Patronal, Recreación Histórica y Etnográfica. Se celebra en Abril. Hito festivo marcado por su imponente castillo; destaca por la representación de las tradicionales "Embajadas de Moros y Cristianos" ante las murallas de la villa e intensa devoción mariana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45092','fiesta','Fiestas en honor a San Juan Bautista','Patronal y Etnográfica. Se celebra en Junio. Pequeña festividad en los Montes de Toledo basada en cultos religiosos tradicionales, rifas benéficas para la iglesia parroquial y música de charanga.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45093','fiesta','Fiestas en honor a San Bartolomé','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad de marcado carácter vecinal dinamizada por la emigración estival, caracterizada por la procesión, campeonatos de cartas y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45094','fiesta','Fiestas del Santísimo Cristo de la Gracia','Patronal y Etnográfica. Se celebra en Septiembre. Celebración tradicional con procesión litúrgica tradicional por el centro histórico, subasta de roscas de San Blas y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45096','fiesta','Fiestas de la Virgen del Sagrario y San Vicente Mártir','Patronal y Etnográfica. Se celebra en Agosto y Enero. Celebración con gran arraigo local; incluye la tradicional procesión de la patrona, concursos gastronómicos de gachas manchegas y un activo ambiente de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45097','fiesta','Fiestas del Santo Cristo de la Tabla','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Festejo comarcal talaverano con encierros de reses bravas por las calles, la tradicional subasta de banzos y comidas colectivas en la plaza de la Constitución.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45098','fiesta','Fiestas del Santísimo Cristo de la Salud','Patronal, Taurina y Ganadera. Se celebra en Agosto / Septiembre. Festejo de gran relevancia en los Montes de Toledo muy ligado al sector ganadero; destaca por sus multitudinarios encierros urbanos, ferias comerciales y desfiles de carrozas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45099','fiesta','Fiestas de Nuestra Señora de la Natividad (Fiesta de la Maya y los Sargentos)','Etnográfica, Enológica y Religiosa. Se celebra en Abril. Fiesta declarada de Interés Turístico Regional de extraordinario valor histórico. Destaca por la comitiva ritual de "Los Sargentos" y los bailes de los danzantes ante la Virgen, ligada a la cuna de su denominación de origen vinícola.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45100','fiesta','Fiestas en honor a San Bartolomé Apóstol','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad de carácter netamente familiar, basada en la procesión tradicional, juegos infantiles manchegos y veladas musicales al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45101','fiesta','Fiestas de la Virgen del Socorro (Fiesta de la Jota Pujada)','Etnográfica, Patronal y Folclórica. Se celebra en Septiembre. Hito etnográfico manchego de gran relevancia provincial; sobresale por la antiquísima tradición de la "Jota Pujada", donde los vecinos pujan dinero públicamente para poder bailar la jota tradicional en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45102','fiesta','Fiestas de la Virgen de la Angustias','Patronal, Taurina y Feria Comercial. Se celebra en Septiembre. Celebración masiva en La Sagra; famosa por sus encierros tradicionales de toros por el casco urbano, pasacalles monumentales de peñas y competiciones de tirada de reja.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45103','fiesta','Fiestas de la Virgen del Prado y San Sebastián','Patronal y Etnográfica. Se celebra en Agosto. Festejo de la comarca de la Jara adaptado al retorno estival con procesión mariana, tradicionales concursos gastronómicos de migas y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45104','fiesta','Feria del Vino de Montearagón','Enológica, Gastronómica y Feria Comercial. Se celebra en Septiembre. Festejo comarcal de gran interés agrario; aglutina catas multitudinarias, pisada tradicional de uva, apertura de bodegas y mercadillos artesanales de la comarca del Tajo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45105','fiesta','Fiestas de la Virgen de los Remedios','Patronal y Romería. Se celebra en Mayo y Octubre. Celebración local en la Sierra de San Vicente con romería a la ermita, cantos de mayos, fuegos artificiales y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45106','fiesta','Fiesta del Olivo de Mora','Gastronómica, Etnográfica y Feria Comercial. Se celebra en Abril. Fiesta declarada de Interés Turístico Regional de enorme calado nacional. Conmemora el final de la recogida de la aceituna con un fastuoso desfile de carros alegóricos y carrozas artesanales monumentales, catas de aceites vírgenes y festivales de folclore folclórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45107','fiesta','Fiestas del Santísimo Cristo de las Aguas','Patronal y Etnográfica. Se celebra en Junio. Celebración muy concurrida debido a su proximidad a la capital provincial; destaca por las procesiones litúrgicas solemnes, grandes verbenas de peñas y competiciones populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45109','fiesta','Fiestas de San Bartolomé Apóstol y la Fiesta del Milagro','Patronal, Romería y Etnográfica. Se celebra en Mayo (Milagro) y Agosto (Patrón). Hito festivo en los Montes de Toledo; destaca su multitudinaria Romería del Milagro a la ermita de la Milagra junto al municipio vecino de Hontanar, desfiles y encierros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45114','fiesta','Fiestas del Santo Cristo de la Misericordia','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Celebración serrana tradicional que conserva la subasta de banzos de la imagen, encierros de vaquillas en plaza fija y concursos gastronómicos de caldereta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45115','fiesta','Fiestas del Santísimo Cristo de las Injurias','Patronal, Enológica y Taurina. Se celebra en Mayo. Festejo de la Mesa de Ocaña muy ligado a su potente tradición cooperativista vinícola; incluye encierros tradicionales urbanos, catas de vino públicas y grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45116','fiesta','Fiestas del Santísimo Cristo de la Salud','Patronal y Etnográfica. Se celebra en Septiembre. Festividad manchega tradicional con solemne procesión a los pies del cerro de Noez, tracas pirotécnicas de gran estruendo y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45117','fiesta','Fiestas del Santo Cristo de la Navas y San Blas','Patronal y Etnográfica. Se celebra en Mayo y Febrero. Celebración alcarreña y serrana tradicional que conserva el adorno floral, bendición de rollos de San Blas y torneos tradicionales de caliche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45118','fiesta','Fiestas de San Miguel Arcángel y la Virgen de la Monjía','Patronal, Romería y Etnográfica. Se celebra en Mayo y Septiembre. Festejo tradicional con gran devoción mariana; destaca la traída en romería de la Virgen desde su ermita, pasacalles de gigantes y cabezudos y animadas verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45119','fiesta','Fiestas en honor a la Virgen de la Región','Patronal, Taurina y Feria Comercial. Se celebra en Septiembre. Festividad de La Sagra con gran arrastre; destaca por sus arraigados encierros urbanos de toros, concursos de peñas públicas y desfiles de carrozas monumentales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45120','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad de la Sierra de San Vicente en entorno de baja demografía, articulada en torno a comidas vecinales y música tradicional en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45121','fiesta','Semana Santa de Ocaña','Religiosa, Histórica y Etnográfica. Se celebra en Marzo / Abril (Semana Santa). Fiesta declarada de Interés Turístico Nacional. Destaca por la sobriedad castellana y el riguroso orden de sus procesiones barrocas, donde participan nazarenos con cadenas y calvarios históricos de gran valor artístico en su monumental Plaza Mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45122','fiesta','Fiestas de la Virgen del Rosario','Patronal, Taurina y Feria Comercial. Se celebra en Octubre. Celebración de la Sagra de gran afluencia por su vecindad con Toledo; resalta por sus encierros nocturnos, la pólvora pirotécnica de nivel y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45123','fiesta','Fiestas de la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Julio. Festejo de la Mesa de Ocaña lindando con Aranjuez; incluye pasacalles de la banda de música local, concursos de carrozas vecinales y eventos para las peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45124','fiesta','Fiesta de la Primavera y de la Primavera de Orgaz (Fiesta de la Doña Jimena)','Etnográfica, Recreación Histórica y Patronal. Se celebra en Mayo (Jimena) y Agosto (Cristo). Hito etnográfico provincial de enorme empaque. Sobresale en mayo la espectacular recreación histórica medieval en honor a Doña Jimena, con mercados tradicionales, desfiles con trajes de época castellanos y muestras de oficios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45125','fiesta','Jornadas Medievales de Oropesa','Recreación Histórica y Feria Comercial. Se celebra en Abril. Fiesta declarada de Interés Turístico Regional de masivo impacto nacional. La villa ducal se transforma por completo en un gran burgo medieval, destacando el famoso "Rescate de la Princesa" en el castillo, justas de caballeros, torneos y mercado artesanal gigantesco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45126','fiesta','Fiestas de la Virgen de la Almudena','Patronal y Etnográfica. Se celebra en Septiembre (traslado estival). Celebración local de carácter familiar en la comarca de Torrijos, caracterizada por la procesión litúrgica, subastas parroquiales y bailes en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45127','fiesta','Fiestas del Santo Cristo de la Veracruz','Patronal y Etnográfica. Se celebra en Mayo y Agosto. Celebración de arraigo tradicional con pasacalles de dulzaineros, procesión nocturna de antorchas y tradicionales degustaciones de migas y zurra manchego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45128','fiesta','Fiestas de la Virgen de la Natividad','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festejo muy conocido en La Sagra por su gran tradición cerámica y arcillera; destaca por sus arraigados encierros de toros por el campo y calles del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45129','fiesta','Fiestas de la Virgen de la Candelaria y San Vicente','Patronal y Etnográfica. Se celebra en Febrero y Agosto. Festejo tradicional al pie de su monumental picota gótica; incluye los tradicionales cultos religiosos, la puja de varas de las andas y verbenas veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45130','fiesta','Fiestas en honor a la Virgen de la Luz y San Sebastián','Patronal y Etnográfica. Se celebra en Agosto (festa estival). Celebración tradicional del Valle del Tiétar toledano que reúne a los emigrantes en torno a procesiones tradicionales, bailes folclóricos de la comarca y calderetas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45131','fiesta','Fiestas del Santo Cristo de la Esperanza','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festividad en la Sierra de San Vicente; sobresale por la bendición y subasta de banzos, sus tradicionales sueltas de vaquillas en recinto tradicional y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45132','fiesta','Fiestas de la Virgen de la Natividad','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festejo comarcal de gran tirón por su proximidad a Talavera de la Reina; incluye encierros urbanos tradicionales, pasacalles musicales con charangas y eventos de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45133','fiesta','Fiestas de San Pedro y de la Virgen de la Soledad','Patronal, Taurina y Etnográfica. Se celebra en Junio y Septiembre. *. Celebración de gran arraigo comarcal bajo las torres de su castillo medieval; destaca por sus concurridos encierros, competiciones de tiro de reja y conciertos masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45134','fiesta','Fiestas de los Santos Mártires (San Cosme y San Damián)','Patronal, Taurina y Feria Comercial. Se celebra en Septiembre. Festejo en la comarca de Torrijos de gran tradición; sobresale por la procesión solemne, los encierros urbanos tradicionales y el concurso de carrozas artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45135','fiesta','Fiestas del Santísimo Cristo de la Salud','Patronal, Enológica y Feria Comercial. Se celebra en Septiembre. Festejo masivo en la Mancha Alta conocido por su gran devoción al Cristo "Almoradiel"; incluye masivas procesiones con miles de oferentes, catas de vino y un gran real de feria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45136','fiesta','Festival de la Celestina y Fiestas del Cristo de la Caridad','Literaria, Recreación Histórica y Patronal. Se celebra en Julio (Cristo) y Agosto (Celestina). Fiesta declarada de Interés Turístico Regional de gran valor cultural. Todo el pueblo rinde homenaje a Fernando de Rojas transformando cuevas subterráneas reales en escenarios teatrales, con desfiles y un mercado renacentista de primer nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45137','fiesta','Fiestas de la Virgen de la Paz','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festejo de la vega del Tajuña y Tajo toledano con tradicionales sueltas de vaquillas, desfiles de carrozas elaboradas por vecinos y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45138','fiesta','Fiestas de San Juan Bautista y de la Virgen de la Bienvenida','Patronal, Artesanal y Etnográfica. Se celebra en Junio y Agosto. Hito festivo e identitario muy ligado a su famosa alfarería y cerámica declarada Patrimonio de la Humanidad; incluye ferias tradicionales artesanales, procesiones medievales sobre el puente histórico del Tajo y concursos de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45139','fiesta','Fiestas de San Bartolomé Apóstol','Patronal y Etnográfica. Se celebra en Agosto. Celebración en el límite extremeño de la comarca de la Jara, caracterizada por la procesión litúrgica tradicional, subastas benéficas y calderetas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45140','fiesta','Fiestas en honor a Santo Domingo de Guzmán','Patronal y Etnográfica. Se celebra en Agosto. Festejo de gran raigambre en la comarca de los Montes de Toledo; destaca por su tradicional procesión, los certámenes de carrozas elaboradas por las peñas y degustaciones populares de carne de caza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45141','fiesta','Fiestas de la Virgen de la Serna','Patronal, Etnográfica y Cervantina. Se celebra en Julio. Celebración manchega vinculada a su patrimonio de molinos de viento; incluye la solemne traída de la virgen desde su ermita, pasacalles de gigantes y cabezudos, y semanas culturales de inspiración quijotesca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45142','fiesta','Feria y Fiestas de Santiago Apóstol y la Semana Santa de Quintanar','Patronal, Religiosa y Feria Comercial. Se celebra en Marzo/Abril (Semana Santa) y Agosto (Feria). Su Semana Santa está declarada de Interés Turístico Regional por el rigor de sus cofradías y la procesión de los pasos. En agosto, su gran feria de muestras comerciales y conciertos atrae a miles de visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45143','fiesta','Fiestas en honor a San Roque','Patronal y Taurina. Se celebra en Agosto. Festividad local de la comarca de Torrijos marcada por la alta participación vecinal en sus tradicionales encierros urbanos de reses bravas y animadas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45144','fiesta','Fiestas de la Virgen de los Dolores y San Nicasio','Patronal y Etnográfica. Se celebra en Septiembre. Hito festivo de la Sierra de San Vicente; sobresale por la belleza de sus rondas tradicionales de guitarras y laúdes, y las comidas comunitarias a base de cordero serrano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45145','fiesta','Fiestas de Nuestra Señora de la Oliva','Patronal, Taurina y Romería. Se celebra en Septiembre. Festejo de la comarca de la Sagra de gran poder de convocatoria; destaca por su emotiva ofrenda floral, sus encierros tradicionales por el casco urbano y potentes espectáculos pirotécnicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45146','fiesta','Fiestas de la Virgen de la Difunta','Patronal y Etnográfica. Se celebra en Agosto. Celebración tradicional jameña marcada por el retorno estival; incluye la procesión litúrgica, campeonatos de juegos autóctonos de cartas y calderetas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45147','fiesta','Fiestas de Jesús Nazareno','Patronal y Etnográfica. Se celebra en Septiembre. Festejo tradicional cercano a la autovía A-40; cuenta con solemne procesión, competiciones de caliche y juegos populares manchegos junto a orquestas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45148','fiesta','Fiestas de la Virgen de la Inmaculada Concepción','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Pequeña celebración en los valles de los Montes de Toledo adaptada a las pedanías; incluye pasacalles de dulzaineros, misas tradicionales y cenas colectivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45149','fiesta','Fiesta de los Molinos de El Romeral','Etnográfica y Gastronómica. Se celebra en Abril. Celebración dedicada a ensalzar la arquitectura manchega; se realizan moliendas tradicionales en vivo en sus centenarios molinos, concursos de gachas y catas de aceite comarcales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45150','fiesta','Fiestas del Santo Niño y San Bartolomé Apóstol','Patronal y Etnográfica. Se celebra en Agosto. Festejo de la comarca de Talavera; incluye el tradicional baile de la bandera delante de la imagen del santo patrón, actividades infantiles y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45151','fiesta','Fiestas del Santísimo Cristo de la Luz y de la Salud','Patronal y Histórica. Se celebra en Agosto. Festejo vinculado al entorno del Castillo de Montalbán y la iglesia templaria de Melque; destaca por sus procesiones nocturnas de gran devoción y actividades culturales medievales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45152','fiesta','Fiestas en honor al Santísimo Cristo de la Valparaíso','Patronal y Taurina. Se celebra en Mayo. Celebración de la antigua judería y señorío de Pusa; resalta por sus tradicionales sueltas de novillos en la plaza mayor amurallada, subasta de banzos y pólvora pirotécnica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45153','fiesta','Fiesta de la Vaquilla (San Sebastián) y Fiestas del Cristo de la Agonía','Etnográfica y Patronal. Se celebra en Enero (Vaquilla) y Septiembre (Patronales). Su Fiesta de la Vaquilla en enero posee un incalculable valor etnográfico como rito de iniciación invernal, donde los mozos corren la vaquilla simulada. En septiembre destacan sus encierros camperos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45154','fiesta','Fiestas del canal y de la Virgen del Buen Suceso','Patronal y Etnográfica. Se celebra en Septiembre. Celebración en la comarca de la Sierra de San Vicente centrada en la tradición religiosa, la almoneda de objetos donados a la parroquia y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45155','fiesta','Fiestas del Cristo de la Salud','Patronal y Gastronómica. Se celebra en Septiembre. Festividad local marcada por la procesión solemne, los tradicionales concursos gastronómicos de carcamusas toledanas y animadas reuniones de peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45156','fiesta','Fiestas en honor a Nuestra Señora del Rosario','Patronal y Taurina. Se celebra en Agosto. Gran festividad en la Mesa de Ocaña; destaca por sus tradicionales festejos taurinos, masivo desfile de carrozas monumentales, conciertos en la plaza de la Constitución y certámenes folclóricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45157','fiesta','Fiestas del Santísimo Cristo del Amparo','Patronal, Taurina y Enológica. Se celebra en Agosto. Festejo de la Sagra Alta muy ligado a sus vinos con Denominación de Origen Méntrida; incluye encierros tradicionales de toros por las calles y grandes verbenas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45161','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal, Taurina y Feria Comercial. Se celebra en Agosto. Celebración de gran concurrencia urbana debido al crecimiento demográfico; sobresale por sus masivos encierros camperos y urbanos, desfiles de peñas y macro-conciertos nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45162','fiesta','Fiestas del Santo Cristo de la Esperanza','Patronal y Etnográfica. Se celebra en Agosto. Festejo de la Jara Alta de gran belleza natural; destaca por las rondas nocturnas tradicionales de cantos folclóricos de quintos y calderetas comunitarias de venado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45163','fiesta','Feria y Fiestas de la Virgen de los Remedios','Patronal, Taurina y Feria Industrial. Se celebra en Septiembre. Festejo de gran relevancia provincial ligado a su industria del mazapán y el mueble; cuenta con una potente feria taurina, desfiles de gigantes, espectáculos de pólvora y un gran real ferial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45164','fiesta','Fiestas de San Sebastián','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Micro-festividad de marcado carácter familiar en la comarca de Talavera, sustentada por una procesión tradicional, torneos de naipes y cenas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45165','fiesta','Fiesta de Las Mondas','Etnográfica, Histórica y Romería. Se celebra en Semana de Pascua (Abril). Fiesta declarada de Interés Turístico Nacional. Es una de las celebraciones vivas más antiguas de España de origen romano; destaca el espectacular desfile de carrozas históricas por la ciudad donde acuden alcaldes de toda la comarca portando ofrendas a la Virgen del Prado, acompañados por el carro tradicional tirado por carneros de Gamonal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45166','fiesta','Fiestas de Jesús Nazareno','*. Patronal, Taurina y Histórica. *. Se celebra en Agosto. *. Celebración de enorme empaque monumental. Sus festejos taurinos tradicionales se realizan utilizando como coso su famosísima Plaza Mayor barroca del siglo XVII con galerías de madera, ofreciendo una estampa histórica única.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45167','fiesta','Fiestas de San Antonio Abad y las Jornadas Cervantinas de El Toboso','Recreación Histórica, Literaria y Patronal. Se celebra en Abril (Cervantinas) y Agosto (Patronales). Sus Jornadas Cervantinas están declaradas de Interés Turístico Regional; la villa de Dulcinea se transforma en un gran teatro de calle del Siglo de Oro, atrayendo a miles de entusiastas de la literatura universal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45168','fiesta','Procesión del Corpus Christi de Toledo','Religiosa, Histórica y Etnográfica. Se celebra en Mayo / Junio (Corpus Christi). Fiesta de Interés Turístico Internacional de máxima relevancia global. Las calles medievales de la ciudad imperial se cubren de toldos antiguos, tapices finos del siglo XVII y plantas aromáticas para el paso de la Custodia de Arfe, en una comitiva litúrgica y militar de un valor histórico y estético inigualable.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45169','fiesta','Fiestas del Salvador','Patronal y Etnográfica. Se celebra en Agosto. Festividad local de la comarca de Campo de Arañuelo centrada en los actos litúrgicos, la subasta de banzos y concursos populares de trajes tradicionales bordados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45170','fiesta','Fiestas en honor a San Atanasio','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Celebración de la Jara toledana sustentada por los emigrantes locales; incluye procesión, tradicionales juegos populares de lanzamiento de reja y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45172','fiesta','Fiestas de Santa Ana','Patronal, Etnográfica y Vestimenta Tradicional. Se celebra en Julio. Festejo de gran valor folclórico; destaca por el desfile de mujeres e infantes luciendo los valiosos y centenarios trajes tradicionales ricos en ricos bordados torriqueños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45173','fiesta','Fiestas de la Sementera','Patronal, Taurina y Feria Comercial. Se celebra en Septiembre. Festejo de gran relevancia comarcal en su activo centro urbano; sobresale por su concurrida feria taurina con encierros urbanos, desfiles de comparsas y un gran recinto de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45174','fiesta','Fiestas de la Virgen de la Candelaria','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Celebración vecinal menor vinculada a su yacimiento arqueológico celtíbero; incluye procesión litúrgica, campeonatos de cartas tradicionales y música de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45175','fiesta','Fiestas del Santísimo Cristo del Consuelo','Patronal y Etnográfica. Se celebra en Septiembre. Festividad típicamente manchega con solemnes misas procesionales, tiradas de traca pirotécnica, concursos de arada y habilidad con tractor, y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45176','fiesta','Fiestas de San Juan Bautista y la Virgen del Rosario','Patronal, Taurina y Etnográfica. Se celebra en Junio y Septiembre. Celebración de la Sagra muy dinámica gracias a la juventud local; incluye sueltas de vaquillas en plaza portátil, pasacalles con charangas y concurridos concursos de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45177','fiesta','Feria y Fiestas del Santísimo Cristo de la Vera-Cruz de Urda','Religiosa, Romería y Feria Comercial. Se celebra en Septiembre. Hito religioso de nivel nacional. Es considerado un santuario de peregrinación masiva que atrae a decenas de miles de romeros de toda España para venerar la sagrada imagen del Cristo, con un gran mercado tradicional en las calles del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45179','fiesta','Fiestas de San Blas y el Carnaval de las Ánimas','Etnográfica y Patronal. Se celebra en Febrero (Carnaval) y Agosto (Patronales). Su Carnaval de las Ánimas posee un altísimo valor etnográfico provincial, donde los vecinos visten el traje de "ánimas" de pedrería y realizan el baile tradicional de la soldadesca en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45180','fiesta','Fiestas del Santo Domingo de Guzmán y la Fiesta del Milagro','Patronal, Taurina y Etnográfica. Se celebra en Mayo (Milagro) y Agosto (Patronales). Festejo de gran raigambre en la Sagra Alta; destaca por sus arraigados encierros camperos y urbanos, la tradicional procesión de bueyes pequeños de madera para los niños y animadas peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45181','fiesta','Fiestas de la Virgen de Gracia y Fiesta de la Sandia','Patronal y Gastronómica. Se celebra en Septiembre. Festejo tradicional célebre por su vinculación al cultivo tradicional de sandías de gran fama regional; incluye concursos de peso de frutas, encierros de vaquillas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45182','fiesta','Fiestas en honor a Nuestra Señora del Águila y San Fortunato','Patronal, Gastronómica y Romería. Se celebra en Mayo y Septiembre. Festejo de los Montes de Toledo famoso por su industria del cuero; destaca por la romería al cerro del Águila, bailes populares de jotas y degustaciones multitudinarias de venado en salsa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45183','fiesta','Fiestas de la Virgen del Carmen','Patronal y Taurina. Se celebra en Julio. Festividad local campiñera que incluye encierros tradicionales por el casco urbano, concursos gastronómicos de migas manchegas y un activo ambiente de peñas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45184','fiesta','Fiestas de San Julián','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Micro-festividad de carácter familiar en la comarca de Oropesa, vertebrada por la misa litúrgica, campeonatos de cartas tradicionales de guiote y veladas musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45186','fiesta','Feria y Fiestas del Santísimo Cristo del Consuelo','Patronal, Taurina y Histórica. Se celebra en Septiembre. Festejo manchego de gran tradición histórica ligado al Infante Don Fadrique; incluye las jornadas fadriqueñas con mercados medievales, solemnes procesiones y encierros taurinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45185','fiesta','Fiestas del Santísimo Cristo de la Viga','Etnográfica, Religiosa y Danza Ritual. Se celebra en Mayo. Fiesta declarada de Interés Turístico Regional. Posee un valor folclórico y etnográfico excepcional; los Danzantes del Cristo, vestidos con indumentarias tradicionales blancas, realizan complejas y veloces danzas de paloteo y torres humanas cumpliendo promesas seculares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45187','fiesta','Fiesta de las Ánimas (La Fiesta de los Mayordomos)','Etnográfica, Romería y Tradición Local. Se celebra en Febrero (Ánimas) y Septiembre (Romería). Su Fiesta de Ánimas está declarada de Interés Turístico Regional, destacando el volteo ritual de banderas monumentales en la plaza y los desfiles de capitanes de cofradías antiguas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45188','fiesta','Fiestas en honor a la Virgen de la Mercedes','Patronal y Taurina. Se celebra en Septiembre. Festejo de la Sagra famoso por su vinculación histórica a las industrias del cemento; sobresale por sus populosos encierros de reses bravas por las calles y grandes orquestas de música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45189','fiesta','Fiestas de San Sebastián','Patronal y Etnográfica. Se celebra en Agosto (traslado estival). Festividad de arraigo estrictamente local orientada al regreso estival de familias, caracterizada por la procesión del santo, rifas parroquiales y bailes en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45190','fiesta','Fiestas del Santo Niño de las Injurias','Patronal y Etnográfica. Se celebra en Septiembre. *. Celebración tradicional local centrada en la subasta de banzos de la imagen religiosa, tiradas de traca pirotécnica y meriendas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45191','fiesta','Fiestas del Santísimo Cristo de la Gran Poder','Patronal y Romería. Se celebra en Mayo. Celebración religiosa manchega con procesión a orillas del embalse de Castro, cantos de mayos tradicionales, juegos populares de madera y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45192','fiesta','Fiestas de la Virgen de la Piedad y Fiesta del Vino','Patronal, Enológica y Taurina. Se celebra en Noviembre. Festejo de gran tradición vinícola manchega; destaca por la espectacular procesión nocturna donde se queman cientos de miles de carretillas de pólvora pirotécnica, y catas masivas de vino.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45193','fiesta','Fiestas del Santo Niño de Bogas y Representación de La Pasión','Teatro Popular, Religiosa y Patronal. Se celebra en Semana Santa (Pasión) y Julio (Patronales). Destaca a nivel provincial por su cuidada representación teatral viviente de la Pasión de Cristo realizada por los propios vecinos en Semana Santa, atrayendo notable turismo comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45194','fiesta','Fiestas de Nuestra Señora de la Paz','Patronal y Etnográfica. Se celebra en Agosto. Micro-festividad de carácter estrictamente familiar en un entorno de baja demografía a orillas del río Cedena, vertebrada por cultos religiosos e invitaciones a zurra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45195','fiesta','Fiestas en honor a Nuestra Señora del Castellar','Patronal, Taurina y Romería. Se celebra en Septiembre. Gran festejo en la Mesa de Ocaña; destaca por la bajada de la Virgen desde el santuario del valle del Tajo, sus tradicionales encierros y comidas comunitarias de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45196','fiesta','Fiestas de Nuestra Señora de las Angustias y el Certamen "Alfarero de Oro"','Taurina, Patronal y Feria Comercial. Se celebra en Septiembre. Hito taurino de nivel nacional en la Sagra. Su certamen de novilladas "Alfarero de Oro" es un referente absoluto en España, acompañado por sus famosos y masivos encierros urbanos de toros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45197','fiesta','Fiestas de Santa María Magdalena','Patronal, Taurina y Etnográfica. Se celebra en Julio. Festejo tradicional manchego que cuenta con una arraigada procesión nocturna, suelta de vaquillas en su plaza de toros tradicional y concursos de gachas y migas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45198','fiesta','Fiestas de Nuestro Padre Jesús Nazareno','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festividad con notable arrastre en la comarca; sobresale por las solemnes procesiones del nazareno con subasta de banzos, encierros camperos tradicionales y ambiente de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45201','fiesta','Fiestas en honor a San Antonio de Padua','Patronal, Taurina y Feria Comercial. Se celebra en Junio. Festejo campiñero con notable afluencia por su cercanía a Madrid; incluye tradicionales encierros de toros por las calles de la villa, pasacalles de peñas y conciertos públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45205','fiesta','Fiestas en honor a la Virgen del Consuelo','Patronal, Taurina y Gastronómica. Se celebra en Septiembre. Festejo de gran relevancia en la Sagra; destaca por su famoso "Toro enmaromado" de Yuncos, encierros urbanos multitudinarios, desfiles de carrozas de peñas y macro-orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45200','fiesta','Feria y Fiestas de Nuestra Señora de la Finibusterre','Patronal, Taurina y Cinegética. Se celebra en Septiembre. Festejo de enorme empaque en los Montes de Toledo. Muy vinculado al patrimonio de la montería y la caza mayor; destaca por sus procesiones solemnes, corridas de toros de figuras nacionales y degustaciones populares de carnes de caza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90471','fiesta','Fiestas Patronales en honor a la Virgen del Rosario','Patronal. Se celebra en Octubre. Celebración de arraigo estrictamente local caracterizada por la misa solemne, la procesión de la patrona, verbenas populares nocturnas y actividades infantiles adaptadas a la baja demografía del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90472','fiesta','Fiesta del Emigrante y Feria de la Aceituna y el Vino','Gastronómica, Enológica y Patronal. Se celebra en Agosto. Festividad de reconocimiento comarcal vinculada a la rica tradición agrícola de la "Tierra de Barros", destacando las catas de vinos locales, degustaciones de aceitunas y actividades etnográficas de gran calado en la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90473','fiesta','Fiestas del Santísimo Cristo de la Sangre','Patronal y Religiosa. Se celebra en Septiembre. Festejos de fuerte identidad local marcados por la bajada y procesión de la venerada imagen del Cristo, subastas de ofrendas tradicionales y verbenas populares en la plaza del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90474','fiesta','Fiestas de la Virgen de los Milagros y San Bartolomé','Patronal y Romería. Se celebra en Agosto. Celebración con proyección comarcal y provincial debido al flujo de visitantes que acuden a su santuario y disfrutan del entorno del balneario romano, combinando devoción mariana con eventos náuticos en su embalse.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90837','fiesta','Recreación Histórica de la Batalla de La Albuera','Recreación Histórica y Etnográfica. Se celebra en Mayo. Fiesta de Interés Turístico Regional que conmemora los hechos de la Guerra de la Independencia de 1811 con un despliegue masivo de regimientos de época de varios países, desfiles militares, campamentos históricos y un alto rigor etnográfico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06001','fiesta','Festival Medieval de Alburquerque','Recreación Histórica y Etnográfica. Se celebra en Agosto. Fiesta de Interés Turístico Regional que transforma el barrio gótico-judío de "Villa Adentro" y las faldas del Castillo de Luna en un escenario medieval vivo con mercados, torneos de caballeros, teatro callejero y bodas de la época.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06002','fiesta','Fiesta de "Los Mayos" y Fiestas del Cristo de la Agonía','Etnográfica y Patronal. Se celebra en Mayo y Septiembre. Hito etnográfico de raigambre fronteriza donde destaca la vistosa tradición de "Los Mayos" con muñecos satíricos expuestos en las calles, complementada en septiembre con los ritos religiosos en torno a su castillo fortificado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90475','fiesta','Fiestas Patronales de San Pedro de Verona y la Virgen del Rosario','Patronal. Se celebra en Abril y Octubre. Celebración de arraigo estrictamente local con procesiones tradicionales, subastas de roscas de pan de San Blas y orquestas populares adaptadas a la demografía de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90476','fiesta','Fiestas del Rosario y San Andrés','Patronal. Se celebra en Octubre y Noviembre. Festividad local en el entorno del Parque Natural de Cornalvo que congrega a vecinos y emigrantes retornados en torno a misas solemnes y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06004','fiesta','Fiestas de la Piedad y Feria de la Vendimia','Enológica, Gastronómica y Patronal. Se celebra en Agosto. Fiesta de Interés Turístico Regional de gran empaque provincial que celebra la tradición vitivinícola de la capital de la Tierra de Barros, con el encendido de la fuente del vino, pisada de la uva y catas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90477','fiesta','Fiestas del Santísimo Cristo de la Salud','Patronal y Religiosa. Se celebra en Septiembre. Celebración de escala comarcal que destaca por la multitudinaria procesión y bajada del Cristo, el tradicional canto de coplas populares y encierros de vaquillas de gran arraigo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06005','fiesta','Feria de Agosto y Fiestas del Santísimo Cristo del Humilladero','Patronal, Feria y Etnográfica. Se celebra en Agosto y Septiembre. Hito festivo de la Campiña Sur con gran afluencia comarcal; sobresale su feria de ganado reconvertida, sus tradicionales capeas taurinas y el valor histórico de sus cofradías medievales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06006','fiesta','Carnaval de Badajoz y Feria de San Juan','Etnográfica, Feria y Taurina. Se celebra en Febrero/Marzo y Junio. Fiesta de Interés Turístico Internacional por su Carnaval, uno de los más masivos del mundo, famoso por su espectacular desfile de comparsas, artefactos y el ambiente callejero ininterrumpido.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90838','fiesta','Fiestas de la Virgen del Soterraño','Patronal y Taurina. Se celebra en Septiembre. Celebración de relevancia comarcal famosa por sus tradicionales encierros y festejos taurinos celebrados en su singular plaza de toros, ubicada dentro del recinto del castillo medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90478','fiesta','Fiestas de la Virgen del Fuego','Patronal y Religiosa. Se celebra en Agosto. Fiestas de marcado retorno estival adaptadas a la baja densidad del municipio, centradas en la procesión de la patrona y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90479','fiesta','Fiestas del Santísimo Cristo de la Buena Muerte','Patronal. Se celebra en Agosto. Festejos de carácter local que aprovechan la llegada de emigrantes para celebrar actos litúrgicos a los pies de su castillo y veladas musicales en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90480','fiesta','Feria de Agosto y Fiestas de San Isidro Labrador','Feria Local y Romería. Se celebra en Mayo y Agosto. Celebración con arraigo en la comarca de la Campiña Sur, destacando la romería en el paraje de Las Quinientas y los festivales flamencos durante la feria estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90481','fiesta','Fiestas de la Virgen de los Milagros','Patronal y Taurina. Se celebra en Septiembre. Festejos de fuerte tradición local y vinculación taurina debido a la dinastía de los "Bienvenida", combinando capeas populares con la devoción a su patrona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90482','fiesta','Fiestas de la Virgen de las Flores','Patronal y Romería. Se celebra en Septiembre. Fiesta tradicional de la comarca de Tentudía que destaca por la vistosa procesión de la Virgen, las subastas de ramos y dulces artesanales y las verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90483','fiesta','Feria de San Gregorio y Fiesta de la Enramá','Etnográfica y Feria Local. Se celebra en Mayo. Reconocimiento comarcal por la singularidad de "La Enramá", una antiquísima costumbre etnográfica de emparejamiento vecinal por sorteo, complementada con su feria bajo el castillo templario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06007','fiesta','Romería de Nuestra Señora de Belén','Romería y Religiosa. Se celebra en Septiembre. Hito etnográfico de gran relevancia en La Serena, celebrado en el Santuario de Belén con una multitudinaria jornada de convivencia campestre, caballos engalanados y subastas de ofrendas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90484','fiesta','Fiestas de la Santa Cruz','Etnográfica y Religiosa. Se celebra en Julio. Festividad singular en el sur de la provincia donde las calles se engalanan artísticamente con arcos de flores y hiedra, destacando sus tradicionales capeas taurinas de plaza porticada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06025','fiesta','Fiestas de San José','Patronal. Se celebra en Marzo. Celebración de arraigo local y cercanía con la capital autonómica, con desfiles de gigantes y cabezudos, orquestas musicales y muestras de artesanía local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06026','fiesta','Fiestas de la Virgen de Tentudía','Romería y Recreación Histórica. Se celebra en Septiembre. Hito histórico y religioso de la comarca que incluye la subida al Monasterio de Tentudía —punto más alto de la provincia— para rememorar la batalla medieval del rey Alfonso X el Sabio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06027','fiesta','Fiestas de la Virgen de la Encarnación','Patronal. Se celebra en Septiembre. Fiestas de arraigo local concentradas en torno a su joya parroquial del siglo XV, con actos religiosos tradicionales y espectáculos musicales nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06028','fiesta','Romería de la Virgen de Piedraescrita','Romería y Etnográfica. Se celebra en Abril (Lunes de Pascua). Fiesta de Interés Turístico Regional que congrega a miles de personas para contemplar el desfile de artísticas carrozas engalanadas con miles de flores de papel, caballistas vestidos con trajes regionales y folklore extremeño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06029','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Festejos estivales dirigidos al reencuentro vecinal con competiciones de juegos tradicionales, orquestas populares en el paseo y actividades para niños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06030','fiesta','Fiestas de San Sebastián','Patronal y Etnográfica. Se celebra en Enero. Pequeña festividad invernal que conserva el rito tradicional de las hogueras de San Sebastián, reparto de dulces típicos de la zona y procesión vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06031','fiesta','Fiestas del Día del Emigrante','Retorno Estival. Se celebra en Agosto. Celebración pensada para aglutinar a los antiguos vecinos que regresan en verano, ofreciendo verbenas en la plaza, campeonatos deportivos y calderetas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06033','fiesta','Fiestas de la Virgen de los Remedios','Patronal. Se celebra en Septiembre. Festividad local en las cercanías de las Vegas Altas, conocida por sus verbenas nocturnas, la subasta de brazos de la Virgen y degustaciones de repostería tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06034','fiesta','Festival de Teatro Clásico en el Teatro Romano de Regina','Recreación Histórica y Cultural. Se celebra en Julio/Agosto. Hito cultural y etnográfico de gran calado provincial que revive la antigua ciudad romana de Regina Turdulorum con representaciones escénicas y visitas guiadas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06035','fiesta','Fiestas de San Cristóbal y Los Ranchos','Gastronómica y Romería. Se celebra en Julio. Celebración popular en los accesos a la Cíjara, famosa por "Los Ranchos", donde peñas de vecinos cocinan calderetas y platos típicos en régimen de convivencia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06036','fiesta','Salón Ovino de Castuera y Feria de San Isidro','Gastronómica, Feria y Etnográfica. Se celebra en Septiembre y Mayo. Reconocimiento provincial y regional por su Salón Ovino, hito etnográfico y económico de La Serena donde se premian los mejores quesos de la D.O.P. Queso de la Serena y ganado autóctono.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06008','fiesta','Fiestas del Santísimo Cristo de la Paz','Patronal y Náutica. Se celebra en Septiembre. Festejos singulares por su ubicación fronteriza junto al Gran Lago de Alqueva, combinando los ritos religiosos locales con competiciones náuticas y playeras en su playa fluvial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06037','fiesta','Fiestas de la Virgen de los Dolores y Romería Internacional','Romería y Religiosa. Se celebra en Septiembre. Hito etnográfico de carácter transfronterizo en el Santuario de Chandavila, atrayendo a miles de peregrinos de España y Portugal debido a la mística de sus apariciones marianas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06038','fiesta','Fiestas de San Justo y San Pastor','Patronal. Se celebra en Agosto. Celebración de arraigo estrictamente local adaptada al verano para congregar a los emigrantes con orquestas, juegos de agua y eventos deportivos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06039','fiesta','Fiestas de San Bartolomé Apóstol','Patronal. Se celebra en Agosto. Festejos locales marcados por la procesión del santo, carreras de cintas a caballo y bailes populares en la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06040','fiesta','Fiestas de la Virgen del Carmen','Patronal. Se celebra en Julio. Celebración típicamente vecinal con triduos religiosos, pasacalles musicales, verbenas nocturnas y competiciones de juegos tradicionales de mesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06041','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Pequeñas fiestas patronales de ámbito estrictamente local que vertebran el verano del municipio a través de verbenas populares y campeonatos de fútbol sala.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06043','fiesta','Fiestas de la Virgen de los Dolores','Patronal. Se celebra en Septiembre. Celebración local junto al río Guadiana con procesiones tradicionales, subastas de exvotos y pequeños conciertos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06009','fiesta','Feria de Septiembre y Fiesta de la Velá (Virgen de las Cruces)','Patronal, Feria y Agrícola. Se celebra en Septiembre. Gran festividad comarcal y provincial en las Vegas Altas; destaca la romería urbana e hípica de "La Velá" hacia la ermita de las Cruces y una de las ferias comerciales más potentes de la región.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06045','fiesta','Fiestas de la Virgen de la Merced','Patronal. Se celebra en Septiembre. Pequeños festejos de arraigo local con pasacalles infantiles, misas solemnes y orquestas musicales de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06047','fiesta','Carnaval de Esparragosa de la Serena','Etnográfica y Carnaval. Se celebra en Febrero/Marzo. Hito etnográfico comarcal único por la antigüedad y conservación de sus cantos e ingeniosas coplas tradicionales de murga satírica, atrayendo a visitantes de toda La Serena.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06049','fiesta','Fiesta de la Santa Cruz de Feria','Etnográfica y Religiosa. Se celebra en Mayo. Fiesta de Interés Turístico Regional de espectacular belleza plástica; las mujeres del pueblo visten ropas barrocas hechas a mano y los vecinos decoran minuciosamente decenas de cruces con flores, encajes y altares efímeros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06051','fiesta','Fiesta de la Hispanidad y Feria de la Miel','Gastronómica y Etnográfica. Se celebra en Octubre / Febrero. Hito etnográfico de la Siberia Extremeña centrado en su estatus de gran productor apícola, con ferias de degustación de mieles puras, talleres de cera tradicional y folclore extremeño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06011','fiesta','Fiesta de la Chanfaina','Gastronómica y Etnográfica. Se celebra en Abril. Fiesta de Interés Turístico Regional que ensalza el plato pastoril por excelencia de la Baja Extremadura. Incluye un concurso de calderas de chanfaina, catas de vino locales y exhibiciones folclóricas de música extremeña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06054','fiesta','Fiestas del Santísimo Cristo de las Misericordias','Patronal y Religiosa. Se celebra en Septiembre. Festividad de gran peso comarcal por la masiva devoción a su Cristo, destacando la procesión de las antorchas, las tradicionales capeas en la plaza y los espectáculos de folclore folclórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06055','fiesta','Fiestas del Corpus Christi y San Onofre','Patronal y Religiosa. Se celebra en Junio. Hito etnográfico del sur de la provincia debido al espectacular alfombrado de flores y sal que cubre sus calles empinadas para el paso de la Custodia, sumado a las danzas tradicionales de los Danzantes de San Onofre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06056','fiesta','Fiestas de San Blas y la Virgen de la Aurora','Patronal y Etnográfica. Se celebra en Febrero y Agosto. Celebración serrana local donde sobrevive el canto tradicional de la aurora y el reparto de roscas bendecidas entre los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06057','fiesta','Fiestas de la Virgen de Nazaret','Patronal. Se celebra en Septiembre. Festejos de fuerte raigambre vecinal con capeas tradicionales de vaquillas, juegos de mesa tradicionales y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06059','fiesta','Feria de San Miguel y Fiesta de la Virgen de la Consolación','Feria Local y Patronal. Se celebra en Septiembre. Festejos con tirón en la campiña mudéjar extremeña, caracterizados por los desfiles hípicos, exposiciones agrícolas locales y verbenas de gran concurrencia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06012','fiesta','Ferias de Agosto y Fiesta de la Virgen de la Inmaculada','Feria Local y Patronal. Se celebra en Agosto. Reconocimiento comarcal destacado por sus conciertos de verano de primer nivel, ferias de atracciones infantiles de gran envergadura y competiciones deportivas regionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06061','fiesta','Feria de San Juan y Romería de la Virgen de la Antigua','Romería y Feria Local. Se celebra en Junio y Abril. Fuerte arraigo comarcal debido a su famosa romería del Lunes de Pascua a la ermita, donde se degusta el famoso queso "jabeño" artesanal y dulces de sartén.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06062','fiesta','Fiestas del Santísimo Cristo de la Almorrana','Patronal y Etnográfica. Se celebra en Septiembre. Celebración metida en plena reserva de la biosfera con la tradicional danza de los palos y los tiznaos ante la imagen del Cristo, un elemento etnográfico singular de la sierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06013','fiesta','Feria de Agosto y Fiestas de la Virgen de la Consolación','Feria, Taurina y Patronal. Se celebra en Agosto. Gran referente festivo de la Siberia Extremeña. Sus ferias destacan por los tradicionales festejos taurinos en su plaza de toros de piedra, sus encierros populares urbanos y el gran ambiente festivo en sus chiringuitos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06064','fiesta','Fiestas del Ramo y de la Virgen de la Preciosa Sangre','Etnográfica y Patronal. Se celebra en Agosto. Festividad local que destaca por la subasta tradicional del "Ramo", una estructura engalanada con roscas de pan y dulces típicos locales para sufragar los gastos de la hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06065','fiesta','Fiestas de la Virgen de la Aurora','Patronal. Se celebra en Septiembre. Pequeña celebración típicamente vecinal marcada por la procesión litúrgica, orquestas musicales de fin de semana y competiciones deportivas de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06066','fiesta','Fiestas del Señor de la Humildad','Patronal y Taurina. Se celebra en Septiembre. Festejos locales que combinan la fe hacia su patrón con la suelta de vaquillas por las calles del casco antiguo y la degustación de embutidos ibéricos de la dehesa local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06067','fiesta','Fiestas del Cristo de la Humildad y Virgen de Loreto','Patronal, Religiosa y Gastronómica. Se celebra en Septiembre. Celebración con arraigo comarcal debido a su cercanía a la frontera andaluza, aunando procesiones solemnes multitudinarias con ferias comerciales dedicadas al sector del cerdo ibérico de bellota.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06068','fiesta','Fiestas Patronales de la Virgen de los Dolores','Patronal. Se celebra en Septiembre. Festejos de fuerte arraigo vecinal marcados por los actos religiosos tradicionales, subastas de ofrendas locales y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06069','fiesta','Fiestas de San Blas y Feria de Agosto','Etnográfica y Feria Local. Se celebra en Febrero y Agosto. Celebración con gran calado comarcal por sus raíces moriscas, destacando las tradicionales candelas y hogueras de San Blas y las verbenas estivales en la falda de la sierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06014','fiesta','Semana Santa de Jerez de los Caballeros y Salón del Jamón Ibérico','Religiosa, Gastronómica y Etnográfica. Se celebra en Marzo/Abril y Mayo. Fiesta de Interés Turístico Nacional por su Semana Santa de gran valor monumental y silencio templario, sumada al Salón del Jamón que atrae a miles de visitantes de todo el país.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06071','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Celebración estrictamente local de carácter veraniego, estructurada en torno a comidas de convivencia vecinal, juegos tradicionales y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06073','fiesta','Fiestas de Nuestra Señora de la Candelaria','Patronal y Etnográfica. Se celebra en Febrero. Pequeña festividad invernal que conserva el rito etnográfico de la bendición de las tradicionales roscas de pan de la Candelaria y la quema de hogueras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06015','fiesta','Fiestas Patronales de Nuestra Señora de la Granada y Feria de San Miguel','Patronal, Feria y Monumental. Se celebra en Agosto y Septiembre. Hito festivo de la Campiña Sur con gran afluencia provincial, caracterizado por sus tradicionales capeas taurinas en la bellísima Plaza Mayor porticada de estilo mudéjar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06072','fiesta','Fiestas de San Agustín y la Virgen de la Asunción','Patronal. Se celebra en Agosto. Festejos de escala local y comarcal que aprovechan su ubicación como balcón del Guadiana, destacando sus competiciones deportivas y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06075','fiesta','Fiestas de Los Silaos y de San Rosendo','Etnográfica e Histórica. Se celebra en Agosto. Festividad local en un entorno monumental único, destacando la subida nocturna a su castillo medieval, orquestas populares y la conservación de leyendas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06076','fiesta','Fiestas de Santa Abundancia','Patronal y Agrícola. Se celebra en Agosto. Celebración adaptada al retorno estival con una singular advocación patronal vinculada a las cosechas, misas extremeñas y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06077','fiesta','Fiestas de San Antonio de Padua','Patronal. Se celebra en Junio. Fiestas tradicionales de arraigo estrictamente vecinal, caracterizadas por la procesión del santo y pequeñas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06078','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Festejos tradicionales de verano con catas de vino locales artesunales de pitarra y juegos populares infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06079','fiesta','Fiestas de la Virgen de la Natividad','Patronal. Se celebra en Septiembre. Festejos locales de baja demografía centrados en los actos religiosos tradicionales de la hermandad y bailes de sociedad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06080','fiesta','Fiestas de San Jerónimo y la Virgen del Castillo','Recreación Histórica y Patronal. Se celebra en Septiembre. Gran relevancia histórica y patrimonial; las fiestas se enmarcan entre su teatro romano y el castillo medieval, atrayendo turismo comarcal y provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06081','fiesta','Fiestas del Santísimo Cristo del Humilladero','Patronal y Taurina. Se celebra en Septiembre. Festejos tradicionales que cuentan con encierros populares de vaquillas de gran tradición en la comarca de Zafra-Río Bodión.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06082','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio. Pequeña celebración patronal de carácter eminentemente local con pasacalles, triduos religiosos y música en directo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06018','fiesta','Festival Internacional de Teatro Clásico de Mérida y Feria de Septiembre','Cultural, Histórica y Feria. Se celebra en Julio/Agosto y Septiembre. Hito masivo de nivel internacional; su Festival de Teatro Clásico revive los monumentos de la antigua Augusta Emerita y atrae a miles de espectadores globales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06084','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Festejos estivales tradicionales basados en la procesión del santo con subasta de roscas, campeonatos de fútbol y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06016','fiesta','Día del Jamón de Monesterio','Gastronómica y Etnográfica. Se celebra en Septiembre. Fiesta de Interés Turístico Regional que congrega en las dehesas del sur de Badajoz a miles de personas para disfrutar de degustaciones populares de jamón ibérico de bellota y concursos nacionales de cortadores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06086','fiesta','Fiestas de la Virgen de la Granada','Patronal e Histórica. Se celebra en Agosto. Celebración tradicional que dinamiza el municipio a la sombra de su alcazaba árabe, con un mercadillo medieval asociado y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06087','fiesta','Feria de San Isidro Labrador y Fiesta de la Aceituna','Gastronómica y Romería. Se celebra en Mayo y Agosto. Celebración de escala comarcal dedicada al Aceite de Oliva con D.O.P. Monterrubio, con catas, maquinaria agrícola y folclore extremeño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06017','fiesta','Fiestas de San Pedro de Alcántara','Patronal y Feria Local. Se celebra en Septiembre. Gran feria y fiestas patronales en las Vegas Bajas, destacando sus conciertos de pop/rock nacional, grandes atracciones feriales y corridas de toros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06089','fiesta','Fiestas de San Lorenzo','Patronal. Se celebra en Agosto. Pequeñas fiestas patronales veraniegas de arraigo vecinal, con competiciones de juegos populares de mesa y verbenas musicales nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06090','fiesta','Fiestas del Santísimo Cristo de la Misericordia','Patronal. Se celebra en Septiembre. Festejos locales marcados por las misas solemnes, triduos de la cofradía y pequeñas orquestas en la plaza principal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06091','fiesta','La Encamisá (Fiesta de San Antón)','Etnográfica, Ecuestre y Religiosa. Se celebra en Enero. Fiesta de Interés Turístico Regional de enorme espectacularidad. Cientos de jinetes con caballos engalanados con mantas de madroños recorren las calles entre hogueras al grito de ¡Viva San Antón!, repartiendo vino y biñuelos artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06092','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Festejos locales estivales con procesiones tradicionales alrededor de su castillo medieval y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06093','fiesta','Pasión Viviente de Oliva de la Frontera','Recreación Histórica y Religiosa. Se celebra en Marzo/Abril (Semana Santa). Fiesta de Interés Turístico Regional donde los vecinos transforman las calles y el santuario en la antigua Jerusalén, escenificando con gran dramatismo y rigor histórico los últimos días de Cristo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06094','fiesta','Fiestas de San Isidro y de la Virgen del Campo','Romería y Patronal. Se celebra en Mayo y Agosto. Festejos locales marcados por una concurrida romería campera comarcal y actividades lúdicas durante el mes estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06019','fiesta','Feria del Toro de Olivenza','Taurina, Feria y Etnográfica. Se celebra en Marzo. Fiesta de Interés Turístico Nacional que abre la temporada taurina en España, atrayendo a miles de aficionados nacionales e internacionales gracias a la fusión de la cultura española y portuguesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06097','fiesta','Fiestas de San Bartolomé y la Fiesta del Agua','Náutica, Veraniega y Patronal. Se celebra en Agosto. Gran afluencia comarcal y provincial gracias a su playa de interior con Bandera Azul, combinando procesiones tradicionales con festivales náuticos estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06096','fiesta','Fiestas del Santísimo Cristo de la Salud','Patronal. Se celebra en Mayo. Celebración estrictamente local con misa solemne, subasta tradicional de ramos y música popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06098','fiesta','Fiestas de Nuestra Señora de Loreto','Patronal. Se celebra en Septiembre. Festejos locales de carácter tradicional con verbenas populares nocturnas y actividades recreativas infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06099','fiesta','Feria de San Juan y Fiesta del Emigrante','Feria Local y Retorno Estival. Se celebra en Junio y Agosto. Festejos tradicionales de verano con bailes populares en su plaza porticada y degustación de vinos de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06100','fiesta','Octava del Corpus de Peñalsordo','Etnográfica, Histórica y Religiosa. Se celebra en Junio. Fiesta de Interés Turístico Regional de espectacular valor etnográfico que conmemora la conquista cristiana del castillo árabe con una soldadesca montada sobre burros y una curiosa mojiganga.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06101','fiesta','Fiestas de la Virgen de los Remedios','Patronal. Se celebra en Agosto. Festejos estivales para el reencuentro de emigrantes con comidas populares y orquestas de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06102','fiesta','Fiestas de la Virgen del Carmen','Patronal e Histórica. Se celebra en Agosto. Festejos tradicionales que destacan por el marco del imponente castillo de la cantera y actividades culturales comarcales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06103','fiesta','Fiestas de San Pedro y Festival de Teatro Vegas Bajas','Cultural y Patronal. Se celebra en Junio y Octubre. Reconocimiento comarcal destacado por su certamen de teatro nacional de larga trayectoria y sus potentes ferias patronales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06104','fiesta','Fiestas de Santa Olalla','Patronal. Se celebra en Agosto. Celebración vecinal con tradicionales verbenas de verano y juegos de mesa infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06107','fiesta','Fiestas de San Isidro Labrador','Romería y Feria Local. Se celebra en Mayo. Festejos de fuerte arraigo serrano local con carrozas artesanales y jinetes que recorren el entorno de la Sierra de San Pedro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06108','fiesta','Fiestas de la Virgen de la Belén','Romería y Taurina. Se celebra en Abril (Lunes de Cuasimodo). Destaca su romería en la ermita de Belén, que cuenta con una antiquísima e histórica plaza de toros rectangular donde se celebran capeas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06109','fiesta','Feria de Agosto y Fiesta de la Velada','Feria Local y Etnográfica. Se celebra en Agosto. Relevancia comarcal por la tradicional "Velada" del granito y ferias comerciales muy concurridas en la comarca de La Serena.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06113','fiesta','Fiestas del Santísimo Cristo de la Misericordia','Patronal y Religiosa. Se celebra en Septiembre. Festejos tradicionales de la comarca de Tierra de Barros con vistosas procesiones y degustación de vinos de la tierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06114','fiesta','Fiestas de San Blas','Patronal y Etnográfica. Se celebra en Febrero. Pequeña fiesta invernal serrana caracterizada por el reparto de los tradicionales cordones de San Blas bendecidos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06115','fiesta','Fiestas de San Isidro Labrador','Romería. Se celebra en Mayo. Romería local tradicional con jornadas de campo, carrozas de papel y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06116','fiesta','Feria Ibérica del Cerco de la Bellota','Gastronómica y Etnográfica. Se celebra en Diciembre. Hito comarcal y provincial centrado en la puesta en valor de sus dehesas comunales, con muestras gastronómicas de ibéricos de máxima calidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06117','fiesta','Feria de la Alfarería y del Barro','Etnográfica y Artesanal. Se celebra en Mayo. Gran proyección provincial por ser uno de los focos de alfarería tradicional más importantes de España, exhibiendo técnicas ancestrales del barro rojo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06119','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio. Festejos tradicionales locales con pasacalles infantiles, torneos de fútbol sala y verbenas de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06123','fiesta','Fiesta del Corpus Christi de San Vicente de Alcántara','Etnográfica y Religiosa. Se celebra en Junio. Fiesta de Interés Turístico Regional famosa por sus espectaculares y kilométricas alfombras florales de serrín teñido, corcho y romero que cubren por completo las calles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06118','fiesta','Fiestas del Espíritu Santo','Patronal. Se celebra en Mayo/Junio. Festejos de arraigo estrictamente local adaptados a su entorno rural con procesiones y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06120','fiesta','Feria de Agosto','Feria Local y Agrícola. Se celebra en Agosto. Feria estival en el entorno de las Vegas Altas con potentes muestras agrícolas, orquestas comerciales y actividades juveniles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90839','fiesta','Fiestas de Santa Marta e Feria de las Flores','Patronal. Se celebra en Julio. Festejos con tirón comarcal, destacando las tradicionales capeas de vaquillas y el engalanamiento efímero de algunas placetas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06122','fiesta','Fiesta de la Vendimia y Semana de la Extremadura de la Escuela','Enológica, Gastronómica y Etnográfica. Se celebra en Agosto. Reconocimiento provincial por la pisada de la uva de los primeros mostos de Tierra de Barros y actos etnográficos de gran relieve escolar y cultural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06124','fiesta','Fiestas del Santísimo Cristo de la Reja (Las Capeas)','Etnográfica, Taurina y Patronal. Se celebra en Septiembre. Fiesta de Interés Turístico Regional de gran raigambre popular; su Plaza Mayor Monumental se cierra con tradicionales tablados de madera para acoger capeas ancestrales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06125','fiesta','Feria de Agosto y Fiestas de la Virgen de Altagracia','Feria Local y Patronal. Se celebra en Agosto. Gran tradición ganadera mesteña reflejada en sus ferias estivales de la Siberia Extremeña, con bailes tradicionales y espectáculos folclóricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06126','fiesta','Fiestas de Santa María Magdalena','Patronal. Se celebra en Julio. Festejos tradicionales de arraigo agrícola con actividades ligadas a la cultura del vino de Tierra de Barros y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06127','fiesta','Fiestas de la Virgen de la Coronada','Patronal y Taurina. Se celebra en Agosto. Relevancia comarcal en la Siberia por sus populares festejos taurinos de vaquillas, triduos solemnes cantados y verbenas multitudinarias en el paseo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06128','fiesta','Fiestas de la Virgen de Gracia y San José','Patronal y Feria Local. Se celebra en Septiembre. Festejos comarcales con gran presencia de peñas juveniles, orquestas musicales de primer nivel y eventos tradicionales ecuestres.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06020','fiesta','Fiestas de la Virgen de los Santos','Patronal. Se celebra en Noviembre. Festejos de fuerte tradición local de raigambre luso-extremeña, caracterizados por comidas comunitarias y actos devocionales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06130','fiesta','Fiestas de la Virgen de la Encinilla','Patronal. Se celebra en Agosto. Pequeñas fiestas estivales pensadas para el reencuentro de familias y emigrantes con verbenas al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06131','fiesta','Festival "La Enconchada" y Fiesta de la Purísima','Cultural y Patronal. Se celebra en Agosto y Diciembre. Festejos locales que ponen en valor su patrimonio histórico industrial molinero con música tradicional y actividades lúdicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06132','fiesta','Fiestas de San Blas y del Rosario','Patronal y Etnográfica. Se celebra en Febrero y Octubre. Celebración local tradicional basada en la entrega de las roscas del santo protector de la garganta y pequeñas verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06133','fiesta','Fiestas de la Virgen de la Piedad','Patronal. Se celebra en Agosto. Festejos locales vinculados al paso de la Vía de la Plata con carreras de cintas tradicionales a caballo y orquestas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06134','fiesta','Fiestas de San Martín de Tours','Patronal. Se celebra en Noviembre. Pequeña festividad otoñal típicamente rural enfocada en actos religiosos y migas populares para los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06135','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre. Festejos locales por su cercanía al Parque Natural de Cornalvo, con verbenas nocturnas tradicionales de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06136','fiesta','Fiestas del Santísimo Cristo de la Piedad','Patronal y Taurina. Se celebra en Septiembre. Festejos tradicionales de raigambre comarcal que cuentan con tradicionales capeas de vaquillas de gran seguimiento local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06137','fiesta','Fiestas Patronales de San Miguel Arcángel','Patronal y Romería. Se celebra en Septiembre. Celebración de la comarca de La Siberia con su tradicional encierro de vaquillas, capeas populares, tiradas al plato y la concurrida procesión del santo por las calles de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06901','fiesta','Fiesta de "Valdelacalzada en Flor" y Fiestas de San Isidro','Etnográfica, Agrícola y Romería. Se celebra en Marzo y Mayo. Hito etnográfico de relevancia provincial que celebra la floración de los frutales de regadío en las Vegas Bajas con rutas senderistas, certámenes fotográficos y degustaciones culinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06138','fiesta','Fiestas de San Juan Bautista y la Virgen del Rosario','Patronal. Se celebra en Junio y Octubre. Festejos de carácter estrictamente local organizados en torno a la hoguera tradicional de San Juan, misas solemnes, campeonatos de fútbol sala y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06139','fiesta','Fiestas de la Virgen de la Asunción y San Jacinto','Patronal y Retorno Estival. Se celebra en Agosto. Celebración de marcado carácter familiar diseñada para acoger a los emigrantes retornados, dinamizada con orquestas de baile en la plaza del pueblo y competiciones deportivas infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06140','fiesta','Fiestas Patronales de la Virgen de las Flores','Patronal y Transfronteriza. Se celebra en Septiembre. Festejos en la raya con Portugal que congregan a vecinos de ambos lados de la frontera para presenciar los actos litúrgicos, capeas tradicionales de vaquillas y bailes nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06141','fiesta','Feria del Garbanzo y Fiestas de la Virgen del Valle','Gastronómica, Etnográfica y Patronal. Se celebra en Agosto y Septiembre. Reconocimiento comarcal y provincial por su consolidada feria gastronómica en torno al garbanzo local, cocinado en calderetas populares dentro de los muros de su histórico castillo-palacio templario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06146','fiesta','Fiestas de la Virgen de la Salud','Patronal y Etnográfica. Se celebra en Agosto. Festejos veraniegos de gran tradición en la comarca de La Serena, destacando la subasta de exvotos y brazos de la virgen, campeonatos de juegos tradicionales de mesa y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06147','fiesta','Fiestas del Santísimo Cristo de la Salud','Patronal. Se celebra en Septiembre. Pequeñas fiestas serranas de carácter estrictamente vecinal, caracterizadas por las procesiones devocionales, pasacalles musicales, comidas de convivencia y música de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06148','fiesta','Fiestas Patronales de Santa Ana y la Virgen de la Salud','Patronal. Se celebra en Julio y Septiembre. Celebración puramente local y vecinal con procesión tradicional de la santa, juegos infantiles tradicionales en el paseo de la localidad y verbenas musicales de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06142','fiesta','Fiestas del Señor de la Humildad','Patronal. Se celebra en Septiembre. Festividad local íntima adaptada a la baja densidad del municipio, centrada en los ritos litúrgicos, pequeños conciertos al aire libre y juegos recreativos para los niños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06143','fiesta','Fiesta de "La Fuga de la Diabla"','Etnográfica y Recreación Histórica. Se celebra en Agosto. Gran hito etnográfico de la provincia; el pueblo apaga sus luces y se transforma en un escenario místico donde se recrea la liberación de la Diabla y su posterior captura, con la participación masiva de los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06144','fiesta','Fiestas de la Virgen del Rosario','Patronal y Retorno Estival. Se celebra en Agosto. Festejos populares enfocados en el reencuentro de familias que emigraron, con torneos de cartas, comidas populares comunitarias y verbenas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06145','fiesta','Fiestas de Santa Ana','Patronal. Se celebra en Julio. Festejos veraniegos de arraigo puramente local en las vegas del Guadiana, complementados con orquestas de baile nocturnas, actividades lúdicas infantiles y competiciones deportivas de fútbol sala.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06149','fiesta','Fiesta de la Vendimia y Tradicional Velada de la Virgen de la Coronada','Enológica, Gastronómica y Patronal. Se celebra en Septiembre. Fiesta de Interés Turístico Regional de gran empaque comercial y vitivinícola; destaca por la pisada de la uva, la obtención del primer mosto, la vistosa procesión de la virgen y su potente feria industrial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06150','fiesta','Feria de San Juan y Fiestas de la Virgen del Rosario','Feria Local y Patronal. Se celebra en Junio y Octubre. Festejos locales que ganan vistosidad gracias a las actividades culturales organizadas en el entorno de su castillo medieval, sumado a capeas de vaquillas y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06151','fiesta','Fiestas del Santísimo Cristo de la Almorrana','Patronal y Religiosa. Se celebra en Mayo. Celebración local de fuerte devoción religiosa mariana y cristológica, caracterizada por la procesión del cristo, triduos solemnes, orquestas musicales y concursos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06152','fiesta','Fiestas de la Virgen de Montevirgen','Patronal y Romería. Se celebra en Septiembre. Festejos de gran arraigo en la comarca vinícola de Tierra de Barros, con peregrinación a la ermita de la patrona, degustaciones de caldos locales y encierros taurinos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06022','fiesta','Fiestas de Santiago Apóstol y la "Carrerita" del Domingo de Resurrección','Patronal, Feria y Etnográfica. Se celebra en Julio y Abril. Fiesta de Interés Turístico Regional por la espectacular "Carrerita" de la mañana de Pascua, donde los portadores corren a gran velocidad con la Virgen para encontrarse con Cristo Resucitado ante miles de personas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06154','fiesta','Feria Transfronteriza de los Gurumelos y Fiestas de San Ginés de Arlés','Gastronómica, Etnográfica y Patronal. Se celebra en Marzo y Agosto. Hito gastronómico comarcal y provincial de gran relevancia dedicado a la exaltación del gurumelo, hongo silvestre autóctono de la dehesa, con jornadas micológicas, catas y mercados artesanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06156','fiesta','Fiestas de los Santos Mártires San Fabián y San Sebastián','Patronal. Se celebra en Enero y Agosto (Fiesta del Emigrante). Pequeñas fiestas locales complementadas en verano con verbenas y calderetas para congregar a las familias que regresan por vacaciones al entorno rural del término municipal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06155','fiesta','Fiestas de la Virgen del Rosario','Patronal y Taurina. Se celebra en Octubre. Festejos que combinan la arraigada devoción a su patrona con tradicionales encierros urbanos de vaquillas, suelta de reses en plaza portátil y animadas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06157','fiesta','Fiestas de la Virgen de la Antigua','Patronal y Etnográfica. Se celebra en Agosto. Celebración en los confines orientales de La Siberia donde destaca la tradicional "Alborada", un canto de antiquísima raíz folclórica interpretado por los vecinos durante la madrugada festiva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06023','fiesta','Feria Internacional Ganadera y Tradicional de San Miguel','Feria, Agrícola, Ganadera y Etnográfica. Se celebra en Octubre. *. Fiesta de Interés Turístico Nacional de dimensiones colosales; es el certamen ganadero y comercial más importante de la península ibérica, atrayendo a cientos de miles de visitantes de todo el país y el extranjero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06024','fiesta','Fiestas de la Virgen de la Altagracia','Patronal. Se celebra en Agosto. Festejos de fuerte tradición local basados en la procesión de la patrona, tradicionales encierros de vaquillas por las calles de la villa y orquestas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06160','fiesta','Representación Popular de "El Alcalde de Zalamea"','Recreación Histórica y Cultural. Se celebra en Agosto. Fiesta de Interés Turístico Regional donde centenares de vecinos escenifican la inmortal obra de Calderón de la Barca en espacios históricos de la villa, completada con un gran mercado medieval de época.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06162','fiesta','Fiestas de la Virgen de las Nieves','Patronal. Se celebra en Agosto. Festejos de relevancia comarcal debido al gran ambiente de sus tradicionales capeas y encierros de reses bravas, complementados con torneos deportivos, folclore y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06161','fiesta','Fiestas de San Bartolomé Apóstol y la Virgen de la Aurora','Patronal. Se celebra en Agosto. Celebración típicamente vecinal adaptada al retorno estival, centrada en la misa y procesión de los santos patronos, verbenas nocturnas al aire libre y juegos de mesa tradicionales). Hemos finalizado por completo la Provincia de Badajoz. Siguiendo el orden jerárquico establecido por el proyecto para la Comunidad de Extremadura, corresponde avanzar al siguiente bloque territorial. ¿Deseas que comencemos de inmediato con la Provincia de Cáceres, iniciando por la letra A (Abadía, Albertía, Albalá, Alcañiz, Alcantara, Almoharín, etc.)?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90086','fiesta','Fiestas Patronales de Santo Domingo de Guzmán','Patronal. Se celebra en Agosto. Festejos de fuerte arraigo vecinal y retorno estival en el Valle del Ambroz, caracterizados por campeonatos de juegos tradicionales, procesión de la imagen del santo y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90092','fiesta','Fiesta de las Tablas y San Joaquín','Etnográfica y Patronal. Se celebra en Agosto. Festividad de reconocimiento comarcal centrada en la "Fiesta de las Tablas", un hito etnográfico singular donde los jóvenes procesionan vistosas tablas engalanadas con roscas de pan, dulces artesanales y embutidos de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06003','fiesta','Festival Internacional de Teatro Clásico de Alcántara','Cultural y Recreación Histórica. Se celebra en Agosto. Fiesta de Interés Turístico Regional que transforma el imponente marco del Conventual de San Benito y los alrededores de su icónico puente romano en un escenario de artes escénicas de primer nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90093','fiesta','Fiestas de Santa Catalina de Alejandría','Patronal. Se celebra en Noviembre. Pequeña celebración de carácter estrictamente local adaptada a la baja demografía invernal del municipio, enfocada en los oficios religiosos tradicionales y bailes populares en el hogar del pensionista.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90094','fiesta','Fiesta de "La Chaquetía" y la Cruz de Mayo','Etnográfica y Gastronómica. Se celebra en Noviembre y Mayo. Celebración de raigambre comarcal que preserva el rito etnográfico de recolectar castañas, higos y frutos de otoño en la dehesa, combinada con la vistosa decoración de cruces florales en primavera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90095','fiesta','Fiesta del Tuero y Fiestas de la Virgen de los Remedios','Etnográfica y Patronal. Se celebra en Agosto. Festejo tradicional marcado por "El Tuero", una costumbre de origen pastoril donde los quintos del pueblo recolectan y queman un tronco de grandes dimensiones, acompañado de verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90840','fiesta','Fiestas Patronales de la Virgen del Sopo','Patronal y Romería. Se celebra en Septiembre. Celebración de arraigo local centrada en la bajada de la virgen desde su ermita, subastas tradicionales de exvotos del campo y bailes populares nocturnos en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90841','fiesta','Fiesta del Cristo del Sepulcro y Los Tableros','Etnográfica y Religiosa. Se celebra en Septiembre. Hito etnográfico de la comarca de La Vera donde destaca el desfile de las "tableras" ataviadas con vistosos trajes regionales polícromos, portando ricas ofrendas de pan bendecido ante la imagen patronal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90096','fiesta','Fiestas del Cristo de la Agonía','Patronal. Se celebra en Septiembre. Festejos populares que unen los dos barrios históricos separados por la antigua Vía de la Plata, dinamizados con charangas, suelta de vaquillas y conciertos populares al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90097','fiesta','Fiestas Patronales de San Blas','Patronal. Se celebra en Febrero. Pequeña festividad invernal de ámbito doméstico y vecinal, fundamentada en la bendición de los tradicionales cordones de San Blas para proteger la garganta y una posterior comida comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90098','fiesta','Fiestas de la Virgen de la Consolación','Patronal y Taurina. Se celebra en Agosto. Celebración con fuerte arraigo en el Geoparque Villuercas-Ibores-Jara, famosa por sus encierros tradicionales al estilo de la sierra y la concurrida procesión de su patrona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90099','fiesta','Romería de la Virgen del Campo','Romería y Etnográfica. Se celebra en Abril (Martes de Pascua). Festividad comarcal de la Sierra de San Pedro que destaca por su tradicional peregrinación campestre hacia el santuario y los cantos de coplas populares extremeñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90101','fiesta','Feria del Higo y Fiestas de la Virgen de la Sopetrán','Gastronómica y Patronal. Se celebra en Septiembre. Reconocimiento provincial por su feria agroalimentaria dedicada a la exaltación del higo calabacita, combinada con jornadas técnicas gastronómicas, catas y folclore regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10021','fiesta','Día de la Luz (Carreras de Caballos de Arroyo de la Luz)','Etnográfica, Hípica y Religiosa. Se celebra en Abril (Lunes de Pascua). Fiesta de Interés Turístico Regional de espectacular dinamismo donde los jinetes y amazonas corren a lomos de sus caballos a gran velocidad por la abarrotada calle principal del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10022','fiesta','Fiesta de San Roque y la Virgen de la Consolación','Patronal y Retorno Estival. Se celebra en Agosto. Festejos serranos típicos de las laderas de la Vera que aprovechan la recogida de la cereza y el retorno vacacional para celebrar capeas tradicionales y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10024','fiesta','Fiesta de la Apertura de la Temporada Termal y Fiestas de Santa Rosa de Lima','Etnográfica, Cultural y Patronal. Se celebra en Marzo y Agosto. Hito etnográfico y turístico comarcal que recrea la antigua tradición termal romana del municipio con pasacalles clásicos, mercados de artesanía y visitas guiadas a sus termas romanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10025','fiesta','Fiestas del Santísimo Cristo del Humilladero','Patronal. Se celebra en Septiembre. Celebración serrana de fuerte identidad local en la transición al Valle del Jerte, con procesiones litúrgicas tradicionales, campeonatos de calva y bailes populares nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10026','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Agosto. Festejos veraniegos organizados bajo la silueta de su histórico castillo fortificado, caracterizados por verbenas populares nocturnas, juegos infantiles y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10027','fiesta','Fiestas del Cristo de la Amargura','Patronal. Se celebra en Agosto. Pequeña festividad vecinal de fuerte arraigo familiar y litúrgico con orquestas de fin de semana y concursos de repostería casera tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10028','fiesta','Fiestas del "Periquillo" y San Juan Bautista','Etnográfica y Patronal. Se celebra en Junio. Pequeño hito etnográfico local marcado por la figura del "Periquillo", un personaje folclórico disfrazado que interactúa con los vecinos durante la procesión de las roscas bendecidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10029','fiesta','Fiesta del Boto y Fiestas de los Santos Florentina y Fulgencio','Etnográfica y Religiosa. Se celebra en Agosto y Octubre. Festejo de relevancia comarcal centrado en la milenaria devoción a las reliquias de los Santos Visigodos, destacando el rito del reparto del pan bendecido y los cantos populares serranos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10030','fiesta','Fiestas de San Bartolomé Apóstol','Patronal y Taurina. Se celebra en Agosto. Celebración local junto al entorno de los Mármoles romanos de Augustóbriga, dinamizada con capeas tradicionales de toros al estilo tradicional ebanístico y orquestas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10031','fiesta','Fiestas de San Ramón Nonato','Patronal y Retorno Estival. Se celebra en Agosto. Festividad local en el entorno del Castro de Villasviejas del Tamuja, vertebrada mediante comidas populares de peñas y bailes populares en la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10032','fiesta','Romería de San Antón Abad y Fiestas de los Toros','Romería, Etnográfica y Taurina. Se celebra en Enero y Septiembre. Celebración de relevancia comarcal famosa por la bendición de caballerías de San Antón y sus tradicionales festejos taurinos celebrados en recintos urbanos de gran solera histórico-artística.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10033','fiesta','Fiestas de la Virgen de la Peña','Patronal y Romería. Se celebra en Septiembre. Pequeños festejos rurales condicionados por la abrupta orografía de sus pedanías, centrados en la procesión de la virgen y una caldereta popular para los vecinos asistentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10037','fiesta','Feria de San Fernando y Fiestas de San Jorge','Recreación Histórica, Feria y Etnográfica. Se celebra en Mayo y Abril. Fiesta de Interés Turístico Nacional por la festividad de San Jorge, que incluye la espectacular quema del dragón en la emblemática Plaza Mayor y la recreación de las batallas entre moros y cristianos en el casco histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10038','fiesta','Fiestas de San Sebastián','Patronal. Se celebra en Enero y Agosto (Fiesta del Emigrante). La localidad con menor demografía de la provincia organiza pequeños festejos familiares estivales con música tradicional y concursos de juegos tradicionales de mesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10039','fiesta','Fiestas del Santísimo Cristo de la Agonía','Patronal. Se celebra en Septiembre. Celebración íntima en plena Sierra de Gata, estructurada en torno a la procesión del cristo, verbenas de fin de semana y competiciones tradicionales de juegos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10040','fiesta','Fiesta de "Los Pastores" y Fiestas del Cristo de la Agonía','Etnográfica y Patronal. Se celebra en Septiembre. Celebración que mantiene vivos los ritos de la transhumancia pastoril con demostraciones de ordeño tradicional, esquilado de ovejas y degustación de migas extremeñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10041','fiesta','Fiestas de la Virgen del Pilar y San Cristóbal','Patronal y Etnográfica. Se celebra en Octubre y Julio. Hito festivo en Las Hurdes que congrega a las alquerías vecinas, destacando las muestras folclóricas de tamborileros hurdanos y degustaciones de productos locales de la colmena.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10042','fiesta','Fiestas de San Sebastián','Patronal. Se celebra en Enero. Pequeña festividad invernal de arraigo estrictamente local adaptada a la baja demografía del término municipal, centrada en ritos litúrgicos tradicionales y una hoguera popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10043','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Festejos locales marcados por las tradicionales hogueras de la noche de San Juan, pasacalles musicales, torneos de fútbol sala de peñas locales y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10044','fiesta','Fiestas de la Virgen de Belén y Feria de la Vendimia','Enológica, Romería y Patronal. Se celebra en Abril y Agosto. Celebración de relevancia comarcal unida a su prestigiosa tradición vitivinícola de pitarra, destacando la multitudinaria romería al santuario y las catas populares de vino local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10045','fiesta','Fiestas de San Roque','Patronal y Taurina. Se celebra en Agosto. Festejos locales muy animados por la llegada de visitantes en verano, caracterizados por encierros tradicionales de vaquillas y bailes populares en la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10046','fiesta','Festival Internacional de Música Celta "El Magusto"','Cultural y Etnográfica. Se celebra en Noviembre. Hito etnográfico de relevancia provincial y transfronteriza celebrado en pleno Parque Natural Tajo Internacional, combinando conciertos de música celta con talleres de ecología y artesanía de la corcha.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10047','fiesta','Fiestas de San Jovita y los Santos Mártires','Patronal y Taurina. Se celebra en Septiembre. Festejos locales de las inmediaciones del Valle del Alagón, conocidos por sus encierros al estilo tradicional, campeonatos de tiro al plato y animadas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10048','fiesta','Fiestas Patronales de San Mateo Apóstol','Patronal. Se celebra en Septiembre. Festejos locales orientados a la convivencia vecinal en el límite provincial, caracterizados por calderetas de carne de caza de la sierra, misas de coro y bailes de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10049','fiesta','Fiesta del Torta del Casar y Fiestas de la Virgen del Prado','Gastronómica, Etnográfica y Patronal. Se celebra en Septiembre. Gran festividad comarcal y provincial orientada a la apoteosis gastronómica de su famoso queso con D.O.P., organizando catas multitudinarias, mercados de pastores y la tradicional suelta de vaquillas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10050','fiesta','Fiestas de la Cruz Bendita','Etnográfica, Religiosa y de Convivencia Histórica. Se celebra en Mayo. Hito etnográfico en Las Hurdes que conmemora la pacífica herencia histórica de sus tres barrios históricos: judío, árabe y cristiano, mediante una espectacular procesión conjunta y folklore de tamborileros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10051','fiesta','Fiesta del Tamborilero','Etnográfica y Folclórica. Se celebra en Agosto. Hito cultural comarcal de gran valor etnográfico que reúne a los mejores intérpretes de flauta de tres agujeros y tamboril de toda Extremadura y Salamanca, preservando sones medievales puros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10052','fiesta','Fiestas de la Virgen del Pilar','Patronal. Se celebra en Octubre. Celebración típicamente vecinal a lo largo del trazado de la Vía de la Plata, caracterizada por triduos religiosos solemnes, juegos tradicionales infantiles y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10053','fiesta','Fiestas de San Gregorio','Patronal. Se celebra en Mayo. Festejos íntimos de arraigo local organizados en torno a la procesión del santo por las parcelas agrícolas de regadío del Alagón, con orquestas de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10056','fiesta','Fiestas de San Sebastián y los Toros de Agosto','Patronal y Taurina. Se celebra en Agosto. Festejos locales que destacan por los encierros urbanos tradicionales y capeas de vaquillas, complementados con campeonatos de pesca y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10057','fiesta','Fiestas del Santísimo Cristo de la Humildad','Patronal. Se celebra en Septiembre. Celebración local a las puertas del Parque Nacional de Monfragüe, con procesiones tradicionales de antorchas, comidas de hermandad vecinal y música de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10054','fiesta','Fiestas de los Santos Mártires y Fiesta del Cerezo en Flor','Etnográfica, Agrícola y Patronal. Se celebra en Enero y Marzo. Participación integrada en la festividad del Valle del Jerte que celebra el milagro blanco de los cerezos con rutas senderistas entre castaños centenarios y lagares tradicionales de pitarra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10055','fiesta','Fiestas de San Marcos y de la Virgen de la Asunción','Patronal y Romería. Se celebra en Abril y Agosto. Festejos en el Valle del Ambroz que aprovechan la piscina natural local para dinamizar el verano con conciertos populares, campeonatos de cartas y procesiones litúrgicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10058','fiesta','Fiestas de la Virgen de la Soledad','Patronal y Taurina. Se celebra en Septiembre. Festejos locales en Campo Arañuelo caracterizados por la tradicional suelta de vaquillas, espectáculos de variedades, comidas populares de toro de lidia y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10059','fiesta','Fiestas de San Blas y de la Virgen de la Almudena','Patronal. Se celebra en Febrero y Agosto. Celebraciones locales marcadas por la tradicional procesión de los santos con la bendición de las típicas roscas de pan de San Blas y verbenas estivales nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10060','fiesta','Fiestas de San Benito y la Virgen de la Avellaneda','Patronal y Etnográfica. Se celebra en Mayo y Agosto. Festejos serranos de gran arraigo en Los Ibores, conocidos por la danza tradicional de los palos interpretada ante el santo y la gran afluencia a su cueva kárstica monumental.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10061','fiesta','Fiesta de "La Borrasca" y San Miguel','Etnográfica, Ecuestre y Patronal. Se celebra en Diciembre y Septiembre. Hito etnográfico de raigambre fronteriza; destaca "La Borrasca", donde jinetes locales corren a caballo por las calles empedradas de la villa portando antorchas de fuego tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10062','fiesta','Fiesta de "Enraizamiento" y las Fiestas de San Antonio de Padua','Transfronteriza y Etnográfica. Se celebra en Junio. Festividad singular en el extremo más occidental de la provincia, caracterizada por la estrecha convivencia con el folklore portugués, fados, calderetas de pescado del río y verbenas de ambos países.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10063','fiesta','Fiestas de San Juan Bautista','Patronal y Retorno Estival. Se celebra en Agosto. Pequeña celebración veraniega enfocada en congregar a los antiguos vecinos emigrados, dinamizada con juegos de mesa tradicionales de naipes, comidas populares y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10064','fiesta','Fiesta de la Virgen de la Navelonga y Fiesta de las Bodegas','Enológica, Romería y Patronal. Se celebra en Abril y Agosto. Festividad de arraigo en la Sierra de Gata que destaca por la apertura tradicional de las antiguas bodegas de pitarra excavadas bajo las casas señoriales para invitar a vecinos y forasteros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10065','fiesta','Fiestas del Santísimo Cristo del Amparo','Patronal y Religiosa. Se celebra en Septiembre. Festejos locales marcados por la sobria procesión del cristo por las calles porticadas de arquitectura verata tradicional, subastas de ramos florales y bailes de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10066','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Celebración tradicional íntima vinculada históricamente a la figura de Pizarro, dinamizada hoy con verbenas de fin de semana y competiciones de juegos tradicionales locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10034','fiesta','Fiestas de la Virgen del Castillo','Patronal. Se celebra en Septiembre. Festejos serranos con espectaculares vistas al Valle del Jerte, destacando las danzas tradicionales de paloteo ante la patrona y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10035','fiesta','Fiesta de la Quema del Judas y Fiestas de Santiago Apóstol','Etnográfica y Patronal. Se celebra en Abril (Domingo de Resurrección) y Julio. Hito etnográfico del Valle del Jerte por la espectacular quema de un monigote gigante a orillas del río Jerte en Semana Santa, complementado con ferias estivales masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10036','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre y Mayo. Celebración de arraigo estrictamente local vinculada a las tareas de recolección de cerezas, con orquestas de baile en la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10067','fiesta','Fiestas de San Juan de Coria','Taurina, Etnográfica y Tradicional. Se celebra en Junio. Fiesta de Interés Turístico Nacional de masivo impacto; su fisonomía medieval intramuros se convierte en un laberinto para la suelta tradicional del toro de San Juan.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10068','fiesta','Fiestas del Santísimo Cristo del Amparo','Patronal, Histórica y Taurina. Se celebra en Septiembre. Hito histórico y comarcal vinculado a la figura imperial de Carlos V; destaca por sus tradicionales capeas taurinas de plaza cuadrada porticada y el gran ambiente festivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10069','fiesta','Fiestas de la Virgen de la Alta Gracia','Patronal. Se celebra en Agosto. Celebración típicamente vecinal adaptada al retorno veraniego, estructurada con pasacalles musicales locales, torneos deportivos de peñas y orquestas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10070','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Septiembre. Festejos de arraigo local tradicionales, caracterizados por el canto tradicional de las auroras marianas de madrugada, subastas del ramo de dulces y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10071','fiesta','Fiesta del Pino de San Julián','Etnográfica y Patronal. Se celebra en Agosto. Hito etnográfico de la Sierra de Gata donde los jóvenes talan e izan un gran pino tradicional en medio de la plaza del pueblo entre cantos de folclore extremeño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10072','fiesta','Fiesta de "As Sanislas" (San Blas) y Virgen de la Divina Pastora','Etnográfica, Lingüística y Patronal. Se celebra en Febrero y Agosto. Hito antropológico único de la Sierra de Gata; los festejos y cánticos se desarrollan usando "A Fala", el dialecto galaico-extremeño protegido autóctono de la localidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10073','fiesta','Fiestas del Santísimo Cristo de la Agonía','Patronal. Se celebra en Septiembre. Festejos locales tradicionales en las llanuras trujillanas, caracterizados por procesiones devocionales solemnes, bailes populares nocturnos y comidas colectivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10075','fiesta','Fiestas de San Bartolomé Apóstol','Patronal. Se celebra en Agosto. Celebración de arraigo estrictamente local enfocada al turismo familiar veraniego, ofreciendo orquestas en la plaza de la localidad y competiciones de juegos tradicionales de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10076','fiesta','Fiestas del Niño Dios y San Isidro','Patronal y Tradicional. Se celebra en Enero y Mayo. Festejos que ganan gran vistosidad gracias a su desarrollo dentro de las murallas de almohades perfectamente conservadas del pueblo, sumando capeas locales tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10077','fiesta','Fiestas del Rosario y Santiago Apóstol','Patronal. Se celebra en Agosto. Celebración local de fuerte arraigo vecinal, caracterizada por la tradicional subasta de brazos de la virgen, campeonatos de fútbol sala locales y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10078','fiesta','Fiestas de San Antonio de Padua y los Chiviteros','Etnográfica y Patronal. Se celebra en Junio y Septiembre. Hito etnográfico serrano de la cordillera de Béjar, destacando la fiesta de los chiviteros vinculada al antiguo pastoreo tradicional de cabras e industrias del cuero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10079','fiesta','Fiestas de la Visitación de la Virgen a Santa Isabel y Fiesta del Chíviri Local','Patronal y Etnográfica. Se celebra en Julio. Hito etnográfico en la comarca de La Vera, caracterizado por bailes tradicionales extremeños, vistosos trajes veratos y el profundo arraigo de la leyenda de la Serrana de la Vera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10080','fiesta','Fiesta del Cerezo en Flor y Fiestas del Santísimo Cristo del Socorro','Etnográfica, Agrícola y Patronal. Se celebra en Marzo y Agosto. Celebración de relevancia comarcal en el Valle del Ambroz, participando activamente en los circuitos turísticos de la floración y el retorno veraniego de emigrantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10082','fiesta','Fiestas de San Roque (Tradicionales Toros de Garrovillas)','Taurina y Etnográfica. Se celebra en Agosto. Espectacular festejo de calado provincial celebrado en su monumental Plaza Mayor porticada del siglo XV, la cual se transforma por completo con barreras de madera para sus famosas capeas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10083','fiesta','Fiestas Patronales de la Virgen de Altagracia','Patronal. Se celebra en Agosto. Festejos de fuerte arraigo familiar y local en la comarca de Los Ibores, dinamizados con comidas de convivencia, juegos infantiles y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10084','fiesta','Fiestas de Santiago Apóstol y la Virgen de la Chanca','Patronal y Etnográfica. Se celebra en Julio y Agosto. Celebración de gran identidad serrana que realza la arquitectura tradicional de piedra del municipio con pasacalles, rondallas líricas extremeñas y eventos taurinos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10085','fiesta','Fiestas de San Marcos Evangelista','Patronal. Se celebra en Abril. Celebración puramente vecinal centrada en la bendición y reparto del tradicional pan de San Marcos, actividades recreativas en el campo y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10086','fiesta','Fiestas Patronales de San Antonio de Padua','Patronal. Se celebra en Junio. Pequeña festividad local marcada por los ritos litúrgicos, la procesión de la imagen del santo, subastas de exvotos y orquestas de música popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10087','fiesta','Fiesta de la Virgen de Guadalupe (Día de Extremadura)','Religiosa, Etnográfica y Patronal. Se celebra en Septiembre. Fiesta de Interés Turístico Nacional de inmenso valor histórico y espiritual, con procesiones multitudinarias en el Real Monasterio, desfiles hípicos y la asistencia de peregrinos de todo el país.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10088','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Celebración litúrgica local tradicional caracterizada por las hogueras populares, comidas comunitarias al aire libre y pequeños campeonatos de juegos de mesa tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10090','fiesta','Fiestas de Santa Catalina y Ruta Literaria de Gabriel y Galán','Cultural, Etnográfica y Patronal. Se celebra en Noviembre y Mayo. Destaca en el ámbito comarcal por conjugar sus fiestas de invierno con los actos culturales dedicados al poeta universal Gabriel y Galán en su emblemática casa-museo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10089','fiesta','Fiestas de San Antonio de Padua','Patronal y Taurina. Se celebra en Junio. Festejos locales que ganan dinamismo con la organización de tradicionales encierros y capeas de vaquillas por el casco urbano, complementados con verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10091','fiesta','Fiesta de "El Peropalo" Local y Fiestas de Santa Bárbara','Etnográfica y Patronal. Se celebra en Diciembre. Celebración de gran singularidad en la Sierra de Gredos extremeña, famosa por sus danzas de paloteo tradicionales, el consumo de licores artesanales de pitarra y hogueras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10092','fiesta','Fiestas de San Bartolomé Apóstol','Patronal. Se celebra en Agosto. Pequeñas verbenas veraniegas orientadas al ocio de las familias retornadas, organizando triduos solemnes, campeonatos deportivos locales y cenas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10093','fiesta','Fiestas de San Sebastián y la Virgen de la Consolación','Patronal y Etnográfica. Se celebra en Enero y Agosto. Tradición invernal basada en las luminarias urbanas de San Sebastián, complementada con encierros tradicionales de reses bravas durante el período de vacaciones estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10094','fiesta','Fiestas de San Juan Bautista','Patronal y Transfronteriza. Se celebra en Junio. Festejos en el Parque Natural del Tajo Internacional con fuerte influencia lusa en su folclore, degustaciones de dulces típicos fronterizos y verbenas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10095','fiesta','Fiestas de San Juan Bautista','Patronal y Taurina. Se celebra en Junio. Festejos populares de fuerte arraigo local orientados en torno a tradicionales espectáculos taurinos urbanos, verbenas nocturnas al aire libre y encendido de hogueras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10096','fiesta','Representación de "Los Conversos" y Fiestas del Santísimo Cristo de la Salud','Recreación Histórica, Cultural y Patronal. Se celebra en Julio y Septiembre. Fiesta de Interés Turístico Regional que revive el pasado judío de su célebre barrio judío mediante obras dramáticas junto al río, mercados tradicionales y gastronomía sefardí.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12069','fiesta','Fiestas de San Sebastián','Patronal. Se celebra en Enero. Festividad invernal íntima y vecinal caracterizada por la procesión litúrgica del santo patrón, la quema de ramajes tradicionales en hogueras y pequeñas verbenas de salón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10098','fiesta','Fiestas de la Virgen de la Alta Gracia','Patronal. Se celebra en Septiembre. Festejos populares de los Cuatro Lugares con tradicionales ofrendas de roscas de pan, pujas públicas de brazos de la virgen y espectáculos musicales nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10099','fiesta','Fiestas de San Marcos Evangelista y Santa María Magdalena','Patronal. Se celebra en Abril y Julio. Celebraciones locales marcadas por capeas tradicionales de vaquillas, desfiles folclóricos, charangas musicales urbanas y verbenas populares en el paseo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10100','fiesta','Fiestas de San Lino y Nuestra Señora del Buen Varón','Patronal y Taurina. Se celebra en Agosto. Epicentro festivo veraniego de la Sierra de Gata con gran afluencia comarcal; sobresalen sus encierros urbanos al estilo tradicional y las verbenas en su casco histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10101','fiesta','Fiestas de San Pedro Ad Víncula','Patronal y Retorno Estival. Se celebra en Agosto. Celebración vecinal menor adaptada al reencuentro de familias que emigraron, articulada mediante cenas vecinales al aire libre, pequeños torneos deportivos y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10102','fiesta','Feria de Agosto y Fiestas de la Virgen de la Jarrera','Patronal y Retorno Estival. Se celebra en Agosto. Festejos estivales tradicionales dinamizados por actividades culturales locales, capeas de vaquillas en recintos portátiles y orquestas musicales de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10103','fiesta','Fiestas de la Virgen de los Hitos','Patronal y Romería. Se celebra en Septiembre. Tradición comarcal unida a las dehesas del entorno de Monfragüe, caracterizada por la romería ecuestre a la ermita, cantos regionales extremeños y comidas camperas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10104','fiesta','Fiesta del Tabaco y el Pimentón y Ferias de Santiago Apóstol','Gastronómica, Agrícola y Taurina. *. Se celebra en Agosto. *. Relevancia provincial y regional por exaltar el Pimentón de la Vera D.O.P. Incluye grandes desfiles de carrozas agrícolas, importantes ferias taurinas de renombre y conciertos multitudinarios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10105','fiesta','Fiesta de "Los Escobazos"','Etnográfica y Religiosa. Se celebra en Diciembre. Fiesta de Interés Turístico Regional de espectacular plasticidad; los vecinos se golpean amistosamente con escobas de retama encendidas y procesionan a caballo portando el estandarte de la Virgen de la Concepción.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10106','fiesta','Fiestas de San Gregorio y San Antonio','Patronal. Se celebra en Mayo y Agosto. Festejos en las faldas de Traslasierra centrados en procesiones tradicionales, reparto de dulces artesanales bendecidos y bailes populares en la plaza consistorial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10107','fiesta','Fiesta de "El Cerezo en Flor" y Fiesta de "La Otoñada"','Etnográfica, Agrícola y Gastronómica. Se celebra en Marzo y Noviembre. Fiesta de Interés Turístico Internacional celebrada de forma rotativa en el Valle del Jerte, atrayendo a miles de visitantes globales para contemplar el millón de cerezos blancos florecidos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10108','fiesta','Fiestas de San Antonio (Alquería de Las Mestas)','Etnográfica y Patronal. Se celebra en Agosto. Singular hito folclórico de Las Hurdes, donde se conservan ritos ancestrales, cánticos tradicionales hurdanos al son del tamboril y degustación de productos de miel silvestre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10109','fiesta','Fiestas de la Virgen del Consuelo','Patronal y Feria Local. Se celebra en Agosto. Festejos de la comarca de Villuercas-Ibores con tradicionales encierros y capeas taurinas, pasacalles urbanos de gigantes y cabezudos y verbenas populares multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10110','fiesta','Fiestas de San Cristóbal y del Cristo de la Caridad','Patronal y Taurina. Se celebra en Julio y Agosto. Relevancia comarcal por sus tradicionales espectáculos de toros, sus artísticos jardines de hiedra natural esculpida que ornamentan las calles y grandes festivales de folclore folclórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10111','fiesta','Fiestas del Santísimo Cristo de la Luz','Patronal y Romería. Se celebra en Septiembre. Festejos playeros y serranos marcados por la masiva concurrencia a orillas de la garganta de Alardos, combinando devoción con capeas urbanas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10112','fiesta','Fiestas de San Juan Bautista y Conmemoración Histórica de Fernando el Católico','Recreación Histórica y Patronal. Se celebra en Junio y Enero. Fuerte identidad histórica comarcal que rememora la muerte del Rey Católico acaecida en el municipio en 1516, con desfiles renacentistas y conferencias etnográficas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10113','fiesta','Fiestas de la Virgen Sorbajona','Patronal y Taurina. Se celebra en Agosto. Festejos veraniegos destacados por sus tradicionales capeas de vaquillas en recintos urbanos, animadas orquestas nocturnas en el paseo de la localidad y comidas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10121','fiesta','Fiestas Patronales de San Alipio','Patronal. Se celebra en Agosto. Celebración de carácter puramente local adaptada al verano para los residentes y veraneantes, estructurada en torno a procesiones solemnes y espectáculos musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10115','fiesta','Fiesta de "La Pedida de la Patatera"','Gastronómica y Etnográfica. Se celebra en Febrero/Marzo (Martes de Carnaval). Fiesta de Interés Turístico Regional de gran afluencia provincial, donde la población vestida de época recorre las calles cantando y pidiendo este embutido tradicional extremeño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10116','fiesta','Fiestas de San Cristóbal y Feria de San Roque','Feria Local y Patronal. Se celebra en Julio y Agosto. Festividad de los "chinatos" con gran tirón en los accesos a Monfragüe; destacan los tradicionales encierros de vaquillas, festivales de rock locales y competiciones folclóricas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10117','fiesta','Fiestas del Santísimo Cristo de la Salud','Patronal. Se celebra en Agosto. Pequeña celebración en las estribaciones de las Hurdes bajas, enfocada en la procesión del cristo de la salud, verbenas de plaza y juegos tradicionales infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10118','fiesta','Fiesta de "Los Mayos" y Fiestas de San Lorenzo','Etnográfica y Patronal. Se celebra en Mayo y Agosto. Tradición etnográfica singular basada en el levantamiento del árbol mayo por los quintos locales, complementada en verano con capeas tradicionales de reses bravas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10119','fiesta','Fiestas de la Virgen de la Gracia','Patronal. Se celebra en Agosto. Festejos tradicionales de retorno estival con misas de gala, tradicionales subastas de roscas bendecidas de pan y orquestas musicales de baile en el paseo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10120','fiesta','Fiestas del Santísimo Cristo de la Sangre','Patronal. Se celebra en Agosto. Festejos locales marcados por las misas tradicionales ante su valioso puente romano, pasacalles infantiles y espectáculos musicales de variedades los fines de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10121','fiesta','Feria de Agosto y Fiesta de la Ruta del Tomate','Agrícola, Gastronómica y Feria. Se celebra en Agosto. Gran hito de relevancia comarcal y provincial centrado en su capitalidad del sector hortofrutícola, ofreciendo masivas degustaciones culinarias de gazpacho y ferias comerciales potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10122','fiesta','Fiestas Patronales de San Francisco de Asís','Patronal. Se celebra en Octubre. Pequeñas celebraciones rurales de arraigo litúrgico y vecinal, con bendición de animales tradicionales, degustaciones de repostería casera y verbenas de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10123','fiesta','Fiestas de la Virgen de la Jarrera','Patronal y Etnográfica. Se celebra en Agosto. Celebración de la dehesa de Mirabel que cobra vistosidad con las actividades organizadas al pie de su histórico castillo señorial, incluyendo capeas y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10124','fiesta','Fiestas de San Ildefonso','Patronal y Etnográfica. Se celebra en Enero. Festividad invernal singular de Traslasierra que conserva tradiciones de vestimentas folclóricas locales, pasacalles de tamborileros extremeños y hogueras populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10125','fiesta','Fiestas de la Purísima Concepción y Los Toros','Patronal y Taurina. Se celebra en Septiembre. Festejos populares comarcales famosos por la suelta de reses bravas por las calles fortificadas de la villa y el gran ambiente festivo que se vive en sus tradicionales peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10126','fiesta','Fiestas del "Jurramacho" (Carnaval) y Fiestas de la Virgen del Castillo','Etnográfica y Patronal. Se celebra en Febrero y Septiembre. Hito etnográfico provincial de gran valor por el "Jurramacho", un antiquísimo disfraz de carnaval basado en ropas viejas para no ser reconocido, sumado a los ritos marianos en su castillo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10127','fiesta','Fiesta de "Los Negritos de San Blas"','Etnográfica y Danza Tradicional. Se celebra en Febrero. Fiesta de Interés Turístico Regional de colosal valor antropológico; los danzantes se tiznan la cara con corcho quemado e interpretan danzas rituales portando los emblemáticos sombreros de tres espejos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10128','fiesta','Fiestas de San Buenaventura','Taurina y Patronal. Se celebra en Julio. Festejos de gran calado provincial y comarcal en la Sierra de Gata, célebres por sus tradicionales e intensos encierros urbanos de toros bravos, capeas populares y un multitudinario ambiente de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10129','fiesta','Fiestas de San Andrés y San Bartolomé','Patronal. Se celebra en Agosto y Noviembre. Celebración de arraigo estrictamente local que potencia el reencuentro estival con misas solemnes, campeonatos de juegos de cartas de baraja española y orquestas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10130','fiesta','Fiesta del Cerezo en Flor y Fiestas de San Jorge','Etnográfica, Agrícola y Patronal. Se celebra en Marzo y Abril. Forma parte de la Fiesta del Cerezo en Flor, declarada Fiesta de Interés Turístico Nacional, atrayendo a miles de visitantes a sus rutas entre bancales floridos, mercados de artesanía y folclore del Jerte.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10131','fiesta','Carnaval de Navalmoral de la Mata (Carnavalo)','Etnográfica y Carnaval. Se celebra en Febrero / Marzo. Fiesta de Interés Turístico Nacional con un enorme arraigo e impacto en el noreste extremeño, famosa por sus espectaculares desfiles de carrozas, comparsas coloridas y un ambiente callejero masivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10132','fiesta','Fiestas de San Isidro Labrador y la Virgen del Rosario','Romería y Patronal. Se celebra en Mayo y Agosto. Celebración en la comarca de Los Ibores destacada por la procesión del santo con caballos engalanados, subastas de roscas de pan bendecido y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10133','fiesta','Fiestas de San Bartolomé Apóstol','Patronal y Taurina. Se celebra en Agosto. Festejos locales de gran participación caracterizados por sus tradicionales capeas de vaquillas en la plaza del pueblo, orquestas de música y comidas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10134','fiesta','Fiesta de la Castaña y Fiestas de Santiago Apóstol','Gastronómica, Etnográfica y Patronal. Se celebra en Noviembre y Julio. Destaca su hito gastronómico serrano en el Geoparque Villuercas-Ibores-Jara, donde se asan miles de kilos de castañas asadas tradicionales acompañadas de licores artesanales y folklore local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10136','fiesta','Fiestas de San Blas y la Virgen del Puerto','Patronal. Se celebra en Febrero y Agosto. Pequeños festejos vecinales de fuerte tradición religiosa vinculados a las ruinas romanas de Cáparra, dinamizados con procesiones folclóricas, orquestas locales y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10137','fiesta','Fiestas de San Gregorio y San Miguel','Patronal. Se celebra en Mayo y Septiembre. Festejos de ámbito estrictamente vecinal y familiar con bailes populares en la plaza del ayuntamiento, pasacalles tradicionales con tamborileros y competiciones deportivas de fútbol sala.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10138','fiesta','Fiestas del Salvador y la Fiesta de la Alborá','Patronal y Etnográfica. Se celebra en Agosto. Hito etnográfico de la comarca de La Vera, caracterizado por su precioso casco histórico decorado y los cánticos tradicionales nocturnos que rememoran antiguas leyendas extremeñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10139','fiesta','Fiestas de San Lorenzo y San Pedro de Alcántara','Patronal y Religiosa. Se celebra en Agosto y Octubre. Celebración unida a la mística del vecino Palancar, el convento más pequeño del mundo; incluye procesiones vecinales tradicionales, reparto de dulces de sartén y pequeñas orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10143','fiesta','Festival El Festivalino de Pescueza','Etnográfica, Cultural y Sostenible. Se celebra en Abril. Hito cultural de repercusión provincial y autonómica conocido como "el festival más pequeño del mundo", que lucha contra la despoblación rural llenando el pueblo de conciertos, talleres ecológicos y plantaciones de árboles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10145','fiesta','Fiestas de la Virgen de la Romana','Patronal y Romería. Se celebra en Agosto. Festejos de la raya fronteriza que unen tradición ecuestre, procesiones solemnes, subastas de exvotos y música de verbena adaptada a su población.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10146','fiesta','Fiesta de La Enramá','Etnográfica y Tradicional. Se celebra en Agosto. Fiesta de Interés Turístico Regional de alto valor antropológico en Las Hurdes, donde se realiza un sorteo ritual de emparejamiento de jóvenes del pueblo que lucen vistosos ramilletes de flores hechos a mano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10147','fiesta','Fiesta de Jarramplas','Etnográfica y Ritual. Se celebra en Enero (19 y 20). Fiesta de Interés Turístico Nacional de espectacularidad masiva; un personaje cubierto con una máscara y un traje multifibras recorre las calles del pueblo más alto de Extremadura mientras los vecinos le lanzan miles de kilos de nabos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10148','fiesta','Feria del Martes Mayor de Plasencia','Etnográfica, Mercado Tradicional y Feria. Se celebra en Agosto (Primer martes). Fiesta de Interés Turístico Nacional de enorme empaque que rememora los mercados medievales de la ciudad. Las plazas se llenan de hortelanos, artesanos de toda Extremadura, tamborileros y catas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10149','fiesta','Fiestas de la Virgen del Consuelo','Patronal. Se celebra en Septiembre. Celebración de ámbito estrictamente local con triduos y procesiones tradicionales, bailes nocturnas en la plaza mayor del pueblo y actividades recreativas infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10150','fiesta','Romería de la Virgen del Casar','Romería y Tradicional. Se celebra en Abril (Lunes de Pascua). Festejos de gran arraigo comarcal que se celebran en torno a la ermita del embalse de Portaje, reuniendo a cientos de caballistas vestidos de época y comidas populares de cordero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10151','fiesta','Fiesta del Castillo y Fiestas de los Santos Mártires','Recreación Histórica y Patronal. Se celebra en Enero y Julio. Pequeña recreación medieval organizada en torno a las murallas de su castillo de Marmionda, complementada en verano con verbenas nocturnas y eventos lúdicos para familias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10152','fiesta','Fiestas de San Gregorio y la Virgen de la Encina','Patronal. Se celebra en Mayo y Agosto. Festejos tradicionales de la provincia cacereña centrados en la bendición de campos, procesión de la imagen sagrada, encierros infantiles y verbenas populares de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10153','fiesta','Fiestas de San Bartolomé Apóstol','Patronal. Se celebra en Agosto. Celebración local centrada en el reencuentro estival, con juegos populares tradicionales, degustaciones de repostería casera artesana y veladas musicales en el paseo principal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10154','fiesta','Fiestas de la Virgen del Rosario','Patronal y Serrana. Se celebra en Agosto. Pequeños festejos vecinales adaptados a la fisonomía del Valle del Jerte con pasacalles musicales de flauta y tamboril, actividades lúdicas infantiles y cenas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10155','fiesta','Fiestas de la Virgen de la de la Encina','Patronal. *. Se celebra en Septiembre. *. Festejos tradicionales de la comarca del Alagón que cuentan con suelta de reses bravas en plaza portátil, espectáculos de copla española y concursos de gastronomía popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10159','fiesta','Fiestas de San Blas y la Virgen de las Nieves','Patronal. Se celebra en Febrero y Agosto. Festejos íntimos de montaña con reparto de cordones tradicionales bendecidos de San Blas para proteger la garganta y animadas verbenas estivales en la plaza de la localidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10156','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. La espectacular fisonomía de arquitectura de adobe y madera del pueblo dota de gran belleza estética a sus procesiones tradicionales y catas de vino de pitarra local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10157','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre. Celebración de raíces veratas con procesión de la imagen del santo arcángel, tradicionales ofertorios de roscas típicas de la comarca y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10158','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Pequeños festejos veraniegos locales vertebrados por competiciones deportivas de calva, orquestas populares para amenizar las noches y procesión religiosa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10160','fiesta','Fiestas de San Blas y la Ruta de los Trompe-l''œil (Trampantojos)','Cultural, Etnográfica y Patronal. Se celebra en Agosto. Festejos que ganan gran afluencia comarcal gracias al atractivo etnográfico de sus fachadas pintadas con murales hiperrealistas de oficios antiguos, combinados con verbenas y folklore extremeño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10901','fiesta','Fiestas de San Agustín','Patronal y de Colonización. Se celebra en Agosto. Celebración en este municipio de colonización del siglo XX que destaca por sus festejos de vaquillas, peñas juveniles de gran animación y espectáculos musicales flamencos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10161','fiesta','Fiestas de San Gregorio y la Virgen de la Asunción','Patronal y Familiar. Se celebra en Mayo y Agosto. Celebración vecinal menor debido a la baja demografía local, enfocada en la hermandad vecinal, pequeñas comidas populares y un trío musical nocturno.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10162','fiesta','Fiestas de San Ildefonso y la Virgen de la Luz','Patronal y Taurina. Se celebra en Agosto. Festejos en las estribaciones de la Sierra de San Pedro con capeas populares tradicionales de reses vacunas, competiciones de tiro al plato y bailes populares al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10163','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Celebración de raigambre local marcada por la misa solemne y procesión hípica del patrón por las calles, espectáculos de variedades folclóricas y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10165','fiesta','Fiestas de Santa Ana y San Joaquín','Patronal. Se celebra en Julio. Festejos vecinales de verano centrados en las ceremonias religiosas tradicionales, campeonatos de naipes locales de dominó y orquestas de música popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10166','fiesta','Fiestas de San Agustín','Patronal y Romería. Se celebra en Agosto. Festejos celebrados a los pies de su histórico cerro fortificado, caracterizados por la subida a la antigua ermita, verbenas musicales populares y festejos taurinos tradicionales de vaquillas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10167','fiesta','Fiestas del Santísimo Cristo de la Salud','Patronal. Se celebra en Septiembre. Festejos de ámbito puramente local marcados por la bajada litúrgica de la venerada imagen del Santo Cristo, subastas de ofrendas del campo y bailes nocturnos con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10168','fiesta','Fiestas de Santa Marta','Patronal. Se celebra en Julio. Celebración estival en plena llanura trujillano-cacereña con encierros tradicionales infantiles, capeas de reses bravas en recinto vallado y orquestas de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10169','fiesta','Fiestas de Santiago Apóstol y Feria de la Trashumancia','Etnográfica, Romería y Patronal. Se celebra en Julio. Festejos de gran interés fronterizo dentro del Parque Natural Tajo Internacional que recuperan las antiguas costumbres ganaderas con exhibiciones de esquileo y desfiles ecuestres.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10170','fiesta','Fiestas de Santiago Apóstol y la Virgen de los Remedios','Patronal. Se celebra en Julio. Celebración tradicional de la comarca de los Cuatro Lugares marcada por los cantos religiosos folclóricos de rondalla, comidas vecinales de paella y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10171','fiesta','Fiestas de San Juan Bautista y la Virgen de la Amnistía','Patronal y Taurina. Se celebra en Junio y Septiembre. La espectacular panorámica de su castillo de la Sierra de Gata sirve de marco para encierros urbanos tradicionales de toros, grandes capeas y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10172','fiesta','Fiestas del Santísimo Cristo de la Paz','Patronal y Etnográfica. Se celebra en Septiembre. Festejos tradicionales de las Tierras de Granadilla donde se conservan antiguos bailes populares al son del tamboril tradicional hurdano y subastas de dulces artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10173','fiesta','Fiestas de la Virgen del Rosario y San Juan Bautista','Patronal y Ornitológica. Se celebra en Octubre y Junio. Festejos que complementan el patrimonio de su parque ornitológico de Arrocampo con procesiones marianas tradicionales, orquestas de baile musicales y competiciones locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10174','fiesta','Fiestas de San Juan Bautista','Patronal y Etnográfica. Se celebra en Junio y Agosto (Fiesta del Toro). Celebración en el Valle del Ambroz marcada por el antiquísimo toro de piedra vetón de su plaza; incluye folklore extremeño tradicional, verbenas y rutas de senderismo entre castaños centenarios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10175','fiesta','Fiestas del Santísimo Cristo de la Victoria de Serradilla','Patronal, Religiosa y Etnográfica. Se celebra en Agosto y Septiembre. Festividad de extraordinario impacto devocional comarcal y provincial; miles de fieles acuden en peregrinación masiva a venerar la milagrosa imagen barroca, con imponentes procesiones y cánticos populares en habla extremeña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10176','fiesta','Fiestas de San Ildefonso y San Antonio','Patronal y de Naturaleza. Se celebra en Enero y Agosto. Festejos en la antesala de Monfragüe que potencian actividades ambientales estivales combinadas con procesiones del santo, grandes calderetas populares de carne y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10177','fiesta','Fiestas del Cristo de los Remedios','Patronal. Se celebra en Septiembre. Dada su cercanía con la capital de provincia, cuenta con una gran afluencia a su procesión mariana, encierros infantiles tradicionales, conciertos de rock extremeño y actividades de cetrería.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10178','fiesta','Fiestas del Santo Cristo del Amparo','Patronal. Se celebra en Septiembre. Festejos locales marcados por la bajada de la sagrada imagen del Cristo, tradicionales capeas de vaquillas, juegos populares infantiles y bailes con orquesta en la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10179','fiesta','Fiestas de San Antón y Fiestas de la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Enero y Octubre. Celebración de arraigo estrictamente local caracterizada por la bendición de animales en San Antón, procesiones tradicionales de la patrona, verbenas populares y luminarias vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10180','fiesta','Fiestas de San Marco y Feria de San Miguel','Patronal y Feria Local. Se celebra en Abril y Septiembre. Celebración de arraigo comarcal que destaca por la tradicional bendición de campos en San Marcos, grandes verbenas populares y espectáculos taurinos de buena afluencia en la zona del Campo Arañuelo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10181','fiesta','Fiesta de San Miguel Arcángel','Patronal. Se celebra en Septiembre. Festejos de marcado carácter vecinal y familiar orientados al reencuentro estival tardío, con actos religiosos tradicionales, orquestas nocturnas y competiciones deportivas de fútbol sala.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10182','fiesta','Fiestas de San Blas','Patronal y Etnográfica. Se celebra en Febrero. Pequeña festividad invernal adaptada a la baja demografía del municipio en pleno entorno de Monfragüe, con misa tradicional, bendición de las roscas de San Blas y una comida popular comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10183','fiesta','Fiesta del Ya Tornan y Fiestas del Santísimo Cristo del Amparo','Recreación Histórica, Etnográfica y Patronal. Se celebra en Mayo y Septiembre. Hito etnográfico de la cabecera del Valle del Jerte con la recreación histórica del "Ya Tornan", que conmemora el regreso de los pastores trashumantes con hogueras, mercado de época, folklore local y escenificaciones teatrales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10184','fiesta','Fiestas de San Lucas y Fiesta de la Cereza en Flor','Patronal y Etnográfica. Se celebra en Octubre y Marzo/Abril. Festejos de relevancia comarcal gracias al espectacular mirador del Valle del Jerte, destacando la quema del "Tarangallo" en San Lucas, sus danzas folclóricas y su participación activa en los eventos primaverales de la floración.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10187','fiesta','Fiesta del Capazo','Etnográfica y Mascarada. Se celebra en Abril (Sábado in albis). Destacado hito etnográfico de la Sierra de Gata donde los vecinos portan encinas y lanzan capazos ardientes de aceite en honor a la Virgen de la Bien Parida, un ritual ancestral purificador de altísimo valor histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10185','fiesta','Fiestas de San Marcos y la Virgen de los Ángeles','Patronal y Romería. Se celebra en Abril y Agosto. Festejos serranos tradicionales que combinan la romería campestre a la ermita de la patrona con actividades recreativas veraniegas y verbenas populares para acoger a las familias retornadas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10186','fiesta','Fiestas de San Miguel Arcángel','Patronal y Taurina. Se celebra en Septiembre. Celebración de arraigo local cercana a Trujillo, caracterizada por la procesión litúrgica del santo patrón, tradicionales capeas urbanas de vaquillas, charangas y orquestas de baile en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10190','fiesta','Fiestas de San Miguel y Romería de la Virgen de Monfragüe','Patronal y Romería. Se celebra en Septiembre y Abril. Festejos con notable tirón comarcal debido al paraje natural donde se celebran, destacando la vistosa romería con caballos engalanados hacia el Castillo de Monfragüe y las verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10189','fiesta','Fiesta de La Encamisá','Etnográfica y Religiosa. Se celebra en Diciembre (Noche del 7 de diciembre). Fiesta de Interés Turístico Nacional de impresionante fuerza plástica y emotividad. Centenares de jinetes cubiertos con sábanas blancas con un lucero bordado escoltan el estandarte de la Inmaculada Concepción entre miles de disparos de fogueo y hogueras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10192','fiesta','Fiestas de la Virgen del Torrealba','Patronal y Romería. Se celebra en Abril (Lunes de Pascua) y Septiembre. Tradición local que destaca por la concurrida procesión de la patrona desde su ermita, subastas de roscas de pan bendecido, folklore extremeño y animadas veladas musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10193','fiesta','Fiestas del Santísimo Cristo del Humilladero','Patronal. Se celebra en Agosto. Festejos populares de verano en el entorno de Cáceres que registran gran afluencia de jóvenes de la comarca gracias a sus verbenas, encierros tradicionales de reses y campeonatos de peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10194','fiesta','Fiestas de Nuestra Señora del Salor','Patronal y Romería. Se celebra en Septiembre. Celebración de raigambre local famosa por la romería a la ermita de la Virgen a orillas del río Salor, donde los vecinos degustan los tradicionales platos de cochinillo asado locales en régimen de convivencia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10195','fiesta','Fiesta del Chíviri y Feria Nacional del Queso de Trujillo','Etnográfica, Gastronómica y Feria. Se celebra en Abril (Domingo de Resurrección) y Mayo. El Chíviri es Fiesta de Interés Turístico Regional donde miles de personas vestidas con trajes tradicionales cantan y bailan en la Plaza Mayor. Su Feria del Queso es un evento gastronómico de impacto nacional absoluto.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10196','fiesta','Fiestas de San Vito y Fiesta de la Cereza en Flor','Patronal y Etnográfica. Se celebra en Junio y Marzo/Abril. Hito paisajístico y etnográfico del Valle del Jerte que atrae numerosos visitantes durante la primavera del cerezo, complementado en junio con los ritos tradicionales al santo mártir y folklore extremeño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10197','fiesta','Fiestas de San Blas y la Virgen del Campo','Patronal. Se celebra en Febrero y Septiembre. Festejos vecinales de ámbito estrictamente local con procesión religiosa tradicional, tiro al plato, juegos infantiles en la plaza y orquestas musicales de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10198','fiesta','Feria del Queso Artesano de Valdefuentes','Gastronómica y Etnográfica. Se celebra en Octubre. Hito gastronómico con amplio reconocimiento provincial dedicado a los quesos artesanos de la comarca, con degustaciones de tortas locales, mercados de artesanía y actuaciones de folklore regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10199','fiesta','Fiestas de Santa María Magdalena','Patronal. Se celebra en Julio. Festejos veraniegos de arraigo familiar y local adaptados para la dinamización vecinal, centrados en la procesión de la santa, campeonatos deportivos de cartas y música nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10200','fiesta','Fiestas de San Jerónimo','Patronal. Se celebra en Septiembre. Celebración puramente local con tradicionales ritos litúrgicos, verbenas de plaza del pueblo, comidas vecinales de hermandad y actividades recreativas para los más pequeños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10201','fiesta','Fiestas de la Virgen del Rosario','Patronal y Retorno Estival. Se celebra en Agosto. *. Pequeña festividad rural enfocada en la recepción de los antiguos vecinos emigrados, dinamizada mediante juegos de agua, verbenas nocturnas al aire libre y cenas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10202','fiesta','Fiestas de San Roque y la Virgen del Carrascal','Patronal y Taurina. Se celebra en Agosto y Septiembre. Festejos de notable arraigo local en el Valle del Alagón, conocidos por sus tradicionales capeas y encierros de vaquillas por el casco antiguo, combinados con verbenas populares de gran ambiente.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10203','fiesta','Romería de San Isidro Labrador y Jornadas Medievales de la Boda Regia','Romería, Recreación Histórica y Transfronteriza. Se celebra en Mayo y Agosto. Fiesta de Interés Turístico Regional por su espectacular desfile de carrozas de San Isidro. Su "Boda Regia" recrea el enlace histórico del rey Manuel I de Portugal e Isabel de Aragón en su barrio gótico-judío.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10204','fiesta','Los Empalaos de Valverde de la Vera','Etnográfica y Religiosa. Se celebra en Abril (Noche del Jueves Santo). Fiesta de Interés Turístico Nacional de impresionante misticismo y valor histórico. Los penitentes recorren descalzos las calles empedradas de la villa atados a un timón de madera con sogas de esparto y una corona de espinas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10205','fiesta','Fiesta de San Dionisio y Fiesta de "A Festa do Borrego"','Patronal y Etnográfica (Falanu extremeña). Se celebra en Octubre y Febrero. Hito etnográfico singular de Sierra de Gata debido a la conservación de la "fala" —lengua local romance— en sus cánticos, sumado a los desfiles de caballos y las tradicionales comidas de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10206','fiesta','Fiestas de los Santos Mártires Fabián y Sebastián','Patronal. Se celebra en Enero y Agosto (Fiesta del Veraneante). Festejos de arraigo estrictamente local con pasacalles musicales tradicionales, procesión de los santos patronos, verbenas veraniegas en el paseo del pueblo y competiciones de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10207','fiesta','Fiestas del Santísimo Cristo de las Mercedes','Patronal y Taurina. Se celebra en Septiembre. Festejos populares caracterizados por sus tradicionales capeas de vaquillas en plaza portátil, la concurrida procesión del Cristo, subastas de exvotos y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10208','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Pequeña celebración rural íntima adaptada a la baja densidad del pueblo, estructurada en torno a la misa solemne, pequeños espectáculos musicales al aire libre y cenas vecinales comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10209','fiesta','Fiestas de Santo Domingo de Guzmán','Patronal. Se celebra en Agosto. Celebración estival de arraigo familiar y vecinal enfocada al reencuentro de emigrantes, dinamizada con competiciones deportivas de cartas, juegos de agua infantiles y orquestas de baile nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10210','fiesta','Fiestas de Santiago Apóstol y la Virgen de la Piedad','Patronal y Romería. Se celebra en Julio y Noviembre. Festejos de fuerte tradición local en Sierra de Gata, conocidos por los tradicionales ritos religiosos en su histórica iglesia fortificada, pasacalles folclóricos y veladas musicales populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10212','fiesta','El Peropalo de Villanueva de la Vera','Etnográfica y Carnaval. Se celebra en Febrero/Marzo (Carnaval). Fiesta de Interés Turístico Nacional de extraordinario valor histórico. Un muñeco de paja que representa a un antiguo malhechor es juzgado, paseado y ajusticiado por los vecinos entre coplas ancestrales, tamboriles y rondas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10211','fiesta','Fiesta del Árbol de Villanueva de la Sierra','Etnográfica e Histórica. Se celebra en Febrero (Martes de Carnaval). Hito etnográfico e histórico excepcional; se trata de la Fiesta del Árbol más antigua del mundo contemporáneo —instaurada en 1805— donde los niños del colegio plantan árboles acompañados por una comitiva festiva y folclórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10214','fiesta','Fiestas de San Bartolomé Apóstol','Patronal. Se celebra en Agosto. Festejos locales marcados por el reencuentro veraniego, caracterizados por la procesión litúrgica tradicional del santo, campeonatos de fútbol sala y animadas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10213','fiesta','Carnaval de Ánimas de Villar del Pedroso','Etnográfica y Tradicional. Se celebra en Febrero/Marzo (Carnaval). Hito etnográfico de la comarca de Los Ibores que destaca por la conservación de antiguos ritos militares del siglo XVII en honor a las ánimas benditas, con desfiles de sargentos y soldadesca vestidos con trajes de época.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10215','fiesta','Fiestas de San Pantaleón','Patronal. Se celebra en Julio. Festejos de arraigo estrictamente local en el corazón serrano, caracterizados por las procesiones devocionales, competiciones de juegos tradicionales de mesa, comidas de convivencia y música de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10216','fiesta','Fiestas de San Ramón Nonato','Patronal y Taurina. Se celebra en Agosto. Festejos de relevancia en Trasierra-Tierras de Granadilla por la gran afluencia a sus encierros urbanos y capeas de reses bravas en la plaza de la localidad, combinados con grandes orquestas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10217','fiesta','Fiestas del Santísimo Cristo de la Veracruz','Patronal. Se celebra en Septiembre. Festejos locales estructurados en torno a los emotivos triduos y procesión del cristo, pasacalles musicales, bailes con orquesta popular en la plaza mayor y degustaciones gastronómicas de productos ibéricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10218','fiesta','Fiesta de "El Jueves de las Comadres" y Fiestas de San Bartolomé','Etnográfica, Patronal y Taurina. Se celebra en Febrero y Agosto. Hito fronterizo comarcal único por la antiquísima tradición de "Las Comadres" con meriendas campestres colectivas, complementada en agosto con los tradicionales encierros a caballo en su recinto fortificado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90003','fiesta','Feria y Fiesta de la Fresa de Abegondo','Gastronómica y Feria Local. Se celebra en Mayo. Celebración de notable arraigo local y comarcal en las Mariñas Coruñesas, enfocada en la promoción de la fresa local mediante degustaciones gratuitas, concursos de postres, música folclórica y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90184','fiesta','Fiestas de la Virgen del Carmen de Milladoiro y Fiestas de San José de Bertamiráns','Patronal y Urbana. Se celebra en Agosto y Mayo. Festejos que registran una altísima afluencia comarcal debido al peso demográfico de sus dos núcleos urbanos, destacando por sus potentes verbenas con las principales orquestas de Galicia y torneos deportivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90185','fiesta','Fiestas del Santísimo Cristo de la Santa Cruz','Patronal y Religiosa. Se celebra en Mayo. Celebración de carácter estrictamente local adaptada a la baja densidad del municipio, centrada en la misa solemne, la procesión religiosa tradicional y una pequeña verbena musical nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90001','fiesta','Fiesta de las Alfombras Florales de Ares','Etnográfica y Religiosa. Se celebra en Junio (Fin de semana del Corpus Christi). Fiesta de Interés Turístico de Galicia de extraordinaria belleza plástica. Los vecinos trabajan durante toda la noche para cubrir un kilómetro de calles costeras con espectaculares mosaicos de pétalos y sal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90002','fiesta','Fiestas de Santiago Apóstol y Feria Histórica de Arteixo','Patronal y Recreación Histórica. Se celebra en Julio y Octubre. Hito festivo de gran peso provincial debido a su proximidad industrial, donde destaca su feria histórica de época con mercados artesanos tradicionales, pasacalles folclóricos y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90186','fiesta','Fiesta del Queso de Arzúa (Festa do Queixo)','Gastronómica y Cultural. Se celebra en Marzo. Fiesta de Interés Turístico de Galicia y uno de los hitos gastronómicos más masivos de la provincia, que atrae a miles de visitantes para degustar el queso con D.O.P. Arzúa-Ulloa combinando el mercado con un potente festival de música rock y folk.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90187','fiesta','Fiestas de San Vicente y Fiesta del Emigrante','Patronal y Retorno Estival. Se celebra en Enero y Agosto. Festejos rurales centrados en el reencuentro de las familias que emigraron, dinamizados mediante la tradicional churrascada popular, orquestas tradicionales de baile y actividades infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90003','fiesta','Fiestas de San Salvador y Fiesta de la Empanada','Patronal y Gastronómica. Se celebra en Agosto. Celebración de arraigo local en la comarca de Betanzos, caracterizada por la degustación de empanadas artesanales gallegas en el campo de la fiesta, folclore tradicional y verbenas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01003','fiesta','Fiestas de San Roque y el Lanzamiento del Globo de Betanzos','Etnográfica, Tradicional y Fluvial. Se celebra en Agosto. Fiesta de Interés Turístico de Galicia de enorme valor tradicional; destaca el espectacular lanzamiento del globo de papel más grande del mundo y los tradicionales viajes fluviales en barca hacia "Os Caneiros".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90188','fiesta','Festival de la Luz','Cultural y Etnográfica. Se celebra en Septiembre. Hito cultural y social con gran proyección provincial organizado en un entorno rural y agrícola, que aúna grandes conciertos benéficos, demostraciones etnográficas, mercado artesano y ecología.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01004','fiesta','Fiestas de Verano de Boiro','Patronal y Marítima. Se celebra en Julio. Grandes festejos en la ría de Arousa con amplio tirón comarcal, caracterizados por sus espectaculares castillos de fuegos artificiales sobre el mar, conciertos de primer nivel y regatas tradicionales de traineras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90189','fiesta','Fiesta de la Filloa de Lestedo','Gastronómica y Etnográfica. Se celebra en Febrero/Marzo (Domingo de Piñata). Fiesta de Interés Turístico de Galicia vinculada a los tradicionales carnavales de los "Xenerais da Ulla", famosa por su máquina artesanal gigante que elabora miles de filloas por hora para los asistentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90190','fiesta','Romería de Santa Minia','Romería y Religiosa. Se celebra en Septiembre. Hito religioso de gran relevancia en el entorno compostelano; miles de peregrinos acuden a venerar las reliquias de la santa, complementado con un gran mercado tradicional de puestos ambulantes y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90004','fiesta','Romería de San Fins de Castro','Romería y Etnográfica. Se celebra en Agosto. Famosa romería gallega celebrada en un robledal, conocida por la tradición etnográfica de "O Berro", donde los romeros gritan juntos para pedir curación, seguida de una gran merienda campestre con gaiteros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90005','fiesta','Fiestas de Santa Marta','Patronal y Playera. Se celebra en Julio. Festejos estivales muy concurridos gracias a la afluencia de turistas en la playa de Madalena, combinando competiciones náuticas, sardiñadas populares en el pinar y orquestas musicales de renombre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01005','fiesta','Muestra del Encaje de Camariñas y Fiestas del Carmen','Etnográfica, Artesanal y Marítima. Se celebra en Abril (Semana Santa) y Julio. La Muestra del Encaje es Fiesta de Interés Turístico de Galicia y un hito internacional de artesanía viva; se complementa en julio con la emotiva procesión marítima de la patrona de los marineros en plena Costa da Morte.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90191','fiesta','Festival Rock in Cambre y Fiestas del Santísimo Cristo de Cambre','Cultural y Patronal. Se celebra en Agosto. Reconocimiento a nivel provincial por su veterano festival de rock gratuito al aire libre, integrado dentro de los festejos patronales de la villa que atraen a numeroso público joven de la comarca coruñesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01006','fiesta','Fiestas de San Juan de Carballo','Patronal y Etnográfica. Se celebra en Junio. Gran festividad de la capital de Bergantiños, caracterizada por sus espectaculares "cacharelas" o hogueras de San Juan, el tradicional concurso de alfombras florales, desfiles de carrozas y conciertos masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15901','fiesta','Fiesta de la Virgen del Carmen y Danza de Arcos','Marítima y Etnográfica. Se celebra en Julio. Destacado festejo marinero en el norte de la provincia, famoso por su ancestral "Danza de Arcos" ejecutada por los marineros en el puerto y la multitudinaria procesión de barcos engalanados por la ría.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01007','fiesta','Fiestas de San Mamede y Fiesta de la Bicicleta de Carnota','Patronal y Deportiva/Local. Se celebra en Agosto. Celebración de verano muy ligada al turismo de costa, estructurada en torno a pasacalles con bandas de gaitas, competiciones deportivas tradicionales frente a su famoso hórreo y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15022','fiesta','Fiestas de la Virgen del Mar y Fiesta del Percebe','Patronal y Gastronómica. Se celebra en Agosto. Festividad costera con gran afluencia provincial, destacando su exaltación del percebe extraído de los acantilados locales y las procesiones marítimas que acompañan a la patrona de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15023','fiesta','Fiestas de la Virgen de la Junquera','Patronal y Religiosa. Se celebra en Agosto. *. Gran referente festivo y comercial de la Costa da Morte, famoso por la solemne procesión de la virgen, sus espectaculares espectáculos pirotécnicos nocturnos y grandes verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15024','fiesta','Fiestas de la Virgen de la Saleta y Fiesta de la Juventud','Patronal y Local. Se celebra en Septiembre. Festejos locales marcados por las celebraciones litúrgicas en la ermita, torneos vecinales de cartas y música de orquestas gallegas para amenizar las veladas de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15025','fiesta','Fiestas de San Martiño','Patronal. Se celebra en Noviembre. Pequeña festividad de ámbito estrictamente rural e interior, centrada en la tradicional misa, magostos locales de castañas y música tradicional interpretada por agrupaciones del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15027','fiesta','Fiestas de Nuestra Señora de los Remedios','Patronal. Se celebra en Septiembre. Celebración puramente vecinal adaptada al entorno rural del interior coruñés, con oficios religiosos, sesión vermú tradicional y pequeñas verbenas populares de orquestas de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15028','fiesta','Feria Medieval de Corcubión','Recreación Histórica y Cultural. Se celebra en Julio. Hito histórico que transforma el casco antiguo de la villa marítima en un mercado de época medieval vivo, atrayendo numeroso público con torneos, teatro de calle y gastronomía marinera antigua.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15029','fiesta','Fiesta de la Patata de Coristanco (Festa da Pataca)','Gastronómica y Etnográfica. Se celebra en Septiembre. Hito etnográfico y agrícola con reconocimiento provincial y autonómico que homenajea el cultivo estrella de la zona mediante desfiles de tractores engalanados con patatas, concursos culinarios y folklore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01001','fiesta','Fiestas de María Pita y las Hogueras de San Juan','Patronal, Etnográfica y Cultural. Se celebra en Agosto y Junio. Su noche de San Juan es Fiesta de Interés Turístico Internacional, reuniendo a más de cien mil personas en las playas de Riazor y Orzán cubiertas de hogueras. Las Fiestas de María Pita llenan agosto de grandes conciertos globales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15031','fiesta','Fiestas de la Virgen del Burgo y Festival BurgoRock','Patronal y Cultural. Se celebra en Julio. Celebración de la comarca urbana coruñesa que destaca por las actividades musicales en el paseo marítimo de O Burgo, conciertos juveniles al aire libre y grandes orquestas de la escena gallega.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15032','fiesta','Fiesta del Queso de Curtis','Gastronómica. Se celebra en Abril. Festejos tradicionales vinculados a la feria ganadera de la zona, dedicados a la promoción y comercialización del queso de la Denominación de Origen Protegida Arzúa-Ulloa y quesos artesanales locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15033','fiesta','Fiestas de la Virgen de la Leche','Patronal y Religiosa. Se celebra en Agosto. Celebración de arraigo estrictamente local en las tierras del Sar, caracterizada por la procesión litúrgica tradicional de la virgen, comidas campestres vecinales y orquestas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15034','fiesta','Fiestas de la Virgen de la O de Olveira','Patronal. Se celebra en Diciembre/Agosto. Festejos rurales locales dinamizados por el paso del Camino de Santiago, centrados en el folclore tradicional de gaiteros de la comarca, comidas de convivencia y música de orquesta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15035','fiesta','Fiestas de San Salvador y Carnaval de Fene','Carnaval y Patronal. Se celebra en Febrero/Marzo y Agosto. Festejos con notable tirón en la comarca de Ferrolterra debido a la gran tradición de su desfile de comparsas de carnaval en el "Miércoles de Ceniza" y sus animadas orquestas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15036','fiesta','Semana Santa de Ferrol y Fiestas de San Julián','Religiosa, Marítima y Patronal. Se celebra en Marzo/Abril y Agosto. Su Semana Santa es Fiesta de Interés Turístico Internacional, caracterizada por el extraordinario valor artístico y militar de sus procesiones solemnes coordinadas por cofradías centenarias de ambiente marinero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01011','fiesta','Semana Santa de Fisterra y Fiesta del Longueirón','Religiosa, Gastronómica y Etnográfica. Se celebra en Marzo/Abril y Agosto. Su Semana Santa es Fiesta de Interés Turístico de Galicia, famosa por la sobrecogedora representación popular de la Resurrección a los pies del faro del Fin del Mundo, combinada con su feria gastronómica estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15038','fiesta','Fiestas de San Julián y Fiesta de la Tercera Edad','Patronal y Social. Se celebra en Enero y Agosto. Pequeña festividad rural e íntima adaptada a la baja densidad del pueblo, estructurada en torno a la misa, comidas vecinales de hermandad y música tradicional local de gaitas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90192','fiesta','Fiestas de San Lorenzo','Patronal. Se celebra en Agosto. Celebración de ámbito puramente rural centrada en la solemne procesión parroquial, campeonatos de juegos tradicionales de cartas entre vecinos y pequeñas orquestas musicales de fin de semana). Hemos alcanzado la letra I de la Provincia de A Coruña de la Comunidad Autónoma de Galicia, completando el bloque solicitado. ¿Deseas que continuemos de inmediato con el siguiente bloque de municipios que arranca con la letra L y la letra M (Laxe, Lousame, Malpica de Bergantiños, Mañón, Mazaricos, Melide, etc.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90006','fiesta','Fiestas de Nuestra Señora de la Atalaya y el Simulacro del Naufragio','Marítima, Religiosa y Etnográfica. Se celebra en Agosto. Fiesta de Interés Turístico de Galicia; destaca la sobregogedora representación del naufragio donde los marineros escenifican el rescate de los náufragos que caminan descalzos hacia la Virgen del Carmen.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15042','fiesta','Fiestas de San Juan de Lousame','Patronal. Se celebra en Junio. Festejos de ámbito estrictamente local con las tradicionales hogueras o cacharelas de San Juan, pasacalles folclóricos y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15043','fiesta','Fiestas del Mar de Malpica','Marítima y Romería. Se celebra en Agosto. Gran relevancia comarcal en la Costa da Morte, famosa por la vistosa procesión marítima hacia las Islas Sisargas, sardiñadas populares en el puerto y orquestas gallegas de primer nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15044','fiesta','Fiestas de la Virgen del Carmen de O Barqueiro','Marítima y Patronal. Se celebra en Julio. Celebración costera en el extremo norte de la provincia, caracterizada por la procesión marítima por la ría de O Barqueiro, música tradicional de gaitas y verbenas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15045','fiesta','Fiesta de la Fervenza y Fiestas de San Juan','Etnográfica y Agrícola. Se celebra en Julio. Festejos que ensalzan la cultura ganadera de la zona y su patrimonio natural, potenciados con ferias de productos artesanos, degustaciones de carne local y música folk.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90842','fiesta','Fiestas de San Roque de Melide','Patronal y Cultural. Se celebra en Agosto. Hito festivo en el centro de Galicia y punto neurálgico del Camino de Santiago, reuniendo a miles de peregrinos y vecinos en torno a sus conciertos, folclore y sus famosas pulperías tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15047','fiesta','Fiestas de la Virgen de la Albariña','Romería y Religiosa. Se celebra en Agosto. Romería típicamente rural del interior coruñés orientada al reencuentro estival, con misas rezadas, tradicionales almuerzos campestres familiares en los robledales y música de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15048','fiesta','Fiestas de San Pedro y Fiesta de la Cebolla de Miño','Gastronómica y Patronal. Se celebra en Junio y Agosto. Festejos estivales muy concurridos por el turismo playero de la ría de Betanzos, donde destaca el mercado artesanal de ristras de cebollas cultivadas en la zona y sus animadas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15049','fiesta','Festival Irmandiño de Moeche','Recreación Histórica y Folk. Se celebra en Agosto. Hito etnográfico que conmemora las Revueltas Irmandiñas del siglo XV con el tradicional "asalto" simbólico con antorchas al Castillo de Moeche, acompañado de un potente festival de música folk.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15050','fiesta','Romería de la Virgen de la Cela','Romería y Religiosa. Se celebra en Julio. Festejos en el entorno de las Fragas do Eume, centrados en la devoción a la virgen en el monasterio histórico, procesiones rurales de penitentes y sesiones vermú de carácter vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15051','fiesta','Fiesta del Pulpo de Mugardos (Festa do Polbo)','Gastronómica. Se celebra en Julio. Fiesta de Interés Turístico de Galicia; miles de personas colapsan el muelle para degustar el pulpo preparado "a la mugardesa" —con salsa de pimientos y cebolla— en un gran ambiente de charangas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15053','fiesta','Fiestas de San Pedro y Fiesta del Carmen','Marítima y Tradicional. Se celebra en Junio y Julio. Gran repercusión comarcal en la ría de Muros y Noia, caracterizada por la espectacular danza de arcos tradicional, procesiones marítimas de barcos de pesca engalanados y verbenas en su casco histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01013','fiesta','Romería de Nuestra Señora de la Barca','Romería, Religiosa y Etnográfica. Se celebra en Septiembre. Fiesta de Interés Turístico de Galicia y una de las romerías marianas más multitudinarias e iconográficas del país norteño, famosa por el rito de pasar bajo la Pedra de Abalar y la Pedra dos Cadrís.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15054','fiesta','Fiesta del Pimiento de Couto y Día de Narón','Gastronómica y Cultural. Se celebra en Julio y Noviembre. Hito comarcal en Ferrolterra centrado en la promoción del pimiento local con I.G.P. mediante degustaciones multitudinarias, conciertos populares gratuitos y grandes espectáculos de orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15055','fiesta','Fiesta del Pan de Neda','Gastronómica y Etnográfica. Se celebra en Septiembre. Gran arraigo provincial que homenajea la histórica tradición panadera del municipio desde el siglo XVI, con mercadillos de empanadas, dulces, bollos artesanales y música folclórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15056','fiesta','Feria del Románico de Negreira y Fiestas de San Cristóbal','Recreación Histórica y Patronal. Se celebra en Agosto y Julio. Celebración de escala comarcal en la comarca de Barcala que transforma las inmediaciones del Pazo de Cotón en un mercado medieval con torneos de caballeros, cetrería y teatro ambulante.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01014','fiesta','Fiestas de San Bartolomé y Feria Medieval de Noia','Patronal, Recreación Histórica y Feria. Se celebra en Agosto y Julio. Gran festejo de la ría noiesa que destaca por sus espectaculares conciertos de pop-rock nacional, las tradicionales carreras de caballos en la playa y una de las ferias medievales más cuidadas de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15058','fiesta','Alfaroleiros (Feria de Alfarería Tradicional) y Fiestas de Santaia','Etnográfica, Artesanal y Urbana. Se celebra en Agosto. Relevancia provincial debido a Alfaroleiros, la feria de cerámica tradicional más importante del norte peninsular que reúne a maestros alfareros de España y Portugal en Santa Cruz.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90193','fiesta','Fiestas de Santa María de Ordes','Patronal. Se celebra en Agosto. Festejos locales de gran concurrencia juvenil en la comarca ordense, conocidos por contratar a las mejores formaciones de la orquesta gallega y por sus actividades deportivas veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15060','fiesta','Fiesta de la Trucha de Oroso (Festa da Troita)','Gastronómica. Se celebra en Mayo. Festejo de gran atractivo comarcal en Sigüeiro que congrega a miles de personas en torno al concurso de pesca en el río Tambre, degustaciones populares de truchas fritas y verbenas musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15061','fiesta','Festival Internacional del Mundo Celta de Ortigueira','Cultural, Folk y Etnográfica. Se celebra en Julio. Fiesta de Interés Turístico Internacional; es uno de los mayores festivales de música folk del planeta, congregando a decenas de miles de personas en un macrocampamento en el pinar de Morouzos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15062','fiesta','Fiestas de San Campio de San Ourente','Romería y Religiosa. Se celebra en Julio. Famosa romería milagrera a la que acuden devotos de toda la provincia para pedir sanación mental, caracterizada por las misas continuas, puestos ambulantes de exvotos y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15902','fiesta','Fiestas de Nuestra Señora del Carmen de Oza','Patronal y Rural. Se celebra en Julio. Festejos rurales centrados en las verbenas populares de orquestas locales, pasacalles matinales con grupos de gaitas de la comarca y la clásica merienda vecinal en el campo de la fiesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15064','fiesta','Feria del Vino de Paderne (Mostra del Viño)','Enológica y Gastronómica. Se celebra en Junio. Festejo dedicado a la exaltación de los vinos de la tierra, especialmente el "Blanco Legítimo", complementado con puestos de empanada gallega, pulpo á feira y música folclórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15065','fiesta','Fiestas de la Pascua y Fiesta del Pimiento de Padrón (en Herbón)','Patronal, Feria Gastronómica y Etnográfica. Se celebra en Marzo/Abril y Agosto. Fiesta de Interés Turístico de Galicia; las fiestas de Pascua atraen multitudes de toda la provincia por sus ferias ganaderas y caballares, mientras que en agosto Herbón celebra su mundialmente conocido pimiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15066','fiesta','Fiesta del Gallo de Piñeiro (Festa do Galo de Piñeiro)','Gastronómica y Etnográfica. Se celebra en Agosto. Festejo de notable éxito comarcal centrado en la recuperación de la raza avícola autóctona, con exposiciones de ejemplares vivos, degustaciones de guisos tradicionales y concentración de motos antiguas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01002','fiesta','Fiestas del Nazareno y Procesión de los Ataúdes','Religiosa, Romería y Etnográfica. Se celebra en Septiembre. Fiesta de Interés Turístico de Galicia de gran misticismo; los penitentes que se han salvado de una enfermedad grave desfilan detrás de la imagen del Nazareno ofreciendo y portando sus propios ataúdes abiertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90194','fiesta','Fiesta de la Barquiña de Ponteceso','Patronal y Cultural. Se celebra en Septiembre. Festejos en Bergantiños en honor a la Virgen de la Barquiña, caracterizados por grandes orquestas de verbena, certámenes poéticos dedicados a Eduardo Pondal y pasacalles folclóricos de gaitas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01017','fiesta','Fiestas de las Peras y Fiestas de San Nicolás','Etnográfica, Tradicional y Fluvial. Se celebra en Septiembre. Hito etnográfico provincial de gran arraigo; destaca el desfile de los históricos gigantes y cabezudos "Galán y Tarta", las cucañas marítimas en el río Eume y el concurso tradicional de las peras gigantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90007','fiesta','Fiesta del Carmen y Fiesta de la Horta de Portosín','Marítima y Gastronómica. Se celebra en Septiembre y Agosto. Festejos marineros de la ría de Muros y Noia, que destacan por la espectacular procesión marítima de barcos engalanados y sardiñadas populares que congregan a numerosos turistas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01018','fiesta','Fiestas de Nuestra Señora de la Guadalupe y el canto de "A Rianxeira"','Marítima, Etnográfica y Religiosa. Se celebra en Septiembre. Fiesta de Interés Turístico de Galicia. Su momento cumbre y de máxima emoción es la procesión nocturna de bengalas por el puerto donde miles de personas cantan al unísono el himno de "A Rianxeira".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15073','fiesta','Fiesta de la Dorna de Ribeira','Etnográfica, Marinera y Humorística. Se celebra en Julio. Fiesta de Interés Turístico de Galicia; espectacular y divertidísima festividad marinera donde las peñas se visten de marineros antiguos y compiten en el puerto con artefactos flotantes artesanales sin motor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15074','fiesta','Fiestas de San Isidro Labrador','Patronal y Agrícola. Se celebra en Mayo. Pequeños festejos rurales centrados en la misa del campo, desfiles locales de tractores decorados por los agricultores del municipio y música folclórica con gaita gallega.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15075','fiesta','Fiestas de San Roque y Fiesta de la Sardina de Sada','Patronal y Gastronómica. Se celebra en Agosto. Gran atractivo estival en las Mariñas Coruñesas, famoso por su sardiñada popular masiva gratuita en la playa de las Delicias, regatas de vela ligera y conciertos musicales nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15076','fiesta','Feria de San Sadurniño','Feria Agrícola y Ganadera. Se celebra en Agosto. Feria tradicional dedicada a la exhibición de maquinaria agrícola, ganado autóctono, mercado de hortalizas locales y música de bandas populares gallegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15077','fiesta','Fiestas de San Pedro de Santa Comba','Patronal. Se celebra en Junio. Festejos en la comarca del Jallas con gran afluencia de comarcas vecinas, caracterizados por la contratación de espectáculos pirotécnicos de renombre y verbenas con las grandes orquestas gallegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15078','fiesta','Fiestas del Apóstol Santiago y Fiestas de la Ascensión','Patronal, Cultural y Religiosa. Se celebra en Julio y Mayo. Fiesta de Interés Turístico Internacional; epicentro espiritual y cultural de Galicia. Destacan los espectaculares fuegos del Apóstol con la quema de la fachada gótica efímera en la Plaza del Obradoiro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15079','fiesta','Fiestas de San Pedro de Santiso','Patronal y Rural. Se celebra en Junio. Pequeña celebración rural íntima centrada en los oficios religiosos parroquiales, sesión vermú tradicional animada por un dúo musical y juegos tradicionales infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15080','fiesta','Fiesta de la Trucha de Sobrado dos Monxes','Gastronómica. Se celebra en Julio. Festejo gastronómico comarcal en el entorno de su famoso monasterio cisterciense, con degustaciones de truchas preparadas de diversas formas, folklore gallego y puestos de artesanía local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15081','fiesta','Fiestas de Santiago Apóstol de As Somozas','Patronal. Se celebra en Julio. Festejos locales típicamente vecinales estructurados en torno a las orquestas gallegas de fin de semana, churrascadas populares y torneos de cartas en el campo de la fiesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15082','fiesta','Feria de San Martiño de Francos','Feria Ecuestre y Etnográfica. Se celebra en Noviembre. Hito etnográfico de enorme tradición en el área de Santiago de Compostela, siendo una de las ferias de compraventa de caballos más antiguas y populosas de Galicia, con degustación de pulpo en las pulperías efímeras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15083','fiesta','Fiestas de San Antolín de Toques','Patronal y Rural. Se celebra en Septiembre. Celebración de ámbito estrictamente vecinal y rural, caracterizada por la misa en su joya románica prerrománica, pasacalles de gaitas y una pequeña orquesta musical nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90843','fiesta','Fiestas de San Juan de Tordoia','Patronal. Se celebra en Junio. Festejos populares e íntimos adaptados a la baja densidad del término municipal, centrados en el encendido de hogueras de San Juan, orquestas locales y campeonatos de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15085','fiesta','Fiesta del Toro de Touro y Carnaval de los "Xenerais da Ulla"','Etnográfica y Carnaval. Se celebra en Febrero/Marzo. Hito etnográfico tradicional compartido en la cuenca del Ulla, famoso por los "Generales" a caballo vestidos con uniformes militares antiguos que se enfrentan en vistosos e ingeniosos duelos dialécticos satíricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15086','fiesta','Fiestas de San Cristóbal de Trazo','Patronal. Se celebra en Julio. Festejos rurales centrados en la tradicional bendición automovilística en honor al santo patrón, sesión vermú popular prolongada y orquestas gallegas de baile por la noche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90195','fiesta','Fiestas de San Cristóbal de Bembibre','Patronal. Se celebra en Julio. *. Festejos de escala local y comarcal con gran ambiente en su tradicional desfile de camiones y coches engalanados, competiciones hípicas de resistencia y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15087','fiesta','Fiestas del Océano y Pantín Classic Pro','Deportiva, Cultural y Costera. Se celebra en Agosto/Septiembre. Hito deportivo e internacional absoluto por la celebración del Pantín Classic, una de las pruebas de surf más longevas y prestigiosas de Europa que llena la playa de Pantín de música, puestos de comida y ambiente global.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15089','fiesta','Fiesta del Vino del Ulla (Festa do Viño da Ulla) y Carnaval de los Generales','Enológica, Gastronómica y Etnográfica. Se celebra en Abril y Febrero. Destacado hito enológico comarcal dedicado a la promoción de los vinos tintos y blancos de la subzona de la D.O. Rías Baixas, amenizado con catas, folclore y los famosos escarceos de los Generales del Ulla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90844','fiesta','Fiestas de San Pedro de Vilarmaior','Patronal y Rural. Se celebra en Junio. Pequeña festividad rural menor adaptada a la baja demografía del municipio, centrada en los oficios litúrgicos tradicionales, tiradas de fuegos artificiales de fogueo y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15090','fiesta','Fiestas de Santa María de Vilasantar','Patronal. Se celebra en Agosto. Celebración puramente vecinal y familiar orientada al retorno de veraneantes, dinamizada con comidas campestres colectivas, juegos infantiles en el campo de la fiesta y música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15092','fiesta','Asalto al Castillo de Vimianzo y Fiestas de Verano','Recreación Histórica y Etnográfica. Se celebra en Julio y Agosto. Gran repercusión provincial por la recreación festiva del asalto de los campesinos del siglo XV a la fortaleza medieval, donde los participantes se tiñen de pintura simulando una batalla pacífica, seguido de conciertos folk.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15093','fiesta','Festa da Carballeira de Zas','Cultural, Folk y Etnográfica. Se celebra en Agosto. Fiesta de Interés Turístico de Galicia; un festival de música folk folk de enorme tradición en la Costa da Morte celebrado en un robledal centenario, atrayendo a miles de jóvenes para acampar y disfrutar de bandas celtas internacionales). Hemos completado de manera íntegra todos los municipios de la Provincia de A Coruña, llegando satisfactoriamente hasta la letra Z. Siguiendo el orden jerárquico establecido por el proyecto para la Comunidad de Galicia, corresponde avanzar al siguiente bloque territorial. ¿Deseas que comencemos de inmediato con la Provincia de Lugo, iniciando por la letra A (Abadín, Alfoz, Antas de Ulla, Baleira, Barreiros, Becerreá, etc.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90542','fiesta','Feria de Gontán y Fiestas de Santa María','Feria Agrícola, Ganadera y Patronal. Se celebra en Septiembre. Tradicional feria ganadera de gran arraigo en la comarca de la Tierra Llana, conocida por la compraventa de ganado caballar y vacuno, exposición de maquinaria y degustación de pulpo á feira.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90543','fiesta','Mercado Medieval de Alfoz y Fiestas de San Pedro','Recreación Histórica y Patronal. Se celebra en Julio. Festejo comarcal de notable éxito que se desarrolla en el entorno del Castillo de Castro de Ouro, donde se recrea la época del Mariscal Pardo de Cela con torneos, mercados de artesanía y trajes de época.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90544','fiesta','Fiesta del Pan de Antas de Ulla y Fiestas de San Juan','Gastronómica y Patronal. Se celebra en Mayo y Junio. Celebración de la comarca de Ulloa dedicada a la exaltación de su pan artesanal y productos agrícolas locales, complementada con muestras folclóricas gallegas y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90545','fiesta','Fiestas de San Cristóbal de Cádavo','Patronal y Romería. Se celebra en Julio. Festejos de arraigo estrictamente local marcados por la bendición tradicional de vehículos, comidas campestres vecinales en los valles orientales y verbenas con orquestas de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90040','fiesta','Fiestas de San Bartolo y Fiesta de la Tortilla de Barreiros','Patronal y Gastronómica. Se celebra en Agosto. Celebración estival de gran afluencia costera en la Mariña Lucense, potenciada por el turismo de playa, con concursos de tortillas artesanales, sardiñadas populares y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28001','fiesta','Feria del Ternerito de los Ancares (Feira del Cachafo) y Fiestas de San Juan','Feria Ganadera, Gastronómica y Patronal. Se celebra en Mayo y Junio. Hito festivo de la montaña lucense de relieve comarcal, centrado en la puesta en valor de la excelente carne de Ternera Gallega Suprema, con mercados agrarios y degustaciones masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90546','fiesta','Belén Electrónico de Begonte y Fiestas de San Pedro','Etnográfica, Religiosa y Patronal. Se celebra en Diciembre/Enero y Junio. Declarada Fiesta de Interés Turístico de Galicia debido a su célebre Belén Electrónico articulado y animado, un hito etnográfico navideño de gran calado provincial y autonómico desde 1972.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90547','fiesta','Fiestas de San Gil y Fiesta de la Filoxera','Patronal y Etnográfica. Se celebra en Septiembre. Festejos locales en la comarca de Lemos vinculados a la cultura vitivinícola, estructurados en torno a procesiones tradicionales, cenas vecinales comunitarias y pequeñas orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90548','fiesta','Fiesta de la Carne en Caldeiro de Castro de Carballedo','Gastronómica. Se celebra en Abril. Festejo gastronómico local de fuerte arraigo que exalta la preparación tradicional de la carne cocinada al estilo de los antiguos feriantes, acompañado de música de gaitas y mercado artesano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90549','fiesta','Fiestas de San Roque y la Virgen de la Dulce Nombre','Patronal. Se celebra en Agosto. Celebración de corte tradicional en la Tierra Llana, con vistosos desfiles de carrozas vecinales, misas solemnes en el casco histórico fortificado y bailes de sesión vermú con agrupaciones locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90550','fiesta','Fiestas de Santiago Apóstol y Feria de Artesanía','Patronal y Feria Artesanal. Se celebra en Julio. Festejos comarcales dinamizados por el Camino Primitivo, que combinan las celebraciones litúrgicas con un mercado de artesanía tradicional, demostraciones de oficios antiguos y verbenas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90551','fiesta','Feria de San Román de Cervantes','Feria Ganadera y Etnográfica. Se celebra en Septiembre. Festejo tradicional de la alta montaña de Os Ancares, donde se dan cita ganaderos de la sierra para comerciar con razas autóctonas, complementado con cantos de taberna y folklore de montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90041','fiesta','Fiesta de la Maruxaina de San Ciprián','Etnográfica, Mitológica y Marinera. Se celebra en Agosto (Segundo sábado). Fiesta de Interés Turístico de Galicia de extraordinaria singularidad. Los vecinos se visten de marineros antiguos y juzgan en la playa a la "Maruxaina", una ninfa marina mítica, en una noche iluminada por antorchas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27016','fiesta','Fiestas Patronales de Chantada y Folión de Carros','Etnográfica, Tradicional y Vinícola. Se celebra en Agosto. Declarada Fiesta de Interés Turístico de Galicia; su histórico desfile del "Folión de Carros" exhibe artísticas plataformas tiradas por bueyes que recrean minuciosamente oficios tradicionales e historias agrarias de la Ribeira Sacra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90552','fiesta','Fiestas de San José y Fiesta de la Juventud','Patronal. Se celebra en Mayo. Festejos vecinales de ámbito rural e interior centrados en oficios religiosos parroquiales, campeonatos de billarda o tute entre peñas y pequeñas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90553','fiesta','Feria y Fiesta de la Virgen del Monte','Romería, Religiosa y Feria Local. Se celebra en Septiembre. Notable romería tradicional en la Tierra Llana, donde los fieles acuden al santuario mariano a cumplir promesas, combinando la fe con grandes carpas de pulperías artesanales y música folclórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27017','fiesta','Fiesta de la Castaña del Courel (Festa da Castaña)','Gastronómica, Etnográfica y Forestal. Se celebra en Noviembre (Alterna sede con Quiroga). Fiesta de Interés Turístico de Galicia celebrada en plena sierra del Courel, que homenajea el fruto del castaño mediante magostos gigantes y gratuitos, degustación de vino nuevo y música tradicional gallega.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28004','fiesta','Feria del Butelo de A Fonsagrada','Gastronómica y Etnográfica. Se celebra en Febrero (Fin de semana de Carnaval). Fiesta de Interés Turístico de Galicia de gran empaque; es la gran cita de la montaña lucense dedicada a ensalzar su embutido rey, el butelo, atrayendo a miles de visitantes con degustaciones masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27019','fiesta','Fiesta del Carmen y Alfombras Florales de Foz','Marítima, Religiosa y Playera. Se celebra en Julio y Agosto. Festejos playeros de gran tirón estival en la costa cantábrica lucense. Destaca el esmero vecinal en la confección nocturna de alfombras de flores para la procesión de la patrona de los marineros y grandes conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27020','fiesta','Fiesta del Queso de Friol y Pan de Ousá','Gastronómica. Se celebra en Marzo. Reconocimiento provincial y autonómico destacado por la enorme comercialización de quesos artesanales y hogazas de pan locales, amenizado con certámenes folclóricos, charangas y orquestas gallegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27022','fiesta','Fiesta de San Juan y Fiesta de la Torta de Guitiriz','Patronal y Gastronómica. Se celebra en Junio. Festejos tradicionales que ponen en valor su famoso postre artesanal de maíz, la torta de Guitiriz, complementando las hogueras de San Juan con festivales folclóricos de música gallega.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27023','fiesta','Fiesta del Pimiento de Mougán','Gastronómica. Se celebra en Agosto. Hito gastronómico comarcal consagrado a la promoción del pimiento local con Indicación Geográfica Protegida, con raciones populares gratuitas, música tradicional y animadas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27024','fiesta','Fiestas de la Virgen de los Remedios y San Pedro','Patronal y Romería. Se celebra en Septiembre. Celebración de arraigo netamente vecinal en la montaña de la sierra, centrada en la tradicional misa, la sesión vermú familiar y competiciones locales de juegos populares de cartas). Hemos alcanzado con éxito la letra I de la Provincia de Lugo en la Comunidad Autónoma de Galicia, completando estrictamente el progreso solicitado. ¿Continuamos de inmediato con el siguiente bloque de municipios que arranca con la letra L y la letra M (Láncara, Lourenzá, Lugo, Meira, Mindoniedo, Monforte de Lemos, etc.)?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27026','fiesta','Fiestas de San Juan de A Pobra de San Xiao y Feria de la Ternera Gallega','Patronal, Ganadera y Gastronómica. Se celebra en Junio. Celebración de relieve comarcal en los valles orientales de la provincia que fusiona las tradicionales hogueras de San Juan con un consolidado concurso-exposición ganadero que ensalza el vacuno autóctono.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90554','fiesta','Fiesta de la Faba de Lourenzá (Festa da Faba)','Gastronómica y Etnográfica. Se celebra en Octubre. Fiesta de Interés Turístico de Galicia que rinde homenaje a su hito agrícola con Indicación Geográfica Protegida, dinamizando el hermoso valle con mercados micológicos, catas populares, desfiles folclóricos y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','fiesta','Fiestas de San Froilán y Fiesta del Arde Lucus','Patronal, Recreación Histórica y Etnográfica. Se celebra en Octubre y Junio. Ambas son Fiestas de Interés Turístico Nacional; San Froilán destaca por su masiva feria etnográfica otoñal y las casetas del pulpo, mientras que el Arde Lucus revive de forma masiva el pasado romano a los pies de la muralla de la UNESCO.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27029','fiesta','Fiesta del Malla de Meira y Fiestas de la Virgen de la Asunción','Etnográfica, Histórica y Patronal. Se celebra en Agosto. Fiesta de Interés Turístico de Galicia; un excepcional hito etnográfico donde los vecinos recrean los antiguos trabajos agrícolas de la separación del grano y la paja usando maquinaria tradicional e histórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27031','fiesta','Fiestas Patronales en honor a la Virgen de Montserrat','Patronal y Cultural. Se celebra en Agosto. Gran festividad y hito de la Ribeira Sacra lucense, caracterizada por sus espectaculares conciertos multitudinarios en la explanada de la Compañía, desfiles hípicos tradicionales y fuegos artificiales desde el castillo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27032','fiesta','Feria de Santos de Monterroso','Feria Agrícola, Ganadera y Etnográfica. Se celebra en Noviembre (Día de Todos los Santos). Fiesta de Interés Turístico de Galicia; una de las ferias de mercado agrario y ganadero más masivas y multitudinarias del norte peninsular, documentada históricamente desde el año 1450.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27033','fiesta','Feria del Potro de Muras y Fiestas de San Pedro','Feria Ganadera y Patronal. Se celebra en Septiembre. Festejos en la sierra de la Jistrera enfocados en la puesta en valor del caballo de Pura Raza Gallega, con exhibiciones de monte, degustación de carne de potro y folklore tradicional de gaitas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27034','fiesta','Fiesta de la Androlla y Fiestas de Nuestra Señora de los Dolores','Gastronómica, Etnográfica y Patronal. Se celebra en Febrero (Domingo de Carnaval) y Septiembre. Hito festivo de la alta montaña de los Ancares, célebre por la exaltación culinaria de su embutido tradicional ahumado, dinamizado con cantos de taberna tradicionales y mercados de quesos de la sierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27035','fiesta','Fiestas de la Virgen de la Veiga','Patronal y Vinícola. Se celebra en Agosto. Pequeña celebración rural íntima adaptada a la baja densidad del municipio más pequeño de Galicia, centrada en los actos religiosos parroquiales y la promoción de los viñedos locales de montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90845','fiesta','Fiestas de la Virgen del Carmen','Patronal y Retorno Estival. Se celebra en Agosto. Festejos de montaña en el acceso gallego que aprovechan el regreso de los emigrantes en verano, ofreciendo verbenas en la plaza de la localidad, juegos tradicionales infantiles y churrascadas colectivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27038','fiesta','Fiestas de las Flores de Ourol','Patronal. Se celebra en Julio. Celebración de ámbito estrictamente vecinal y rural en los valles del interior de la Mariña, caracterizada por la misa tradicional, procesión de los ramos de flores de época y pequeñas verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90555','fiesta','Feria de la Artesanía de Outeiro de Rei y Fiestas de San Juan','Feria Artesanal y Patronal. Se celebra en Julio y Junio. Festejos comarcales de la Tierra Llana que sobresalen por la promoción de la alfarería tradicional de Bonxe, con demostraciones de artesanos torneando barro en directo, música tradicional y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27040','fiesta','Fiestas de San Tirso y Fiesta de la Juventud','Patronal y Cultural. Se celebra en Enero y Agosto. Festejos dinamizados comarcalmente por la masiva afluencia del Camino de Santiago, que congregan a numerosos peregrinos en torno a sus verbenas estivales, pasacalles tradicionales y conciertos de música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27041','fiesta','Muestra del Vino de Pantón y Fiestas de la Virgen de las Aguas rojas','Enológica, Gastronómica y Patronal. Se celebra en Mayo y Agosto. Hito festivo de la Ribeira Sacra enfocado en la promoción de los caldos locales de la D.O. Ribeira Sacra, caracterizado por catas comentadas, mercados artesanos tradicionales y orquestas gallegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27042','fiesta','Fiestas de San Juan de Paradela y Feria de Mayo','Patronal y Feria Local. Se celebra en Junio y Mayo. Festejos rurales de arraigo local e interior centrados en las procesiones solemnes, concursos de ganado de la zona, juegos tradicionales de cartas y sesiones vermú con música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27043','fiesta','Ferias de las Fiestas de la Primavera de O Páramo','Feria Agrícola y Ganadera. Se celebra en Junio. Festejo tradicional ecuestre y ganadero con notable aceptación comarcal, con concursos morfológicos de caballos, exhibiciones de doma del norte y puestos de pulperías artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27044','fiesta','Fiesta de la Virgen de la Pastoriza','Romería y Religiosa. Se celebra en Septiembre. Romería local tradicional de la Tierra Llana caracterizada por la peregrinación piadosa hacia la ermita, misas rezadas, subasta de ofrendas del campo y comidas campestres vecinales en los prados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28009','fiesta','Romería de Santa María la Real de O Cebreiro y Fiesta del Queso de O Cebreiro','Romería, Religiosa y Gastronómica. Se celebra en Septiembre y Abril. Fiesta de Interés Turístico de Galicia; hito espiritual monumental en la entrada gallega del Camino Francés, famosa por su gran romería y la promoción de su singular queso artesanal con forma de sombrero de hongo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27046','fiesta','Fiesta del Emigrante de Pol y Fiestas de Mosteiro','Retorno Estival y Patronal. Se celebra en Agosto. Festejo de gran valor afectivo comarcal celebrado en la carballeira de Mosteiro, donde se reúnen los vecinos ausentes para disfrutar de una multitudinaria comida de la dehesa con pulpo y orquestas gallegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90556','fiesta','Fiestas del Corpus Christi y San Antonio','Patronal y Religiosa. Se celebra en Junio y Agosto. Festejos tradicionales locales centrados en los artísticos alfombrados de sal de las calles del casco antiguo, pasacalles matinales con gaiteros de la comarca y verbenas de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90557','fiesta','Fiesta de la Trucha de A Pontenova','Gastronómica y Deportiva. Se celebra en Mayo. Festejo con amplio reconocimiento provincial y autonómico centrado en el concurso internacional de pesca deportiva en el río Eo, degustaciones multitudinarias, mercados artesanos y verbenas gallegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27050','fiesta','Mostra del Aceite de Quiroga y Fiesta de la Alborada','Gastronómica, Agrícola y Patronal. Se celebra en Abril (Semana Santa) y Agosto. Hito etnográfico único en Galicia que pone en valor la producción tradicional de aceite de oliva gallego de olivares locales de montaña, con molienda real en directo en almazaras históricas restauradas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27056','fiesta','Fiestas de la Asunción y San Roque','Patronal y Cultural. Se celebra en Agosto. Celebración de relieve local caracterizada por sus certámenes de pintura rápida, torneos deportivos tradicionales, pasacalles folclóricos y verbenas concurridas gracias a su excelente nudo ferroviario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27051','fiesta','Fiestas de San Roque y Fiesta del Carmen','Patronal, Marítima y Turística. Se celebra en Agosto y Julio. Fiesta de gran empaque y elegancia provincial en la ría del Eo, destacando el vistoso desfile tradicional del "Coco y la Coca" —gigantes tradicionales del municipio—, grandes conciertos poprock y fuegos en el puerto.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27052','fiesta','Fiesta de la Cereza y del Aceite de Ribas de Sil','Gastronómica y Agrícola. Se celebra en Junio. Festejos en San Clodio consagrados a ensalzar las cerezas de los valles del Sil y los aceites artesanales locales de la Ribeira Sacra, amenizados con mercados de artesanía y música folk.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27053','fiesta','Fiestas de San Juan de Chao de Pousadoiro','Patronal y Fluvial. Se celebra en Junio. Festejos rurales de ámbito puramente local junto al río Eo, caracterizados por hogueras tradicionales, almuerzos campestres de peñas vecinales y música tradicional interpretada por gaiteros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27054','fiesta','Fiesta de los Oficios Artesanos de Riotorto','Etnográfica y Artesanal. Se celebra en Abril. Hito etnográfico comarcal que pone en valor el trabajo tradicional de los "ferreiros" o herreros locales de la cuenca, forjando hierro candente en vivo en la plaza, mercado artesanal y gaitas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27055','fiesta','Fiestas de San Benito de Samos','Patronal y Religiosa. Se celebra en Julio. Celebración ligada comarcalmente al imponente Monasterio benedictino del Camino de Santiago, caracterizada por solemnes misas cantadas, conciertos corales líricos y animadas verbenas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27057','fiesta','Fiestas de San Juan de Sarria','Patronal y Etnográfica. Se celebra en Junio. Hito festivo de la provincia con gran volumen de visitantes por ser el gran centro de inicio del Camino; destaca la "Noite do Lume" o noche del fuego con hogueras monumentales, folklore tradicional gallego y grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27058','fiesta','Fiestas de Escairón y Fiesta de la Artesanía','Patronal, Ecuestre y Feria Local. Se celebra en Agosto. Festejos de notable éxito comarcal famosos por la célebre carrera de burros tradicional de Escairón, competiciones de tirada de cuerda, desfiles hípicos y grandes orquestas gallegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27059','fiesta','Feria del Vino de Amandi (Feira do Viño de Amandi)','Enológica y Gastronómica. Se celebra en Marzo (Fin de semana de Ramos). Fiesta de Interés Turístico de Galicia; magno festival enológico de la Ribeira Sacra que congrega millares de personas para catar los caldos locales de mencía cultivados en bancales heroicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27060','fiesta','Fiesta del Caldo de Huesos de Taboada (Festa do Caldo de Ósos)','Gastronómica. Se celebra en Febrero. Hito gastronómico comarcal que recupera una antiquísima receta culinaria pastoril de cocido tradicional de invierno, complementado con muestras micológicas locales y folklore gallego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27061','fiesta','Fiesta de la Esfola de Trabada y Fiestas de San Denis','Etnográfica y Patronal. Se celebra en Octubre. Pequeño festejo rural tradicional enfocado en la recuperación de la labor etnográfica del deshojado manual del maíz en las carballeiras, seguido de una merienda popular con gaitas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27062','fiesta','Fiestas de Santiago Apóstol y la Virgen de la Nueva','Patronal. Se celebra en Julio. Festejos serranos revitalizados de forma comarcal por la marea de peregrinos del Camino Francés, ofreciendo folklore tradicional gallego de montaña, conciertos de música celta y pequeñas verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90846','fiesta','Mercado de Primavera de Ferreira y Fiestas de Santa Filomena','Feria Agrícola y Patronal. Se celebra en Marzo y Septiembre. Celebración tradicional del valle lucense basada en la compraventa de ganado caballar de monte, degustaciones masivas de miel local y repostería artesana en las carpas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28012','fiesta','Fiestas de San Ramón y Fiesta del Queso de San Simón da Costa','Patronal, Gastronómica y Feria. Se celebra en Agosto y Abril. Fiesta del Queso declarada de Interés Turístico comarcal y provincial, consagrada a ensalzar su famoso queso ahumado artesanal con forma de peonza, arropada por los grandes festejos estivales de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28013','fiesta','Semana Santa de Viveiro y Rapa das Bestas de Candaoso','Religiosa, Etnográfica y Tradicional. Se celebra en Marzo/Abril y Julio. Su Semana Santa es Fiesta de Interés Turístico Internacional, sobresaliendo por la incalculable antigüedad y valor artístico de sus tallas articuladas medievales y el recogimiento de sus cofradías costeras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90847','fiesta','Encuentro Internacional de Torneiros de Madera de Xermade','Etnográfica y Artesanal. Se celebra en Septiembre. Hito artesanal de gran originalidad provincial y autonómica que reúne a maestros artesanos de la madera de varios países del mundo, con talleres en directo, mercados y exposiciones folclóricas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27025','fiesta','Fiestas de San Bartolo y Fiesta del Percebe','Patronal y Gastronómica. Se celebra en Agosto. Festejos veraniegos de la costa cantábrica lucense muy populosos por su exaltación gastronómica del percebe de los acantilados marinos locales, amenizados con charangas y verbenas gallegas). Hemos finalizado de manera íntegra y exhaustiva la Provincia de Lugo, llegando rigurosamente hasta la letra Z (X). Siguiendo el orden global y la jerarquía de este ambicioso proyecto para la Comunidad de Galicia, el siguiente paso territorial es cambiar de provincia. ¿Deseas que continuemos de inmediato con el primer bloque de la Provincia de Ourense, iniciando por la letra A (Allariz, Amoeiro, Arnoia (A), Avión, etc.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34002','fiesta','Fiesta del Buey (Festa do Boi) y Fiesta del Arnoia','Etnográfica, Histórica y Patronal. Se celebra en Junio (Corpus Christi) y Agosto. Fiesta de Interés Turístico de Galicia de gran valor histórico; conmemora una tradición medieval del siglo XIV donde un buey guiado por mozos recorre el bellísimo casco histórico entre gremios de época y desfiles tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90507','fiesta','Fiestas de Santiago Apóstol y Fiesta del Caballo','Patronal y Ecuestre. Se celebra en Julio. Festejos locales marcados por las competiciones de doma y andadura ecuestre en el entorno rural, combinados con sesiones vermú familiares, misas solemnes y orquestas de verbena.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90508','fiesta','Fiesta del Pimiento de A Arnoia','Gastronómica. Se celebra en Agosto. Fiesta de Interés Turístico de Galicia; multitudinario hito gastronómico de la comarca del Ribeiro donde se fríen y degustan miles de kilos de sus famosos pimientos autóctonos, con catas de vino y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90509','fiesta','Fiesta de la Fiesta Mexicana de Avión y Fiestas de San Roque','Etnográfica, Cultural y Patronal. Se celebra en Agosto. Celebración singular impulsada por el fortísimo arraigo de la emigración gallega a México; el pueblo se transforma con mariachis, artesanía azteca, gastronomía del país americano y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90510','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Festejos rurales de frontera estrictamente vecinales, caracterizados por pasacalles tradicionales de gaiteiros, torneos locales de cartas, comidas de convivencia y pequeñas formaciones musicales nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90511','fiesta','Fiestas de San Roque y Fiesta del Pescado','Patronal y Gastronómica. Se celebra en Agosto y Junio. Festejos comarcales en la Baixa Limia que ensalzan la riqueza fluvial de la zona con degustaciones de truchas y peces de río, complementados con folklore local y orquestas de la escena gallega.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90512','fiesta','Fiestas de San Salvador y Romería de los Milagros','Patronal y Romería. Se celebra en Agosto y Septiembre. Notable afluencia de devotos de toda la provincia al cercano santuario mariano, uniendo los ritos litúrgicos tradicionales con el turismo termal local, música folclórica y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90513','fiesta','Fiestas de San Benito de Piñor y Carnaval de Barbadás','Patronal, Urbana y Carnaval. Se celebra en Julio y Febrero/Marzo. Hito festivo de la periferia urbana de la capital provincial que destaca por la potencia de sus verbenas de verano con las mejores orquestas gallegas y un vistoso desfile de comparsas de Entroido.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90514','fiesta','Fiestas del Cristo de los Milagros y Fiesta del Botelo','Patronal, Gastronómica y Vinícola. Se celebra en Septiembre y Enero. Gran empaque festivo en el oriente ourensano; destaca su certamen culinario del embutido tradicional botelo arropado por catas de la D.O. Valdeorras, competiciones de piragüismo en el Sil y conciertos masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90515','fiesta','Fiestas de San Roque y Fiesta del Emigrante','Patronal y Retorno Estival. Se celebra en Agosto. Celebración serrana muy marcada por el retorno estival de familias asentadas en el extranjero, vertebrada en torno a grandes cenas comunitarias al aire libre, campeonatos deportivos y música folclórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90516','fiesta','Fiestas de la Virgen de la Saleta de Astureses','Romería y Religiosa. Se celebra en Septiembre. Romería tradicional en un entorno monumental románico de gran valor histórico, con misas continuas, puestos ambulantes de exvotos y rosquillas artesanales, y folklore gallego de gaitas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90517','fiesta','Fiestas de San Ba thoseme y Fiesta de la Juventud','Patronal. Se celebra en Agosto. Celebración puramente vecinal y de interior rural, dinamizada con comidas de campo colectivas, juegos infantiles tradicionales en el pinar local y música de dúos u orquestas pequeñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90520','fiesta','Fiestas de la Virgen de la Alborada y Feria del Vino','Patronal y Enológica. Se celebra en Septiembre. Festejos populares vinculados a la recolecta agrícola y la tradición vitivinícola del Ribeiro, estructurados en torno a sesiones vermú con música tradicional y pequeñas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90521','fiesta','Fiestas de Nuestra Señora de la Encarnación y Feria de la Pizarra','Patronal y Local. Se celebra en Marzo y Septiembre. Celebración local en los valles mineros orientales, caracterizada por la procesión litúrgica tradicional de la patrona, comidas de peñas vecinales, charangas y bailes en la plaza del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34007','fiesta','Fiesta del Pulpo de O Carballiño (Festa do Pulpo)','Gastronómica y Etnográfica. Se celebra en Agosto (Segundo domingo). Fiesta de Interés Turístico Nacional; cumbre absoluta de la gastronomía gallega que congrega en su Parque Municipal a decenas de miles de personas para consumir toneladas de pulpo preparado por pulpeiras tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90522','fiesta','Fiestas del Santo Cristo de Mundil y Romería Ecuestre','Romería, Ecuestre y Patronal. Se celebra en Agosto. Notable tirón comarcal gracias al centro ecuestre local, destacando sus vistosas exhibiciones de caballos andadura, marchas hípicas por los robledales, música folclórica y verbenas de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90523','fiesta','Fiesta del Ribeiro de Castrelo y Fiestas de la Virgen de las Nieves','Enológica, Gastronómica y Náutica. Se celebra en Agosto. Festejos muy concurridos gracias a su embalse fluvial; fusiona regatas tradicionales de vela ligera con catas de vinos tintos y blancos locales de la D.O. Ribeiro y música folk al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90524','fiesta','Entroido de Castrelo do Val (Fiesta de los Vellarracos)','Etnográfica y Carnaval. Se celebra en Febrero/Marzo. Destacado hito etnográfico del carnaval ourensano; los "Vellarracos" visten trajes tradicionales con caretas de cartón que representan caras de animales y portan una fusta de cuero asustando jocosamente a vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34003','fiesta','Fiesta de los Fachós y Fiestas de la Virgen de los Remedios','Etnográfica, Religiosa y Patronal. Se celebra en Enero (Noche del 19 de enero) y Septiembre. Hito etnográfico de la Ribeira Sacra; en la Fiesta de los Fachós los vecinos recorren las murallas oscuras de su castillo medieval portando antorchas monumentales de paja de hasta 3 metros de largo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34004','fiesta','Fiestas de la Virgen de la Armada y Fiesta de la Romería de San Rosendo','Patronal, Cultural y Religiosa. Se celebra en Agosto y Marzo. Festejos de gran calado comarcal y provincial vinculados al imponente monasterio fortificado; destaca el desfile tradicional de gigantones de época, certámenes poéticos gallegos y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90525','fiesta','Fiestas de San Benito y Fiesta de la Vendimia','Patronal y Agrícola. Se celebra en Julio y Septiembre. Festejos rurales centrados en las tierras del vino Ribeiro, con oficios religiosos tradicionales, sesión vermú popular prolongada y orquestas de baile nocturnas adaptadas a la demografía de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32029','fiesta','Fiesta del Cordero (Festa do Cordeiro) y Fiestas de Santa Ana','*. Gastronómica y Patronal. *. Se celebra en Septiembre y Julio. *. Celebración de la alta montaña ourensana consagrada a la exaltación del cordero asado de forma tradicional de las dehesas de la sierra, acompañado de música folclórica gallega y gaiteros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32026','fiesta','Fiestas de Santiago de Barra de Miño','Patronal. Se celebra en Julio. Celebración de arraigo local junto al cauce del Miño, caracterizada por campeonatos vecinales de cartas entre peñas, pasacalles matinales de gaitas y verbenas de plaza de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32027','fiesta','Fiestas de la Virgen de la Asunción y Feria de Artesanía','Patronal y Local/Termal. Se celebra en Agosto. Festejos locales revitalizados por su patrimonio termal histórico, combinando mercados tradicionales de artesanos de la comarca con folclore musical gallego y animadas veladas nocturnas de orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32028','fiesta','Entroido de Cualedro (Fiesta de los Zarramacos)','Etnográfica y Carnaval. Se celebra en Febrero/Marzo. Interesante hito etnográfico de carnaval que conserva la mítica figura del "Zarramaco", personaje con máscaras de madera pintadas y grandes cencerros de hierro atados a la cintura que golpea el suelo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32030','fiesta','Fiestas de Santa María la Real y Fiesta de la Empanada de Forlo','Patronal y Gastronómica. Se celebra en Agosto. Festejos de la Baixa Limia que destacan por exaltar su empanada tradicional elaborada con pan de centeno de la sierra, combinando procesiones en su joya barroca con verbenas veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32031','fiesta','Fiestas de San Vitor de San Pedro de Rocas','Romería, Histórica y Religiosa. Se celebra en Agosto. Notable valor histórico y comarcal en el entorno de San Pedro de Rocas —el monasterio rupestre más antiguo de Galicia—, con peregrinación a las tumbas excavadas en piedra y música de gaitas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32033','fiesta','Fiestas de la Virgen de la Guía','Romería y Patronal. Se celebra en Agosto. Romería típicamente rural de interior centrada en la solemne procesión parroquial hacia la ermita de la loma, sesión vermú tradicional y pequeñas verbenas de orquestas comarcales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34001','fiesta','Fiestas de San Bartolomé','Patronal y de Retorno Estival. Se celebra en Agosto. Festejos de montaña en el nudo de transportes que aprovechan el gran retorno estival, ofreciendo tradicionales carpas de pulperías artesanales, charangas de calle y orquestas gallegas de primer nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90526','fiesta','Fiestas de San Pedro y Fiesta del Alcornocoso','Patronal y Rural. Se celebra en Junio. Celebración de ámbito estrictamente vecinal adaptada a la baja demografía interior, caracterizada por la misa tradicional del campo, pasacalles folclóricos de gaitas y juegos infantiles). Hemos alcanzado rigurosamente la letra I de la Provincia de Ourense de la Comunidad Autónoma de Galicia, cerrando este bloque de progresión. ¿Continuamos de inmediato con el siguiente bloque de municipios que arranca con la letra L y la letra M (Larouco, Laza, Leiro, Lobeira, Lobios, Maceda, Manzaneda, etc.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32038','fiesta','Fiestas del Santísimo Cristo de la Ascensión y Fiesta de la Vendimia','Patronal y Agrícola. Se celebra en Mayo y Septiembre. Festejos locales de carácter rural ligados a la recolecta de uva en la subzona de Valdeorras, caracterizados por pasacalles tradicionales de gaitas, comidas populares y pequeñas verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32039','fiesta','Entroido de Laza','Etnográfica, Mascarada e Histórica. Se celebra en Febrero/Marzo. Hito etnográfico de relevancia nacional por su carnaval ancestral, considerado uno de los más puros del mundo; destacan los imponentes "Peliqueiros" con sus látigos, el lanzamiento masivo de hormigas vivas con tierra, los desfiles de carros satíricos y la tradicional reparto de bica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32040','fiesta','Fiesta de la Vendimia de Leiro','Enológica, Gastronómica y Etnográfica. Se celebra en Agosto. Fiesta de Interés Turístico de Galicia; espectacular hito del vino Ribeiro que sobresale por su vistoso concurso de carrozas engalanadas con motivos agrarios y racimos reales, acompañado de un gran túnel del vino.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32041','fiesta','Romería de la Virgen del Viso','Romería y Religiosa. Se celebra en Mayo (Domingo de la Ascensión) y Septiembre. Romería tradicional en la Baixa Limia de notable arrigo comarcal, donde los fieles suben a la ermita del monte para procesionar la imagen mariana, seguido de almuerzos campestres familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32042','fiesta','Fiesta de los Callos Limiaos y Fiestas de San José','Gastronómica y Patronal. Se celebra en Agosto. Festejo comarcal en pleno Parque Natural Baixa Limia-Serra do Xurés que rinde homenaje a su receta típica de callos, atrayendo numeroso turismo estival y termal con verbenas de primer nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32043','fiesta','Entroido de Maceda y Fiestas de las Nieves','Etnográfica, Carnaval y Patronal. Se celebra en Febrero/Marzo y Agosto. Destacado valor etnográfico provincial gracias a la figura de los "Felos de Maceda", máscaras ancestrales de carnaval emparentadas con las de la sierra que recorren las aldeas a caballo y a pie sembrando el desorden.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32044','fiesta','Entroido de Manzaneda (Fiesta de las Máscaras)','Etnográfica y Carnaval. Se celebra en Febrero/Marzo. Hito etnográfico único caracterizado por el espectacular toque rítmico de los "Fulións" —grandes bombos de piel tradicionales— y la vistosa danza de las "Máscaras" con sombreros cónicos de cintas de colores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32045','fiesta','Fiestas de San Vitoiro','Patronal y Cultural. Se celebra en Agosto. Festejos populares con arraigo comarcal que se distinguen por sus tradicionales desfiles de gigantones y cabezudos históricos de época, competiciones de hípica locales y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32046','fiesta','Fiestas de Santa María de Melón','Patronal y Religiosa. Se celebra en Agosto. Pequeña celebración rural menor organizada en torno al entorno patrimonial de su histórico monasterio cisterciense, con misas rezadas tradicionales, sesión vermú popular y música orquestal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32047','fiesta','Fiestas de San Benito de la Merca','Patronal. Se celebra en Julio. Festejos de ámbito vecinal y rural que aprovechan el pintoresco paraje de su monumental conjunto de hórreos tradicionales, dinamizados con campeonatos de cartas, comidas populares y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32048','fiesta','Fiestas de San Benito y Fiesta de la Juventud','Patronal y de Retorno Estival. Se celebra en Agosto. Festejos serranos de frontera marcados por el regreso de familias emigradas, organizándose tradicionales almuerzos de pulpo en carpas ambulantes, charangas de calle y bailes nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32049','fiesta','Fiesta de la Carne Carne de Montederramo y Fiestas de San Roque','Gastronómica, Ganadera y Patronal. Se celebra en Octubre y Agosto. Hito gastronómico comarcal de la Ribeira Sacra consagrado a ensalzar la carne vacuna de raza Caldelá autóctona criada en las praderas serranas, con degustaciones masivas en los robledales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32050','fiesta','Fiestas de la Virgen de la Asunción e Inmaculada','Patronal e Histórica. Se celebra en Agosto. Festejos que ganan espectacularidad gracias a las actividades culturales organizadas en el entorno monumental de su imponente fortaleza e iglesia medieval, con folklore y orquestas de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32051','fiesta','Fiesta de las Sopas de Burro Cansado y Fiestas del Carmen','Gastronómica, Etnográfica y Deportiva. Se celebra en Agosto. Festejo comarcal único que recupera un postre tradicional pastoril a base de pan, vino tinto azucarado y leche caliente, complementado con competiciones de piragüismo en el embalse.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32052','fiesta','Fiestas del Santo Ángel de la Guarda de Luintra','Patronal y Etnográfica. Se celebra en Agosto. Festejos en el corazón de la Ribeira Sacra que conmemoran la tradición de los históricos paragüeros y afiladores locales ambulantes, combinando folklore gallego con verbenas veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32053','fiesta','Fiesta del Pimiento de Oímbra','Gastronómica. Se celebra en Agosto. Hito agrícola con amplia repercusión provincial que promociona su variedad de pimiento dulce autóctono con Indicación Geográfica Protegida, con catas comentadas, mercados artesanos y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34008','fiesta','Fiestas del Corpus Christi y Fiesta del Magosto','Patronal, Etnográfica y Cultural. Se celebra en Junio y Noviembre (Día de San Martín). El Magosto es una festividad tradicional multitudinaria con estatus provincial y autonómico donde miles de vecinos asan castañas en hogueras urbanas y dehesas de la ciudad, combinada con el gran despliegue musical del Corpus.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32055','fiesta','Fiestas de San Mauro','Patronal. Se celebra en Enero. Pequeña festividad invernal de ámbito estrictamente vecinal, caracterizada por la misa tradicional con cánticos folclóricos, sesión vermú y orquestas populares de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32056','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Transfronteriza. Se celebra en Agosto. Festejos locales junto a la frontera con Portugal que congregan a vecinos de ambos lados para compartir comidas campestres de peñas, música tradicional y pequeñas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32057','fiesta','Fiestas de San Ramón y Fiesta de la Castaña','Patronal y Gastronómica. Se celebra en Agosto y Noviembre. Festejos en los cañones del Sil orientados a poner en valor su tradición forestal de los sotos de castaños, con magostos colectivos, música folclórica y bailes en la plaza de la localidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32058','fiesta','Fiestas de San Pedro y Fiesta de la Juventud','Patronal y Urbana. Se celebra en Junio. Celebración de la corona periférica capitalina que destaca por contratar formaciones de gran nivel del circuito de orquestas gallegas, registrando buena afluencia de jóvenes de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90527','fiesta','Fiesta de la Ternera al Caldero de A Peroxa','Gastronómica. Se celebra en Julio. Festejo gastronómico comarcal consagrado a la preparación tradicional de carne de ternera guisada en grandes potes de cobre según la receta histórica de los feriantes, atrayendo a multitud de comensales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32060','fiesta','Fiestas de Santiago Apóstol y Fiesta de las Bodegas','Patronal y Enológica/Etnográfica. Se celebra en Julio y Agosto. Notable tirón local gracias a su ruta de bodegas tradicionales subterráneas excavadas en piedra, donde peñas de vecinos abren sus puertas para degustar caldos caseros y pinchos con charangas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32061','fiesta','Fiestas de la Virgen de la O y Fiesta de la Juventud','Patronal. Se celebra en Diciembre y Agosto. Celebración puramente vecinal y rural en el norte de la provincia, caracterizada por misas solemnes tradicionales, comidas comunitarias al aire libre y orquestas pequeñas comarcales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90528','fiesta','Fiestas de San Bartolomé y la Virgen de los Desamparados','Patronal y Cultural. Se celebra en Agosto. Festejos de gran tradición en la montaña ourensana de relieve comarcal; destacan sus certámenes folclóricos internacionales de bandas de gaitas y desfiles de cabezudos barrocos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90529','fiesta','Fiestas de San Bartolomé','Patronal y Rural. Se celebra en Agosto. Pequeña celebración veraniega de carácter estrictamente familiar orientada a la dinamización vecinal, centrada en la procesión litúrgica tradicional del santo y un dúo musical nocturno.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90530','fiesta','Fiesta de los "Sanamallos" de Punxín','Patronal y Etnográfica. Se celebra en Mayo. Festejos locales marcados por ritos agrarios tradicionales primaverales de bendición de campos, pasacalles matinales con gaiteros de la comarca y pequeñas verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32066','fiesta','Fiestas de San Pedro y la Virgen de los Remedios','Patronal. Se celebra en Junio y Septiembre. Celebración de ámbito estrictamente vecinal y rural, caracterizada por la procesión parroquial tradicional, juegos infantiles en el campo de la fiesta y veladas musicales con conjuntos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32067','fiesta','Romería de la Virgen de la Saínza','Romería, Religiosa e Histórica. Se celebra en Septiembre (Día 24). Fiesta de Interés Turístico de Galicia; espectacular y singular hito histórico donde los vecinos escenifican desde el siglo XIX un combate medieval simulado entre un bando cristiano y uno moro con el asalto a un castillo efímero de madera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32082','fiesta','Fiestas de San Andrés y la Virgen de la Guía','Patronal y Cultural. Se celebra en Agosto y Noviembre. Festejos rurales locales dinamizados por festivales de bandas de folklore tradicional de la comarca, acompañados de comidas vecinales de hermandad y orquestas gallegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32069','fiesta','Fiesta de la Historia (Festa da Istoria) y Feria del Vino del Ribeiro','Recreación Histórica, Enológica y Etnográfica. Se celebra en Agosto (Último sábado) y Mayo. Fiesta de Interés Turístico Nacional por su Fiesta de la Historia; la antigua capital del Reino de Galicia transforma de forma masiva su barrio judío medieval, obligando a usar la moneda de época maravedí en mercados y torneos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32071','fiesta','Fiesta de la Castaña y de la Seta de Riós','Gastronómica, Agrícola y Etnográfica. Se celebra en Noviembre. Hito micológico y forestal comarcal destacado por poner en valor la excelencia de las castañas de sus sotos centenarios, arropado por degustaciones populares gratuitas de asados y música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32072','fiesta','Fiestas de San Roque y Fiesta de la BacoFesta','Patronal, Enológica e Histórica. Se celebra en Agosto. Notable repercusión en Valdeorras gracias a la BacoFesta, un hito que fusiona la estética romana imperial clásica con la promoción y cata multitudinaria de sus prestigiosos vinos locales de godello.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32074','fiesta','Fiestas de San Amaro y la Virgen de la Salud','Patronal. Se celebra en Enero y Julio. Festejos locales marcados por las celebraciones devocionales de curación, pasacalles matinales con agrupaciones tradicionales de gaiteros y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90531','fiesta','Fiestas de San Ildefonso','Patronal y Urbana. Se celebra en Enero y Septiembre. Celebración con gran solvencia económica industrial periférica, caracterizada por la gran infraestructura de sus orquestas de primer nivel, campeonatos de peñas y actividades infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32076','fiesta','Fiesta del Pan de Cea','Gastronómica y Etnográfica. Se celebra en Julio (Primer domingo). Fiesta de Interés Turístico de Galicia; multitudinaria exaltación artesana de su histórico pan con Indicación Geográfica Protegida, elaborado en sus singulares hornos circulares de piedra antiguos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90532','fiesta','Fiesta de la Pía y Fiestas de San Juan','Patronal y Rural. Se celebra en Junio. Festejos rurales de la montaña interior adaptados a la baja densidad, centrados en las tradicionales hogueras de San Juan, orquestas de baile de la comarca y torneos vecinales de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32077','fiesta','Fiestas del Santo Cristo de Sandiás','Patronal. Se celebra en Mayo. Festejos de arraigo estrictamente local en la llanura de A Limia, caracterizados por procesiones solemnes, tiradas de fuegos de fogueo tradicionales y música orquestal en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32078','fiesta','Entroido de Sarreaus (Fiesta de los Vergalleiros)','Etnográfica y Carnaval. Se celebra en Febrero/Marzo. Interesante hito etnográfico de carnaval que recupera la figura típica del "Vergalleiro", máscara tradicional con látigo decorada con cuernos de chivo que asusta jocosamente a los asistentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32079','fiesta','Fiestas de Santiago Apóstol de Taboadela','Patronal. Se celebra en Julio. Festejos locales tradicionales con procesión litúrgica del santo patrón, pasacalles folclóricos de gaitas, competiciones deportivas vecinales y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32080','fiesta','Fiesta del Vino de la Ribera Sacra de A Teixeira','Enológica y Gastronómica. Se celebra en Noviembre. Festejo de la viticultura heroica comarcal dedicado a ensalzar los caldos nuevos de mencía y godello, complementado con magostos colectivos de castañas y música de agrupaciones tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32081','fiesta','Fiestas de San Antonio de Toén','Patronal. Se celebra en Junio. Festejos de arraigo puramente local caracterizados por comidas vecinales de hermandad al aire libre, sesión vermú tradicional prolongada y música de orquestas comarcales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32082','fiesta','Fiestas de la Virgen de la Junquera','Patronal y Romería. Se celebra en Septiembre. Romería local tradicional de A Limia adaptada a la baja demografía, con peregrinación piadosa hacia la ermita, subasta tradicional de exvotos y música orquestal nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32083','fiesta','Fiesta de la "Festa da Treboada" y Fiestas del Carmen','Etnográfica y Patronal. Se celebra en Agosto. Notable hito etnográfico serrano a los pies de Peña Trevinca; destaca la espectacular reunión tradicional de agrupaciones de bombos gigantes que simulan una estruendosa tormenta sonora por las calles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32084','fiesta','Fiestas de San Juan de Verea','Patronal y Rural. Se celebra en Junio. Pequeños festejos rurales menores centrados en las tradicionales hogueras vecinales de San Juan, sesión vermú popular animada por un dúo musical local y torneos de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32085','fiesta','Entroido de Verín y Fiesta de los Cigarrones','Etnográfica, Mascarada e Histórica. Se celebra en Febrero/Marzo. Fiesta de Interés Turístico Nacional; su espectacular carnaval destaca por el atronador desfile masivo de los "Cigarrones", máscaras de madera labrada con látigos centenarios y grandes cencerros de latón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34012','fiesta','Entroido de Viana do Bolo (Fiesta del Androlla)','Etnográfica, Carnaval y Gastronómica. Se celebra en Febrero/Marzo (Domingo de Gordo). Fiesta de Interés Turístico de Galicia; hito absoluto que fusiona su ancestral carnaval dominado por los saltos de los "Boteiros" y los desfiles satíricos de las "Lareiras" con una masiva degustación de su embutido de tripa rey.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32087','fiesta','Fiesta de la Fiesta del Castillo de Vilamarín','Cultural y Patronal. Se celebra en Julio. Festejos locales que ganan prestancia al desarrollarse actividades folclóricas de bandas de música tradicional gallega e instalaciones artísticas dentro de su histórico pazo-castillo medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32088','fiesta','Fiesta de las Covas de Vilamartín','Enológica, Etnográfica y Cultural. Se celebra en Agosto (Primer sábado). Notable éxito comarcal; miles de personas recorren una espectacular ruta subterránea abriendo decenas de históricas cuevas excavadas en arcilla roja para degustar caldos locales al ritmo de charangas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32089','fiesta','Fiesta de la Patata de Vilar de Barrio','Gastronómica y Agrícola. Se celebra en Octubre. Festejo de la llanura de A Limia consagrado a la puesta en valor de su producción de patata local, con exposiciones agrarias de hortalizas, concursos culinarios tradicionales y folklore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32090','fiesta','Fiestas de San Juan de Vilar de Santos','Patronal y Etnográfica. Se celebra en Junio. Festejos que aprovechan el importante enclave de su museo etnográfico local para dinamizar la zona con muestras de oficios antiguos perdidos, música folclórica y pequeñas verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32091','fiesta','Entroido de Vilardevós (Fiesta de los Chocalleiros)','Etnográfica y Carnaval. Se celebra en Febrero/Marzo. Interesante hito de carnaval fronterizo que mantiene viva la mítica figura del "Chocalleiro", personaje cubierto con máscaras satíricas de cartón prensado y cencerros que interactúa con vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32092','fiesta','Entroido de Vilariño de Conso (Fiesta del Cabrito)','Etnográfica, Carnaval y Gastronómica. Se celebra en Febrero/Marzo. Notable valor etnográfico de montaña; sus desfiles tradicionales de "Fulións" con cuernos y pieles salvajes se complementan con un banquete multitudinario a base de cabrito asado en carpas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34013','fiesta','Entroido de Xinzo de Limia y Fiesta del Olvido','Etnográfica, Mascarada e Histórica. Se celebra en Febrero/Marzo y Agosto. Fiesta de Interés Turístico Internacional por su Carnaval, el ciclo de carnaval más largo de España con cinco domingos festivos dominados por las históricas y respetadas "Pantallas", máscaras ancestrales de vejiga.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32036','fiesta','Fiestas de la Virgen de la Asunción y Ciclos de Órgano','Patronal, Cultural y Religiosa. Se celebra en Agosto. Notable relieve comarcal e histórico ligado a su colegiata medieval, destacando por sus solemnes conciertos de música clásica sacra ejecutados en su histórico órgano ibérico del siglo XVIII.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32037','fiesta','Fiesta de la Alfarería Tradicional de Niñodaguia','Etnográfica, Artesanal y Patronal. Se celebra en Julio. Hito etnográfico provincial excepcional dedicado a la alfarería amarilla vidriada tradicional de Niñodaguia, con demostraciones de olleros cociendo piezas en hornos históricos de leña al aire libre). Hemos completado al 100% de manera rigurosa todos los municipios de la Provincia de Ourense, cerrando exitosamente la letra Z (X). De acuerdo al orden alfabético global de provincias y de la Comunidad de Galicia, la última provincia gallega pendiente es Pontevedra. ¿Procedemos de inmediato a abrir el bloque de la Provincia de Pontevedra, arrancando por la letra A (Agolada, Arbo, Baiona, Barro, Bueu, etc.)?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36020','fiesta','Fiestas Patronales de San Pedro y Fiesta de la Artesanía en Os Pendellos','Patronal, Etnográfica y Artesanal. Se celebra en Junio y Agosto. Notable valor etnográfico comarcal; sus ferias tradicionales de artesanía y muestras de oficios antiguos se desarrollan en el incomparable marco de "Os Pendellos", un mercado medieval de piedra único del siglo XVIII.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90533','fiesta','Fiesta de la Lamprea de Arbo','Gastronómica y Enológica. Se celebra en Abril (Último fin de semana). Declarada Fiesta de Interés Turístico Nacional. Es una de las citas culinarias más antiguas e importantes de Galicia, consagrada a la exaltación de este prehistórico pez fluvial cocinado en su propia sangre, regado con vinos de la D.O. Rías Baixas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36002','fiesta','Fiesta de la Arribada de la Carabela Pinta','Recreación Histórica y Cultural. Se celebra en Marzo (Primer fin de semana). Fiesta de Interés Turístico Internacional de masiva afluencia global; conmemora la llegada de Martín Alonso Pinzón en 1493 con la noticia del Descubrimiento de América, transformando el casco histórico fortificado en un riguroso mercado renacentista vivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90677','fiesta','Fiesta del Vino de Barro (Festa do Viño)','Enológica y Gastronómica. Se celebra en Junio. Festejo de gran relevancia comarcal y provincial centrado en la puesta en valor de los caldos locales albariños y tintos de la zona del Salnés, arropado por certámenes de catas, sardiñadas populares y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36003','fiesta','Fiesta del Corpus Christi de Bueu (Alfombras Florales)','Religiosa y Etnográfica. Se celebra en Junio. Declarada Fiesta de Interés Turístico de Galicia de extraordinaria belleza plástica; los vecinos confeccionan durante la madrugada extensos mantos kilométricos con millones de pétalos y hiedra para el paso de la Custodia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90534','fiesta','Fiestas de San Roque y la Virgen Grande','Patronal y Urbana/Termal. Se celebra en Agosto. Festejos dinamizados comarcalmente por la masiva afluencia del Camino de Santiago Portugués y su patrimonio termal, destacando por sus potentes verbenas populares, conciertos de poprock al aire libre y desfiles de peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36004','fiesta','Fiesta del Vino Albariño de Cambados','Enológica, Gastronómica y Cultural. Se celebra en Agosto (Primer domingo). Fiesta de Interés Turístico Nacional; es la manifestación vitivinícola más antigua de Galicia y una de las cumbres festivas de las Rías Baixas, destacando por sus casetas de degustación en el Paseo de la Calzada, desfiles de cofradías y macroconciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90535','fiesta','Fiestas de San Miguel y Fiesta de la Juventud','Patronal. Se celebra en Septiembre. Festejos tradicionales de carácter puramente vecinal adaptados a la baja demografía interior, caracterizados por la procesión litúrgica tradicional del santo, sesiones vermú familiares y pequeñas orquestas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36005','fiesta','Fiestas del Santísimo Cristo del Consuelo y Danzas Ancestrales de Cangas','Patronal, Religiosa y Etnográfica. Se celebra en Agosto e Invierno/Primavera. Notable valor etnográfico provincial; destacan sus antiquísimas danzas tradicionales de San Sebastián, San Roque y el Carmen ejecutadas en el atrio parroquial, combinadas con espectaculares castillos de fuegos artificiales sobre el mar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19066','fiesta','Fiesta del Jamón de A Cañiza (Festa do Xamón)','Gastronómica. Se celebra en Agosto (Día 15). Declarada Fiesta de Interés Turístico de Galicia; multitudinario hito gastronómico de la montaña pontevedresa donde se degustan toneladas de jamón curado local preparado asado, curado, en tortilla o empanado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90536','fiesta','Romería Vikinga de Catoira','Recreación Histórica y Etnográfica. Se celebra en Agosto (Primer domingo). Fiesta de Interés Turístico Internacional de brutal impacto visual; los vecinos se visten de guerreros nórdicos para escenificar a bordo de un drakkar real el violento desembarco y asalto simbólico a las Torres de Oeste medievales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36902','fiesta','Fiesta del Ecce Homo de Cerdedo y Fiesta del Requeixo de Corredoira','Patronal, Romería y Gastronómica. Se celebra en Agosto y Septiembre. Festejos tradicionales de la comarca interior que fusionan las solemnes procesiones de devoción popular con la promoción de su requesón artesanal con miel, amenizados con folklore tradicional gallego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90537','fiesta','Fiestas de la Virgen de la Guía','Patronal y Romería. Se celebra en Septiembre. Romería típica del interior rural serrano enfocada a la dinamización vecinal, centrada en la peregrinación piadosa hacia la ermita de la loma, sesión vermú tradicional y pequeñas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90538','fiesta','Fiestas de San Pedro de Crecente','Patronal y Rural. Se celebra en Junio. Celebración de ámbito puramente local junto a la cuenca del Miño, caracterizada por misas solemnes tradicionales con cánticos tradicionales, orquestas musicales pequeñas de fin de semana y campeonatos de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90539','fiesta','Fiesta del "Lacón con Grelos" de Cuntis (Festa do Lacón con Grelos)','Gastronómica y Etnográfica. Se celebra en Febrero/Marzo (Domingo de Piñata). Declarada Fiesta de Interés Turístico de Galicia; hito gastronómico invernal que colapsa la villa con millares de personas comiendo el tradicional cocido gallego, complementado con el vistoso "Entierro del Chapante".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90540','fiesta','Fiestas del Santo Cristo de la Peña de Francia','Patronal y Romería. Se celebra en Septiembre. Pequeña festividad menor adaptada a la baja densidad del interior pontevedrés, estructurada en torno a la misa rezada del campo de la fiesta, comidas vecinales familiares y orquestas comarcales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36017','fiesta','Rapa das Bestas de Sabucedo y Fiestas de San Paio','Etnográfica, Mascarada y Tradicional. Se celebra en Julio (Primer fin de semana). Fiesta de Interés Turístico Internacional; hito antropológico y etnográfico milenario de espectacular fuerza plástica donde los aloitadores se enfrentan cuerpo a cuerpo con los caballos salvajes en el curro para rapar sus crines.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36018','fiesta','Fiestas de Nuestra Señora de los Dolores','Patronal y Religiosa. Se celebra en Agosto. Festejos locales de la comarca de Tabeirós-Tierra de Montes, caracterizados por tradicionales misas solemnes en el casco urbano, música folclórica con gaita gallega y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36019','fiesta','Fiestas de San Lorenzo de Fornelos','Patronal y de Retorno Estival. Se celebra en Agosto. Festejos de montaña enfocados en el reencuentro de las familias emigradas, organizándose tradicionales almuerzos campestres vecinales en los prados, juegos infantiles y música de orquesta de baile.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36021','fiesta','Fiestas de San Benito de Gondomar','Patronal y Romería. Se celebra en Julio. Hito milagrero comarcal en el Valle Miñor; miles de personas acuden a ofrecer exvotos de cera al santo abogado de las verrugas, combinando la masiva devoción religiosa con orquestas gallegas de primer nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36009','fiesta','Fiesta del Marisco de O Grove (Festa do Marisco)','Gastronómica, Marítima y Cultural. Se celebra en Octubre. Fiesta de Interés Turístico Nacional; magno y monumental festival gastronómico de la península grovense que atrae cientos de miles de visitantes para degustar centollos, cigalas, mejillones y rodaballo en carpas gigantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36001','fiesta','Fiesta del Monte de A Guarda','*. Etnográfica, Marinera y Romería. *. Se celebra en Agosto (Segundo domingo). *. Declarada Fiesta de Interés Turístico de Galicia; espectacular y estruendoso festejo donde miles de peñistas suben al Monte Santa Trega haciendo restallar cajas y tambores en una espectacular marea sonora tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36901','fiesta','Fiesta del Carmen y Fiesta de la Exaltación del Mejillón','Marítima y Gastronómica. Se celebra en Julio y Agosto. Gran relevancia costera en el interior de la ría; destaca por la imponente procesión marítima de decenas de barcos de batea engalanados acompañando a la patrona y su feria dedicada al marisco isleño). Hemos alcanzado rigurosamente la letra I (Illa de Arousa) de la Provincia de Pontevedra de la Comunidad Autónoma de Galicia, completando exhaustivamente el progreso solicitado. ¿Continuamos de inmediato con el siguiente bloque de municipios que arranca con la letra L y la letra M (Lalín, Lama (A), Marín, Meaño, Meis, Moaña, Mondariz, etc.)?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36024','fiesta','Feria del Cocido de Lalín (Feira do Cocido)','Gastronómica, Etnográfica y Cultural. Se celebra en Febrero (Domingo anterior al de Carnaval). Fiesta de Interés Turístico Internacional; hito absoluto de la gastronomía de interior que congrega a miles de comensales para degustar el emblemático cocido con hortalizas locales, coronado por un multitudinario desfile de carrozas y comparsas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36025','fiesta','Fiestas del Santísimo Cristo de la Agonía y Fiesta del Codillo','Patronal y Gastronómica. Se celebra en Agosto. Celebración de la montaña de interior marcada por el retorno estival de familias emigradas, caracterizada por la degustación del codillo tradicional, folklore gallego con pandereteras y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36007','fiesta','Fiestas del Carmen y Fiesta de San Miguel (Danza de las Espadas)','Marítima, Etnográfica y Militar. Se celebra en Julio y Septiembre. Fiesta de Interés Turístico de Galicia gracias a la ancestral Danza de las Espadas del siglo XVII ejecutada por los mareantes, combinada con las galas militares de la Escuela Naval en honor a la patrona del mar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36027','fiesta','Fiestas de San Benito de Meaño y Fiesta del Huevo de Pascua','Patronal y Romería. Se celebra en Julio. Festejos en el corazón vitivinícola de la comarca del Salnés, caracterizados por las ofrendas religiosas tradicionales de figuras de cera al santo, degustaciones de repostería artesana local y animadas verbenas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36028','fiesta','Escenificación de la Pasión de Cristo en Paradela y Fiesta de los Vinos de Meis','Religiosa, Recreación Histórica y Enológica. Se celebra en Marzo/Abril (Semana Santa) y Julio. Fiesta de Interés Turístico de Galicia por las sobrecogedoras y realistas representaciones escénicas de la Pasión realizadas de forma popular por los propios vecinos del municipio, completada con su feria de vinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36008','fiesta','Fiestas de San Martiño y Fiesta del Carmen','Marítima, Patronal y Etnográfica. Se celebra en Noviembre y Julio. Notable relieve en la península del Morrazo; destaca el tradicional descorche del vino nuevo en los "furanchos" locales durante el otoño, sumado a vistosas procesiones marítimas de barcos pesqueros en verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36030','fiesta','Fiestas de la Virgen de la Peña de Francia','Patronal y Romería. Se celebra en Agosto. Romería tradicional de la cuenca fluvial que destaca por la procesión hípica campestre hacia la ermita de la loma, complementada con grandes meriendas de peñas en los sotos y bailes tradicionales con gaiteros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36031','fiesta','Fiestas de Nuestra Señora de la Encarnación','Patronal y Cultural/Termal. Se celebra en Mayo. Festejos locales dotados de gran elegancia paisajística gracias a su conjunto monumental de aguas termales e histórico balneario decimonónico, con conciertos corales líricos y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36032','fiesta','Fiesta del "Carneiro ao Espeto" de Moraña','Gastronómica y Etnográfica. Se celebra en Julio (Último domingo). Fiesta de Interés Turístico de Galicia; espectacular y masivo hito culinario donde decenas de carneros abiertos en canal son asados lentamente al aire libre en asadores circulares de leña durante horas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36033','fiesta','Fiesta de la "Festa da Rosa" de Mos','Etnográfica y Cultural. Se celebra en Junio (Día 13). Hito etnográfico comarcal que recupera una antiquísima leyenda medieval vinculada al Pazo de Mos, caracterizado por el tradicional concurso de flores ornamentales exóticas locales, mercado artesanal y gaitas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36034','fiesta','Romería de Santa Marta de Ribarteme (Procesión de los Ataúdes)','Religiosa, Romería y Etnográfica. Se celebra en Julio (Día 29). Fiesta de Interés Turístico de Galicia de altísimo impacto antropológico internacional; los fieles que han superado una situación cercana a la muerte desfilan dentro de féretros reales abiertos portados por sus familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36035','fiesta','Fiestas de San Juan de Panxón y Fiestas de la Virgen de las Angustias','Patronal y Playera. Se celebra en Junio y Agosto. Gran concurrencia estival en el Valle Miñor; destaca la multitudinaria noche de las hogueras o cacharelas a la orilla del mar en la arena de la playa y sus grandes orquestas de la escena gallega.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36010','fiesta','Fiestas de la Virgen del Mar y Curro de Valga (Rapa das Bestas)','Marítima, Etnográfica y Ganadera. Se celebra en Agosto y Mayo. Notable valor paisajístico y etnográfico al pie del Atlántico, caracterizado por la tradicional bajada de caballos salvajes desde la sierra del Groba para su marcaje, con el Monasterio cisterciense como marco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36037','fiesta','Fiesta de la "Festa do Choco" de Pazos','Gastronómica. Se celebra en Abril. Festejos gastronómicos de ámbito estrictamente local dedicados a la promoción culinaria del choco preparado en su tinta, acompañados de sesiones vermú familiares y pequeños bailes con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90044','fiesta','Fiesta de la Almeja de Campelo (Festa da Ameixa) y Fiestas de San Juan','Marítima, Gastronómica y Patronal. Se celebra en Julio y Junio. Notable afluencia en las proximidades de la ría, destacando por las degustaciones populares masivas del marisco de la ensenada, festivales de folklore tradicional gallego y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90848','fiesta','Fiesta de la Trucha de Ponte Caldelas','Gastronómica y Deportiva. Se celebra en Mayo (Último fin de semana). Hito culinario comarcal de gran tradición en las riberas del río Verdugo, con concursos de pesca deportiva de trucha fluvial, degustaciones masivas en los puestos de madera y música folk.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90849','fiesta','Alfombras Florales del Corpus Christi de Ponteareas','Etnográfica, Religiosa y Tradicional. Se celebra en Junio (Fin de semana de Corpus). Fiesta de Interés Turístico Internacional de monumental belleza plástica; los vecinos decoran durante toda la noche las calles del casco antiguo con tapices kilométricos de pétalos formando intrincados mosaicos artísticos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36011','fiesta','Fiestas de la Peregrina y Feria Franca de Pontevedra','Patronal, Recreación Histórica y Taurina. Se celebra en Agosto y Septiembre (Primer fin de semana). La Feria Franca está declarada Fiesta de Interés Turístico de Galicia, reuniendo de forma masiva a miles de vecinos vestidos rigurosamente con trajes medievales para cenar en las calles del casco antiguo histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36039','fiesta','Fiestas del Santísimo Cristo de la Agonía y Fiesta del Callo','Patronal y Gastronómica. Se celebra en Septiembre y Noviembre. Festejos urbanos de gran concurrencia industrial en la comarca de la Louriña, conocidos por la macrodegustación popular de su tradicional receta de callos con garbanzos y sus potentes verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36040','fiesta','Fiestas de la Virgen de la O','Patronal y Rural. Se celebra en Julio. Celebración de ámbito puramente vecinal centrada en las procesiones solemnes por los campos del término municipal, juegos tradicionales infantiles en la plaza de la iglesia y música de orquestas comarcales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36012','fiesta','Fiesta de la Coca de Redondela y Fiesta del Choco','Etnográfica, Mitológica y Gastronómica. Se celebra en Junio (Corpus) y Mayo. Fiesta de Interés Turístico de Galicia; destaca la representación del mito de la "Coca" —un dragón medieval legendario de la ría— derrotado por los mozos en la espectacular Danza de las Espadas y las Penlas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36046','fiesta','Fiesta del Vino Tinto de Salnés de Barrantes','Enológica y Gastronómica. Se celebra en Junio (Primer fin de semana). Fiesta de Interés Turístico de Galicia; multitudinario hito enológico consagrado a la degustación del peculiar y tradicional vino tinto "Barrantes", acompañado de catas populares y folclore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36047','fiesta','Fiestas de San Antonio de Rodeiro','Patronal. Se celebra en Junio. Festejos rurales de la comarca de Deza de carácter estrictamente local, caracterizados por los oficios religiosos parroquiales tradicionales, sesión vermú popular y pequeñas agrupaciones musicales nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36048','fiesta','Feria del Vino de O Rosal','Enológica y Gastronómica. Se celebra en Julio. Notable relieve provincial en el estuario del Miño, dedicado a la promoción y cata de sus prestigiosos vinos blancos de la subzona de la D.O. Rías Baixas, con mercado artesanal y música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36049','fiesta','Carnaval de Salceda (Enfrentamiento de Castro Barreiro y Feira)','Etnográfica y Carnaval. Se celebra en Febrero/Marzo. Hito etnográfico único caracterizado por la histórica y encendida rivalidad vecinal satírica entre el barrio de Arriba y el barrio de Abaixo, exhibiendo espectaculares carrozas y coplas tradicionales murgueras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36050','fiesta','Fiesta del Vino del Condado de Salvaterra','Enológica, Gastronómica e Histórica. Se celebra en Agosto (Último fin de semana). Fiesta de Interés Turístico de Galicia; celebrada dentro del recinto amurallado fortificado a orillas del Miño, se centra en la cata masiva de vinos espumosos, albariños y condados locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36013','fiesta','Fiestas de San Ginés y Fiesta de la Cebolla de Sanxenxo','Patronal, Gastronómica y Turística. Se celebra en Agosto. Inmensa afluencia turística estival en la capital del turismo de las Rías Baixas, destacando por su vistoso mercado artesanal de artísticas ristras de cebollas decoradas y espectaculares verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36052','fiesta','Fiesta de la Empanada de Bandeira y Feria Internacional de Galicia','Gastronómica, Agrícola y Feria Industrial. Se celebra en Agosto. La Fiesta de la Empanada de Bandeira es Fiesta de Interés Turístico de Galicia, famosa por sus multitudinarias catas populares de empanadas artesanales gallegas gigantes y subastas benéficas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90541','fiesta','Fiesta de la Ostra de Arcade','Gastronómica y Marítima. Se celebra en Abril (Primer fin de semana). Fiesta de Interés Turístico de Galicia de gran tirón; miles de personas colapsan el puerto marítimo de Arcade para degustar las famosas ostras locales al natural o en escabeche con vino albariño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36054','fiesta','Fiestas del Alivio de Tomiño','Patronal y Romería. Se celebra en Septiembre. Festejos con notable arraigo en el Bajo Miño fronterizo, caracterizados por la procesión devocional de la patrona hacia su santuario, pasacalles tradicionales con bandas de música locales y grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36014','fiesta','Fiestas de San Telmo y Fiesta de la Angula','Patronal, Gastronómica e Histórica. Se celebra en Abril (Lunes de San Telmo). Festejos de gran empaque comarcal y transfronterizo; destaca la procesión nocturna de las antorchas por las empinadas calles del casco antiguo histórico medieval fortificado a los pies de su catedral.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36056','fiesta','Fiesta de la "Festa do Angazo" y Fiesta de la Anguila','Gastronómica y Etnográfica. Se celebra en Agosto. Festejos que ensalzan la tradición fluvial y pesquera del río Ulla, destacando por sus degustaciones de empanadas de anguila, cañas de aguardiente local artesana y folklore tradicional de gaitas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36015','fiesta','Fiestas del Santísimo Cristo de la Victoria y Fiesta de la Reconquista de Vigo','Religiosa, Recreación Histórica y Etnográfica. Se celebra en Agosto y Marzo (Día 28). La Reconquista es Fiesta de Interés Turístico de Galicia, transformando de forma masiva las calles del Casco Vello en una recreación de 1809 donde los vigueses expulsan armados a las tropas napoleónicas francesas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36059','fiesta','Fiesta del "Galo de Corral" de Vila de Cruces','Gastronómica y Etnográfica. Se celebra en Mayo (Último domingo). Hito gastronómico comarcal consagrado a la puesta en valor y cría tradicional de la raza avícola autóctona criada en libertad, con demostraciones culinarias, mercados de artesanos y folklore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36058','fiesta','Carnaval de Vilaboa (Fiesta de las "Madamas e Galáns")','Etnográfica y Carnaval. Se celebra en Febrero/Marzo. Destacado valor etnográfico provincial gracias a la conservación de sus vistosos trajes tradicionales de carnaval; las parejas bailan vestidas de blanco con sombreros monumentales de flores y abalorios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36016','fiesta','Fiestas de San Roque y la Fiesta del Agua (Festa de San Roque / da Auga)','Patronal, Etnográfica y Cultural. Se celebra en Agosto (Día 16). Fiesta de Interés Turístico Nacional; multitudinario y divertidísimo hito festivo veraniego de la ría donde decenas de miles de personas son refrescadas con agua lanzada desde balcones y camiones de bomberos tras la procesión del santo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36061','fiesta','Fiesta del Mejillón y del Berberecho de Vilanova','Gastronómica y Marítima. Se celebra en Agosto. Festejos playeros costeros dedicados a ensalzar los bivalvos y cefalópodos locales extraídos de las dehesas de la ría de Arousa, amenizados con charangas de calle, mercados tradicionales y verbenas gallegas). Hemos finalizado por completo todos los municipios de la Provincia de Pontevedra, cerrando con rigor la letra Z (V). Con este bloque, se completa formalmente la Comunidad Autónoma de Galicia en estricto orden alfabético.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90646','fiesta','Festes de Sant Roc y Romería al Castell d''Alaró','Patronal, Etnográfica y Romería. Se celebra en Agosto. Celebración de fuerte arraigo tradicional en la comarca de Raiguer que destaca por el desfile de gigantes, los dimonis y la tradicional subida al castillo, atrayendo gran público local y de municipios colindantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07001','fiesta','Festes de Sant Jaume y Festes de Sant Pere','Patronal, Marinera y Etnográfica. Se celebra en Junio y Julio. Festividades de alta relevancia comarcal y provincial con la tradicional procesión marítima de Sant Pere y los históricos bailes de gigantes ante las murallas medievales, respaldados por una alta densidad demográfica y turística.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07002','fiesta','Festes de Sant Honorat y Sant Jaume','Patronal y Etnográfica (Danzas ancestrales). Se celebra en Enero y Julio. Hito etnográfico singular de Mallorca debido a la ejecución de los Cossiers, una de las danzas rituales de hombres más antiguas y mejor conservadas de las islas, poseedora de un altísimo valor patrimonial e histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90017','fiesta','Festes de Sant Pere y Fiesta de Nuestra Señora de los Ángeles','Patronal, Marinera y Conmemorativa. Se celebra en Junio y Agosto. Celebraciones tradicionales que vertebran el municipio y su puerto, destacando la procesión marítima y la conmemoración de las batallas históricas contra los piratas moriscos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07004','fiesta','Festes de Sant Antoni y Festes de Sant Salvador','Etnográfica, Patronal y Religiosa. Se celebra en Enero y Agosto. La celebración de Sant Antoni en Artà constituye un fenómeno etnográfico de nivel regional por el fervor popular, los cantos tradicionales de los loaments, las monumentales hogueras y las danzas de sus célebres dimonis). ¿Puedo continuar con el siguiente bloque de municipios de la isla de Mallorca?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90647','fiesta','Festes de la Nativitat de Nostra Senyora (Festes de la Mare de Déu de la Setmana)','Patronal y Etnográfica. Se celebra en Septiembre. Fiestas de arraigo estrictamente local y de retorno estival, condicionadas por la baja demografía del municipio, donde destacan las verbenas populares y las actividades culturales en la plaza de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90648','fiesta','Festa des Vermenar (Fiesta de la Vendimia)','Enológica, Gastronómica y Etnográfica. Se celebra en Septiembre. Festividad de gran empaque provincial y regional vinculada a la Denominación de Origen Binissalem, caracterizada por la pisada tradicional de uva, el desfile de carrozas, la batalla de uvas y la degustación masiva de los fideus de vermenar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90649','fiesta','Festes de Sant Pere y Fira des Sopes de Mallorca','Patronal y Gastronómica. Se celebra en Junio y Octubre. Celebración de escala comarcal en el municipio más pequeño de la isla, que gana relieve gracias a su feria gastronómica dedicada a las sopas mallorquinas tradicionales, atrayendo a visitantes de la comarca del Raiguer.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90650','fiesta','Festes de Sant Mateu y Festa del Quarteró','Patronal y Etnográfica. Se celebra en Septiembre. Festividades tradicionales de gran arraigo local y de montaña en la Serra de Tramuntana, célebres por sus carreras de hombres en ropa interior (Cofis), verbenas populares y la tradicional cena comunitaria del fin de la vendimia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90018','fiesta','Festes del Rei En Jaume (en Santa Ponça) y Fiestas de San Jaime','Recreación Histórica, Patronal y Militar. Se celebra en Julio y Septiembre. Hito cultural y de recreación histórica de nivel regional que conmemora el desembarco de las tropas del rey Jaime I en 1229 con batallas simuladas de moros y cristianos, desfiles de gigantes y un gran impacto turístico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90651','fiesta','Festes de Sant Victorià y Romería a San Miguel','Patronal y Romería. Se celebra en Julio y Pascua (Abril/Mayo). Celebración de carácter marcadamente vecinal y de retorno, donde destaca la romería folclórica hacia la histórica ermita de Sant Miquel, un templo gótico primitivo del siglo XIII.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07005','fiesta','Festes de la Mare de Déu d''Agost y Fira de ses Vacas','Patronal y Feria Sectorial/Ganadera. Se celebra en Agosto y Octubre. Festividades de relevancia comarcal en el Migjorn mallorquín; combina las verbenas de verano con una de las ferias agrícolas y ganaderas más consolidadas y concurridas del sur de la isla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90019','fiesta','Mercado Medieval de Capdepera y Festes de Sant Bartomeu','Recreación Histórica, Feria y Patronal. Se celebra en Mayo y Agosto. Su Mercado Medieval es una de las recreaciones históricas más multitudinarias e importantes de las Islas Baleares, transformando su castillo del siglo XIV en una villa medieval con gremios artesanales y música de época.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90652','fiesta','Festes de Sant Bartomeu y Fira del Sant Crist','Patronal y Feria Tradicional. Se celebra en Agosto y Octubre. Fiestas de arraigo local que congregan a la comunidad en torno a cenas al aire libre, muestras de artesanía, carreras populares y verbenas musicales de marcado carácter familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90020','fiesta','Festes de Sant Joan Baptista','Patronal y Cultural. Se celebra en Junio. Celebración patronal de escala local en la Serra de Tramuntana que destaca por fusionar la tradición religiosa vecinal con eventos culturales y artísticos debido al fuerte perfil cosmopolita e histórico de sus residentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90654','fiesta','Fiesta de la Mare de Déu de Lluc (Patrona de Mallorca) y Sa Ruixada','Religiosa, Romería y Tradicional. Se celebra en Agosto y Septiembre. Sede del Santuario de Lluc, centro espiritual de la isla. Es un hito etnográfico y religioso regional por recibir la masiva peregrinación de la Marxa des Güell a Lluc a peu, que moviliza a decenas de miles de personas de toda Mallorca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90655','fiesta','Festes de Sant Pere y Fira de la Dolça','Patronal y Gastronómica. Se celebra en Junio y Octubre. Atractivo comarcal destacado gracias a su feria gastronómica artesanal especializada en repostería tradicional mallorquina, dulces y licores de la sierra, complementando sus fiestas patronales veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90656','fiesta','Festes de Sant Joan Baptista y Fira del Vi i del Formatge','Patronal y Gastronómica/Enológica. Se celebra en Agosto y Mayo. Fiestas tradicionales de baja escala demográfica y carácter estrictamente local, dinamizadas en primavera por su feria agroalimentaria dedicada al vino de la variedad local Malvasía y a los quesos artesanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07008','fiesta','Festes de Sant Agustí y Fiesta de Santa Margalida','Patronal y Etnográfica (Danzas ancestrales). Se celebra en Julio y Agosto. Relevancia etnográfica y provincial muy alta debido a las danzas de los Els Cavallets, jóvenes que bailan con figuras de cartónpiedra sujetas a la cintura, acompañados por los Gegants de la villa y el fervor multitudinario de Sant Agustí.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90658','fiesta','Festes de la Mare de Déu de la Setmana Santa (Natividad)','Patronal y Taurina/Etnográfica. Se celebra en Septiembre. Celebración que genera gran atención comarcal por la pervivencia del polémico Correbou, la única tradición de toro ensogado de las islas, combinada con verbenas populares en el núcleo urbano de la sierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07027','fiesta','Dijous Bo y Festes de Sant Abdon i Sant Senen','Feria de Ferias, Agropecuaria, Artesanal y Patronal. Se celebra en Julio y Noviembre. El Dijous Bo es la feria mercado más grande, multitudinaria e importante de Mallorca. Es un hito regional masivo que paraliza la isla y reúne cientos de expositores de calzado, piel, ganadería y gastronomía autóctona). ¿Puedo continuar con el siguiente bloque de municipios de la isla de Mallorca comenzando por la letra L?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07011','fiesta','Festes de Sant Domènec y Festa d''es Sequer','Patronal y Gastronómica. Se celebra en Agosto y Septiembre. Festividad de relevancia comarcal en el centro de la isla, donde destaca la feria tradicional dedicada al higo y sus derivados culinarios, combinada con las verbenas estivales del santo patrón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07029','fiesta','Festes de la Mare de Déu de Lloseta y Fira de la Sabata','Patronal y Feria Sectorial. Se celebra en Septiembre. Celebración de arraigo local que potencia la histórica industria del calzado artesanal del municipio a través de su feria de muestras, acompañada de pasacalles de gigantes y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07030','fiesta','Festes de Sant Feliu y Fira de la Miel','Patronal y Gastronómica. Se celebra en Agosto y Noviembre. Feria otoñal de notable asistencia comarcal especializada en la apicultura tradicional mallorquina, que sirve de complemento económico a las fiestas patronales de verano con sus carreras tradicionales y correfocs.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07031','fiesta','Fires de Llucmajor (Fira de ses Festes) y Festes de Santa Càndida','Ferias Tradicionales y Patronal. Se celebra en Agosto, Septiembre y Octubre. Gran relevancia comarcal y provincial por su ciclo de ferias de origen medieval que culminan en la Darrera Fira, atrayendo masivamente a visitantes de toda la isla para disfrutar de muestras agrícolas, artesanales y ganaderas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07012','fiesta','Festes de Sant Antoni y Fires i Festes de Primavera','Etnográfica, Patronal y Feria Tradicional. Se celebra en Enero y Mayo/Junio. La celebración de Sant Antoni en Manacor es un hito etnográfico de nivel regional de extraordinaria afluencia, famoso por las monumentales hogueras, el baile ritual de los dimonis frente a la iglesia y el canto masivo de los tradicionales glosats.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07034','fiesta','Festes de Sant Joan Baptista y Fira de l''Esclata-sang','Patronal y Gastronómica/Micológica. Se celebra en Junio y Noviembre. Municipio de la sierra muy concurrido en otoño por su feria gastronómica monográfica dedicada al esclata-sang [níscalo silvestre], un hito gastronómico tradicional en la comarca del Raiguer.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07035','fiesta','Festes de la Mare de Déu de la Salut y Fira del Tomàquet de Ramellet','Patronal y Gastronómica. Se celebra en Septiembre. Celebración de arraigo local en el Pla de Mallorca que se dinamiza con la promoción y venta del tomate de colgar autóctono, un pilar culinario de la gastronomía de la isla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90659','fiesta','Sant Marçal y Fira del Fang','Patronal y Feria Artesanal. Se celebra en Junio y Marzo. Hito artesanal y comarcal centrado en la alfarería tradicional. La Fira del Fang congrega a ceramistas nacionales e internacionales, complementando las tradicionales verbenas de las fiestas de Sant Marçal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07014','fiesta','Festes de Sant Bartomeu','Etnográfica y Patronal. Se celebra en Agosto. Posee un incalculable valor etnográfico gracias a los Cossiers de Montuïri, cuya danza ancestral ritual es una de las más puras y fervientes de la isla, atrayendo a multitud de folcloristas e historiadores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07039','fiesta','Festes de Sant Joan Baptista y Fira de Sant Francesc','Patronal y Feria Agropecuaria. Se celebra en Junio y Abril. Festividades de relieve comarcal con gran arraigo agrario; su feria de primavera destaca por las exhibiciones de ganadería autóctona y la tradicional muestra de artesanía popular en el centro histórico). Isla: Mallorca (Bloque 4: Municipios de Palma a San Juan [Sant Joan].','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07016','fiesta','Festes de Santa Praxedis y Fiestas del Beato Junípero Serra','Patronal e Histórico-Cultural. Se celebra en Julio y Septiembre. Celebraciones que unen el fervor vecinal con el homenaje histórico a fray Junípero Serra, fundador de misiones en California, atrayendo a delegaciones internacionales y visitantes de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07017','fiesta','Festes de la Patrona (Nuestra Señora de los Ángeles) y Sant Antoni','Recreación Histórica, Etnográfica y Patronal. Se celebra en Enero y Julio/Agosto. Hito cultural masivo a nivel regional. El simulacro de la batalla de Moros y Cristianos del 2 de agosto es de un realismo y fervor popular sobrecogedores. En enero destaca la espectacular e histórica subida del pino de Sant Antoni.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07018','fiesta','Festes de Sant Roc y Fira de l''Albercoc','Patronal y Gastronómica. Se celebra en Agosto y Junio. Festa de marcado arraigo local en el Pla de Mallorca que gira en torno al cultivo y comercialización del albaricoque local, complementada en agosto con cenas al aire libre, conciertos y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07045','fiesta','Festes de la Mare de Déu d''Agost y Fira Ecológica','Patronal y Feria Sectorial. Se celebra en Agosto. Celebración tranquila de baja escala demográfica y perfil marcadamente vecinal en la Tramuntana, reforzada por su consolidada feria de productos agroalimentarios de producción ecológica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90660','fiesta','Festes de Sant Antoni y Fira de l''Arròs pobler','Etnográfica, Tradicional y Gastronómica. Se celebra en Enero y Noviembre. La noche de Sant Antoni en Sa Pobla es una de las manifestaciones de patrimonio inmaterial más puras y masivas de Baleares, célebre por sus cantos satíricos tradicionales, monumentales hogueras y las espectaculares danzas de los dimonis y caparrots.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07019','fiesta','Festes de Sant Joan Baptista y Festa del Botifarró','Patronal y Gastronómica. Se celebra en Junio y Octubre. De relieve comarcal por la pervivencia del Corremulla y su feria gastronómica de otoño dedicada al embutido tradicional balear, donde se asan miles de botifarrons en hogueras comunitarias). Isla: Mallorca (Bloque 5: Municipios de Sant Llorenç des Cardassar a Vilafranca de Bonany.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90663','fiesta','Festes de la Mare de Déu de Trobada y Fiestas del Turista (en Cala Millor)','Patronal y Turística. Se celebra en Agosto y Septiembre. Equilibra la devoción vecinal de su núcleo de interior con los pasacalles, fuegos artificiales y conciertos multitudinarios organizados en la zona costera para despedir la temporada turística estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07053','fiesta','Festes de Santa Eugènia y Fira Agrícola i Ramadera','Patronal y Feria Tradicional. Se celebra en Julio y Abril. Festividades de baja densidad demográfica con un ambiente hogareño, dinamizadas en primavera por una pequeña muestra de maquinaria agrícola, artesanía local y compraventa de animales de corral.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07055','fiesta','Festes de la Beata (Santa Catalina Tomàs)','Etnográfica, Religiosa y Patronal. Se celebra en Septiembre (Primer domingo). Hito etnográfico provincial de altísima consideración por la procesión de La Beata, definida como la más típica de Mallorca; los jóvenes visten trajes payeses tradicionales y disputan jarrones de barro a los dimonis, quienes los rompen contra el suelo a los pies de la santa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07056','fiesta','Festes de Margalida y Fira de Santa Maria','Patronal y Feria Tradicional/Enológica. Se celebra en Julio y Abril. Su feria de primavera es una de las muestras agrarias, artesanales y de vino tradicional más concurridas de la comarca del Raiguer, respaldada por la fuerte raigambre de las bodegas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07020','fiesta','Festes de Sant Jaume y Fira de Santanyí','Patronal y Feria Artesanal/Gastronómica. Se celebra en Julio y Octubre. Celebraciones que vertebran el Migjorn mallorquín; destaca su feria de otoño con exposiciones de la famosa piedra caliza de Santanyí, productos agroalimentarios de proximidad y eventos musicales nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07058','fiesta','Festes de Sant Llorenç y Fira de ses Herbes','Patronal y Etnográfica/Botánica. Se celebra en Agosto y Junio. Atractivo comarcal singular por su feria de las hierbas, donde se recrea la destilación tradicional del agua de azahar en alambiques de cobre y se adorna el pueblo con plantas aromáticas de la Serra de Tramuntana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07047','fiesta','Festes de la Beata Sor Francinaina Cirer y Fira del Ram','Religiosa, Patronal y Feria Tradicional. Se celebra en Febrero y Mayo. Celebración de arraigo local centrada en la devoción a su beata local y complementada por su feria tradicional de primavera que congrega muestras de artesanía, ganadería y actividades lúdicas infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07022','fiesta','Sa Fira de Sineu y Festes de la Mare de Déu d''Agost','Feria Histórica Agropecuaria y Patronal. Se celebra en Mayo (Primer domingo) y Agosto. Hito regional masivo. Sa Fira es la feria más antigua de Mallorca, establecida por privilegio real de Sancho I en 1318; es la única feria netamente agrícola y ganadera tradicional que congrega a decenas de miles de personas de todo el archipiélago.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07023','fiesta','Fira i Festes de Nostra Senyora de la Victòria (Es Firó)','Recreación Histórica, Conmemorativa y Masiva. Se celebra en Mayo. Celebración multitudinaria de rango regional. Es Firó conmemora la victoria de los sollericos contra los piratas turcos en 1561; la recreación en la playa y en la plaza con pólvora, trabucos, trajes históricos y fervor colectivo es un fenómeno cultural único.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07062','fiesta','Festes de Sant Joan y Fira de la Flor d''Ametler','Patronal y Feria Turístico-Gastronómica. Se celebra en Junio y Febrero. Destaca en el invierno isleño por su feria monográfica dedicada a la flor del almendro y sus aplicaciones gastronómicas y cosméticas, sirviendo de escaparate de la Mallorca tradicional ante el visitante foráneo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07063','fiesta','Festes de la Beata (Santa Catalina Tomàs) y Fiestas de San Bartolomé','Patronal, Religiosa y Cultural. Se celebra en Julio y Agosto. Festividad de alta relevancia comarcal y turística; el desfile del Carro de la Beata recorre las empedradas y decoradas calles de este icónico pueblo de montaña, atrayendo a multitud de visitantes por su belleza plástica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07024','fiesta','Festa del Meló y Festes de Santa Bàrbara','Gastronómica, Feria Agropecuaria y Patronal. Se celebra en Septiembre. Fiesta gastronómica de gran calado comarcal en torno al cultivo tradicional del melón; incluye concursos de peso y calidad del fruto, exposiciones agrícolas locales y multitudinarias verbenas de fin de verano). Con este bloque completamos de forma estricta todos los municipios de la isla de Mallorca (de la A a la Z). Para mantener el orden jerárquico y alfabético oficial de la Comunidad Autónoma de las Islas Baleares, el proyecto debe continuar ahora con las islas menores. ¿Puedo continuar con el siguiente bloque correspondiente a las festividades tradicionales de la isla de Menorca y sus municipios (Alaior, Es Castell, Ciutadella de Menorca, Ferreries, Maó-Mahón, Es Mercadal, Es Migjorn Gran, Sant Lluís)?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90016','fiesta','Festes de Sant Llorenç','Patronal y Etnográfica (Jaleo). Se celebra en Agosto. Celebración de gran relevancia provincial que destaca por sus tradicionales jaleos, donde los caballos de raza menorquina saltan entre la multitud al ritmo de la música, complementada con el popular desfile de carrozas de Ses Corregudes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90850','fiesta','Festes de Sant Jaume','Patronal y Etnográfica (Jaleo). Se celebra en Julio. Festividades de notable impacto comarcal y turístico en el levante de la isla; el muelle de Cales Fonts y la plaza del ayuntamiento se convierten en el epicentro de los tradicionales caracoleos ecuestres y verbenas marineras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07006','fiesta','Festes de Sant Joan','Etnográfica, Ecuestre y Patronal. Se celebra en Junio. Hito cultural y etnográfico masivo de nivel nacional. Su origen medieval, el estricto protocolo de sus estamentos tradicionales [caixers], los espectaculares e históricos juegos de Ses Voltes y los Caragols ecuestres atraen a decenas de miles de visitantes de todo el país.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90657','fiesta','Festes de Sant Bartomeu','Patronal y Etnográfica (Jaleo). Se celebra en Agosto. Festividad de arraigo comarcal celebrada en el interior de la isla, caracterizada por la pureza de sus toques de replique de campanas, la procesión de la Qualcada y los concurridos jaleos ecuestres en la plaza de la Iglesia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90021','fiesta','Festes de la Mare de Déu de Gràcia','Patronal, Marina y Etnográfica. Se celebra en Septiembre. Celebración masiva de nivel regional que clausura el verano menorquín en la capital de la isla, destacando por el solemne canto del Esclat de Gràcia, los tradicionales jaleos en la plaza de la Constitución y las regatas y eventos lúdicos en su puerto histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07037','fiesta','Festes de Sant Martí','Patronal y Etnográfica (Jaleo). Se celebra en Julio. Fiestas tradicionales de gran atractivo en el centro geográfico de la isla, que congregan a numerosos jinetes [caixers y cavallers] y destacan por la tradicional subida al Santuario de la Virgen de Toro, el punto más alto de Menorca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07902','fiesta','Festes de Sant Cristòfol','Patronal y Etnográfica (Jaleo). Se celebra en Julio y Agosto. Festividad comarcal de alta raigambre popular que resalta por la peculiaridad de los caballos danzando al son de la banda de música y el entrañable homenaje que se rinde a los ancianos del pueblo durante los actos tradicionales). Isla: Menorca (Bloque 2: Municipio de Sant Lluís.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07052','fiesta','Festes de Sant Lluís','Patronal y Etnográfica (Jaleo). Se celebra en Agosto. Celebración tradicional de escala comarcal fundada durante la dominación francesa de la isla; combina el estricto protocolo de la qualcada menorquina con desfiles de gigantes, cabezudos y verbenas nocturnas). Isla: Ibiza [Eivissa] (Bloque 1: Municipios de Ibiza a Sant Joan de Labritja.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90662','fiesta','Festes de Sant Antoni y Fiestas de Sant Bartomeu','Patronal, Tradicional y Folclórica. Se celebra en Enero y Agosto. Festividades de relevancia comarcal que combinan la tradición invernal de la bendición de animales y exhibiciones de ball pagès con los masivos eventos estivales del puerto, destacando la multitudinaria batalla campal simulada de "Cartagineses y Romanos" en la playa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90022','fiesta','Festes de Sant Joan','Patronal y Etnográfica. Se celebra en Junio. Celebración de arraigo tradicional en el norte rural de la isla, famosa por la quema de los foguerons [hogueras] en la noche de San Juan, donde los locales saltan el fuego para purificarse, acompañados de buñuelos tradicionales y vino de la tierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90023','fiesta','Festes de Sant Josep','Patronal, Folclórica y Gastronómica. Se celebra en Marzo. Festividad de relieve comarcal muy concurrida por abrir la temporada de fiestas patronales en la isla, caracterizada por las muestras de indumentaria tradicional y joyería de oro payesa [entallons], danzas ancestrales en el pozo y verbenas de música rock.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90851','fiesta','Festes de Santa Eulària (Primer Domingo de Mayo)','Etnográfica, Patronal y Folclórica. Se celebra en Mayo. Gran relevancia comarcal y provincial. Destaca por su espectacular desfile de carros tradicionales engalanados, considerados un emblema del patrimonio móvil de Ibiza, reuniendo a agrupaciones folclóricas de todo el archipiélago y exhibiciones de artesanía local). Isla: Formentera (Bloque Único: Municipio de Formentera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07009','fiesta','Festes de Sant Jaume (San Jaime) y Festes de la Mare de Déu de la Mola','Patronal, Folclórica y Cultural. Se celebra en Julio y Octubre. La festividad institucional y patronal de la menor de las Pitiusas congrega a toda la isla en San Francisco Javier; destaca por la pureza de sus muestras de ball pagès acompañadas de xeremies y tambores, conciertos al aire libre y un marcado ambiente de reencuentro comunitario y turístico). Con este registro cerramos de forma estricta el 100% de la Comunidad Autónoma de las Islas Baleares (Illes Balears), habiendo listado de forma jerárquica y alfabética cada una de sus islas y municipios. Para continuar con el proyecto en una nueva sesión o mensaje de acuerdo al orden oficial del Estado, corresponde dar el salto a la siguiente Comunidad Autónoma según la lista de tareas pendientes. ¿Deseas que prepare el inicio de la Comunidad Valenciana comenzando por la provincia de Alicante y sus municipios de la letra A?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90401','fiesta','Fiestas Patronales en honor a la Virgen del Rosario','Patronal y Moros y Cristianos. Se celebra en Septiembre. Celebración de arraigo estrictamente local y marcado carácter familiar en la comarca de la Marina Alta, condicionada por su baja densidad demográfica, donde destacan las cenas populares y las pequeñas verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03001','fiesta','Fiestas de Moros y Cristianos y Danses de Rei en Jaume','Moros y Cristianos y Etnográfica (Danzas tradicionales). Se celebra en Junio y Diciembre. Festividad de relieve comarcal que destaca por sus danzas tradicionales del solsticio de invierno y el valor de su alfarería artesanal, la cual se promociona de forma paralela durante los actos públicos de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90378','fiesta','Festes de la Mare de Déu d''Agres','Religiosa, Recreación Histórica y Patronal. Se celebra en Septiembre. Relevancia comarcal y provincial en el interior de Alcoy; destaca por la escenificación teatral del hallazgo de la virgen por un pastor en el castillo de Agres, atrayendo a numerosos peregrinos de toda la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90852','fiesta','Fiestas de Moros y Cristianos en honor a San Antonio de Padua','Moros y Cristianos y Patronal. Se celebra en Agosto. Fiestas tradicionales de baja escala demográfica y perfil vecinal, que dinamizan el municipio en época estival con desfiles de comparsas, dianas musicales y comidas de hermandad en la plaza Mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90379','fiesta','Fiestas Patronales en honor a Santiago Apóstol y Moros y Cristianos','Patronal y Moros y Cristianos. Se celebra en Julio. Celebración tradicional que vertebra esta localidad de la Vega Baja, donde destacan los desfiles de las huestes moras y cristianas, la ofrenda floral al santo patrón y la gastronomía popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90380','fiesta','Fiestas en honor a San Juan Bautista y San Mosén Jaime','Patronal y Etnográfica (Fira Feslalí). Se celebra en Junio y Febrero. Atractivo comarcal en la Marina Alta gracias a su muestra etnológica y turística vinculada a la floración del almendro, complementando sus fiestas patronales veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90853','fiesta','Fiestas Patronales de San Roque','Patronal y de Retorno. Se celebra en Agosto. Celebración estrictamente local en un municipio de mínima demografía, sustentada por las verbenas veraniegas y las procesiones religiosas tradicionales que reúnen a la población flotante estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03002','fiesta','Fiestas de Moros y Cristianos de Alcoy y Cabalgata de Reyes Magos','Moros y Cristianos (Histórica) y Tradición Navideña. Se celebra en Abril y Enero. Sus Moros y Cristianos ostentan la declaración de Fiesta de Interés Turístico Internacional, siendo la cuna y máximo exponente de esta tradición en España. Su Cabalgata de Reyes Magos es, además, la más antigua de todo el país.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46022','fiesta','Fiestas Patronales en honor a San Roque y la Virgen de la Luz','Patronal y Moros y Cristianos. Se celebra en Agosto. Celebración de arraigo puramente local en las faldas de la Serra Mariola, caracterizada por la convivencia vecinal en las calles, carreras populares infantiles y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90009','fiesta','Fiestas del Santísimo Cristo del Buen Acierto','Patronal y Etnográfica (Peñas). Se celebra en Noviembre. De notable relevancia comarcal en la Marina Baixa, con una gran participación vecinal a través de peñas asociadas, desfiles humorísticos, ofrendas de flores y actos religiosos tradicionales de gran concurrencia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90854','fiesta','Fiestas Patronales de la Virgen del Carmen','Patronal y Tradicional. Se celebra en Julio. Fiestas de arraigo vecinal en la comarca de la Vega Baja del Segura, caracterizadas por las procesiones de la virgen, verbenas populares en la plaza y campeonatos deportivos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90381','fiesta','Fiestas Patronales en honor a los Santos de la Piedra (San Abdón y San Senén)','Patronal y Enológica. Se celebra en Julio. Celebración de arraigo local en la comarca del Vinalopó que incluye catas y promoción del vino artesanal con Denominación de Origen Alicante, acompañando a las verbenas populares del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03003','fiesta','Hogueras de San Juan (Fogueres de Sant Joan)','Monumental, Masiva y Etnográfica. Se celebra en Junio. Declaradas Oficialmente de Interés Turístico Internacional, constituyen el hito cultural masivo de la capital provincial, congregando a cientos de miles de visitantes en torno a la plantá y cremá de monumentos satíricos de madera y cartón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90382','fiesta','Feria del Automóvil, Fiestas de Moros y Cristianos y de los Santos Justo y Pastor','Moros y Cristianos, Patronal y Feria Comercial. Se celebra en Julio. Relevancia comarcal consolidada en la Vega Baja gracias al gran empaque de sus desfiles de comparsas de Moros y Cristianos, sumado a su histórica tradición como centro comercial y agrícola de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90383','fiesta','Fiestas Patronales de San Bartolomé Apóstol','Patronal y de Retorno. Se celebra en Agosto. Pequeña festividad veraniega de carácter estrictamente local en el interior alicantino, sustentada por las reuniones familiares, cenas en las calles de la villa y tradicionales procesiones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90855','fiesta','Fiestas Patronales de San Miguel y Moros y Cristianos','Patronal y Moros y Cristianos. Se celebra en Septiembre. Celebración vecinal de escala local en el Condado de Cocentaina, dinamizada por la participación de las escuadras moras y cristianas del municipio en un ambiente de proximidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03004','fiesta','Fiestas del Santísimo Cristo del Sagrario y Moros y Cristianos (Sant Blai)','Moros y Cristianos, Patronal y Pirotécnica. Se celebra en Septiembre (y el Castell de l''Olla en Agosto). Gran empaque provincial y regional; destaca de forma masiva su Castell de l''Olla en agosto, un espectáculo pirotécnico disparado íntegramente desde el mar declarado de Interés Turístico que congrega a decenas de miles de personas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03005','fiesta','Fiestas en honor a la Virgen de las Nieves (Años pares)','Patronal, Tradicional y Etnográfica. Se celebra en Agosto. Festividad de rango regional declarada de Interés Turístico por la singularidad de la traída de la Virgen desde Hondón de los Frailes cada dos años, movilizando a toda la comarca del Medio Vinalopó en un fervor multitudinario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90384','fiesta','Fiestas en honor a San Francisco y la Virgen del Rosario','Patronal y de Retorno. Se celebra en Agosto. Verbenas populares de baja escala demográfica y carácter estrictamente vecinal, cuyo objetivo principal es el reencuentro de la población nativa durante el periodo estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03006','fiesta','Fiestas de San Jorge (Moros y Cristianos)','Moros y Cristianos y Etnográfica. Se celebra en Abril. Posee la declaración de Fiesta de Interés Turístico Nacional; destaca por la pureza de sus desfiles, las monumentales batallas de arcabucería y el acto etnográfico singular del Ball dels Espies.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90385','fiesta','Fiestas de San Joaquín y la Virgen de los Ángeles','Patronal y de Retorno. Se celebra en Agosto *. Celebración puramente vecinal de baja demografía en el interior de la provincia, basada en procesiones tradicionales, campeonatos de cartas populares y música nocturna en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90856','fiesta','Fiestas de Moros y Cristianos en honor a la Divina Aurora','Moros y Cristianos y Patronal. Se celebra en Septiembre. De gran arraigo comarcal en el Alto Vinalopó; resalta por la representación teatral del "Tratado de Almisra" y la alta implicación de la población en las embajadas de arcabucería.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90386','fiesta','Fiestas del Pilar y Fiestas Patronales de la Virgen del Rosario','Romería, Patronal y Folclórica. Se celebra en Octubre. La Romería de la Virgen del Pilar a la ermita de La Pilarica goza de gran relevancia comarcal en la Vega Baja, destacando por las muestras de jotas locales y la masiva acampada tradicional en la sierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90387','fiesta','Fiestas de San Jerónimo y la Virgen del Rosario','Patronal y Tradicional. Se celebra en Septiembre y Octubre. Celebración tradicional de escala estrictamente local, fundamentada en comidas populares, desfiles de carrozas infantiles y verbenas organizadas para la comunidad local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90388','fiesta','Fiestas Patronales de San Roque','Patronal y Tradicional. Se celebra en Agosto. Fiestas de arraigo familiar en la Marina Alta, dinamizadas por pasacalles musicales, cenas populares en las calles principales de la villa y verbenas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90389','fiesta','Fiestas en honor a la Virgen de los Dolores','Patronal y de Retorno. Se celebra en Agosto. Localidad de baja demografía en el Valle de Guadalest con celebraciones enfocadas al reencuentro de familiares emigrados, incluyendo actos litúrgicos clásicos y música popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90390','fiesta','Fiestas de Moros y Cristianos en honor a la Virgen de la Cueva Santa','Moros y Cristianos y Patronal. Se celebra en Agosto. Celebración de arraigo comarcal que incluye desfiles tradicionales de bandos moros y cristianos en el entorno del embalse, sumando actos de devoción a la patrona de los agricultores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90391','fiesta','Fiestas Patronales de San Vicente Ferrer y la Virgen de la Soledad','Patronal y Tradicional. Se celebra en Agosto. Festividad local de la Marina Alta centrada en el reencuentro estival, con verbenas al aire libre, despertás musicales y torneos de pelota valenciana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03007','fiesta','Festes Majors Patronals (Virgen del Sufragio y San Jaime Apóstol)','Patronal, Histórica y Masiva. Se celebra en Noviembre. Hito cultural y festivo de nivel regional debido a su alto impacto demográfico y turístico. Destaca la escenificación del hallazgo de la Virgen en una barca arrastrada a la costa y el colosal desfile del humor de las peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90392','fiesta','Fiestas de Moros y Cristianos en honor a San Miguel','Moros y Cristianos y de Retorno. Se celebra en Septiembre. Fiestas vecinales de baja densidad demográfica en el interior alicantino, organizadas con pequeñas procesiones e informales desfiles de disfraces y comparsas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90393','fiesta','Fiestas Patronales de San Miguel','Patronal y de Retorno. Se celebra en Agosto. Celebración estrictamente local en uno de los municipios con menor censo de la provincia, caracterizada por cenas de sobaquillo vecinales y una pequeña verbena musical.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90394','fiesta','Fiestas de San José, San Agustín y San Francisco Javier','Patronal y Cultural. Se celebra en Agosto. Festa de marcado arraigo local en el Valle de Pop, donde las competiciones de pilota valenciana en la calle de la villa y las verbenas nocturnas centran el entretenimiento de los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90395','fiesta','Fiestas Patronales de Santiago Apóstol','Patronal y Tradicional. Se celebra en Julio. Celebración de carácter local en la Vega Baja que reúne desfiles de carrozas, verbenas en el recinto ferial y la solemne procesión del apóstol por el casco urbano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90396','fiesta','Fiestas de Moros y Cristianos en honor a San Joaquín','Moros y Cristianos y Patronal. Se celebra en Agosto. Celebración comarcal que resalta por su tradicional acto de La Ambaixada del Tomate, una parodia local satírica previa a los desfiles serios de las comparsas moras y cristianas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90397','fiesta','Fiestas de San Lorenzo y la Virgen del Rosario','Patronal y de Retorno. Se celebra en Agosto. Pequeña festividad vecinal de escala estrictamente familiar en el Condado de Cocentaina, dinamizada por música ambiente y comidas compartidas al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90398','fiesta','Fiestas de San Lorenzo y de la Juventud','Patronal y de Retorno. Se celebra en Agosto y Octubre. Fiestas de arraigo local en la sierra, basadas en procesiones religiosas tradicionales, actividades infantiles en la plaza de la villa y verbenas de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90399','fiesta','Fiestas en honor a San Jaime, Santa Ana y la Virgen del Rosario','Patronal y Tradicional. Se celebra en Julio. Celebración tradicional de escala familiar, donde destaca el pasacalles del pan bendito y las cenas comunitarias que congregan a los habitantes del núcleo rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03008','fiesta','Fiestas de la Virgen de la Purísima Concepción','Patronal y de Retorno. Se celebra en Agosto. Conocido como el "balcón de la Serrella", este pequeño pueblo celebra sus fiestas estivales bajo un formato plenamente familiar, con verbenas de pequeña escala y pasacalles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90400','fiesta','Fiestas de San Ecce Homo y la Purísima Concepción','Patronal y Tradicional. Se celebra en Agosto. Celebración vecinal en la rectoría de la Marina Alta, centrada en comidas compartidas en la plaza pública, despertás pirotécnicas y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03009','fiesta','Festes de la Puríssima Xiqueta y Fiestas de Moros y Cristianos','Patronal, Moros y Cristianos y Etnográfica. Se celebra en Abril y Junio. Relevancia comarcal y provincial destacada; la bajada de la imagen de la Puríssima Xiqueta mediante un sistema mecánico tradicional genera gran fervor, complementado por un vistoso desfile de Moros y Cristianos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03043','fiesta','Fiestas de Moros y Cristianos en honor a la Virgen de Gracia','Moros y Cristianos y Etnográfica (Gigantes). Se celebra en Mayo. Hito etnográfico de nivel regional; destaca por el desfile de Els Espies [Los Espías] y las colosales figuras de los gigantes de Biar, de origen medieval, junto al imponente encendido de hogueras en la montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03044','fiesta','Fiestas de San Joaquín y la Virgen de la Alborada','Patronal y Tradicional. Se celebra en Agosto. De arraigo en la Vega Baja, destaca la procesión nocturna de la Virgen de la Alborada a las doce de la noche del 15 de agosto, acompañada de cantos populares y un gran castillo de fuegos artificiales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03045','fiesta','Fiestas de la Virgen de los Dolores y el Santísimo Sacramento','Patronal y de Retorno. Se celebra en Agosto. Fiestas tradicionales vecinales en el interior de la Marina Baixa, potenciadas por el turismo rural estival mediante orquestas locales y competiciones deportivas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03046','fiesta','Fiestas de Moros y Cristianos en honor a San José *','Moros y Cristianos y Patronal *. Se celebra en Abril *. De relieve comarcal, sus desfiles se desarrollan a las faldas de su histórico castillo y de la entrada a las Cuevas del Canelobre, atrayendo a numerosos visitantes de las localidades costeras cercanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03049','fiesta','Fiestas de San Roque (Moros y Cristianos)','Moros y Cristianos, Patronal y Etnográfica. Se celebra en Agosto. Festividad de gran empaque comarcal e histórico en la Vega Baja; destaca la tradicional "Fiesta de la Chirimía" y la procesión del santo, declaradas de Interés Turístico por su antigüedad y masiva participación.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03048','fiesta','Fiestas de Moros y Cristianos en honor a la Virgen de las Injurias','Moros y Cristianos y Etnográfica. Se celebra en Octubre. Hito etnográfico provincial de alta consideración; son uno de los desfiles de Moros y Cristianos más antiguos de la comarca, célebres por la rigurosidad histórica de sus trajes y el tradicional baile de Les Pastoretes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03010','fiesta','Fiestas en honor a la Virgen de las Nieves y Moros y Cristianos (Santíssim Crist de la Suor)','Patronal, Moros y Cristianos y Turística. Se celebra en Agosto y Octubre. Elevado impacto turístico y provincial; sus desfiles de Moros y Cristianos destacan por el simulacro de desembarco marítimo en la playa, bajo la imponente silueta del Peñón de Ifach.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03015','fiesta','Fiestas de la Virgen del Carmen y Moros y Cristianos','Marinera, Moros y Cristianos y Patronal. Se celebra en Julio y Octubre. Relevancia comarcal en l''Alacantí. Destaca tanto su procesión marinera costera por la Virgen del Carmen como el espectacular desembarco moro al amanecer en las playas del municipio durante el otoño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03051','fiesta','Fiestas de San Bartolomé Apóstol y Representación del Tratado de Almisra','Recreación Histórica y Patronal. Se celebra en Agosto. Posee una enorme importancia histórico-cultural comarcal debido al "Tratado de Almisra", obra teatral al aire libre que recrea el pacto de fronteras firmado en 1244 entre Jaime I y el infante Alfonso de Castilla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03052','fiesta','Auto Sacramental de los Reyes Magos y Fiestas de Moros y Cristianos en honor a San Cristóbal','Recreación Histórica, Religiosa, Patronal y Moros y Cristianos. Se celebra en Enero y Julio. Su Auto Sacramental de Reyes Magos es un hito etnográfico de nivel provincial basado en el texto del siglo XVIII de Gaspar Fernández y Ávila, atrayendo a miles de visitantes cada 6 de enero, complementado en verano por sus coloridas embajadas de Moros y Cristianos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03011','fiesta','Fiestas de Moros y Cristianos en honor a la Virgen de la Soledad','Moros y Cristianos, Patronal y Recreación Histórica. Se celebra en Septiembre. Festividades de gran empaque comarcal en la Hoya de Castalla que destacan por el riguroso orden de sus comparsas, las espectaculares guerrillas de arcabucería y las solemnes procesiones dedicadas a su patrona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03054','fiesta','Fiestas Patronales en honor a Santa Ana y la Virgen de la Asunción','Patronal y Tradicional. Se celebra en Julio y Agosto. Celebraciones de arraigo estrictamente local y marcado carácter vecinal en el interior de la Marina Alta, fundamentadas en verbenas populares, cenas de hermandad al aire libre y tradicionales partidas de pelota valenciana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03055','fiesta','Romería de Santa Águeda y Fiestas Patronales de San Juan Bautista','Romería, Patronal y Etnográfica. Se celebra en Febrero y Junio. De notable relevancia comarcal en la Vega Baja; la Romería de Santa Águeda es un hito religioso tradicional y multitudinario donde destaca la compra de las famosas "bolicas de Santa Águeda" y exvotos en los puestos ambulantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03012','fiesta','Fira de Tots Sants y Fiestas de Moros y Cristianos en honor a San Hipólito Mártir','Feria Histórica, Comercial, Moros y Cristianos y Patronal. Se celebra en Noviembre y Agosto. La Fira de Tots Sants, creada en 1346 por privilegio real de Pedro IV de Aragón, está declarada Fiesta de Interés Turístico Internacional, constituyendo un hito socioeconómico y etnográfico masivo que congrega a centenares de miles de visitantes cada año.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03057','fiesta','Fiestas Patronales en honor a la Virgen de los Dolores (y Sant Antoni en Abdet)','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo estrictamente local vinculadas a la baja demografía de este núcleo del Valle de Guadalest, centradas en las procesiones tradicionales, las verbenas estivales y la tradicional Festa de los Jóvenes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03058','fiesta','Fiestas Patronales en honor a la Virgen del Carmen','Patronal y Religiosa. Se celebra en Julio. Celebración de arraigo local y comarcal en la Vega Baja del Segura, caracterizada por la masiva participación en la solemne procesión de la Virgen, los coloridos desfiles de carrozas y las verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03013','fiesta','Fiestas de Moros y Cristianos en honor a San Francisco de Asís y Semana Santa','Moros y Cristianos, Religiosa y Patronal. Se celebra en Septiembre/Octubre y Marzo/Abril. Sus Fiestas de Moros y Cristianos ostentan el título de Interés Turístico Nacional, destacando por la espectacularidad e historicidad de sus embajadas y pasacalles, al igual que su Semana Santa, célebre por la imaginería religiosa y la tradición coral del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03061','fiesta','Fiestas Patronales en honor a San Miguel Arcángel','Patronal y Tradicional. Se celebra en Septiembre. Celebraciones tradicionales de escala vecinal y retorno estival marcadas por su demografía moderada, organizando carreras populares, desfiles de carrozas humorísticas y cenas comunitarias en la plaza del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03062','fiesta','Fiestas Patronales en honor a la Virgen de Montserrat','Patronal y Tradicional. Se celebra en Septiembre. Fiestas de arraigo estrictamente local adaptadas a una de las poblaciones más pequeñas de la comarca, dinamizadas por juegos infantiles tradicionales, pasacalles musicales y verbenas populares para la comunidad local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03014','fiesta','Festes de la Santíssima Sang (Bous a la Mar) y Moros y Cristianos','Taurina, Marinera, Moros y Cristianos y Patronal. Se celebra en Julio y Agosto. Hito cultural regional de gran afluencia turística. Su festejo de Bous a la Mar está declarado de Interés Turístico Nacional, caracterizado por una plaza semiabierta al puerto donde los participantes intentan que el toro caiga al agua.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03064','fiesta','Fiestas de la Virgen de los Dolores y Feria de Ganado de Dolores (FEGADO)','Patronal y Feria Sectorial/Ganadera. Se celebra en Septiembre y Agosto. Relevancia comarcal y provincial gracias a su consolidada feria de ganado, catalogada como la más importante de la Comunidad Valenciana en su sector, que recupera las raíces agrarias y tradicionales de la comarca de la Vega Baja.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03016','fiesta','Fiestas de la Venida de la Virgen y Misteri d''Elx (Fiestas de Agosto)','Religiosa, Drama Sacro-Lírico, Patronal y Masiva. Se celebra en Agosto y Diciembre. El Misteri d''Elx es una de las joyas patrimoniales más importantes de España, declarado Obra Maestra del Patrimonio Oral e Inmaterial de la Humanidad por la UNESCO. Las fiestas patronales incluyen hitos masivos como la espectacular Nit de l''Albà y la Nit de la Roà.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90371','fiesta','Festes de Sant Antoni Abat y Moros i Cristians','Moros y Cristianos, Etnográfica y Patronal. Se celebra en Enero y Septiembre *. De relieve comarcal en la Vall d''Albaida; destaca por las hogueras de invierno y la pureza de sus embajadas y desfiles de comparsas de Moros y Cristianos en otoño, muy ligadas a su arraigada industria de la artesanía textil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03042','fiesta','Fiestas de Santa María Magdalena','Patronal y Tradicional. Se celebra en Julio. Fiestas tradicionales de la Marina Alta con pasacalles populares, danzas tradicionales valencianas y noches lúdicas para residentes y turistas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03017','fiesta','Fiestas de Moros y Cristianos en honor a San Antón y Fiestas Mayores Patronales','Moros y Cristianos, Patronal y CívicoReligiosa. Se celebra en Junio y Septiembre. Sus fiestas de Moros y Cristianos son un hito de rango regional de extraordinaria participación, célebres por la espectacularidad de sus desfiles, la Entrada de Bandas y los monumentales certámenes musicales que transforman el municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03067','fiesta','Fiestas Patronales en honor al Espíritu Santo','Patronal y Tradicional. Se celebra en Agosto. Celebración de arraigo estrictamente local condicionada por la baja demografía del interior montañoso; estructurada en torno a misas tradicionales, campeonatos de cartas, pasacalles y verbenas de reencuentro estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03068','fiesta','Fiestas Patronales en honor a San Cayetano','Patronal y Tradicional. Se celebra en Agosto. Fiestas vecinales e íntimas en uno de los municipios con menor población de la provincia, basadas en cenas populares en la calle, juegos infantiles y verbenas de carácter familiar y de retorno.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03018','fiesta','Festes Patronals en honor a Sant Bertomeu y el Santo Cristo del Remedio','Patronal y Etnográfica. Se celebra en Agosto. Celebración de relieve comarcal en la Marina Baixa que destaca por la tradicional "colgada de barracas", vistosos desfiles de disfraces humorísticos, actos religiosos solemnes y una gran participación de la juventud local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03070','fiesta','Fiestas Patronales en honor a la Purísima Concepción y San Roque','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo local en la Vega Baja que congregan a la comunidad en torno a verbenas populares, la tradicional romería, desfiles de carrozas y una monumental paella comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90857','fiesta','Fiestas de Moros y Cristianos en honor a la Virgen de la Luz','Moros y Cristianos y Patronal. Se celebra en Septiembre. Celebraciones locales de fuerte identidad tradicional en El Comtat, caracterizadas por las representaciones de embajadas, las guerrillas de arcabucería y los emotivos actos religiosos en honor a su patrona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03071','fiesta','Festes en honor al Santíssim Crist del Calvari','Patronal y Taurina. Se celebra en Julio y Agosto. De notable relevancia comarcal; sus festejos destacan por las concurridas jornadas taurinas de bous al carrer, las noches de cenas populares en las calles decoradas por los vecinos y los espectaculares correfocs.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03073','fiesta','Fiestas Patronales en honor a la Virgen de la Gracia','Patronal y Tradicional. Se celebra en Septiembre. Fiestas de carácter marcadamente vecinal y de retorno, centradas en el folclor tradicional de la montaña alicantina con despertás, procesiones solemnes y bailes populares en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03074','fiesta','Fiestas Patronales en honor a la Santísima Cruz y San Pedro','Patronal y Tradicional. Se celebra en Mayo. Celebración tradicional de escala local en la Vega Baja que conmemora el milagro de la Cruz con actos religiosos tradicionales, pasacalles de la banda de música y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03020','fiesta','Fiestas de Moros y Cristianos en honor a San Jaime','Moros y Cristianos, Recreación Histórica y Patronal. Se celebra en Julio. Hito cultural de rango regional que sobresale por la representación de la "L''Encantà" — leyenda de origen medieval puesta en escena en el cauce del río— y la espectacularidad costera de sus desfiles e imponentes embajadas moras y cristianas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03078','fiesta','Fiestas Patronales en honor a la Virgen de la Salud','Patronal y Tradicional. Se celebra en Agosto. Fiestas de arraigo estrictamente local basadas en la convivencia vecinal, que combinan el fervor religioso de las procesiones con desfiles de carrozas, competiciones deportivas y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03077','fiesta','Fiestas Patronales en honor a la Virgen de las Nieves','Patronal y Tradicional. Se celebra en Agosto. De relevancia comarcal en el valle del Vinalopó, celebradas con especial solemnidad los años pares debido a la romería de la traída de la imagen, acompañada de pasacalles, mascletás y bailes tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03021','fiesta','Fiestas de Moros y Cristianos y Fiesta de "Els Enfarinats" (Día de los Santos Inocentes)','Etnográfica, Satírica y Moros y Cristianos. Se celebra en Septiembre y Diciembre. La fiesta de Els Enfarinats es un hito etnográfico regional de altísimo valor por su singularidad de justicia satírica y batallas de harina, huevos y pólvora, conviviendo con sus multitudinarias fiestas de Moros y Cristianos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03080','fiesta','Fiestas Patronales en honor a la Virgen de la Belén','Patronal y Tradicional. Se celebra en Septiembre. Celebración de escala local en la Vega Baja que organiza sus actos en los emblemáticos jardines del Palacio de los Marqueses de Fontalba, con verbenas, desfiles informales de peñas y charangas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03022','fiesta','Fogueres de Sant Joan y Festes en honor a la Mare de Déu de Loreto','Patronal, Etnográfica, Marinera y Taurina. Se celebra en Junio y Septiembre. Festividades multitudinarias de relieve regional; las Fogueres de Sant Joan destacan por la espectacular "Nit dels Focs" [saltos de hogueras con coronas de flores], mientras que en el puerto los Bous a la Mar atraen masivamente al turismo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03083','fiesta','Fiestas de Moros y Cristianos en honor a San Bartolomé y San Sebastián, y Fira de Nadal','Moros y Cristianos, Patronal y Feria Gastronómica Tradicional. Se celebra en Agosto y Diciembre. Su feria navideña es un hito masivo a nivel regional enfocado en el turrón tradicional con Indicación Geográfica Protegida, complementando a sus históricas fiestas veraniegas de Moros y Cristianos denominadas "las del helado".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03094','fiesta','Festes de Agost en honor a la Virgen de la Asunción y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festividades de notable afluencia comarcal en la Marina Baixa, célebres por el masivo protagonismo de los "penyistes", los pasacalles de charangas y la ofrenda floral tradicional que llena de colorido el centro histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03903','fiesta','Fiestas Patronales en honor a la Virgen del Pilar','Patronal y Tradicional. Se celebra en Octubre. Fiestas de arraigo local vinculadas al entorno agrícola y lagunar, estructuradas a través de su vistosa ofrenda de flores, competiciones deportivas rústicas, carrozas humorísticas y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03084','fiesta','Fiestas de Moros y Cristianos en honor a Nuestra Señora de los Desamparados *','Moros y Cristianos y Patronal *. Se celebra en Julio *. Celebración local de gran tradición en los valles del río Serpis; incluye las embajadas tradicionales, el disparo festivo de arcabucería y las solemnes procesiones en honor a su patrona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03086','fiesta','Fiestas Patronales en honor a San José y la Virgen del Rosario','Patronal y Tradicional. Se celebra en Julio. Pequeña celebración de arraigo estrictamente local en el valle de Balones, basada en procesiones vecinales, cenas de fiambrera al aire libre y modestas verbenas musicales de reencuentro estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03088','fiesta','Fiestas de Moros y Cristianos en honor a la Purísima Concepción','Moros y Cristianos y Patronal. Se celebra en Diciembre. Poseen gran arraigo histórico y consideración provincial debido a la pureza y rigurosidad de sus Embajadas, sus desfiles multitudinarios y el singular estruendo de los trabucos en pleno invierno alicantino.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03089','fiesta','Fiestas Patronales en honor a la Virgen del Remedio','Patronal, Etnográfica y Gastronómica. Se celebra en Septiembre. De relevancia comarcal en el Medio Vinalopó; destacan las tradicionales "Barracas", la suelta de vaquillas, las muestras culinarias de la tierra y los solemnes actos cívico-religiosos dedicados a la patrona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03091','fiesta','Fiestas Patronales del Salvador y la Virgen de la Soledad','Patronal y Deportiva Tradicional. Se celebra en Agosto. Celebración de arraigo local célebre en toda la comarca por albergar grandes e históricas partidas de Pilota Valenciana a la modalidad de Llargues, que congregan a los mejores especialistas e interesados del deporte autóctono.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03024','fiesta','Fiestas de Moros y Cristianos en honor a la Virgen de los Desamparados','Moros y Cristianos y Patronal. Se celebra en Mayo. Festividades de notable relevancia comarcal y provincial, famosas por el espectacular desfile de "La Entrada", el rigor histórico de sus comparsas y el tradicional acto de "La Ambaixada del Tonyejo".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03025','fiesta','Fiestas de Moros y Cristianos en honor a la Virgen de Loreto','Moros y Cristianos y Patronal. Se celebra en Septiembre. Celebración de fuerte raigambre comarcal y huertana, caracterizada por la espectacularidad de su Entrada de Moros y Cristianos, los solemnes rezos y procesiones, y las activas embajadas infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03026','fiesta','Fiestas de Moros y Cristianos y Patronales en honor a Santa María Magdalena','Moros y Cristianos y Patronal. Se celebra en Julio. Destacada festividad comarcal en el Vinalopó, caracterizada por la solemne bajada del santuario modernista de la santa, acompañada de multitudinarios e históricos desfiles de las comparsas de moros y cristianos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03095','fiesta','Festes de la Soledat y Fira de Fires de Novembre','Patronal, Taurina y Feria Tradicional MultiSectorial. Se celebra en Julio y Noviembre. De relieve comarcal en la Marina Alta; sus verbenas estivales se complementan con una histórica feria otoñal que congrega muestras comerciales, gastronómicas y atracciones populares en su plaza de toros monumental.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03096','fiesta','Fiestas de Moros y Cristianos en honor a la Virgen de la Salud','Moros y Cristianos y Patronal. Se celebra en Abril y Mayo. Gran consideración comarcal y etnográfica en la cuna de las muñecas; destaca por la espectacularidad de su desfile nocturno "Nit de les Olletes", las embajadas líricas de sus comparsas y los disparos de arcabucería.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03097','fiesta','Fiestas Patronales en honor a la Virgen de los Desamparados','Patronal y Taurina. Se celebra en Mayo y Julio. Festividad de arraigo local dinamizada por sus famosas jornadas de bous al carrer, encierros tradicionales y verbenas populares nocturnas que congregan a la juventud de los pueblos de la rectoría.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03027','fiesta','Fiestas de la Reconquista y de Moros y Cristianos (Fiestas del Pájaro Oriol) y Semana Santa','Moros y Cristianos, Histórica, Religiosa y Masiva. Se celebra en Julio y Marzo/Abril. Su Semana Santa cuenta con la declaración de Fiesta de Interés Turístico Internacional debido a su incalculable valor artístico e histórico. Las fiestas de la Reconquista destacan por el histórico desfile de la monumental bandera del Pájaro Oriol.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90858','fiesta','Fiestas Patronales en honor a San Nazario y la Virgen de los Dolores','Patronal y Tradicional. Se celebra en Septiembre. Celebración vecinal de escala local en el interior de la Marina Baixa, basada en procesiones tradicionales, campeonatos de pelota valenciana, cenas populares al aire libre y modestas verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03100','fiesta','Fiestas Patronales en honor a San Lorenzo','Patronal y Tradicional. Se celebra en Agosto. Fiestas de arraigo estrictamente local y retorno estival en el Valle de Jalón, caracterizadas por las verbenas populares, las misas solemnes cantadas y las animadas competiciones lúdicas de pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03101','fiesta','Festes de Sant Bonaventura','Patronal y Taurina. Se celebra en Julio. Fuerte impacto comarcal gracias a sus multitudinarias exhibiciones de bous al carrer con encierros nocturnos de toros cerriles, acompañados de encendidos correfocs y grandes orquestas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03028','fiesta','Baixada del Riu Bullent y Carnaval de Pego','Etnográfica, Lúdico-Deportiva y Carnaval. Se celebra en Febrero y Junio. Hito lúdico de rango comarcal y provincial; la divertida carrera acuática de barcas artesanales por el río Bullent en el marjal y su histórico y multitudinario carnaval atraen a miles de jóvenes de toda la región.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03103','fiesta','Fiestas de Nuestra Señora del Patrocinio','Patronal y Tradicional. Se celebra en Agosto. Celebraciones íntimas y familiares adaptadas a la baja densidad del núcleo, centradas en la solemne procesión mariana, pasacalles musicales, verbenas populares y comidas de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03029','fiesta','Fiestas de Moros y Cristianos en honor a San Bonifacio Mártir','Moros y Cristianos y Patronal. Se celebra en Mayo. De rango e importancia provincial y regional; sus históricas y multitudinarias fiestas de Moros y Cristianos destacan por la belleza de sus trajes, el emotivo acto del Desfile Infantil y las masivas guerrillas de arcabucería.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03902','fiesta','Fiestas Patronales en honor a la Virgen del Pilar','Patronal y Tradicional. Se celebra en Octubre. Relevancia comarcal en el extremo sur de la provincia; destaca por la monumental y colorida ofrenda de flores a la Virgen, su desfile de carrozas artesanales y los concurridos castillos de fuegos artificiales junto a la costa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03105','fiesta','Fiestas Patronales en honor a la Virgen del Remedio','Patronal, Gastronómica y Taurina. Se celebra en Agosto. De relieve comarcal; combina sus tradicionales sueltas de vaquillas con degustaciones multitudinarias del arroz con conejo y caracoles autóctono y verbenas nocturnas en su feria agrícola tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03030','fiesta','Fiestas de Moros y Cristianos en honor al Santísimo Cristo del Calvario','Moros y Cristianos y Patronal. Se celebra en Octubre. Celebración de escala local en El Comtat, famosa por la tradicional e impresionante subida de la procesión nocturna al Ermitorio de la colina por un camino jalonado de cipreses y hogueras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03031','fiesta','Fiestas Patronales de San Francisco de Asís y la Virgen de los Dolores','Patronal y Tradicional. Se celebra en Octubre y Agosto. Fiestas de arraigo local que ganan vistosidad gracias a la fisonomía del casco antiguo y a los tradicionales actos alrededor de su célebre Plaza de los Chorros, con verbenas y pasacalles populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03060','fiesta','Fiestas Patronales en honor a la Virgen del Rosario','Patronal y Tradicional. Se celebra en Agosto. Festividad de escala estrictamente local a la sombra de la Serra de Serrella, conformada por verbenas populares de reencuentro estival, torneos lúdicos populares y cenas vecinales al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03109','fiesta','Fiestas Patronales en honor a Nuestra Señora del Rosario (La Graná)','Patronal, Religiosa y Tradicional. Se celebra en Octubre. De arraigo local en la Vega Baja, conocida por el singular y centenario acto religioso de "La Graná" el domingo de Resurrección, donde se abre un artefacto con forma de granada liberando confeti y aleluyas ante la patrona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03111','fiesta','Fiestas Patronales en honor a la Virgen de la Salud y San Miguel Arcángel','Patronal y Tradicional. Se celebra en Septiembre. Celebraciones locales con alta participación cívica en la Vega Baja, integrando desfiles informales de peñas, encierros infantiles, verbenas populares y solemnes procesiones religiosas en la falda de la sierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03032','fiesta','Fiestas Patronales en honor a la Virgen del Milagro y San Alberto Magno','Patronal y Etnográfica. Se celebra en Septiembre. Festividad tradicional de la Marina Baixa que destaca por la pervivencia de los tradicionales bailes de les dances de Relleu, acompañados de dulzainas y tabales, reuniendo a la comunidad local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03115','fiesta','Fiestas Patronales en honor a San Abdón y San Senén','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo estrictamente local adaptadas a su modesta demografía, enfocadas en orquestas populares nocturnas, despertás pirotécnicas y cenas vecinales al aire libre en la plaza del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03118','fiesta','Fiestas Patronales en honor a San Fulgencio y San Antonio Abad','Patronal y Tradicional. Se celebra en Enero *. Celebración de arraigo local que congrega a los vecinos en pleno invierno para la bendición de animales, hogueras tradicionales comunitarias y la degustación de platos típicos de la huerta de la Vega Baja.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03904','fiesta','Fiestas Patronales en honor a San Isidro Labrador','Patronal, Agrícola y Tradicional. Se celebra en Mayo. Celebraciones locales vinculadas a los orígenes de colonización agraria del pueblo; destaca por el desfile de carrozas engalanadas con motivos agrícolas, las verbenas populares y la procesión del santo patrón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03120','fiesta','Fiestas Patronales en honor a San Miguel Arcángel','Patronal y Tradicional. Se celebra en Septiembre. Festividad de relieve local y comarcal en el Campo de Salinas, animada por desfiles humorísticos de disfraces, la tradicional ofrenda de flores, cenas al aire libre y ruidosas mascletás.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03034','fiesta','Fiestas de Moros y Cristianos y Patronales en honor a San Vicente Ferrer, y Hogueras de San Vicente','Moros y Cristianos, Fogueres y Patronal. Se celebra en Abril y Julio. Gran relevancia provincial y regional; sus fiestas patronales e históricas de Moros y Cristianos son masivas y cuentan con la declaración de Interés Turístico, destacando también sus monumentales Hogueras veraniegas con plantá y cremá.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03117','fiesta','Fiestas Patronales en honor al Cristo de la Salud','Patronal y Tradicional. Se celebra en Septiembre. Pequeña celebración de arraigo estrictamente local en el Valle de la Rectoría, conformada por procesiones vecinales religiosas, orquestas nocturnas en la plaza y juegos infantiles tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03035','fiesta','Fiestas de Moros y Cristianos y Patronales en honor a la Virgen de Loreto','Moros y Cristianos, Patronal y Marinera. Se celebra en Septiembre. Hito festivo de rango provincial y costero; las embajadas y desembarcos se recrean en el marco monumental de su Castillo-Fortaleza del siglo XVI, atrayendo a numeroso público junto a la tradicional procesión marítima.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03123','fiesta','Fiestas de Moros y Cristianos en honor a San Blas','Moros y Cristianos y Patronal. Se celebra en Febrero. Festividades de nivel e impacto regional con declaración de Interés Turístico, famosas por el uso masivo de arcabucería, el estricto rigor histórico de sus imponentes trajes y el gran fervor popular en pleno invierno.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03036','fiesta','Festes Majors en honor a la Divina Aurora','Patronal, Etnográfica y Deportiva Tradicional. Se celebra en Octubre. De arraigo comarcal en la sierra; destaca por albergar históricas y multitudinarias partidas de Pilota Valenciana en la plaza mayor a la modalidad de Palma, constituyendo un pilar fundamental del folclor local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03125','fiesta','Fiestas Patronales en honor a la Virgen de la Piedad','Patronal y Tradicional. Se celebra en Mayo. Celebración vecinal de escala local en la Marina Alta, basada en las cenas comunitarias en la calle principal, el canto de pasodobles tradicionales, procesiones religiosas solemnes y mascletás.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03037','fiesta','Fiestas de Moros y Cristianos en Moraira y Fiestas de San Vicente Ferrer en Teulada','Moros y Cristianos, Patronal y Marinera. Se celebra en Abril y Junio. De relevancia comarcal y alto impacto turístico costero; combina las procesiones solemnes e históricas del interior con el espectacular desembarco pirata y desfiles moros en la playa de Moraira.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03129','fiesta','Fiestas de Moros y Cristianos y Patronales en honor a la Virgen de la Paz','Moros y Cristianos, Patronal y Taurina. Se celebra en Julio y Agosto. Celebraciones locales de fuerte identidad tradicional en la Hoya de Castalla, con animadas embajadas históricas entre la sierra, verbenas populares y sueltas tradicionales de vaquillas por el pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03130','fiesta','Festes de Sant Antoni de Pàdua','Patronal y Tradicional. Se celebra en Julio. Festividad de arraigo estrictamente local condicionada por la bajísima demografía del municipio, el más pequeño de la provincia, basada en cenas vecinales al aire libre, campeonatos de naipes y misas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03131','fiesta','Festes de Sant Lluís Beltran','Patronal y Tradicional. Se celebra en Agosto. Celebración de carácter marcadamente vecinal y de retorno estival en la Rectoría, vertebrada por el tradicional pasacalles de la replegada, comidas comunitarias en las calles y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03132','fiesta','Festa de la Mare de Déu dels Alts Forns y Festa del Pa Beneït','Etnográfica, Patronal y Religiosa. Se celebra en Julio y Agosto. Hito etnográfico de gran interés comarcal por la antiquísima tradición del Pa Beneït, donde las clablesas vestidas con trajes tradicionales portan sobre sus cabezas panes monumentales decorados con flores y encajes para ser bendecidos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03038','fiesta','Certamen Internacional de Habaneras y Polifonía y Fiestas de la Inmaculada Concepción','Certamen Musical, Marinera y Patronal. Se celebra en Julio y Diciembre. Su histórico Certamen de Habaneras ostenta la declaración de Fiesta de Interés Turístico Internacional, erigiéndose en un hito cultural masivo global que rinde tributo a los vínculos marineros y comerciales de la ciudad con Cuba.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03134','fiesta','Festes de la Mare de Déu dels Desemparats y Festes de Sant Roc','Patronal y Tradicional. Se celebra en Agosto. Festejos de escala local y de reunión comunitaria en los núcleos de Alcalà de la Vall y Beniaia, caracterizados por verbenas familiares, pasacalles musicales y cenas populares en las plazas de los pueblos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03136','fiesta','Festes Patronals de Benialí y Fira de la Cirera','Patronal y Gastronómica. Se celebra en Agosto y Junio. Atractivo comarcal destacado gracias a su feria agroalimentaria dedicada a la cereza de la montaña de Alicante, que complementa las fiestas veraniegas itinerantes organizadas por sus ocho núcleos de población.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03137','fiesta','Festes de Sant Cosme i Sant Damià','Patronal, Tradicional y Romería. Se celebra en Septiembre. Celebración de arraigo local en sus tres núcleos urbanos [Benimaurell, Fleix y Campell], donde destacan los pasacalles acompañados de dolçaina i tabalet, las competiciones de pelota valenciana y los actos religiosos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03135','fiesta','Festes de la Mare de Déu dels Desemparats','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo local y de reencuentro estival marcadas por su reducida población, dinamizadas por tradicionales parques infantiles, carreras de cintas, cenas colectivas y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90859','fiesta','Festes de la Mare de Déu del Roser y Moros i Cristians','Moros y Cristianos, Patronal y Taurina. Se celebra en Agosto. De notable relevancia comarcal en la Marina Alta; destaca por la vistosidad de sus desfiles de Moros y Cristianos y por sus concurridas jornadas de bous al carrer con exhibición de ganaderías autóctonas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03039','fiesta','Festes de Moros i Cristians en honor a Santa Marta','Recreación Histórica, Moros y Cristianos y Masiva. Se celebra en Julio. Hito etnográfico masivo de nivel nacional e internacional. Su singular e histórico acto del Desembarc [Desembarco], donde la armada mora ataca la playa defendida por la artillería cristiana con fuego real de arcabucería y galeras, es un espectáculo único en el mundo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03040','fiesta','Fiestas de Moros y Cristianos en honor a Nuestra Señora de las Virtudes','Moros y Cristianos, Patronal y Masiva. Se celebra en Septiembre. Declaradas de Interés Turístico Nacional, constituyen las fiestas de Moros y Cristianos más multitudinarias del mundo por el número de participantes [más de 12.000 festeros], destacando las monumentales entradas de las comparsas de Estudiantes o Contrabandistas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90860','fiesta','Fiestas de la Virgen Pobre y Fiesta de Santo Domingo','Patronal, Enológica y Tradicional. Se celebra en Octubre y Agosto. Relevancia comarcal por la vinculación de sus fiestas de otoño con la cultura del vino moscatel y la mistela de la Cooperativa Valenciana Virgen Pobre, además de su tradicional e histórico rastro de antigüedades semanal). Con este bloque cerramos de forma estricta el 100% de la provincia de Alicante respetando las directrices de la plantilla de continuación. ¿Deseas que prepare el siguiente bloque para avanzar con la provincia de Castellón (Castelló) de forma estrictamente alfabética, comenzando por los municipios de la letra A (Atzeneta del Maestrat, Ain, Albocàsser, Alcalà de Xivert, Alfondeguilla, Almedíjar, Almenara, Almassora, Alfondeguilla, Altura, Arañuel, Ares del Maestrat, Argelita, Artana, Ayódar, Azuébar)? Podríamos determinar de antemano hasta qué municipio o letra deseas que complete en el próximo mensaje.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90861','fiesta','Festes en honor a San Ambrosio y San Cristóbal','Patronal y Tradicional. Se celebra en Agosto. Celebración de arraigo estrictamente local en el corazón de la Sierra de Espadán, condicionada por su baja demografía, vertebrada por cenas populares al aire libre, verbenas vecinales y tradicionales campeonatos de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90353','fiesta','Fiestas Patronales de la Virgen de la Asunción y San Roque, y la Fiesta de Sant Antoni','Etnográfica, Patronal y Taurina. Se celebra en Enero y Agosto. Relevancia comarcal y etnográfica en el Alt Maestrat, destacando en enero la tradicional Festa de Sant Antoni con la bendición de animales, la arrastrada de troncos por caballerías y el reparto de la coqueta, junto a sus tradicionales encierros veraniegos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11001','fiesta','Fiestas de San Juan Bautista y San José (en Alcossebre)','Patronal, Taurina y de Reencuentro Turístico. Se celebra en Agosto y Septiembre. Festividades de gran empaque comarcal y costero que combinan los tradicionales e históricos bous al carrer en el núcleo interior con los espectaculares castillos de fuegos artificiales y verbenas multitudinarias junto a las playas de Alcossebre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12009','fiesta','Fiestas en honor a Santa Quiteria y la Mare de Déu del Roser','Patronal y Taurina. Se celebra en Mayo y Octubre. Hito taurino de gran relevancia a nivel provincial, célebre por la exhibición de toros cerriles de prestigiosas ganaderías y los encierros, complementados etnográficamente por el solemne reparto de las calderas de arroz de Santa Quiteria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12010','fiesta','Fiestas Patronales en honor a los Santos de la Piedra (San Abdón y San Senén) y la Virgen del Rosario','Patronal, Tradicional y Enológica. Se celebra en Agosto. Celebración de arraigo local y de retorno estival donde las verbenas populares se complementan con la puesta en valor de los vinos tradicionales con Indicación Geográfica Protegida de Castellón producidos en sus bodegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12011','fiesta','Fiestas Patronales de la Virgen del Buen Suceso y San Roque','Patronal, Taurina y Marinera. Se celebra en Septiembre. De notable relevancia en la comarca de la Plana Baixa; destaca por la espectacularidad de los encierros taurinos, las tradicionales exhibiciones en la playa de Casablanca y los desfiles de peñas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12901','fiesta','Fiestas de la Segregación y Fiestas Patronales de la Virgen del Niño Perdido','Conmemorativa, Patronal y Taurina. Se celebra en Junio y Octubre. Celebración comarcal que rememora la independencia municipal obtenida en 1985, fusionando la memoria histórica local con desfiles de carrozas, masivas cenas de hermandad y exhibiciones taurinas de bous de vila.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12012','fiesta','Fiestas del Berro y Fiestas Patronales de la Virgen de Gracia y San Miguel','Etnográfica, Conmemorativa, Patronal y Taurina. Se celebra en Marzo y Septiembre. Hito etnográfico en el Alto Palancia; destaca la Fiesta del Berro que conmemora el alumbramiento de las aguas del Manantial de la Esperanza en 1915, atrayendo gran público regional a sus actos folclóricos y su feria taurina otoñal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12013','fiesta','Fiestas Patronales de San Miguel Arcángel y la Virgen del Rosario','Patronal y Tradicional. Se celebra en Agosto. Festejos de escala estrictamente local y familiar marcados por su baja demografía, estructurados en torno a las procesiones del santo patrón, parques infantiles, cenas vecinales en la plaza y orquestas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11002','fiesta','Fiestas de Santa Elena y la Virgen de la Asunción','Patronal, Romería y Tradicional. Se celebra en Agosto. Fiestas de arraigo local de gran belleza plástica debido a la fisonomía del municipio, destacando la romería a la ermita de Santa Elena, los pasacalles de arrieros y las cenas comunitarias en un entorno de alta montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12015','fiesta','Fiestas Patronales de la Santa Cruz y la Virgen del Rosario','Patronal, Taurina y Tradicional. Se celebra en Agosto. Celebraciones tradicionales orientadas al retorno de la población estival en el Alto Mijares, dinamizadas por la suelta de vaquillas, las verbenas nocturnas en los exteriores de la histórica Torre de l''Alcalatén y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12016','fiesta','Fiestas de San Juan Bautista y Fiestas de Santa Cristina','Patronal, Romería y Taurina. Se celebra en Junio y Julio. Atractivo comarcal en las faldas de la Sierra de Espadán, célebre por la multitudinaria romería a la ermita de Santa Cristina, los encierros de reses bravas por su casco antiguo y las tradicionales cordàs pirotécnicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90354','fiesta','Fiestas de San Bartolomé y San Roque, y San Antonio Abad','Patronal, Etnográfica y Romería. Se celebra en Enero y Agosto. Gran arraigo en la comarca de l''Alcalatén; destaca la procesión tradicional de los Animeros, la matanza y el reparto del porrat en enero, combinada con una completa semana de festejos taurinos y culturales en verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12017','fiesta','Fiestas de San Sebastián y la Virgen del Rosario','Patronal y Tradicional. Se celebra en Agosto. Festejos vecinales de pequeña escala demográfica, centrados en los actos religiosos tradicionales, orquestas de fin de semana, competiciones lúdicas intergeneracionales y cenas compartidas al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12018','fiesta','Fiestas Patronales del Santo Cristo de la Agonía y San Mateo','Patronal, Taurina y Gastronómica. Se celebra en Agosto. Fiestas marcadas por el reencuentro veraniego, dinamizadas por la exhibición de toros de corro en la plaza del pueblo, degustaciones de embutidos artesanales y bailes con bandas y orquestas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12020','fiesta','Fiestas en honor a San Roque y San Pedro','Patronal, Taurina y Tradicional. Se celebra en Agosto. Celebración tradicional en el altiplano de la provincia, caracterizada por la entrada de toros por el casco urbano, las verbenas populares y la comida colectiva de la Festa de los Mozos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12022','fiesta','Fiestas en honor a la Virgen de Loreto y los Santos de la Piedra','Patronal, Romería y Tradicional. Se celebra en Septiembre. De relieve comarcal por la tradicional y masiva romería a la ermita de la Virgen de Loreto, acompañada de espectáculos pirotécnicos, verbenas vecinales y puesta en valor del patrimonio hídrico local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12024','fiesta','Fiestas en honor a San Roque y la Virgen del Rosario','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo estrictamente local debido a su baja demografía, fundamentadas en actividades de hermandad vecinal, parques infantiles, pasacalles musicales y verbenas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12025','fiesta','Fiestas de San Juan Bautista y la Virgen de la Ortisella','Patronal, Romería y Tradicional. Se celebra en Agosto. Celebración familiar y vecinal en l''Alcalatén que destaca por la histórica romería folclórica a la ermita de la Mare de Déu de la Ortisella, un paraje natural de alta consideración local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12026','fiesta','Fiestas de San Cristóbal y San Roque','Etnográfica, Patronal y Taurina. Se celebra en Agosto. Relevancia etnográfica en el Alt Maestrat; destaca el antiquísimo baile tradicional del Ball de dalt, las exhibiciones de ganado cerril en el recinto de la villa histórica y la promoción cultural vinculada a su famoso balneario de la Font d''En Segures.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12027','fiesta','Fiesta de la Alcachofa y Fiestas Patronales de San Bartolomé','Gastronómica, Patronal y Etnográfica. Se celebra en Enero y Agosto. La Festa de la Carxofa de Benicarló ostenta la declaración de Fiesta de Interés Turístico Autonómico, erigiéndose en un hito gastronómico regional masivo que ensalza el cultivo local protegido por Denominación de Origen con espectaculares torraes y demostraciones culinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12028','fiesta','Fiestas de San Antonio Abad y Santa Águeda, y la Belle Époque','Etnográfica, Recreación Histórica y Patronal. Se celebra en Enero y Septiembre. Hito cultural y turístico a nivel regional; en invierno destaca el multitudinario Día de las Paellas por San Antonio, y en septiembre su aclamada recreación histórica de la Benicàssim Belle Époque que recupera el esplendor burgués de sus villas marítimas del siglo XIX.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12029','fiesta','Fiestas en honor a los Santos Mártires (San Abdón y San Senén) y la Virgen de la Asunción','Patronal, Taurina y Enológica. Se celebra en Agosto. De arraigo comarcal en la Plana Alta; combina las tradicionales verbenas, pasacalles de gigantes y toros de calle con ferias y catas dedicadas a los vinos de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12031','fiesta','Nueva Jerusalén (Pasión de Borriol) y Fiestas de San Bartolomé','Recreación Histórica, Drama Sacro y Patronal. Se celebra en Jueves Santo (Marzo/Abril) y Agosto. Hito etnográfico masivo a nivel regional. La representación de la Pasión de Cristo por las calles y montañas del municipio por parte de la asociación Nueva Jerusalén es de un realismo sobrecogedor, atrayendo a miles de visitantes cada Semana Santa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12032','fiesta','Fiestas de San Blas y Fiestas de la Virgen de la Misericordia','Patronal, Taurina y Pirotécnica. Se celebra en Febrero y Septiembre. Gran empaque provincial y regional; destaca por las masivas exhibiciones taurinas de su feria de la Misericordia, los desfiles de carrozas, las monumentales tracas que recorren el centro histórico y la devoción tradicional a San Blas con el reparto de rollos bendecidos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12033','fiesta','Fiestas en honor a San Juan Bautista y San Roque, y Romería de las Santas','Patronal, Romería y Taurina. Se celebra en Agosto y Mayo. De relieve comarcal; la romería histórica al ermitorio de Les Santes en la Sierra de Engarcerán es un hito de fervor popular, complementado en verano con tradicionales bous al carrer en su recinto amurallado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12034','fiesta','Fiestas Patronales en honor a San Lorenzo','Patronal y Taurina. Se celebra en Agosto. Festejos de arraigo local y comarcal en el Baix Maestrat, caracterizados por la tradicional Entrada de bous al estil de Càlig, verbenas populares al aire libre y el desfile de carrozas artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12036','fiesta','Fiestas Patronales de San Miguel Arcángel y Feria del Aceite Novell','Patronal, Oleícola y Gastronómica. Se celebra en Agosto y Noviembre. Atractivo comarcal destacado gracias a su feria dedicada al aceite de oliva virgen extra obtenido de sus milenarios olivos monumentales, que complementa las actividades festivas de las verbenas veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12037','fiesta','Fiestas en honor a San Lorenzo','Patronal y Tradicional. Se celebra en Agosto. Celebración de carácter estrictamente vecinal en el municipio con menor población de la Comunitat Valenciana, fundamentada en comidas de hermandad en los antiguos salones locales, misas solemnes y orquestas populares de pequeño formato.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12038','fiesta','Fiestas Patronales de la Virgen de la Fuente y Romería dels Cinc Pobles','Romería, Etnográfica y Patronal. Se celebra en Agosto y Mayo. Posee un incalculable valor etnográfico en Els Ports debido a la histórica Romería a la ermita de San Pedro de Castellfort, donde se reparte el tradicional panoli [pastel dulce] y se recrean antiquísimos votos medievales de los pueblos vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12040','fiesta','Fiestas de la Magdalena','Histórica, Etnográfica, Romería y Masiva. Se celebra en Tercer domingo de Cuaresma (Marzo). Las Fiestas de la Magdalena ostentan el título de Interés Turístico Internacional, conmemorando la fundación de la ciudad con la multitudinaria Romería de les Canyes, el espectacular desfile de las monumentales Gaiates luminosas y la Nit de la Màgia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12041','fiesta','Fiestas Patronales en honor al Santo Cristo del Calvario','Patronal y Tradicional. Se celebra en Septiembre. Festividades de arraigo local y de reunión de descendientes en el Alto Mijares, basadas en verbenas de fin de semana, tradicionales campeonatos deportivos, comidas comunitarias y procesiones solemnes por su orografía de montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12042','fiesta','Romería de Catí a Sant Pere de Castellfort y Fiestas Patronales de la Asunción y San Roque','Romería Histórica, Etnográfica y Patronal. Se celebra en Mayo (Primer sábado) y Agosto. Hito etnográfico comarcal; la romería a San Pedro data de 1321 y se realiza a pie entonando cantos gregorianos tradicionales medievales de enorme valor patrimonial, sirviendo de antesala a los festejos taurinos veraniegos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12043','fiesta','Fiestas de la Virgen del Niño Perdido','Patronal, Taurina y Gastronómica. Se celebra en Septiembre. Festejos de relevancia comarcal en el Alto Palancia, famosos por la exhibición de toros y vaquillas, las masivas comidas populares de calderas tradicionales de cerdo y alubias y espectáculos de variedades nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12044','fiesta','Fiestas Patronales de San Sebastián y la Virgen de la Costa','Patronal y Tradicional. Se celebra en Agosto. Celebración de arraigo local coronada por su castillo medieval, donde destacan las verbenas populares, las tradicionales carreras de cintas a caballo, pasacalles de la banda municipal y el folclore del Baix Maestrat.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12053','fiesta','Fiestas en honor a San Vicente Ferrer y San Roque','Patronal, Taurina y Marinera. Se celebra en Abril y Agosto. Equilibra la devoción tradicional del casco urbano interior con los espectáculos pirotécnicos marítimos y verbenas estivales organizadas en su zona de playa, atrayendo numeroso público comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12056','fiesta','Fiestas Patronales de la Virgen del Rosario','Patronal y Tradicional. Se celebra en Agosto. Fiestas tradicionales de baja escala demográfica y perfil marcadamente familiar en la Sierra de Espadán, vertebradas por actividades infantiles, pasacalles con bandas locales y cenas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12045','fiesta','Fiestas Patronales de la Virgen de la Gracia y San Antonio Abad','Patronal, Etnográfica y Taurina. Se celebra en Enero y Agosto. De relieve comarcal en Els Ports; destaca por la pureza de sus tradiciones de invierno con la monumental hoguera y las representaciones teatrales populares del Sant Antoni, unidas a sus animadas semanas taurinas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12046','fiesta','Fiestas en honor a San Bernardo y la Virgen de los Desamparados','Patronal, Taurina y Tradicional. Se celebra en Agosto. Celebraciones tradicionales de arraigo local y reencuentro de descendientes de la comarca del Alto Mijares, dinamizadas por exhibiciones taurinas de vaquillas y toros embolados y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12049','fiesta','Fiestas de San Pedro Mártir y la Virgen de la Asunción','Patronal y Tradicional. Se celebra en Agosto. Celebración tranquila de perfil vecinal en la comarca de l''Alcalatén, reforzada por espectáculos populares de variedades, misas tradicionales con cantos corales autóctonos y cenas compartidas en la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12051','fiesta','Fiestas Patronales del Salvador, la Virgen de la Asunción y San Roque','Patronal, Romería Histórica y Recreación Medieval. Se celebra en Agosto y Junio. Hito etnográfico comarcal de alta consideración por su monumental núcleo medieval. Destaca por la histórica Romería a San Juan de Peñagolosa y las recreaciones históricas de época templaria, que congregan gran volumen de visitantes de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12057','fiesta','Fiestas Patronales de la Virgen de la Asunción y el Santísimo Cristo del Calvario','Patronal, Taurina y Apícola. Se celebra en Agosto. Atractivo comarcal en el interior de Castellón, famoso por la suelta de reses bravas en sus empinadas calles tradicionales, verbenas nocturnas y la promoción artesanal de sus reconocidas mieles de montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12058','fiesta','Fiestas en honor a San Juan Bautista y San Roque','Patronal y Tradicional. Se celebra en Agosto. Fiestas tradicionales de baja densidad demográfica en el Alto Mijares, marcadas por un ambiente familiar y vecinal con juegos tradicionales, pasacalles con charangas locales y verbenas en la plaza de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12059','fiesta','Fiestas Patronales del Santo Sepulcro, el Corazón de Jesús y la Virgen de Montserrat','Patronal, Cultural y Tradicional. Se celebra en Septiembre. Municipio con proyección provincial gracias al Museo Inacabado de Arte Urbano [MIAU], lo que dinamiza turísticamente sus fiestas tradicionales caracterizadas por procesiones religiosas solemnes, cenas populares y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12060','fiesta','Fiestas Patronales del Santísimo Cristo del Calvario','Patronal y Taurina. Se celebra en Septiembre. Celebración de arraigo local en el Valle del Mijares, dinamizada por la organización de los tradicionales encierros y la suelta de vaquillas, complementada con verbenas y parques infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12061','fiesta','Sant Antoni de Forcall (La Santantonà) y Fiestas Patronales de San Víctor','Etnográfica, Histórica y Patronal. Se celebra en Enero y Agosto. La Santantonà de Forcall es un hito etnográfico masivo a nivel regional, catalogada como Bien de Interés Cultural Inmaterial. Es una de las manifestaciones de patrimonio medieval más puras de la Comunitat, famosa por el encendido de la monumental barraca, la quema y las danzas de los Botargues y Dimonis.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12063','fiesta','Fiestas en honor a la Virgen del Rosario','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo estrictamente local adaptadas a una de las poblaciones con menor censo de la provincia, dinamizadas por juegos de mesa tradicionales, cenas comunitarias de sobaquillo y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12064','fiesta','Fiestas Patronales en honor a San Roque y Nuestra Señora de la Asunción','Patronal y Tradicional. Se celebra en Agosto. Festejos estivales de marcado carácter vecinal orientados a la recepción de veraneantes, estructurados con tradicionales pasacalles, cenas al aire libre y bailes nocturnos en el centro del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12065','fiesta','Fiestas de la Virgen de los Desamparados y del Santo Cristo de la Sed','Patronal, Taurina y Tradicional. Se celebra en Septiembre. Celebraciones tradicionales de arraigo local en el Alto Palancia que congregan a la comunidad en torno a procesiones solemnes, muestras populares de vaquillas de la tierra y verbenas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12067','fiesta','Fiestas del Cristo de la Luz y de la Virgen del Rosario','Patronal, Cultural y Tradicional. Se celebra en Agosto y Septiembre. Fiestas de arraigo local muy próximas a la capital comarcal, caracterizadas por una amplia agenda cultural de teatro de calle, pasacalles con bandas de música locales, orquestas multitudinarias y actos religiosos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12068','fiesta','Fiestas de San Bartolomé','Patronal y Tradicional. Se celebra en Agosto. Celebración vecinal de baja escala demográfica en la comarca de Els Ports, estructurada en torno a comidas comunitarias en el Castillo de los Barones de Herbers, misas tradicionales y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12069','fiesta','Fiestas en honor a la Purísima Concepción','Patronal y Tradicional. Se celebra en Agosto. Celebración de arraigo estrictamente local y marcado perfil familiar condicionada por su baja demografía, basada en cenas vecinales al aire libre, orquestas de fin de semana y procesiones religiosas tradicionales). Con esta exhaustiva entrega completamos la revisión cronológica y alfabética de la provincia de Castellón, llegando rigurosamente hasta el final de la letra H. El proyecto queda preparado para dar continuidad inmediata en el siguiente bloque a partir de la letra I con los municipios restantes. Para continuar de acuerdo al orden oficial y con el mismo formato, ¿puedo iniciar el siguiente bloque con las localidades correspondientes comenzando por Inca (si continuáramos Baleares), o siguiendo Castellón con los municipios de la I en adelante (como Ibodes / Ibarsos / Morella etc.)? Indícame si prosigo con Castellón hasta finalizar la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12071','fiesta','Fiestas de la Virgen de la Divina Pastora y Fiestas de Santa Águeda','Patronal, Religiosa, Taurina y Etnográfica. Se celebra en Febrero y Septiembre. Hito etnográfico de nivel provincial declarado de Interés Turístico; destacan el tradicional volteo humano de campanas en su emblemática Torre Mudéjar, la ofrenda a la Pastora y la multitudinaria exhibición de la Entrada de Toros y Caballos por su fisonomía medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12074','fiesta','Fiestas Patronales en honor a San Felipe Neri y San Isidro Labrador','Patronal, Taurina y Tradicional. Se celebra en Septiembre. Celebración de arraigo local en la Plana Baixa que convoca una alta participación vecinal en sus encierros, desencajonadas de toros cerriles y las concurridas cenas de peñas en los viales del casco urbano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12075','fiesta','Fiestas de San Onofre y Fiestas de la Virgen de la Asunción','Patronal, Romería y Tradicional. Se celebra en Junio y Agosto. Festejos de escala vecinal y reencuentro en Els Ports, caracterizados por la tradicional romería a la ermita de San Onofre, pasacalles de arrieros, comidas comunitarias y verbenas de montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12093','fiesta','Fiestas en honor a la Asunción de la Virgen y San Roque','Patronal, Tradicional y de Montaña. Se celebra en Agosto. Festividades tradicionales de baja escala demográfica y perfil familiar en la Tinença de Benifassà; articula a sus distintos núcleos rurales con bailes tradicionales, procesiones solemnes y comidas al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12094','fiesta','Fiestas Patronales de la Virgen del Rosario y San Miguel Arcángel','Patronal y Taurina. Se celebra en Agosto. De relieve comarcal en la Plana Alta, dinamizada por la organización de los encierros, la suelta de reses bravas en su calle Mayor, pasacalles con charangas locales y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12072','fiesta','Fiestas en honor a San Hermolao y San Miguel Arcángel (Fiestas de la Perla de la Montaña)','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. De notable relevancia comarcal y provincial, destaca por la espectacularidad de los encierros por sus empinadas calles, las tradicionales entrades de bous y la gran animación de sus peñas de la montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12073','fiesta','Fiestas en honor a la Virgen de la Natividad y Santo Domingo de Guzmán','Patronal y Tradicional. Se celebra en Septiembre. Celebración vecinal en el Alto Mijares orientada al reencuentro estival, fundamentada en actividades lúdicas, misas tradicionales con cantos corales autóctonos y orquestas de pequeño formato.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12077','fiesta','Festes de Santa Maria Magdalena y San Roque','Marinera, Etnográfica y Patronal. Se celebra en Julio y Agosto. Hito etnográfico de rango regional por el tradicional Desembarc de la Mare de Déu d''Agost, una de las recreaciones marineras más antiguas y multitudinarias de Castellón, complementada con encierros de toros cerriles y actividades playeras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12078','fiesta','Fiestas Patronales de la Virgen de los Dolores y San Bernardo Abad','Patronal, Taurina y Gastronómica. Se celebra en Septiembre. Atractivo comarcal en el Alto Mijares; destaca por la suelta de vaquillas y toros embolados, las degustaciones de embutidos artesanales y los pasacalles acompañados por la banda de música local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12079','fiesta','Fiestas Patronales de la Virgen del Rosario, San Jaime y la Virgen de los Desamparados','Patronal, Taurina y Turística. Se celebra en Septiembre. Alta concurrencia provincial y turística motivada por su perfil termal; combina su semana de encierros tradicionales y bous al carrer con espectaculares castillos de fuegos artificiales y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12080','fiesta','Sexenni de Morella y Fiestas de San Julián','Etnográfica, Religiosa, Histórica y Masiva. Se celebra en Agosto (Cada 6 años, el próximo en agosto de 2024 / 2030) y Enero. El Sexenni de Morella ostenta la declaración de Fiesta de Interés Turístico Internacional y Bien de Interés Cultural Inmaterial, constituyendo un hito histórico medieval masivo global donde la ciudad se viste de tapices de papel rizado y se suceden danzas ancestrales gremiales únicas como los Torneros o Teixidors.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12081','fiesta','Fiestas Patronales en honor a la Virgen de la Luz','Patronal, Taurina y Tradicional. Se celebra en Septiembre. De relieve comarcal en el Alto Palancia, célebre por sus concurridas jornadas de toros de calle en torno a su histórico Olmo Milenario y las verbenas veraniegas que congregan a numerosos veraneantes de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12083','fiesta','Fiestas en honor a San Roque y la Virgen de la Naranja','Patronal, Romería y Tradicional. Se celebra en Agosto. Fiestas de arraigo local de gran belleza montañesa en Els Ports, destacando la romería a la ermita de la patrona, bailes populares tradicionales, campeonatos de naipes y cenas comunitarias en la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12084','fiesta','Fira d''Onda','Feria Taurina, Patronal y Masiva. Se celebra en Octubre. Hito taurino y de feria monumental de nivel nacional; sus multitudinarios encierros de toros cerriles de ganaderías de primera línea y los festivales de música paralizan la comarca de la Plana Baixa, atrayendo a miles de aficionados y peñas de todo el país.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12085','fiesta','Fiestas de la Virgen de la Paciencia y Fiestas de San Jaime','Patronal, Taurina y de Reencuentro Turístico. Se celebra en Octubre y Julio. Festividades de alto empaque costero declaradas de Interés Turístico Provincial; destacan sus tradicionales encierros al estilo oropesano por el casco antiguo y los espectáculos pirotécnicos marítimos nocturnos junto al mar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12087','fiesta','Fiestas en honor a San Cosme y San Damián','Patronal y Tradicional. Se celebra en Agosto. Celebración de carácter estrictamente vecinal en uno de los pueblos más pequeños de Els Ports; se fundamenta en comidas familiares en las calles empedradas, misas tradicionales con procesión y orquestas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12088','fiesta','Fiestas en honor a la Virgen de la Cueva Santa','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo local y de reunión de descendientes en la Sierra de Espadán, basadas en verbenas familiares, comidas populares de sobaquillo y procesiones religiosas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12089','fiesta','Festes Patronals en honor a la Virgen de la Ermitana','Etnográfica, Patronal y Moros y Cristianos. Se celebra en Septiembre. Hito cultural y etnográfico declarado de Interés Turístico Nacional; destaca la suntuosidad de sus Danses rituales al pie de las murallas del Castillo del Papa Luna, con los Cavallers y los Gegants, fusionados con vistosos desfiles de Moros y Cristianos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12090','fiesta','Fiestas Patronales de la Virgen de Gracia y la Virgen de Vallada','Patronal, Romería y Taurina. Se celebra en Agosto y Septiembre. Celebración de arraigo local en el altiplano de la provincia, caracterizada por la tradicional romería a la ermita de Vallada, espectáculos de vaquillas de la tierra y verbenas familiares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12091','fiesta','Fiestas en honor a la Asunción de la Virgen y San Roque','Patronal, Etnográfica y Taurina. Se celebra en Agosto. Festejos comarcales en Els Ports que destacan por el mantenimiento de sus bailes y música tradicionales de dulzaina, combinados con suertes taurinas de toros embolados y desencajonadas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12092','fiesta','Fiestas Patronales de la Virgen de los Ángeles','Patronal y Tradicional. Se celebra en Agosto *. Festejos veraniegas orientadas al retorno de la comunidad ausente, caracterizadas por bailes populares en la plaza del pueblo, parques infantiles, cenas de hermandad y orquestas musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12095','fiesta','Fiestas en honor al Santísimo Sacramento, San Roque y el Santo Cristo del Calvario','Patronal y Taurina. Se celebra en Octubre. De arraigo comarcal en la cuenca minera; combina las tradicionales verbenas, procesiones solemnes y pasacalles con la suelta de reses bravas en un recinto adaptado en su centro histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12096','fiesta','Fiestas Patronales de los Santos de la Piedra (San Abdón y San Senén)','Patronal, Taurina y Tradicional. Se celebra en Agosto. Celebración tradicional de arraigo comarcal en el Baix Maestrat, caracterizada por los encierros de vaquillas, bailes populares de calle, pasacalles de la banda municipal y el desfile humorístico de carrozas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12097','fiesta','Fiestas en honor a San Isidro Labrador y la Virgen de los Desamparados','Patronal y Tradicional. Se celebra en Agosto. Festejos de escala estrictamente local marcados por su baja demografía de interior, estructurados en torno a las procesiones del santo, campeonatos de naipes, cenas vecinales y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12101','fiesta','Fiestas Patronales de San Rafael Arcángel','Patronal y Tradicional. Se celebra en Octubre. Celebración de arraigo local en la frontera con Cataluña, donde destacan las verbenas populares, las tradicionales comidas vecinales, pasacalles de la banda y competiciones deportivas comarcales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12902','fiesta','Fiestas Patronales en honor a San Juan Bautista','Patronal y Taurina. Se celebra en Junio. De notable relevancia en la comarca de la Plana Alta, célebre por sus concurridas jornadas de bous al carrer con exhibición de ganaderías cerriles bravas, verbenas multitudinarias y cenas comunitarias de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12099','fiesta','Fiestas Patronales de San Jorge y Feria del Ganchillo','Patronal, Artesanal y Tradicional. Se celebra en Abril y Julio. Celebraciones tradicionales marcadas por su dinamismo artesanal, potenciado por la feria monográfica del ganchillo, que complementa las actividades litúrgicas de las verbenas de su patrón primaveral.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11014','fiesta','Fiestas de la Virgen de los Ángeles y Mercado Medieval de Sant Mateu','Recreación Histórica, Romería y Patronal. Se celebra en Agosto y Octubre. Hito monumental e histórico regional en la capital histórica del Maestrat; su Mercado Medieval congrega miles de visitantes en torno a gremios de época y torneos, unido a su tradicional romería al ermitorio de la patrona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12102','fiesta','Fiestas Patronales en honor a Santa Magdalena','Patronal y Taurina. Se celebra en Julio. Celebración de arraigo local al pie de la Sierra de Irta, caracterizada por la suelta de vaquillas, las tradicionales verbenas populares al aire libre, parques infantiles y cenas compartidas por las peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12104','fiesta','Entrada de Toros y Caballos de Segorbe y Fiestas de la Virgen de la Cueva Santa','Etnográfica, Ecuestre, Taurina y Masiva. Se celebra en Septiembre (Segunda semana). La Entrada de Toros y Caballos está declarada Fiesta de Interés Turístico Internacional y Bien de Interés Cultural Inmaterial; es un hito de destreza ecuestre masivo global donde una manada de jinetes guía a los toros a gran velocidad por la calle Colón sin barreras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12105','fiesta','Fiestas de San Bartolomé y San Roque','Patronal y Tradicional. Se celebra en Agosto. Fiestas marcadas por el reencuentro veraniego en el Maestrat, dinamizadas por tradicionales parques infantiles, bailes populares de orquesta y procesiones solemnes por su casco medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12106','fiesta','Fiestas Patronales del Cristo de la Providencia y la Virgen de la Asunción','Patronal y Taurina. Se celebra en Septiembre. De relevancia comarcal en el Alto Palancia, famosos por la suelta de reses bravas en su plaza adaptada, las masivas comidas populares de sobaquillo y espectáculos musicales nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12107','fiesta','Fiestas Patronales en honor a San Antonio de Padua y el Santísimo Cristo de la Piedad','Patronal, Romería y Tradicional. Se celebra en Agosto. Atractivo comarcal destacado por la espectacular procesión y subida a su monumental Calvario, complementado con verbenas populares, pasacalles musicales con charangas y festejos taurinos de calle.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12108','fiesta','Fiestas del Santísimo Sacramento y Muestra Etnológica "Suera un poble al carrer"','Etnográfica, Recreación Histórica y Patronal. Se celebra en Octubre y Diciembre/Enero. Hito etnográfico provincial de alta consideración; la muestra Suera un poble al carrer revive los antiguos oficios del siglo XIX, transformando todo el centro del pueblo con recreaciones históricas que atraen gran número de folcloristas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12109','fiesta','Fiestas Patronales de San Juan Bautista y San Roque','Patronal, Taurina y Tradicional. Se celebra en Agosto. Celebraciones tradicionales marcadas por el retorno estival en la Sierra de Espadán, célebres por los encierros de vaquillas, las tradicionales cordàs y las cenas populares al aire libre en la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12110','fiesta','Fiestas en honor a la Virgen de la Esperanza y San Roque','Patronal y Tradicional. Se celebra en Agosto. Fiestas tradicionales de baja escala demográfica y perfil familiar en el Alto Palancia, vertebradas por actividades infantiles, pasacalles de bandas locales y cenas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12111','fiesta','Fiestas de San Jaime y Fiesta del Barranco de la Valltorta','Patronal, Cultural y Tradicional. Se celebra en Julio. Municipio con proyección provincial gracias al patrimonio mundial de arte rupestre de la Valltorta, dinamizando turísticamente sus fiestas caracterizadas por bailes tradicionales de calle, exhibición de vaquillas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12112','fiesta','Fiestas de San Bartolomé y Sant Antoni de la Todolella','Etnográfica, Patronal y Danzas Ancestrales. Se celebra en Agosto y Enero. Gran valor etnográfico en Els Ports gracias a las danzas tradicionales de la Dansa de les Gitanes y las representaciones del Sant Antoni de invierno, atrayendo a multitud de investigadores de las danzas gremiales medievales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12113','fiesta','Fiestas en honor al Santísimo Cristo de la Agonía y la Virgen de los Desamparados','Patronal y Tradicional. Se celebra en Agosto. Celebración tranquila de perfil vecinal en el Alto Mijares, reforzada por espectáculos populares de variedades, misas solemnes con procesión por sus calles tradicionales y cenas compartidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12116','fiesta','Fiestas en honor al Santísimo Cristo de la Agonía y San Salvador','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo estrictamente local adaptadas a una de las poblaciones con menor censo de la Sierra de Espadán, dinamizadas por juegos infantiles de mesa, orquestas de fin de semana y cenas de sobaquillo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12118','fiesta','Fiestas Patronales en honor a San Roque y la Virgen de la Asunción','Patronal y Tradicional. Se celebra en Agosto. Festejos estivales de marcado carácter vecinal orientados a la recepción de veraneantes en el cauce del Mijares, estructurados con tradicionales pasacalles, cenas al aire libre y bailes nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90356','fiesta','Fiestas Patronales en honor a San Bartolomé y el Sagrado Corazón de Jesús','Patronal y Tradicional. Se celebra en Agosto. Festejos de escala estrictamente local marcados por la baja demografía del municipio en la comarca del Alt Maestrat, fundamentados en comidas populares, verbenas vecinales y campeonatos de juegos de mesa tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12120','fiesta','Fiestas Patronales de San Onofre y la Virgen de la Asunción','Patronal y Tradicional. Se celebra en Julio y Agosto. Celebración de carácter marcadamente vecinal y de retorno estival en la Plana Alta, caracterizada por las procesiones religiosas, las cenas al aire libre de sobaquillo y las verbenas populares de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12121','fiesta','Fiestas Patronales en honor a la Virgen de la Asunción y San Roque, y Romería a la Virgen de la Salud','Patronal, Romería Histórica, Alfarera y Taurina. Se celebra en Agosto y Septiembre. De notable relevancia comarcal en el Baix Maestrat; destaca su monumental Real Santuario de la Virgen de la Salud que acoge masivas romerías tradicionales, complementado por su histórica tradición alfarera y exhibiciones de bous al carrer.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12122','fiesta','Los Peregrinos de les Useres (Els Peregrins) y Fiestas de San Salvador','Etnográfica, Religiosa, Histórica y Patronal. Se celebra en Abril (Último viernes) y Agosto. La secular peregrinación de Els Peregrins de les Useres hasta el Santuario de San Juan de Peñagolosa está declarada Bien de Interés Cultural e Interés Turístico Autonómico, constituyendo un hito etnográfico místico medieval único por su silencio, cantos gregorianos y rigor penitencial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12123','fiesta','Fiestas en honor a San Juan Bautista y la Virgen del Rosario','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo estrictamente local adaptadas a una de las poblaciones con menor censo de la cuenca del Mijares, dinamizadas por cenas comunitarias de hermandad, parques infantiles y verbenas de pequeño formato.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12124','fiesta','Fiestas Patronales de la Inmaculada Concepción y San Juan Bautista','Patronal, Taurina y Feria Agropecuaria. Se celebra en Agosto y Noviembre. Relevancia comarcal en ascenso debido a sus multitudinarias exhibiciones taurinas de toros cerriles y encierros por el casco urbano, además de su consolidada feria agrícola y ganadera de muestras de otoño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12125','fiesta','Fiestas en honor a la Virgen de la Cueva Santa y el Cristo de la Agonía','Patronal, Romería y Tradicional. Se celebra en Agosto. Celebración tradicional de rango local en el Alto Palancia que atrae a gran cantidad de residentes ausentes, destacando la romería al Santuario de la Cueva Santa y las verbenas familiares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12126','fiesta','Fiestas de San Vicente Ferrer y Fiestas de la Sagrada Familia y el Santísimo Cristo','Patronal, Taurina, Religiosa y Masiva. Se celebra en Abril y Octubre. Sus dos festividades mayores ostentan la declaración de Fiestas de Interés Turístico Nacional. Destacan por sus históricas ferias comerciales de origen medieval y, especialmente, por ser uno de los máximos exponentes de exhibiciones taurinas de bous al carrer en España.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12128','fiesta','Fiestas Patronales en honor a la Virgen de la Asunción y San Roque, y Certamen de San Miguel','Patronal, Taurina, Cultural y Tradicional. Se celebra en Agosto y Marzo. Gran empaque provincial gracias al marco monumental del municipio, uno de los pueblos más bonitos de España, donde destacan las tradicionales entradas de toros y vaquillas estilo Vilafamés, serenatas musicales y sus históricas procesiones de Semana Santa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12129','fiesta','Festes de Sant Antoni y Fiestas Patronales de San Roque','Etnográfica, Histórica, Patronal y Teatral. Se celebra en Enero y Agosto. Su celebración de Sant Antoni constituye un fenómeno etnográfico de nivel regional por la pureza de sus ritos medievales, como la monumental Barraca de troncos, la representación teatral de la vida del santo [La Auto] y la espectacular traída de la leña por caballerías.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12130','fiesta','Fiestas de San Bartolomé y San Roque, y Romería a San Bartolomé de Belzo','Patronal, Romería Histórica y Tradicional. Se celebra en Agosto. Atractivo comarcal en el Alto Mijares, célebre por la antiquísima romería de caminantes hacia la ermita de San Bartolomé en pleno macizo de Peñagolosa, acompañada de cantos tradicionales y encierros taurinos veraniegos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12131','fiesta','Fiestas de la Virgen de los Desamparados','Patronal y Tradicional. Se celebra en Septiembre. Fiestas tradicionales de baja densidad demográfica en la Sierra de Espadán, marcadas por un ambiente familiar con orquestas de fin de semana, concursos de disfraces y cenas comunitarias en la plaza Mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12132','fiesta','Las Hogueras de San Antonio (La Matxà) y Fiestas de San Bartolomé','Etnográfica, Tradicional, Ecuestre y Patronal. Se celebra en Enero y Agosto. Hito etnográfico de rango provincial y autonómico por La Matxà, una espectacular procesión ecuestre nocturna donde jinetes y caballos cruzan al galope monumentales hogueras dispuestas por las calles del pueblo, mientras se reparte la tradicional torta de San Antonio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12134','fiesta','Fiestas de San Lorenzo','Patronal y Tradicional. Se celebra en Agosto. Celebración vecinal de pequeña escala en el Alt Maestrat orientada al reencuentro de familias en verano, estructurada en torno a pasacalles con charangas, campeonatos de cartas y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90357','fiesta','Fiestas de San Sebastián','Patronal, Taurina y Tradicional. Se celebra en Enero. De relieve comarcal destacado al abrir la temporada de exhibiciones taurinas de bous al carrer en invierno, atrayendo a miles de aficionados de toda la provincia, combinada con su feria de artesanía tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12137','fiesta','Fiestas de la Virgen del Rosario','Patronal y Tradicional. Se celebra en Agosto. Festejos estrictamente locales condicionados por ser uno de los municipios con menor población de Els Ports, basados en misas solemnes, comidas populares de hermandad en los antiguos hornos de la villa y pequeñas verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11018','fiesta','Carnaval de Vinaròs y Fiestas de San Juan y San Pedro','Carnaval, Gastronómica y Patronal. Se celebra en Febrero y Junio. Su espectacular Carnaval ostenta el título de Interés Turístico Autonómico y aspira al Nacional debido a la fastuosidad de sus galas de reinas y multitudinarios desfiles. Se complementa con las famosas ferias estivales de promoción culinaria de su emblemático Langostino de Vinaròs.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12139','fiesta','Fiestas de San Juan Bautista y Romería a San Juan de Peñagolosa','Romería Histórica, Etnográfica y Patronal. Se celebra en Junio y Agosto *. Hito etnográfico de la montaña castellonense; la ancestral romería al Santuario de San Juan de Peñagolosa congrega las tradiciones de los pueblos del macizo, sirviendo de preludio a sus verbenas y festejos taurinos estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12140','fiesta','Fiestas de San Francisco de Paula y Feria del Aceite de Viver','Patronal, Oleícola y Taurina. Se celebra en Abril y Septiembre/Octubre. Atractivo comarcal en el Alto Palancia gracias a su feria monográfica dedicada a su premiado Aceite de Oliva Virgen Extra del Maestrazgo, que complementa sus tradicionales verbenas populares, pasacalles y exhibiciones taurinas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90862','fiesta','Fiestas Patronales de la Asunción y San Roque','Patronal, Taurina y Tradicional. Se celebra en Agosto. Festejos tradicionales de marcado arraigo local en el Baix Maestrat, célebres por las pruebas de vaquillas por las empinadas y empedradas calles de su casco urbano histórico y las masivas cenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12141','fiesta','Fiestas de la Virgen de la Balma (Fiestas Sexenales)','Etnográfica, Religiosa y Romería Histórica. Se celebra en Septiembre (Cada seis años). Hito etnográfico provincial de altísimo valor cultural debido al Santuario de la Virgen de la Balma, enclavado en la roca. Sus tradicionales representaciones de luchas entre ángeles y demonios y las danzas rituales poseen un inestimable arraigo histórico e historiográfico). Con esta exhaustiva entrega completamos el 100% de la provincia de Castellón, registrando minuciosamente todos sus municipios de la A a la Z según la jerarquía oficial y los estrictos criterios de la plantilla. Para mantener el orden de generación oficial y jerárquico del proyecto, corresponde dar el salto a la última provincia de la Comunidad Valenciana: la provincia de Valencia (València). ¿Puedo continuar con el primer bloque de municipios de la provincia de Valencia comenzando por la letra A (Ademuz, Ador, Agullent, Aielo de Malferit, Aielo de Rugat, Alaquàs, Albaida, Albal, Albalat de la Ribera, Albalat dels Sorells, Albalat dels Tarongers, Alberic, Alborache, Alboraya, Albuixech, Alcàntera de Xúquer, Alcàsser, Alcublas, L''Alcúdia, L''Alcúdia de Crespins, Aldaia, Alfafar, Alfara de la Baronia, Alfara del Patriarca, Alfarp, Alfarrasí, Alfauir, Algar de Palancia, Algemesí.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90863','fiesta','Fiestas Patronales en honor a la Virgen de la Asunción y San Roque, y la Fiesta de las Mozas','Patronal, Romería y Tradicional. Se celebra en Agosto y Diciembre. Festejos de arraigo tradicional en el Rincón de Ademuz que destacan por la romería a la ermita de la Virgen de la Huerta, las verbenas estivales de retorno y las antiquísimas coplas navideñas de la Fiesta de las Mozas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90359','fiesta','Festes Patronals en honor a San Pedro, San Jerónimo y la Virgen de Loreto','Patronal y Tradicional. Se celebra en Agosto. Festejos de escala comarcal en la Safor, fundamentados en la procesión de las antorchas, competiciones de pelota valenciana, noches de teatro de calle y las tradicionales cenas populares de hermandad al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90360','fiesta','Fiestas de Moros y Cristianos en honor a San Vicente Ferrer (Festes del Miracle)','Moros y Cristianos, Recreación Histórica y Patronal. Se celebra en Abril (Pascua de San Vicente) y Septiembre. Hito etnográfico en el Valle de Albaida; sus fiestas de Moros y Cristianos cuentan con un gran valor histórico, complementado en septiembre por la Nit de les Fogueretes, una de las romerías nocturnas con farolillos más antiguas de la región.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46042','fiesta','Festes de Moros i Cristians en honor a San Engracio Mártir','Moros y Cristianos, Patronal y Enológica. Se celebra en Agosto. Relevancia comarcal por la vistosidad de sus desfiles de comparsas, trabucadas y embajadas, que conviven con la arraigada tradición de sus destilerías de licores históricos, cuna de bebidas reconocidas internacionalmente.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46043','fiesta','Festes Patronals en honor a la Virgen de la Asunción','Patronal y Tradicional. Se celebra en Agosto. Celebración de carácter marcadamente vecinal y baja demografía en el Pla de les Conques, estructurada en torno a misas cantadas por el coro local, juegos infantiles tradicionales y verbenas de pequeño formato.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90361','fiesta','Fiestas Mayores en honor a la Virgen del Olivar y al Cristo de la Buena Muerte, y el Cant de la Carxofa','Patronal, Etnográfica, Musical y Pirotécnica. Se celebra en Agosto y Septiembre. Hito etnográfico de nivel provincial debido al Cant de la Carxofa, un antiquísimo canto sacro entonado por un niño que emerge de un artefacto colgado en forma de alcachofa, acompañado de majestuosas mascletás y cordás junto a su castillo señorial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90362','fiesta','Fiestas de Moros y Cristianos y Patronales en honor a la Virgen del Remedio','Moros y Cristianos, Etnográfica (Toque manual de campanas) y Patronal. Se celebra en Octubre. De gran relevancia provincial y regional; su secular tradición del Toque Manual de Campanas está declarada Bien de Interés Cultural e inscrita en la lista del Patrimonio Inmaterial de la UNESCO, sirviendo de banda sonora a los desfiles monumentales de moros y cristianos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90363','fiesta','Fiestas Patronales en honor a Santa Ana','Patronal, Romería y Pirotécnica. Se celebra en Julio. Festejos de gran relieve en el área metropolitana, cuya identidad se fundamenta en la multitudinaria romería al ermitorio de Santa Ana, desfiles de bandas de música, festivales de folklore tradicional y espectaculares castillos de fuegos artificiales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90364','fiesta','Festes de Sant Roc y la Mare de Déu del Roser','Patronal, Etnográfica (Danzas tradicionales) y Taurina. Se celebra en Agosto. Atractivo comarcal en la Ribera Baixa que destaca por la pervivencia de bailes tradicionales como la Muixeranga y los Els Bastonets, complementando las exhibiciones de reses bravas y las verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90365','fiesta','Fiestas Patronales del Santísimo Cristo de las Almas y la Virgen del Rosario','Patronal, Pirotécnica y Tradicional. Se celebra en Septiembre. Celebración de arraigo en L''Horta Nord; congrega a los vecinos en torno a espectáculos de pólvora, desfiles humorísticos de disfraces, cenas tradicionales de sobaquillo en el casco histórico y conciertos al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90366','fiesta','Fiestas Patronales en honor a la Virgen de la Cueva Santa y San Roque','Patronal, Romería y Tradicional. Se celebra en Agosto. Festejos tradicionales marcados por el reencuentro veraniego en la comarca del Camp de Morvedre, vertebrados por las romerías vecinales, procesiones religiosas solemenes, campeonatos de pelota valenciana y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90367','fiesta','Feria y Fiestas de la Mona de Pascua y San Lorenzo','Gastronómica, Tradicional, Feria y Patronal. Se celebra en Pascua (Marzo/Abril) y Agosto. Hito gastronómico de rango provincial; su feria de Pascua congrega a miles de personas para degustar y comprar la tradicional Mona de Alberic, dulce con denominación de calidad, complementado con concursos de carruajes, fuegos artificiales y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46012','fiesta','Fiestas Patronales en honor a Santiago Apóstol y la Virgen del Rosario','Patronal, Taurina y Tradicional. Se celebra en Julio. Celebraciones tradicionales orientadas al retorno de la población en la Hoya de Buñol, dinamizadas por la entrada de vaquillas, las verbenas populares en su auditorio municipal al aire libre y desfiles de bandas de música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46013','fiesta','Fiestas Patronales de San Cristóbal y Día de la Horchata','Patronal, Gastronómica y Masiva. Se celebra en Julio y Julio (Primer miércoles). Relevancia provincial y turística masiva; su célebre Día de la Horchata exalta de forma monográfica la bebida autóctona del cultivo de la chufa con degustaciones gratuitas multitudinarias, sirviendo de escaparate de sus verbenas costeras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46014','fiesta','Fiestas en honor a San Ramón Nonato y la Virgen de la Albuixech','Patronal y Tradicional. Se celebra en Agosto y Septiembre. Festejos de escala vecinal e identidad huertana, caracterizados por tradicionales muestras de tiro y arrastre, espectáculos pirotécnicos, procesiones religiosas solemnes y cenas multitudinarias en la plaza del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90369','fiesta','Fiestas Patronales del Santísimo Cristo de la Salud y la Inmaculada Concepción','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo local y de reunión de descendientes en la Ribera Alta, basadas en verbenas familiares, tradicionales campeonatos deportivos, comidas comunitarias y pasacalles con bandas de música locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90368','fiesta','Fiestas Patronales del Santísimo Cristo de la Fe y San Martin','Patronal, Pirotécnica y Taurina. Se celebra en Agosto. De relieve comarcal en l''Horta Sud; destaca por su intensa semana de festejos taurinos callejeros, la tradicional Mascletà nocturna, desfiles de moros y cristianos locales y multitudinarias orquestas en el centro urbano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46018','fiesta','Fiestas Patronales en honor a la Virgen de la Salud','Patronal, Romería y Tradicional. Se celebra en Agosto. Fiestas tradicionales de baja escala demográfica y perfil familiar en Los Serranos, articuladas en torno a la romería tradicional a la ermita de la Virgen, juegos tradicionales infantiles y cenas de sobaquillo con música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46019','fiesta','Festes de la Mare de Déu de l''Corell (Entrada de la Murta) y COTIF','Etnográfica, Patronal y Torneo Internacional Cultural. Se celebra en Septiembre y Agosto. Hito etnográfico de nivel regional por su tradicional Entrada de la Murta y la espectacular procesión mariana rica en danzas ancestrales como Els Tornejants y Els Negrets, sumando la proyección global de su torneo internacional de fútbol COTIF.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46020','fiesta','Fiestas Patronales de San Onofre Mártir','Patronal, Taurina y Pirotécnica. Se celebra en Octubre *. Celebración de arraigo local en la comarca de La Costera, dinamizada por la organización de los tradicionales encierros y la suelta de vaquillas, completada con competiciones lúdicas intergeneracionales y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90370','fiesta','Festes del Santíssim Crist dels Necessitats','Patronal, Pirotécnica, Etnográfica y Masiva. Se celebra en Julio y Agosto *. Gran empaque provincial; destaca por su histórica bajada del Cristo y muy especialmente por la espectacular Baixà de Sant Roc, una procesión nocturna rodeada del fuego de los coeters, culminando con grandiosos espectáculos de pólvora.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46022','fiesta','Fiestas de la Virgen del Don y San Sebastián','Patronal, Moros y Cristianos y Pirotécnica. Se celebra en Septiembre. Festividades que congregan gran volumen de participación en l''Horta Sud; combinan los tradicionales e históricos desfiles de las huestes moras y cristianas con la solemne ofrenda de flores a la patrona y grandes cordàs.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46024','fiesta','Fiestas Patronales en honor a San Agustín y la Virgen de los Afligidos','Patronal y Tradicional. Se celebra en Septiembre. Festejos vecinales de pequeña escala demográfica en el Valle del Palancia, centrados en los actos religiosos tradicionales, cenas populares de sobaquillo, pasacalles de charangas y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46025','fiesta','Fiestas Patronales en honor a San Bartolomé y el Patriarca San Juan de Ribera','Patronal y Tradicional. Se celebra en Agosto. Celebración tranquila de perfil vecinal estrechamente ligada a su patrimonio religioso monumental histórico, reforzada por espectáculos populares de variedades, pasacalles de la banda municipal y cenas compartidas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46026','fiesta','Fiestas Patronales de San Jaime Apóstol','Patronal, Taurina y Tradicional. Se celebra en Julio. Celebración tradicional con fuerte implantación de la cultura taurina en la comarca del Marquesat, caracterizada por la suelta de reses bravas al estilo tradicional en su plaza y calles amuralladas, junto a verbenas lúdicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46027','fiesta','Festes de Moros i Cristians y del Santíssim Crist de l''Agonia','Moros y Cristianos, Patronal y Etnográfica. Se celebra en Agosto. De relieve comarcal en la Vall d''Albaida; destaca por su singular acto de L''Angelet, donde un niño vestido de ángel anuncia las fiestas descendiendo suspendido por un cable sobre la plaza, sumado a sus tradicionales desfiles moros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46023','fiesta','Festes de la Mare de Déu del Consol y San Miguel','Patronal y Tradicional. Se celebra en Septiembre. Celebración de carácter estrictamente vecinal y reducida población, estructurada con procesiones litúrgicas íntimas por sus calles históricas cercanas al Monasterio de Cotalba, cenas de sobaquillo y pequeñas orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46028','fiesta','Fiestas Patronales en honor a San Ramón Nonato y la Virgen de la Merced','Patronal, Taurina y Tradicional. Se celebra en Agosto y Septiembre. Fiestas tradicionales de baja escala demográfica en el curso del río Palancia, vertebradas por exhibiciones de reses bravas en la plaza, pasacalles de la banda municipal y comidas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46029','fiesta','Festes de la Mare de Déu de la Salut y Semana de Toros de Algemesí','Etnográfica, Religiosa, Histórica y Feria Taurina de Novilladas. Se celebra en Septiembre. Las Festes de la Mare de Déu de la Salut están declaradas Patrimonio Cultural Inmaterial de la Humanidad por la UNESCO, constituyendo un hito mundial insustituible por la pureza de sus danzas ancestrales de La Muixeranga, Els Bastonets y Els Tornejants. A esto se une su histórica Semana de Toros con la singular plaza de madera construida a mano por los peñistas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46031','fiesta','Festes de Sant Josep y de San Antonio Abad','Patronal, Taurina y Pirotécnica. Se celebra en Agosto. Relevancia comarcal en la Ribera Alta; destaca por sus multitudinarios encierros de vaquillas, las competiciones de tiro y arrastre que rescatan el pasado agrario local y espectaculares verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90864','fiesta','Festes del Santíssim Sacrament (Festa del Miracle dels Peixets)','Etnográfica, Religiosa y Patronal. Se celebra en Agosto y Junio. Hito etnográfico comarcal de alta consideración ligado a la milenaria leyenda del milagro de los peces de 1348; destaca la solemne procesión eucarística que mantiene el privilegio histórico de celebrarse en agosto, congregando gran afluencia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46034','fiesta','Festes de Sant Ecce Homo y de la Mare de Déu de l''Asumpció','Patronal y Tradicional. Se celebra en Agosto y Septiembre. Celebración de escala local en la Safor, caracterizada por pasacalles de su sociedad musical, concursos de paellas populares entre peñas de amigos, juegos tradicionales de calle y solemnes procesiones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46035','fiesta','Fiestas Patronales de San Bartolomé y la Virgen de los Desamparados','Patronal, Pirotécnica y Musical. Se celebra en Julio. De notable relevancia comarcal respaldada por una potente capacidad económica municipal; destaca por sus grandes eventos y conciertos gratuitos de artistas nacionales, espectaculares castillos de fuegos artificiales y desfiles de moros y cristianos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46036','fiesta','Fiestas Patronales de la Virgen de la Consolación','Etnográfica, Romería Histórica y Tradicional. Se celebra en Mayo y Agosto (Cada tres años las patronales mayores). Hito etnográfico de la montaña valenciana; destaca la tradicional y secular romería a la ermita con el canto de los Mayos de Alpuente y las espectaculares danzas de labradores tradicionales, poseedoras de un inestimable valor musical e historiográfico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46037','fiesta','Fiestas Patronales en honor a San Pedro Inculcado y los Santos de la Piedra','Patronal y Tradicional. Se celebra en Junio y Septiembre. Festividades veraniegas de arraigo local estructuradas con tradicionales pasacalles, campeonatos de raspall [pelota valenciana], cenas de sobaquillo en las calles de la villa y orquestas populares de formato familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46038','fiesta','Fiestas de Santa Inés y San Bartolomé, y el Canto de los Mayos','Patronal, Romería y Musical Tradicional. Se celebra en Enero y Agosto. Festejos rurales de montaña marcados por su reducida población estable; adquieren notoriedad etnográfica por el mantenimiento del canto folclórico de los Mayos de Andilla en honor a la patrona y cenas comunitarias al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46039','fiesta','Fiestas Patronales del Santísimo Cristo de la Providencia y San Agustín','Moros y Cristianos, Patronal y Folclórica. Se celebra en Septiembre. De relevancia comarcal en la Canal de Navarrés; combina sus procesiones tradicionales con vistosos desfiles de Moros y Cristianos que aprovechan turísticamente el marco natural e histórico de la Albufera de Anna y su Palacio Cervellón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46040','fiesta','Festes de la Purísima, del Santíssim Crist de l''Agonia y Festa de la Maetà','Patronal, Etnográfica, Tradicional y Fluvial. Se celebra en Diciembre, Julio y Agosto. Atractivo comarcal singular ligado al río Júcar y la histórica Acequia Real de Antella; destaca por sus actividades lúdicas fluviales veraniegas, carreras populares, verbenas musicales de peñas y procesiones tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46041','fiesta','Fiestas de las Gordas en honor a la Virgen del Remedio','Etnográfica, Patronal y Romería. Se celebra en Septiembre (Cada siete años las mayores) *. Posee un singular valor etnográfico en la comarca de Los Serranos debido a las Fiestas de las Gordas, celebradas cada siete años, donde destaca el espectacular Entremés de Aras, un auto sacro tradicional entre ángeles y demonios con danzas de espadas ancestrales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46044','fiesta','El Primer Corte de la Miel y Fiestas Patronales de la Virgen del Rosario','Gastronómica, Apícola, Patronal y Masiva. Se celebra en Octubre y Agosto. Su feria monográfica y apícola El Primer Corte de la Miel ostenta la declaración de Fiesta de Interés Turístico Autonómico, constituyendo un hito gastronómico regional masivo que reúne a decenas de miles de visitantes en torno a la apicultura tradicional, demostraciones en vivo en urnas de cristal y muestras gastronómicas). ¿Puedo continuar con el siguiente bloque de municipios de la provincia de Valencia (siguiendo el orden alfabético por la letra B: Barx, Barxeta, Bèlgida, Bellreguard, Bellús, Benagéber, Benaguasil, Benavites, Benegida, Benetússer, Beniarjó, Beniatjar, Benicolet, Benicull de Xúquer, Benifaió, Benifairó de la Valldigna, Benifairó de les Valls, Beniflá, Benigánim, Benimodo, Benimuslem, Beniparrell, Benirredrà, Benisano, Benissoda, Benissufera, Bétera, Bicorp, Bocairent, Bolbaite, Bonrepòs i Mirambell, Bufali, Bugarra, Buñol, Burjassot.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90865','fiesta','Festes de Sant Miquel Arcàngel','Patronal y Tradicional. Se celebra en Agosto. Celebración tradicional de montaña en el valle de la Valldigna orientada al turismo de interior, caracterizada por masivas cenas de paellas en la calle Mayor, procesiones solemnes y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90372','fiesta','Festes de la Puríssima Concepció','Patronal y Tradicional. Se celebra en Julio. Festividades de arraigo comarcal menor en la Costera, estructuradas con pasacalles musicales acompañados por bandas locales, tradicionales parques de juegos infantiles y cenas comunitarias al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46047','fiesta','Fiestas de Moros y Cristianos y Patronales de San Lorenzo','Moros y Cristianos y Patronal. Se celebra en Agosto. Festejos del Valle de Albaida caracterizados por la vistosidad de sus desfiles locales de moros y cristianos, embajadas satíricas, verbenas populares y la tradicional Dansà en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46048','fiesta','Fiestas de Moros y Cristianos en honor a San Miguel Arcángel','Moros y Cristianos, Patronal y Marinera. Se celebra en Septiembre. De notable relevancia en la comarca de la Safor; destaca por sus coloridas y multitudinarias entradas de las comparsas moras y cristianas, sus verbenas costeras y la tradicional fiesta del Chupinazo que inicia la semana festiva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46050','fiesta','Fiestas Patronales de la Inmaculada Concepción y San Isidro Labrador','Patronal y Tradicional. Se celebra en Mayo y Agosto. Festividades de arraigo vecinal en los Serranos que sirven de punto de reunión para los descendientes del municipio en verano, organizando verbenas familiares, comidas populares y campeonatos de truc.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46051','fiesta','Fiestas Patronales de la Virgen de Montiel','Patronal, Romería y Pirotécnica. Se celebra en Septiembre. Gran relieve en la comarca del Camp de Túria; destaca la multitudinaria romería de la Bajada de la Virgen desde su santuario, junto con la masiva participación en las procesiones, las monumentales mascletás y la tradicional Pujada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46052','fiesta','Fiestas Patronales en honor a la Virgen de los Ángeles y San Pablo','Patronal, Taurina y Pirotécnica. Se celebra en Junio. Celebración en la comarca de les Valls que destaca por sus encierros tradicionales de vaquillas, el adorno de calles en torno a su emblemática Torre medieval y espectáculos de orquestas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46054','fiesta','Semana Santa de Benetússer y Fiestas Patronales de San Sebastián','Recreación Histórica, Drama Sacro y Patronal. Se celebra en Marzo/Abril y Junio. Hito etnográfico masivo a nivel regional. Las representaciones de estampas sacras y la Pasión de Cristo en vivo por las calles por parte de actores vecinales cuentan con una raigambre histórica excepcional desde 1949, reuniendo a miles de visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46055','fiesta','Festes de Sant Marc y el Ball de la Bandera','Etnográfica, Patronal y Literaria. Se celebra en Abril. Atractivo etnográfico comarcal singular por la exhibición del Ball de la Bandera, donde el síndico voltea de forma espectacular un estandarte monumental a ras de suelo ante el templo parroquial en tributo al poeta Ausiàs March.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46056','fiesta','Festes en honor a San Roque y la Virgen de la Asunción','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo estrictamente local bajo las faldas del Benicadell, caracterizadas por procesiones religiosas tradicionales de escala familiar, cenas vecinales de hermandad y pequeñas orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46057','fiesta','Festes de la Puríssima Concepció y Sant Joan Baptista','Patronal y Tradicional. Se celebra en Agosto. Celebración familiar orientada a la recepción de veraneantes en la Vall d''Albaida, estructurada con pasacalles musicales con charangas, competiciones tradicionales de pelota valenciana y bailes nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46904','fiesta','Festes de la Beata Inés y la Mare de Déu dels Desemparats','Patronal y Tradicional. Se celebra en Agosto. Festejos tradicionales vecinales de pequeña escala tras su segregación municipal, dinamizados por espectáculos infantiles de calle, procesiones claustrales solemnes y cenas comunitarias en la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46060','fiesta','Festes Majors en honor a la Virgen de la Alborxi y San Roque','Patronal, Pirotécnica y Tradicional. Se celebra en Agosto. De relieve comarcal en la Ribera Alta, famosa por la gran participación ciudadana en los desfiles de carrozas, ruidosos espectáculos de fuegos de tracas kilométricas por el casco antiguo y orquestas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46059','fiesta','Festes Patronals de Sant Benet y la Fiesta de los Santos de la Piedra','Patronal y Tradicional. Se celebra en Julio y Agosto. Celebración de arraigo local integrada en el entorno natural de la Valldigna, caracterizada por tradicionales pasacalles, campeonatos de pelota valenciana al aire libre, cenas comunitarias y espectáculos pirotécnicos menores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46058','fiesta','Festes en honor a la Virgen del Buen Suceso','Patronal, Pirotécnica y Tradicional. Se celebra en Septiembre. Atractivo comarcal destacado gracias a sus espectaculares y masivas cordàs nocturnas de petardos, sirviendo de complemento lúdico a las procesiones solemnes y las comidas populares organizadas en la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46062','fiesta','Fiestas de Moros y Cristianos y Patronales de la Beata Inés de Benigánim','Moros y Cristianos, Etnográfica y Patronal. Se celebra en Agosto y Enero. Atractivo comarcal y provincial; sus desfiles de Moros y Cristianos tienen un alto nivel de participación. Destaca también en enero la devoción a su Beata local con el reparto de panes bendecidos y tradicionales hogueras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46063','fiesta','Festes de Sant Felip y Sant Bernat','Patronal y Tradicional. Se celebra en Agosto. Festejos de escala local y familiar en la Ribera Alta, basados en pasacalles tradicionales acompañados por la sociedad musical del pueblo, procesiones religiosas e infantiles y cenas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46064','fiesta','Festes de la Puríssima Concepció y Sant Roc','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo estrictamente local vinculadas a la baja demografía de este núcleo cercano al río Júcar, basadas en verbenas familiares, parques infantiles y pasacalles musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46065','fiesta','Fiestas Patronales en honor a Santa Bárbara','Patronal, Pirotécnica y Taurina. Se celebra en Julio *. Festejos de área metropolitana marcados por su tradición pirotécnica, la celebración de procesiones religiosas, comidas comunitarias de paellas y una semana de exhibiciones de toros callejeros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46066','fiesta','Festes de Sant Llorenç','Patronal y Tradicional. Se celebra en Agosto. Festejos tradicionales de relieve local muy próximos a la capital comarcal de Gandia, caracterizados por pasacalles con bandas de música locales, orquestas populares familiares y procesiones religiosas solemnes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46067','fiesta','Fiestas Patronales de los Santos Reyes y la Virgen del Fundamento','Patronal, Histórica y Tradicional. Se celebra en Septiembre. De relieve comarcal en el Camp de Túria; destaca por sus procesiones históricas en el marco de su suntuoso e histórico Castillo bajomedieval, acompañadas de pasacalles, bandas de música y fuegos artificiales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46033','fiesta','Fiestas Patronales en honor a San Urbano y la Virgen de la Logia','Patronal y Tradicional. Se celebra en Agosto. Celebración tranquila de perfil vecinal en el valle del río Vernissa, reforzada por espectáculos populares de variedades, pasacalles tradicionales con charangas locales y cenas compartidas en las calles de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46030','fiesta','Festes de la Mare de Déu dels Desemparats y San Vicente Ferrer','Patronal, Taurina y Tradicional. Se celebra en Agosto. Celebración tranquila de perfil familiar en la Baronía, vertebrada por la exhibición de toros de calle, tradicionales cenas populares en la plaza del pueblo y conciertos de la banda de música de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46049','fiesta','Fiestas Patronales en honor a San Ana y el Cristo de la Buena Muerte','Patronal y Tradicional. Se celebra en Septiembre. Celebración estrictamente local vinculada a su baja demografía, basada en misas y procesiones solemnes, campeonatos de juegos de cartas y pequeñas orquestas familiares en la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46061','fiesta','Fiestas Patronales de San Jaime Apóstol','Patronal y Tradicional. Se celebra en Julio. Celebración vecinal en uno de los municipios con menor término de la Safor, basada en actividades lúdicas infantiles, comidas de hermandad vecinal y verbenas musicales familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46068','fiesta','Fiestas Patronales de San Roque y la Virgen del Rosario','Patronal y Tradicional. Se celebra en Agosto. Celebración tranquila de perfil vecinal en la Vall d''Albaida, reforzada por espectáculos populares de variedades, misas tradicionales con cantos corales autóctonos y cenas compartidas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46069','fiesta','Fiestas Patronales en honor a San Antonio de Padua','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo estrictamente local condicionadas por su bajísima población, basadas en cenas vecinales de sobaquillo en la plaza, pasacalles con charangas y orquestas de formato familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46070','fiesta','Festes de les Alfàbegues (Fiestas de la Virgen de Agosto)','Etnográfica, Patronal, Botánica y Pirotécnica. Se celebra en Agosto. Hito etnográfico regional de gran espectacularidad. Destaca la ofrenda de las Alfàbegues, plantas de albahaca monumentales cultivadas de forma artesanal hasta superar los dos metros de altura, acompañadas por los Obrers y Majorals y la espectacular Coetà nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46071','fiesta','Fiestas Patronales en honor a San Juan Evangelista y la Santa Cruz','Patronal y Tradicional. Se celebra en Agosto. Celebración de la Canal de Navarrés orientada al retorno estival; destaca por sus muestras de folclore serrano, comidas populares en las calles de la villa y orquestas nocturnas en su entorno natural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46072','fiesta','Fiestas de Moros y Cristianos de San Blas y la Fiesta de San Agustín','Moros y Cristianos, Histórica, Etnográfica y Patronal. Se celebra en Febrero y Agosto. Sus Fiestas de Moros y Cristianos en invierno ostentan el título de Interés Turístico Nacional, destacando por el gran rigor histórico de sus filaes, el uso masivo de pólvora en las embajadas de arcabucería, la suntuosidad de sus trajes y el espectacular desfile de L''Entrà.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46073','fiesta','Fiestas Patronales en honor al Santísimo Cristo del Amparo','Patronal, Moros y Cristianos y Tradicional. Se celebra en Abril (Semana de Pascua). Festejos de relevancia comarcal en la Canal de Navarrés, famosos por sus coloridas comparsas de moros y cristianos locales, desfiles humorísticos, verbenas nocturnas y procesiones tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46074','fiesta','Fiestas Patronales de San Vicente Ferrer y la Virgen del Pilar','Patronal, Pirotécnica y Tradicional. Se celebra en Octubre. Celebración de arraigo en L''Horta Nord, caracterizada por la organización de calderas populares de arroz, pasacalles con bandas locales, disparos de fuegos artificiales y verbenas para la comunidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46075','fiesta','Fiestas Patronales en honor a la Virgen de Loreto','Patronal y Tradicional. Se celebra en Agosto. Festejos de escala vecinal e íntima en la Vall d''Albaida, estructurados en torno a misas solemnes, comidas comunitarias de hermandad en las plazas de la villa y pequeñas orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46076','fiesta','Fiestas Patronales de la Virgen del Rosario y San Juan Bautista','Patronal, Taurina y Fluvial. Se celebra en Agosto. Festejos veraniegos que se dinamizan en torno a su playa fluvial en el río Turia, combinando las tradicionales exhibiciones de toros cerriles con verbenas nocturnas, parques infantiles y cenas de sobaquillo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46077','fiesta','La Tomatina y Fiestas Patronales de San Luis Bertrán','Fiesta de Impacto Masivo Internacional, Patronal y Musical. Se celebra en Agosto (Último miércoles del mes). La Tomatina de Buñol es una de las festividades de España con mayor repercusión mundial, declarada Fiesta de Interés Turístico Internacional, reuniendo a decenas de miles de turistas globales en una monumental batalla incruenta de tomates, complementada por los históricos certámenes de sus laureadas bandas musicales). ¿Puedo continuar con el siguiente bloque de municipios de la provincia de Valencia (siguiendo el orden alfabético por la letra B y C: Burjassot, Calles, Camporrobles, Canals, Canet d''en Berenguer, Carcaixent, Càrcer, Carlet, Carrícola, Casas Altas, Casas Bajas, Casinos, Castelló de Rugat, Castellonet de la Conquesta, Castielfabib, Catadau, Catarroja, Caudete de las Fuentes, Cerdà, Chella, Chelva, Chera, Cheste, Chiva, Chulilla, Cofrentes, Corbera, Cortes de Pallás, Cotes, Cullera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45003','fiesta','Fiestas Patronales en honor a San Roque y la Virgen de la Cabeza','Patronal, Pirotécnica y Tradicional. Se celebra en Agosto. Festejos de gran arraigo en el área metropolitana de Valencia; destaca por la espectacularidad de su histórica Fiesta de la Clavaría, sus monumentales mascletás y la tradicional Pujada del santo patrón respaldada por una masiva concurrencia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46079','fiesta','Fiestas Patronales en honor a la Virgen del Plan y Santa Quiteria','Patronal y Tradicional. Se celebra en Enero y Agosto. Celebración de carácter rural en la comarca de Los Serranos, vertebrada por sus tradicionales hogueras de invierno en las plazas, el reparto de panes bendecidos, comidas comunitarias y verbenas estivales de retorno.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46080','fiesta','Fiestas Patronales en honor a la Virgen de Tejeda','Patronal y Tradicional. Se celebra en Mayo y Agosto. De notable relevancia en la comarca de Requena-Utiel; destaca por las solemnes procesiones en honor a la Virgen, las tradicionales hogueras, los campeonatos de pelota y las concurridas orquestas estivales que reúnen a los municipios vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46081','fiesta','Fiestas Patronales de San Antonio Abad (Sant Antoni de Canals)','Etnográfica, Histórica, Patronal y Pirotécnica. Se celebra en Enero. Hito etnográfico masivo a nivel regional y nacional, declarado de Interés Turístico Autonómico. Destaca por la quema de La Foguera de Canals, catalogada como la hoguera de leña más grande del mundo, complementada por los desfiles ecuestres y el tradicional reparto de los bandós.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46082','fiesta','Fiestas Patronales en honor a la Virgen contra las Fiebres y San Pedro','Patronal, Taurina y de Reencuentro Turístico. Se celebra en Junio y Septiembre. Equilibra la devoción tradicional del casco urbano histórico con la gran afluencia turística de su zona costera, caracterizada por masivas jornadas de bous al carrer, espectaculares castillos de fuegos artificiales a la orilla del mar y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90866','fiesta','Fiestas Patronales en honor a la Virgen de la Aguas Vivas y San Bonifacio Mártir, y la Feria Modernista','Patronal, Recreación Histórica y Tradicional. Se celebra en Octubre y Junio. Atractivo etnográfico y cultural de nivel provincial gracias a su consolidada Fira Modernista, que recrea el esplendor de la "cuna de la naranja" del siglo XIX con indumentaria de época, mercados de artesanía y visitas a sus históricos huertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46084','fiesta','Fiestas Patronales del Santísimo Cristo de la Agonía y la Virgen de Gracia','Patronal y Tradicional. Se celebra en Septiembre. Celebración de arraigo local en el Valle de Cárcer que destaca por congregar a la comunidad vecinal en torno a tradicionales desfiles de disfraces, procesiones religiosas solemnes, cenas comunitarias y pasacalles musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46085','fiesta','Fiestas Patronales en honor a San Bernardo, María y Gracia','Patronal, Romería y Pirotécnica. Se celebra en Julio y Septiembre. De relieve comarcal en la Ribera Alta; destaca por la romería tradicional a la ermita de San Bernardo, sus concurridos festivales de bandas de música locales, desfiles humorísticos de carrozas y espectaculares castillos de pólvora.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46086','fiesta','Fiestas Patronales en honor al Cristo del Calvario','Patronal y Tradicional. Se celebra en Septiembre. Festejos de escala estrictamente local condicionados por la bajísima demografía del municipio en el Valle de Albaida, fundamentados en cenas vecinales al aire libre, actividades de concienciación ecológica y verbenas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46087','fiesta','Fiestas Patronales en honor a la Santísima Trinidad y la Virgen de Tejeda','Patronal y Tradicional. Se celebra en Junio y Agosto. Festividades orientadas al reencuentro de la población ausente en el Rincón de Ademuz, estructuradas en torno a tradicionales pasacalles, parques infantiles, misas solemnes y orquestas musicales de marcado ambiente vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46088','fiesta','Fiestas Patronales en honor al Salvador','Patronal y Tradicional. Se celebra en Agosto. Celebración tranquila de carácter rural marcada por su baja demografía a orillas del río Turia, dinamizada por orquestas de fin de semana, tradicionales comidas de hermandad, jotas tradicionales y procesiones populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46089','fiesta','Fiestas Patronales de Santa Bárbara y San Isidro Labrador, y la Feria del Dulce Artesano','Gastronómica, Patronal y Tradicional. Se celebra en Agosto y Noviembre. Gran relevancia comarcal en el Camp de Túria gracias a su consolidada feria agroalimentaria dedicada a los tradicionales turrones y peladillas de Casinos, que atrae masivamente a visitantes y complementa sus verbenas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46090','fiesta','Fiestas de Moros y Cristianos en honor a San Antonio Abad y la Virgen del Remedio','Moros y Cristianos y Patronal. Se celebra en Agosto. Celebración tradicional con fuerte arraigo en el Valle de Albaida, caracterizada por la vistosidad de sus desfiles locales de moros y cristianos, pasacalles de la banda municipal, encendidos de hogueras y cenas populares multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46091','fiesta','Fiestas Patronales en honor a San Jaime Apóstol y la Virgen de los Dolores','Patronal y Tradicional. Se celebra en Julio. Festejos estrictamente vecinales debido a su reducida demografía en la Safor, basados en misas solemnes en la iglesia parroquial, comidas de hermandad en los antiguos salones de la villa y pequeñas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46092','fiesta','Fiestas de la Virgen de Gracia y las Volteadas de Campanas','Etnográfica, Patronal y Romería. Se celebra en Septiembre y Pascua. Atractivo etnográfico singular en el Rincón de Ademuz debido a la espectacularidad de los volteos de campanas tradicionales realizados a mano de manera extrema desde su iglesia-fortaleza medieval, sumado a sus romerías rurales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46093','fiesta','Fiestas Patronales de San Pedro Apóstol y la Sangre de Cristo','Patronal, Taurina y Tradicional. Se celebra en Julio. Celebración de la comarca del Marquesat, caracterizada por una intensa y concurrida semana de festejos taurinos callejeros de reses bravas de corro, verbenas populares nocturnas en la plaza y pasacalles con bandas de música locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46094','fiesta','Fiestas Patronales de San Pedro y de San Miguel Mártir, y el Concurso de All i Pebre','Gastronómica, Marinera, Etnográfica y Patronal. Se celebra en Septiembre. Hito etnográfico de nivel regional por el histórico e internacional Concurso de All i Pebre en el Puerto de Catarroja, que ensalza la cocina tradicional de la Albufera atrayendo a miles de comensales, complementado con sus desfiles de moros y cristianos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46095','fiesta','Fiestas Patronales en honor a San Antonio Abad','Patronal y Tradicional. Se celebra en Junio. Fiestas tradicionales de perfil familiar y vitivinícola en la comarca de Requena-Utiel, vertebradas por actividades de recreación infantil, pasacalles de la charanga local, cenas de sobaquillo y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46096','fiesta','Fiestas Patronales en honor a San Antonio Abad','Patronal y Tradicional. Se celebra en Agosto. Celebración vecinal de baja escala demográfica en la comarca de La Costera, estructurada en torno a comidas comunitarias de sobaquillo, procesiones religiosas tradicionales y pequeñas orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46107','fiesta','Fiestas Patronales de San Blas y la Virgen del Rosario, y los choques de comparsas','Patronal, Moros y Cristianos y Tradicional. Se celebra en Febrero *. De relieve comarcal en la Canal de Navarrés; destaca por sus singulares e históricos choques y embajadas de moros y cristianos locales en invierno, acompañados por la degustación de repostería tradicional de la tierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46106','fiesta','Fiestas de San Antón (Fiesta de las Hogueras) y Fiestas Patronales','Etnográfica, Histórica, Patronal y Romería. Se celebra en Enero y Agosto. Gran relevancia etnográfica y provincial en Los Serranos; su fiesta de las hogueras destaca por el encendido de monumentales fuegos en sus barrios históricos morisco y judío, complementada en verano con el tradicional festival de narración oral y música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46108','fiesta','Fiestas Patronales en honor a la Virgen del Rosario','Patronal y Tradicional. Se celebra en Agosto. Festejos veraniegos que se dinamizan en torno a su parque natural y el embalse de Buseo, combinando las tradicionales actividades deportivas infantiles con verbenas nocturnas, pasacalles y masivas cenas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46109','fiesta','Fiestas Patronales de San Lucas Evangelista (Fiestas de la Vendimia)','Patronal, Etnográfica, Taurina y Concurrencia de Masas. Se celebra en Octubre. Relevancia comarcal y provincial muy alta; sus tradicionales fiestas de la vendimia destacan por el vistoso desfile de la Pisá de la uva, sus históricos espectáculos de bous al carrer con la espectacular Entrá de toros y caballos, y la masiva llegada de público ligada a los eventos del motor). ¿Puedo continuar con el siguiente bloque de municipios de la provincia de Valencia (siguiendo el orden alfabético estricto a partir de la letra C: Chiva, Chulilla, Cofrentes, Corbera, Cortes de Pallás, Cotes, Cullera, Daimús, Dos Aguas, L''Eliana, Emperador, Enguera, Énova, Estivella, Estubeny, Faura, Favara, Font de la Figuera, Font d''en Carròs, Fuente Encarroz, Fuenterrobles, Gandia, Gátova, Gavarda, Genovés, Gestalgar, Gilet, Godella, Godelleta, Guadasséquies, Guadassuar, Higueruelas, Jalance, Jarafuel, Játiva/Xàtiva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46111','fiesta','Fiestas del Torico de la Cuerda y Fiestas Patronales de la Virgen del Castillo','Taurina, Etnográfica, Patronal y de Concurrencia de Masas. Se celebra en Agosto y Septiembre. Hito etnográfico regional de gran calado popular; su célebre Torico de la Cuerda cuenta con un arraigo multisecular y atrae a miles de aficionados que abarrotan las calles para seguir las veloces carreras de las reses conducidas por la badana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46112','fiesta','Fiestas de la Enramá (en honor a Santa Bárbara) y la Virgen de los Ángeles','Etnográfica, Patronal y Tradicional. Se celebra en Diciembre y Agosto. De arraigo comarcal en Los Serranos; destaca por la pervivencia en invierno de la fiesta de la Enramá, donde se confeccionan guirnaldas y se sortean los emparejamientos tradicionales entre los jóvenes de la villa, complementada con su turismo estival de montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46097','fiesta','Fiestas de la Virgen de la Soledad y Fiestas de los Maderos (San Antonio Abad)','Patronal, Histórica y Tradicional. Se celebra en Agosto y Enero. De relevancia local en el Valle de Ayora-Cofrentes; resalta por la tradicional bajada de antorchas desde el castillo medieval por las fiestas de la patrona y por sus representaciones culturales vinculadas al entorno fluvial de la confluencia de los ríos Júcar y Cabriel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46098','fiesta','Fiestas Patronales en honor a la Virgen del Castillo y los Santos de la Piedra','Patronal y Tradicional. Se celebra en Septiembre. Festejos de escala comarcal en la Ribera Baixa, vertebrados por las solemnes procesiones litúrgicas dedicadas a los protectores del campo, desfiles de bandas de música locales, competiciones de pelota y cenas colectivas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46099','fiesta','Fiestas Patronales en honor a la Virgen del Rosario y San Isidro Labrador','Patronal y Tradicional. Se celebra en Agosto. Celebraciones tradicionales orientadas al reencuentro de descendientes estivales en el interior de la provincia, dinamizadas por pasacalles con charangas, verbenas populares nocturnas en su núcleo principal y en sus siete aldeas de montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46100','fiesta','Fiestas Patronales de San Miguel Arcángel y San Isidro Labrador','Patronal y Tradicional. Se celebra en Septiembre. Festividades de arraigo estrictamente local adaptadas a la reducida demografía de este núcleo del Valle de Cárcer, basadas en tradicionales cenas vecinales de sobaquillo, procesiones claustrales y bailes familiares de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46105','fiesta','Festes de la Mare de Déu del Castell (Fiestas Mayores) y las Fallas de Cullera','Patronal, Marinera, Pirotécnica y Concurrencia de Masas. Se celebra en Abril (Pascua) y Marzo. Gran empaque regional e internacional respaldado por su proyección turística; destaca la espectacular procesión nocturna de La Baixà de la Virgen desde el castillo y, especialmente, la multitudinaria y singular procesión marinera por el río Júcar con arriesgados e históricos castillos de fuegos artificiales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90867','fiesta','Fiestas Patronales en honor a San Pedro Apóstol y la Virgen de Fátima','Patronal, Marinera y de Reencuentro Turístico. Se celebra en Junio y Julio. Festejos de la comarca de la Safor que combinan las tradicionales misas solemnes con desfiles de moros y cristianos de carácter local, orquestas multitudinarias y eventos recreativos en su zona de playa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46115','fiesta','Fiestas Patronales en honor a la Virgen del Rosario y San Roque','Patronal y Tradicional. Se celebra en Agosto. Celebración marcadamente vecinal y de retorno estival en el macizo interior, caracterizada por las procesiones religiosas, las competiciones populares de naipes, juegos infantiles tradicionales y verbenas de pequeño formato.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46116','fiesta','Fiestas Patronales en honor a la Virgen del Carmen y al Santísimo Cristo del Consuelo','Patronal, Pirotécnica y Tradicional. Se celebra en Julio. De notable relevancia en el Camp de Túria; destaca por la gran participación de peñas y clavarios, sus intensas noches de pólvora que incluyen la tradicional cordà de l''Eliana, pasacalles de bandas musicales y variados conciertos nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46117','fiesta','Fiestas Patronales de la Virgen del Rosario','Patronal y Tradicional. Se celebra en Septiembre. Festejos estrictamente locales condicionados por ser el municipio con el término más pequeño de España, basados en cenas de hermandad entre los vecinos, pasacalles con charangas y pequeñas orquestas familiares en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46118','fiesta','San Miguel y la Virgen de Fátima, y San Antón (Fiesta de las Hogueras)','Patronal, Etnográfica y Romería. Se celebra en Septiembre y Enero. Relevancia comarcal y etnográfica en la Canal de Navarrés; destaca la tradicional procesión de San Miguel con las típicas carrozas artesanales engalanadas, y la espectacular romería invernal con hogueras vecinales y bendición de animales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46119','fiesta','Fiestas de la Virgen de la Aurora y San Felipe Apóstol','Patronal y Tradicional. Se celebra en Julio. Celebración de arraigo local en la Ribera Alta que congrega a la comunidad en torno al canto tradicional de la Aurora en la madrugada, cenas populares de hermandad en las plazas de la villa y orquestas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46120','fiesta','Fiestas Patronales en honor a San Miguel Arcángel','Patronal y Tradicional. Se celebra en Septiembre. Festejos de perfil vecinal en la Vall de Segó, estructurados en torno a procesiones litúrgicas solemnes, concursos de paellas populares entre las peñas del municipio y bailes con orquestas locales de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46121','fiesta','Fiestas Patronales en honor al Cristo de la Buena Dicha','Patronal y Tradicional. Se celebra en Agosto. Celebración vecinal de baja escala demográfica en la Costera, estructurada en torno a comidas comunitarias de sobaquillo, juegos infantiles de agua en las plazas y orquestas familiares de formato reducido.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46122','fiesta','Fiestas Patronales en honor a la Virgen de la Asunción y Santa Bárbara','Patronal, Taurina y Pirotécnica. Se celebra en Agosto. Festejos tradicionales con fuerte implantación de la cultura taurina en la comarca de les Valls, caracterizados por la tradicional Baixada de la santa, encierros de vaquillas de corro y cenas populares con orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46123','fiesta','Fiestas Patronales en honor a la Vera Cruz','Patronal, Taurina y Pirotécnica. Se celebra en Agosto. Celebración tranquila de perfil vecinal en las faldas de la Sierra de Corbera, dinamizada por espectáculos populares de variedades, exhibiciones taurinas callejeras, pasacalles de la banda de música y cenas compartidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90868','fiesta','Fiestas de Moros y Cristianos en honor a los Santos de la Piedra','Moros y Cristianos y Patronal. Se celebra en Diciembre. Festejos de relevancia comarcal en la Costera que destacan por el rigor de sus desfiles locales de moros y cristianos en invierno, conmemorando las batallas históricas y las embajadas, combinados con verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90869','fiesta','Fiestas de Moros y Cristianos y Patronales de la Virgen del Remedio','Moros y Cristianos y Patronal. Se celebra en Agosto. Celebración tradicional en el Baix Maestrat de la Safor, caracterizada por la espectacularidad de los desfiles de sus comparsas moras y cristianas, pasacalles musicales, espectáculos de pólvora y cenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46129','fiesta','Fiestas Patronales de Santiago Apóstol y de las Candelas','Patronal y Tradicional. Se celebra en Julio y Febrero. Fiestas tradicionales de perfil familiar y vitivinícola en la comarca de Requena-Utiel, vertebradas por actividades de recreación infantil, pasacalles de la charanga local, cenas de sobaquillo y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46131','fiesta','Fira i Festes de Gandia (en honor a San Francisco de Borja)','Histórica, Etnográfica, Feria Tradicional y Masiva. Se celebra en Septiembre/Octubre. Hito regional masivo de primer nivel declarado de Interés Turístico Autonómico. Su origen medieval se ensalza con el histórico mercado temático que inunda el centro y, de forma emblemática, con la figura del Tío de la Porra, personaje que saca a los niños de los colegios al ritmo de tambores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46902','fiesta','Fiestas Patronales en honor a la Virgen del de la Merced','Patronal y Tradicional. Se celebra en Septiembre. Festejos estivales de marcado carácter vecinal en el corazón del parque natural de la Sierra Calderona, estructurados con tradicionales pasacalles, campeonatos de truc, cenas de hermandad y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90870','fiesta','Fiestas Patronales de San Vicente Ferrer y la Virgen de la Salud','Patronal y Tradicional. Se celebra en Abril (Pascua). Celebración de arraigo local que congrega a los vecinos en torno a tradicionales desfiles de disfraces, procesiones religiosas solemnes, cenas comunitarias en la plaza del nuevo casco urbano y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46132','fiesta','Fiestas Patronales en honor al Cristo de la Buena Dicha y los Santos de la Piedra','Patronal y Tradicional. Se celebra en Agosto. De relieve comarcal en la Costera; destaca por sus procesiones históricas, pasacalles y de forma muy especial por las suntuosas partidas de Pilota Valenciana organizadas en su emblemático trinquete por ser la cuna histórica del deporte.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46133','fiesta','Fiestas Patronales en honor a los Santos de la Piedra y la Virgen de la Peña','Patronal y Tradicional. Se celebra en Agosto. Festejos veraniegos que se dinamizan en torno a su playa fluvial del río Turia, combinando las tradicionales actividades deportivas infantiles con verbenas nocturnas, pasacalles con bandas y cenas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46134','fiesta','Fiestas de la Virgen de la Estrella y Romería a Santo Espíritu','Patronal, Romería y Tradicional. Se celebra en Agosto y Septiembre. Celebración del Camp de Morvedre con notable afluencia por la tradicional e histórica romería vecinal al Real Monasterio de Santo Espíritu del Monte, sumada a encierros de vaquillas de corro y orquestas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46135','fiesta','Fiestas Patronales en honor a San Bartolomé y el Salvador','Patronal, Musical y Pirotécnica. Se celebra en Agosto. De notable relevancia en l''Horta Nord; destaca por los suntuosos conciertos de sus prestigiosas agrupaciones musicales locales, desfiles humorísticos de disfraces, procesiones religiosas solemnes y grandes espectáculos de pólvora.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46136','fiesta','Fiestas Patronales de San Pedro y de la Virgen del Carmen','Patronal, Taurina y Pirotécnica. Se celebra en Junio y Agosto. Festejos tradicionales en la Hoya de Buñol, caracterizados por una intensa semana de exhibiciones taurinas de bous al carrer, grandes disparos pirotécnicos de fuegos de artificio, conciertos de bandas y cenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46138','fiesta','Fiestas Patronales en honor a la Virgen de la Esperanza','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo estrictamente local adaptadas a la reducida demografía de este núcleo del Valle de Albaida a orillas del embalse de Bellús, basadas en tradicionales cenas de sobaquillo y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46139','fiesta','Fira de Sant Vicent (Festa de les Danses) y Fiestas Patronales','Etnográfica, Feria Histórica y Danzas Tradicionales. Se celebra en Enero y Agosto. Hito etnográfico de nivel regional por su histórica Fira de Sant Vicent, declarada de Interés Turístico. Destaca la espectacular e histórica Festa de les Danses de Guadassuar, donde cientos de parejas bailan por las calles engalanadas al ritmo de la dolçaina de forma multitudinaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46141','fiesta','Fiestas Patronales en honor a la Virgen del de los Desamparados','Patronal y Tradicional. Se celebra en Septiembre. Celebración de carácter rural en la comarca de Los Serranos, vertebrada por sus tradicionales pasacalles, campeonatos lúdicos intergeneracionales de naipes, comidas comunitarias de hermandad y orquestas estivales). Con este registro completamos de forma rigurosa todos los municipios de la provincia de Valencia que alcanzan hasta la letra H. Quedamos en el punto exacto de reinicio para las localidades de la letra I en adelante. ¿Puedo continuar con el siguiente bloque de municipios de la provincia de Valencia comenzando por la letra J de forma estrictamente alfabética (Jalance, Jarafuel, Játiva/Xàtiva, Llanera de Ranes, Llaurí, Llíria, Llocnou de la Corona, Llocnou de Sant Jeroni, Llocnou d''En Fenollet, Llombai, Llosa de Ranes, Llutxent, Loriguilla, Losa del Obispo, Macastre, Manises, Manuel, Marines, Massalavés, Massalfassar, Massamagrell, Massanassa, Meliana, Millares, Miramar, Mislata, Mogente/ Moixent, Moncada, Montserrat, Museros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46142','fiesta','Fiestas Patronales en honor a San Blas y la Virgen del de la Resurrección, y la Fiesta de los Locos','Etnográfica, Patronal y Tradicional. Se celebra en Febrero y Agosto. De singular relieve comarcal en el Valle de Ayora por su antiquísima Fiesta de los Locos [28 de diciembre], donde se nombra un alcalde de locos y los vecinos se pintan la cara y visten trajes estrafalarios, complementando sus verbenas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46144','fiesta','Fiestas Patronales en honor a San Coronado y la Virgen de la Asunción','Patronal y Tradicional. Se celebra en Agosto. Festejos tradicionales marcados por el reencuentro veraniego, estructurados con desfiles de carrozas humorísticas, campeonatos de naipes, verbenas populares nocturnas en la plaza y comidas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46154','fiesta','Fiestas Patronales en honor a San Juan Bautista y la Virgen de la Luz','Patronal y Tradicional. Se celebra en Agosto. Celebración de arraigo local en la Costera que congrega a la comunidad vecinal en torno a tradicionales pasacalles, campeonatos de pelota valenciana, cenas populares de sobaquillo y bailes con orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46155','fiesta','Fiestas Patronales en honor a San Lorenzo Mártir y la Virgen del Carmen','Patronal, Taurina y Tradicional. Se celebra en Agosto. Festejos de escala comarcal en las faldas de la Sierra de Corbera, caracterizados por procesiones religiosas solemnes, verbenas populares al aire libre y sus tradicionales tardes de bous al carrer.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45007','fiesta','Fiestas de San Vicente Ferrer y Fiestas de San Miguel Arcángel','Patronal, Musical y Concurrencia de Masas. Se celebra en Abril (Pascua) y Septiembre. Gran empaque provincial en la "Ciudad de la Música". Destaca por los históricos y multitudinarios conciertos organizados por sus dos laureadas bandas rivales [El Clarín y La Primitiva], además de la ancestral bajada de San Miguel desde su real monasterio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90375','fiesta','Fiestas Patronales en honor a la Virgen del Don','Patronal y Tradicional. Se celebra en Septiembre. Festejos estrictamente vecinales condicionados por ser el municipio de menor extensión de toda la provincia, basados en una cena comunitaria en su única calle principal, misas solemnes y pequeñas actuaciones musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90376','fiesta','Fiestas Patronales en honor a San Jerónimo y la Virgen del Carmen','Patronal y Tradicional. Se celebra en Agosto. Celebración marcadamente vecinal y de retorno estival en el interior de la Safor, vertebrada por pasacalles de la charanga local, parques infantiles, cenas colectivas y verbenas de formato reducido.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90377','fiesta','Fiestas Patronales en honor a San Diego de Alcalá','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo local debido a su reducida demografía en la Costera, dinamizadas por juegos tradicionales de mesa, campeonatos de truc, cenas vecinales al aire libre y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90871','fiesta','Fiestas Patronales de San Antonio de Padua y la Feria Renacentista de los Borja','Recreación Histórica, Feria Temática y Patronal. Se celebra en Julio y Enero. De notable relevancia comarcal y provincial gracias a su monumental Mercado Renacentista de los Borja, que transforma el centro de la villa con artesanos, justas ecuestres y cetrería, conmemorando el marquesado otorgado a la histórica familia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46157','fiesta','Fiestas Patronales en honor al Santísimo Cristo del Milagro y la Natividad de la Virgen','Patronal, Pirotécnica y Tradicional. Se celebra en Agosto. Festejos de relevancia comarcal en la Costera, famosos por sus tradicionales y solemnes procesiones, pasacalles de la banda municipal, grandes castillos de fuegos artificiales y multitudinarias orquestas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90872','fiesta','Fiestas Patronales en honor al Santo Cristo del Consuelo y de los Santos Corporales','Patronal, Romería Histórica y Moros y Cristianos. Se celebra en Abril y Septiembre. Atractivo comarcal en el Valle de Albaida por la histórica romería a su Monasterio del Corpus Christi en memoria del milagro medieval de los Corporales, complementada en verano con coloridos desfiles locales de moros y cristianos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46148','fiesta','Fiestas Patronales en honor a San Juan Bautista y la Virgen de la Soledad','Patronal, Taurina y Tradicional. Se celebra en Agosto. Festejos del Camp de Túria que conmemoran la identidad del pueblo reubicado en los años 60, dinamizados por una intensa semana de espectáculos taurinos callejeros, conciertos de bandas de música y cenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46149','fiesta','Fiestas Patronales en honor a San Sebastián y la Virgen de los Dolores','Patronal y Tradicional. Se celebra en Enero y Agosto. Fiestas tradicionales de baja escala demográfica en los Serranos, articuladas en torno al encendido de hogueras vecinales en invierno y verbenas estivales con cenas de sobaquillo y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46158','fiesta','Fiestas Patronales en honor a San Juan Bautista y la Virgen de los Desamparados','Patronal, Taurina y Tradicional. Se celebra en Julio y Agosto. Celebración tranquila de perfil vecinal en la Hoya de Buñol, reforzada por una semana taurina tradicional de bous al carrer, pasacalles musicales, concursos de paellas comunitarias y orquestas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46159','fiesta','Fiestas Patronales en honor a las Santas Justas y Rufina, y la Fiesta de la Cerámica','Etnográfica, Artesanal, Patronal y Pirotécnica. Se celebra en Julio. Hito etnográfico de nivel regional por su célebre Festa de la Ceràmica, donde los artesanos sacan los tornos a las calles y se realiza la monumental Cabalgata de la Cerámica, repartiendo miles de piezas de loza tradicional manisera entre la multitud.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46160','fiesta','Fiestas Patronales del Santísimo Cristo de la Salud','Patronal y Tradicional. Se celebra en Septiembre. Celebración de arraigo en la Ribera Alta caracterizada por las procesiones solemnes, desfiles humorísticos de disfraces en comparsas, pasacalles de la banda local y multitudinarias cenas en las plazas de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46161','fiesta','Fiestas Patronales de la Virgen del Rosario y del Cristo de las Mercedes','Patronal y Tradicional. Se celebra en Agosto. Fiestas tradicionales de marcado carácter vecinal en el Camp de Túria, estructuradas con tradicionales pasacalles, campeonatos de truc, parques infantiles y verbenas familiares con orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46162','fiesta','Fiestas Patronales de San Miguel Arcángel y el Santísimo Cristo de la Salud','Patronal, Taurina y Tradicional. Se celebra en Agosto. Celebración tradicional en la Ribera Alta, caracterizada por la suelta de reses bravas al estilo tradicional en su casco antiguo, verbenas populares nocturnas y misas mayores con cantos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46163','fiesta','Fiestas Patronales en honor a San Lorenzo Mártir y la Inmaculada Concepción','Patronal, Taurina y Pirotécnica. Se celebra en Agosto. De relieve comarcal en l''Horta Nord; destaca por su intensa semana de festejos taurinos callejeros, espectaculares castillos de fuegos artificiales, pasacalles musicales y cenas colectivas de paellas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46164','fiesta','Fiestas Patronales en honor a la Virgen del Rosario y San Juan Evangelista *','Patronal, Taurina, Pelota Valenciana y Pirotécnica *. Se celebra en Septiembre *. Relevancia comarcal y provincial destacada en l''Horta Nord; es célebre por sus suntuosos desafíos de pelota valenciana en su histórico trinquete, sus encierros taurinos de gran renombre de bous al carrer y majestuosas cordàs.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46165','fiesta','Fiestas Patronales de San Juan Bautista y Festival de Paellas','Patronal, Gastronómica y Tradicional. Se celebra en Junio. De notable relevancia en l''Horta Sud; destaca por su multitudinario festival gastronómico de paellas que congrega a miles de comensales en el polideportivo municipal, complementado con solemnes procesiones de San Juan.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46166','fiesta','Fiestas Patronales del Santísimo Cristo de la Providencia y la Virgen de la Misericordia','Patronal, Pirotécnica y Tradicional. Se celebra en Septiembre. Celebración de arraigo huertano que destaca por congregar a la comunidad en torno a espectáculos de pólvora de gran presupuesto, desfiles tradicionales, pasacalles de la banda local y cenas comunitarias al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46167','fiesta','Fiestas Patronales en honor a San Juan Bautista y San Roque','Patronal y Tradicional. Se celebra en Agosto. Festejos rurales de montaña marcados por su reducida población estable en la Canal de Navarrés, basados en procesiones religiosas tradicionales, orquestas de fin de semana, competiciones de cartas y cenas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46168','fiesta','Fiestas de Moros y Cristianos en honor a San Andrés Apóstol','Moros y Cristianos, Patronal y Marinera. Se celebra en Agosto. Festejos de la comarca de la Safor que se dinamizan turísticamente en verano combinando sus coloridas entradas y embajadas de moros y cristianos locales con conciertos frente al mar y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46169','fiesta','Fiestas Patronales en honor a la Virgen de los Ángeles y al Cristo de la Fe','Patronal, Pirotécnica y de Concurrencia de Masas. Se celebra en Agosto y Septiembre. Gran volumen de participación e impacto en el área metropolitana de Valencia, caracterizado por sus multitudinarias ferias de atracciones locales, espectaculares y masivas mascletás, conciertos multitudinarios y la solemne procesión de la Entrada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46170','fiesta','Fiestas de Moros y Cristianos en honor al Santísimo Cristo del Monte Calvario','Moros y Cristianos, Etnográfica y Patronal. Se celebra en Agosto. Relevancia comarcal en la Costera; destaca por la vistosidad de sus entradas de moros y cristianos y por la espectacular y solemne procesión de la subida del Cristo al Calvario, acompañada del disparo tradicional de salvas de arcabucería.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46171','fiesta','Fiestas Patronales en honor a San Jaime Apóstol y Santa Bárbara, y el Misterio de la Pasión','Patronal, Drama Sacro y Tradicional. Se celebra en Septiembre y Semana Santa. Hito cultural de rango provincial. Su representación dramática del Misterio de la Pasión en Semana Santa cuenta con un gran valor patrimonial e histórico en la comarca de l''Horta Nord, complementando sus verbenas patronales de otoño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46172','fiesta','Fiestas Patronales de la Virgen de Montserrat y la Semana de Música de Cámara','Patronal, Festival Musical y Taurina. Se celebra en Agosto. Atractivo de nivel comarcal en la Ribera Alta gracias a su consolidada e histórica Semana de Música de Cámara, que atrae a concertistas internacionales, combinada con sus tradicionales encierros de vaquillas de corro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46177','fiesta','Fiestas Patronales en honor a San Roque y San Pedro Nolasco','Patronal, Taurina y Pirotécnica. Se celebra en Agosto. De gran relevancia taurina en l''Horta Nord; sus fiestas mayores son famosas por la exhibición de toros cerriles de prestigiosas ganaderías nacionales en el evento de Sant Roc, atrayendo gran afluencia de aficionados provinciales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46178','fiesta','Fiestas Patronales de la Virgen de la Encarnación y San Francisco de Asís','Patronal, Romería y Tradicional. Se celebra en Octubre y Agosto. Celebración del Camp de Túria con notable concurrencia de veraneantes por el turismo de la Sierra Calderona, caracterizada por pasacalles de su banda musical, la romería a la ermita de San Francisco y tradicionales verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46179','fiesta','Fiestas Patronales en honor a San Antón Abad y la Virgen del Remedio','Patronal, Etnográfica y Romería. Se celebra en Enero y Octubre. Festejos de la Canal de Navarrés que destacan por la pureza de sus ritos invernales con el encendido de la gran hoguera municipal, el reparto de los panes bendecidos y tradicionales desfiles folclóricos de trajes payeses.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46180','fiesta','Fiestas Patronales en honor a la Virgen del Rosario','Patronal y Tradicional. Se celebra en Agosto. Celebración vecinal de baja escala demográfica integrada en la comarca de la Costera, estructurada en torno a comidas comunitarias de sobaquillo, procesiones litúrgicas tradicionales y pequeñas orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46181','fiesta','Fiestas de Moros y Cristianos en honor a la Virgen del Rebollet','Moros y Cristianos, Patronal y Marinera. Se celebra en Julio y Septiembre. Hito etnográfico masivo a nivel regional; sus monumentales desfiles de Moros y Cristianos ostentan un gran renombre por la vistosidad de sus boatos, la espectacular Entrada por el centro histórico y las batallas de pólvora en la playa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46182','fiesta','Fiestas Patronales en honor a la Virgen del Rosario y San Roque','Patronal, Romería e Histórica. Se celebra en Agosto y Octubre. De arraigo comarcal en el Camp de Túria; se dinamiza en torno a su patrimonio arqueológico e íbero, combinando tradicionales verbenas, misas solemnes, pasacalles musicales con charangas y cenas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46185','fiesta','Fiestas Patronales en honor a la Virgen de los Dolores y San Roque','Patronal, Cultural y Tradicional. Se celebra en Agosto. Festejos tradicionales de baja escala en la Vall d''Albaida, dinamizados turísticamente por su singular ruta urbana de relojes de sol, estructurando cenas vecinales en las plazas de la villa y pasacalles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46186','fiesta','Fiestas Patronales en honor a San Roque y la Fiesta del Perro','Patronal, Tradicional y Pirotécnica. Se celebra en Agosto. De relieve comarcal en l''Horta Sud; destaca por su tradicional y curiosa Fiesta del Perro del día posterior a San Roque, grandes castillos de fuegos artificiales, pasacalles con bandas de música locales y masivos conciertos gratuitos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46187','fiesta','Fiestas Patronales en honor a San Miguel Arcángel','Patronal y Tradicional. Se celebra en Agosto. Celebración de arraigo local en la Safor que destaca por congregar a la comunidad vecinal en torno a pasacalles con bandas de música tradicionales, procesiones litúrgicas, comidas comunitarias de paellas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46188','fiesta','Fiestas Patronales en honor a la Purísima Concepción y la Virgen del Carmen','Patronal y Tradicional. Se celebra en Junio. Festejos estrictamente locales condicionados por la reducida población del municipio en la huerta de la Safor, basados en misas solemnes, pasacalles matutinos con dolçaina, parques infantiles y pequeñas verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46189','fiesta','Fiestas de Moros y Cristianos en honor a San Pedro y la Virgen de los Desamparados','Moros y Cristianos y Patronal. Se celebra en Agosto. Celebración tradicional de rango vecinal en la Vall d''Albaida, caracterizada por sus desfiles locales de comparsas moras y cristianas, pasacalles con la banda municipal de la villa y tradicionales cenas al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46190','fiesta','Fiestas Mayores en honor al Santísimo Cristo de la Fe y San Vicente Ferrer, y la Cordà de Paterna','Etnográfica, Pirotécnica, Patronal y de Concurrencia de Masas. Se celebra en Agosto (Último domingo). Su espectacular Cordà de Paterna ostenta la declaración de Fiesta de Interés Turístico Internacional, erigiéndose en la máxima expresión de la cultura del fuego valenciana donde en pocos minutos se queman decenas de miles de cohetes de forma extrema en la calle mayor blindada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46191','fiesta','Fiestas Patronales en honor a San Antón Abad y la Virgen de la Sapiencia','Patronal, Taurina y Tradicional. Se celebra en Enero y Agosto. Atractivo comarcal en la comarca de la Serranía; destaca por la pervivencia de sus encierros tradicionales de vaquillas de corro por el casco antiguo a orillas del río Turia, complementando los festejos litúrgicos invernales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46192','fiesta','Fiestas Patronales en honor a San Jaime Apóstol y la Virgen de la Flor','Patronal y Tradicional. Se celebra en Agosto. Celebración marcadamente vecinal en el Camp de Morvedre, vertebrada por las misas solemnes en la iglesia parroquial, campeonatos de pelota valenciana, cenas colectivas de sobaquillo y orquestas de pequeño formato.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46193','fiesta','Fiestas Patronales en honor al Ecce Homo y a la Virgen del de los Dolores','Patronal, Pirotécnica y Tradicional. Se celebra en Julio. Festejos de área metropolitana caracterizados por los conciertos de bandas, desfiles humorísticos de carrozas peñistas, procesiones religiosas tradicionales con bailes de gigantes y grandes espectáculos de pólvora.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46194','fiesta','Fiestas Patronales de la Virgen de la Vallivana y el Cant de la Carxofa','Etnográfica, Patronal, Musical y Pirotécnica. Se celebra en Septiembre. De notable relevancia comarcal y provincial en l''Horta Sud gracias a su antiquísima tradición del Cant de la Carxofa de la procesión de la Virgen, interpretado por un niño desde el interior de un artefacto colgante tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46195','fiesta','Fiestas Patronales en honor a Santa Bárbara y la Virgen del Carmen','Patronal, Marinera y de Reencuentro Turístico. Se celebra en Mayo y Agosto. Festejos de la comarca de la Safor que combinan las tradicionales misas de clavarios con encierros de vaquillas de corro callejeros, conciertos multitudinarios de orquestas y actividades lúdicas en su playa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46196','fiesta','Fiestas Patronales en honor a la Virgen del Rosario','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo estrictamente local condicionados por la bajísima demografía del municipio en el interior de la Vall d''Albaida, basadas en cenas vecinales de sobaquillo, procesiones claustrales y bailes familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46198','fiesta','Festes de Sant Blai (Porrat de Sant Blai) y Fiestas Patronales','Etnográfica, Feria Tradicional, Gastronómica y Patronal. Se celebra en Febrero y Agosto. Su histórico Porrat de Sant Blai cuenta con la declaración de Fiesta de Interés Turístico Provincial, constituyendo un hito etnográfico en la Safor que atrae a miles de visitantes para cumplir con el rito tradicional de pasar la reliquia del santo por la garganta, comprar dulces artesanales y disfrutar de muestras folclóricas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46201','fiesta','Fiestas Patronales en honor a San Miguel Arcángel','Patronal y Tradicional. Se celebra en Agosto. Celebración condicionada por su baja densidad demográfica en el Rincón de Ademuz, fundamentada en un ambiente estrictamente vecinal con comidas de hermandad al aire libre, campeonatos de cartas tradicionales y pequeñas verbenas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90053','fiesta','Fiestas Patronales de la Virgen al Pie de la Cruz','Patronal, Taurina y Pirotécnica. Se celebra en Septiembre. De notable relevancia comarcal en L''Horta Nord; destaca por la gran participación ciudadana en la tradicional procesión de los bajados de la Virgen, combinada con una multitudinaria agenda taurina de bous al carrer y espectaculares exhibiciones de fuegos artificiales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46204','fiesta','Fiestas Patronales de la Virgen del Puig (Festa de Sant Pere)','Histórica, Etnográfica, Patronal y Gastronómica. Se celebra en Septiembre y Enero. Gran relieve e historicidad provincial vinculada al Real Monasterio; en septiembre destacan los solemnes actos litúrgicos, desfiles de bandas locales y orquestas, y en enero gana relieve por la tradicional cocción y reparto masivo de las ollas de Sant Pere.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46102','fiesta','Fiestas Patronales a la Virgen de la Luz y Moros y Cristianos','Moros y Cristianos, Patronal y Pirotécnica. Se celebra en Septiembre. Festejos de gran concurrencia en el área metropolitana, caracterizados por la espectacularidad de sus suntuosos desfiles de las huestes moras y cristianas, la tradicional Passejà de San Onofre y los monumentales disparos pirotécnicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46103','fiesta','Fiestas Patronales en honor a la Virgen de los Ángeles','Patronal, Taurina y Tradicional. Se celebra en Julio. Celebración de la comarca de les Valls, vertebrada por la suelta de reses bravas en sus plazas, parques infantiles, pasacalles de la unión musical local y tradicionales noches de cenas comunitarias al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46207','fiesta','Fiestas Patronales de la Virgen del Milagro y de los Santos de la Piedra','Patronal, de Concurrencia de Masas y Pirotécnica. Se celebra en Septiembre. Relevancia comarcal y provincial muy alta por su célebre noche de la Fiesta de Disfraces, que congrega a decenas de miles de jóvenes de toda la provincia colapsando de forma pacífica las calles del casco urbano, acompañada de grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46208','fiesta','Fiestas Patronales en honor a San Antonio de Padua y la Virgen del Carmen','Patronal y Tradicional. Se celebra en Julio. Festividades de arraigo local en la Safor que reúnen a la comunidad en torno a pasacalles musicales, desfiles lúdicos infantiles, tradicionales cenas de sobaquillo en las calles de la villa y solemnes actos litúrgicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46209','fiesta','Fiestas Patronales del Santísimo Cristo de la Salud','Patronal y Tradicional. Se celebra en Agosto. Celebraciones tradicionales orientadas al reencuentro estival en la Ribera Alta, dinamizadas por pasacalles, campeonatos de truc, verbenas populares nocturnas en su núcleo principal y en las pedanías de Berfull y Tossalnou.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46212','fiesta','Fiestas Patronales en honor a la Virgen del Rosario','Patronal y Tradicional. Se celebra en Julio. Festejos vecinales en la Ribera Alta a orillas del río Magro, basados en tradicionales cenas de sobaquillo entre los vecinos de la población, pasacalles acompañados por la banda local y orquestas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46211','fiesta','Fiestas Patronales de San Vicente Ferrer y la Virgen del Rosario','Patronal y Tradicional. Se celebra en Agosto. Celebración de la Safor integrada en el entorno de la capital de comarca, caracterizada por desfiles humorísticos de disfraces, procesiones solemnes, campeonatos de pelota valenciana tradicional y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46213','fiesta','Fiesta de la Vendimia de Requena','Enológica, Gastronómica, Histórica y Masiva. Se celebra en Agosto y Septiembre. La Fiesta de la Vendimia de Requena, una de las más antiguas de España, ostenta la declaración de Fiesta de Interés Turístico Nacional, constituyendo un hito masivo regional que ensalza el sector vitivinícola de la D.O. Utiel-Requena con la mítica Noche de la Zurra, pisadas de uva y la proclamación de la reina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46214','fiesta','Fiestas de la Asunción de la Virgen y Fiesta de la Ofrenda al río Turia','Patronal, Conmemorativa, Pirotécnica y Tradicional. Se celebra en Agosto. De notable relevancia en el Camp de Túria; destaca por la singularidad de los actos que rinden tributo ecológico e histórico al río Turia, complementados con desfiles de moros y cristianos de carácter local, grandes cordàs y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46215','fiesta','Fiestas Patronales de Santa María y San Roque','Patronal y Tradicional. Se celebra en Agosto. Celebración de arraigo local en la Ribera Baixa que destaca por congregar a los vecinos en torno al río Júcar con competiciones populares acuáticas, cenas comunitarias y pasacalles musicales con bandas de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46216','fiesta','Fiestas Patronales en honor a la Virgen del Rosario y San Agustín','Patronal, Musical y Pirotécnica. Se celebra en Agosto y Septiembre. Celebración de perfil vecinal en L''Horta Nord que destaca por sus conciertos nocturnos al aire libre, pasacalles tradicionales de cabezudos, procesiones litúrgicas solemnes y desfiles infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46217','fiesta','Fiestas Patronales de la Virgen del Socorro y Santiago Apóstol','Patronal y Tradicional. Se celebra en Septiembre. Festejos de escala vecinal e íntima en la Costera, estructurados en torno a misas solemnes, comidas comunitarias de hermandad en las plazas de la población y pequeñas orquestas populares de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46218','fiesta','Fiestas Patronales en honor a San Bartolomé y la Virgen de la Salud','Patronal y Tradicional. Se celebra en Septiembre. Celebración tranquila en la Safor vinculada a su entorno natural y patrimonial, reforzada por espectáculos populares de variedades, pasacalles de la charanga local, cenas colectivas y solemnes procesiones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46219','fiesta','Fiestas Patronales en honor a la Virgen de la Gracia','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo estrictamente local adaptadas a la reducida demografía de este núcleo de la Vall d''Albaida, basadas en tradicionales cenas de sobaquillo entre las familias estivales y pequeñas orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45013','fiesta','Fiestas Patronales en honor a los Santos Mártires (San Abdón y San Senén) y las Fallas de Sagunto','Patronal, Histórica, Taurina y Concurrencia de Masas. Se celebra en Julio y Marzo *. Gran empaque provincial y regional; sus fiestas patronales destacan por la intensidad de sus encierros y exhibiciones taurinas de bous al carrer en el recinto histórico medieval de la judería y puerto, complementadas por las multitudinarias fallas del Camp de Morvedre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46903','fiesta','Fiestas Patronales de San Antonio de Padua','Patronal, Pirotécnica y Tradicional. Se celebra en Junio. Celebración en el área metropolitana de Valencia caracterizada por la activa participación de sus peñas, la organización de espectáculos pirotécnicos urbanos, concursos de paellas multitudinarios y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46223','fiesta','Fiestas Patronales de la Virgen del Rosario y Moros y Cristianos','Moros y Cristianos, Patronal y Musical. Se celebra en Septiembre. De relieve comarcal en L''Horta Sud; destaca por sus coloridas entradas y desfiles de las huestes moras y cristianas, pasacalles, conciertos gratuitos de formato mediano y tradicionales verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46224','fiesta','Fiestas Patronales en honor a la Virgen del de la Escaleta','Patronal y Tradicional. Se celebra en Agosto. Festejos de escala estrictamente local a los pies del Garbí en la Sierra Calderona, con cenas populares de sobaquillo, misas tradicionales con cantos autóctonos y orquestas de pequeño formato.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46225','fiesta','Fiestas Patronales en honor a la Inmaculada Concepción y San Roque','Patronal y Tradicional. Se celebra en Agosto. Celebración tranquila de perfil vecinal en la Ribera Alta, dinamizada por parques infantiles, pasacalles con bandas locales y cenas compartidas en la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46226','fiesta','Fiestas Patronales en honor a San Pedro Apóstol','Patronal y Tradicional. Se celebra en Agosto. Festividades de arraigo estrictamente local adaptadas a la bajísima demografía de este núcleo de la Vall d''Albaida a orillas del embalse de Bellús, basadas en comidas de hermandad y verbenas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46227','fiesta','Fiestas Patronales de la Virgen de la Asunción y el Santísimo Cristo de la Buena Dicha','Patronal y Tradicional. Se celebra en Agosto. Festejos tradicionales de marcado arraigo local en el Valle de Cárcer, caracterizados por tradicionales desfiles de disfraces, procesiones religiosas solemnes y cenas multitudinarias en la calle.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46228','fiesta','Fiestas Patronales en honor a San José y la Virgen de los Ángeles','Patronal, Romería y Tradicional. Se celebra en Agosto. Atractivo comarcal en el corazón de la Sierra Calderona, muy concurrido por el turismo de montaña, fundamentado en procesiones solemnes, tradicionales bajadas de antorchas y verbenas en el núcleo urbano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46229','fiesta','Fiestas Patronales de San Juan Bautista y Fiestas del Cristo de los Afligidos','Patronal, Taurina y Tradicional. Se celebra en Junio y Agosto. De relieve comarcal en la Hoya de Buñol, muy concurrida en verano por el reencuentro de descendientes; destaca por sus jornadas de bous al carrer, encierros de vaquillas de la tierra y verbenas de ambiente familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46230','fiesta','Fiestas Patronales en honor al Santísimo Cristo de la Sangre y el Danza dels Porrots','Etnográfica, Patronal, Marinera y Pirotécnica. Se celebra en Agosto. Hito etnográfico provincial de altísima consideración debido a la ancestral Dança dels Porrots, baile guerrero de origen milenario ejecutado por los jóvenes de la villa al ritmo de golpes tradicionales. Se complementa con las romerías de barcas por la Albufera y grandes cordàs.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46231','fiesta','Fiestas Patronales en honor a los Santos de la Piedra y la Virgen de Gracia','Patronal, Histórica y Tradicional. Se celebra en Agosto. De relevancia comarcal respaldada por el marco monumental del Real Monasterio de Santa María de la Valldigna; combina las procesiones solemnes con pasacalles de música tradicional, competiciones de pelota valenciana y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46232','fiesta','Fiestas Patronales de Santiago Apóstol y San Marcos Evangelista','Patronal, Romería y Tradicional. Se celebra en Agosto y Abril. Festejos de arraigo local en la frontera con Cuenca, caracterizados por la romería tradicional a la ermita de San Marcos con bendición de rollos artesanales, desfiles de bandas locales y orquestas de fin de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46233','fiesta','Fiestas Patronales del Santísimo Cristo de la Piedad','Patronal, Taurina y Pirotécnica. Se celebra en Agosto. De relieve comarcal en la Ribera Baixa; destaca por la gran participación de peñas en el entorno de la Albufera, sus encierros tradicionales de vaquillas de corro, concursos de paellas comunitarias y espectaculares disparos de pólvora.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46234','fiesta','Fiestas Patronales de la Virgen de los Dolores y San Sebastián','Patronal y Tradicional. Se celebra en Agosto y Enero. Fiestas tradicionales de perfil familiar y geológico en Los Serranos, vertebradas en verano por actividades fluviales en el charco gruñidor del río Sot, pasacalles de la charanga local, cenas de sobaquillo y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46235','fiesta','Concurso Internacional de Paella Valenciana de Sueca y Fiestas de la Virgen de Sales','Gastronómica, Histórica, Patronal y Concurrencia de Masas. Se celebra en Septiembre. Su histórico Concurso Internacional de Paella Valenciana de Sueca ostenta la declaración de Fiesta de Interés Turístico Nacional, erigiéndose en un hito culinario masivo global que reúne a cocineros de todo el mundo en la "capital del arroz", complementado por suntuosas procesiones de la patrona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46236','fiesta','Fiestas Patronales del Santísimo Cristo de la Salud','Patronal, Fluvial y Tradicional. Se celebra en Septiembre. Celebración de arraigo local en el Valle de Cárcer que en verano se dinamiza turísticamente en torno al río Júcar con descensos populares de barcas, competiciones acuáticas, complementando las solemnes procesiones del Cristo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46238','fiesta','Fiestas Patronales en honor al Santísimo Cristo de la Sangre y la Virgen de Valldigna','Patronal, Taurina, Pirotécnica y de Concurrencia de Masas. Se celebra en Septiembre. Relevancia comarcal y provincial muy alta en la Safor; destaca por la suntuosidad de sus tradicionales entradas de toros, las grandes tracas que recorren el casco histórico, festivales musicales y masivas orquestas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46237','fiesta','Fiestas Patronales de la Virgen de los Desamparados','Patronal, Pirotécnica y Tradicional. Se celebra en Agosto. Festejos de área metropolitana marcados por su tradición de pólvora, la celebración de procesiones religiosas, pasacalles acompañados por la banda local, cenas comunitarias y orquestas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46239','fiesta','Fiestas Patronales en honor a la Virgen de la Asunción','Patronal y Tradicional. Se celebra en Agosto. Celebración vecinal de baja escala demográfica en el Valle de Ayora, estructurada en torno a comidas comunitarias de sobaquillo, procesiones religiosas tradicionales y orquestas populares de formato reducido.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46240','fiesta','Fiestas Patronales en honor a San Vicente Ferrer y la Virgen del Rosario','Patronal y Tradicional. Se celebra en Abril (Pascua de San Vicente). Festejos estrictamente locales condicionados por la baja población del municipio en el interior de la Vall d''Albaida, basados en misas solemnes, pasacalles con charangas y pequeñas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46241','fiesta','Fiestas Patronales de la Virgen del Remedio y la Fiesta de la Mojiganga','Etnográfica, Patronal y Danzas Ancestrales. Se celebra en Septiembre (Cada siete años las mayores) y Agosto (Anuales). Hito etnográfico provincial de extraordinario valor patrimonial por La Mojiganga de Titaguas, una danza ritual de torres humanas y mudanzas plásticas de origen medieval ejecutada al son de la dulzaina, que congrega a investigadores y folcloristas de toda la región.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46242','fiesta','Fiestas Patronales en honor a San Diego de Alcalá y Santa Marina','Patronal y Tradicional. Se celebra en Agosto y Noviembre. Celebración de arraigo local en el Rincón de Ademuz, condicionada por su demografía, vertebrada por verbenas de retorno estival, comidas de hermandad en la plaza pública y solemnes procesiones religiosas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45014','fiesta','Fiestas Patronales de San Abdón y San Senén (Moros y Cristianos) y Semana Santa','Moros y Cristianos, Religiosa, Pirotécnica y Masiva. Se celebra en Julio y Marzo/Abril. Gran empaque provincial y regional; su Semana Santa ostenta la declaración de Interés Turístico Autonómico destacando la figura única de la Reina de la Encuentro, complementada en verano por sus suntuosos, masivos y ensordecedores desfiles de Moros y Cristianos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46245','fiesta','Fiestas Patronales en honor a la Virgen de la Leche','Patronal y Tradicional. Se celebra en Septiembre. Festejos de escala vecinal en la comarca del Camp de Morvedre, articulados en torno a comidas comunitarias de paellas, pasacalles con la banda local, parques infantiles y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46246','fiesta','Fiestas Patronales en honor a San Miguel Arcángel y el Santísimo Cristo de la Salud','Patronal, Conmemorativa y Tradicional. Se celebra en Septiembre. Celebración en la Ribera Alta que salvaguarda la identidad histórica y memoria del antiguo pueblo inundado por la presa, caracterizada por verbenas populares, la tradicional entrà y procesiones solemnes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46247','fiesta','Fiestas de las Gordas en honor a la Virgen de la Purísima Concepción','Etnográfica, Recreación Histórica y Patronal. Se celebra en Agosto (Cada cinco años). Relevancia comarcal y etnográfica muy alta en Los Serranos debido a sus fiestas quinquenales, célebres por la representación del Entremés de la Roda, un auto sacramental tradicional con espectaculidad de textos antiguos y batallas simuladas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46248','fiesta','Fiestas Patronales de la Virgen de los Dolores y las Fallas de Turís','Patronal, Taurina y Fallera. Se celebra en Agosto y Marzo (Celebración tardía de las Fallas). Atractivo comarcal en la Ribera Alta; destaca por celebrar sus monumentos falleros una semana después de la capital valenciana atrayendo gran público provincial, unido a sus intensos encierros de bous al carrer.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46249','fiesta','Fiestas de la Virgen de la Remedio y Feria Utiel Gastronómica','Patronal, Feria Gastronómica y Enológica. Se celebra en Septiembre y Octubre. Hito regional vinculado a la Denominación de Origen Utiel-Requena; destaca la suntuosa Bajada de la Virgen en romería nocturna iluminada por miles de velas, sumada a su consolidada feria agroalimentaria de promoción del vino de la variedad Bobal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','fiesta','Las Fallas de Valencia y la Festividad de San Vicente Ferrer','Impacto Masivo Global, Pirotécnica y Tradicional. Se celebra en Marzo y Abril. Las Fallas están declaradas Patrimonio Cultural Inmaterial de la Humanidad por la UNESCO, erigiéndose en un hito festivo global de máxima puntuación por sus monumentos satíricos, masivas mascletás, la Ofrenda de Flores y la Cremà.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46251','fiesta','Fiestas Patronales de San Bartolomé y el Santísimo Cristo del Monte Calvario','Patronal y Taurina. Se celebra en Agosto. Festejos de relevancia comarcal en la Costera, famosos por la intensidad de su semana de exhibiciones de toros cerriles callejeros, orquestas multitudinarias en la plaza y desfiles informales de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46252','fiesta','Fiestas de la Virgen de Santerón y San Roque','Etnográfica, Romería Histórica y Patronal. Se celebra en Septiembre (Cada siete años la Bajada mayor) y Agosto (Anuales). Alto valor etnográfico en el Rincón de Ademuz debido a la romería de la Bajada de la Virgen de Santerón desde su ermita fronteriza con Cuenca, acompañada por el ancestral canto de los Mayos y bailes folclóricos de pastores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46253','fiesta','Fiestas Patronales en honor a San Juan Bautista','Patronal y Tradicional. Se celebra en Junio. Celebración estrictamente vecinal condicionada por ser el municipio de menor demografía de la comarca de la Costera, basada en tradicionales cenas al aire libre, parques infantiles y pequeñas verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46254','fiesta','Fiestas de la Virgen de Loreto y el Canto de los Mayos','Patronal, Enológica y Musical Tradicional. Se celebra en Diciembre y Agosto. Celebración de la comarca Requena-Utiel vinculada a la cultura vitivinícola, que adquiere singularidad etnográfica por el mantenimiento del canto nocturno de los Mayos en la víspera del uno de mayo ante el templo parroquial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90873','fiesta','Fiestas Patronales de Santa Catalina y el Santísimo Cristo de la Salud','Patronal, Taurina y Tradicional. Se celebra en Agosto. De notable relevancia en el Camp de Túria; destaca por sus concurridos festejos taurinos callejeros, pasacalles de la corporación musical local, competiciones de pelota valenciana y grandes noches de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46255','fiesta','Festes de la Mare de Déu de la Font','Patronal, Etnográfica y Pirotécnica. Se celebra en Agosto. Atractivo comarcal en la Safor que conmemora el hallazgo milagroso de la patrona flotando sobre las aguas del río Serpis, estructurado con un vistoso desfile procesional, cordàs tradicionales y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46258','fiesta','Carnaval de Villar del Arzobispo y Fiestas Patronales de la Virgen de la Paz','Carnaval Etnográfico y Patronal. Se celebra en Febrero y Agosto. Su Carnaval goza de gran relieve comarcal e histórico por conservar ritos singulares como el desfile de las botargas, la tradicional quema del Chinchoso y el masivo reparto de ceniza tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46259','fiesta','Fiestas Patronales en honor a San Roque','Patronal y Tradicional. Se celebra en Agosto. Festejos veraniegos que se dinamizan por el turismo interior del Parque Natural de las Hoces del Cabriel, centrados en verbenas de fin de semana, concursos de paellas comunitarias y pasacalles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46260','fiesta','Fiestas Patronales de San Honorato y San Vicente Ferrer','Patronal, Gastronómica y Tradicional. Se celebra en Octubre. Celebración de arraigo huertano en L''Horta Nord, popularmente concurrida por su tradicional Festa de las Calderas, donde se cocinan masivamente peroles de arroz con alubias y nabo para toda la población.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46261','fiesta','Fiestas Patronales en honor a la Virgen del Rosario','Patronal, Musical y Taurina. Se celebra en Agosto. Celebración tradicional en la Hoya de Buñol, caracterizada por los intensos conciertos de su sociedad musical, pasacalles tradicionales, jornadas de suelta de reses bravas y cenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46262','fiesta','Fiestas Patronales en honor a Nuestra Señora del de los Ángeles','Patronal y Tradicional. Se celebra en Agosto. Festejos rurales de montaña marcados por la reducida población estable de la comarca de Los Serranos, basados en verbenas familiares estivales, campeonatos de truc y procesiones tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46263','fiesta','Fiestas Patronales en honor a Santa Ana','Patronal y Tradicional. Se celebra en Julio *. Festividades de arraigo estrictamente local adaptadas a la baja demografía del municipio en el Valle de Ayora, estructuradas con cenas vecinales de sobaquillo, procesiones claustrales y pequeños bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22049','fiesta','Fiestas de San Pedro de Verona','Patronal. Se celebra en Mayo. Celebración de ámbito estrictamente local en los Monegros orientales, centrada en ritos religiosos tradicionales y orquesta municipal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22055','fiesta','Fiestas de San Gregorio','Patronal. Se celebra en Mayo. Festejos de primavera con procesión tradicional a la peña del santo y actos populares bien respaldados por el vecindario comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22115','fiesta','Certamen de la Faba de Grado y Fiestas de Santa Ana','Gastronómica / Patronal. Se celebra en Julio (Fiestas) y Septiembre (Certamen). Festejos de amplio arraigo comarcal, muy populares por su tradicional mercado de origen medieval y la promoción comercial y gastronómica de la faba asturiana regulada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22193','fiesta','Fiestas de la Invención de la Santa Cruz','Patronal. Se celebra en Mayo. Pequeña festividad vecinal a orillas del río Cinca, con procesión tradicional, juegos para niños y sesiones de orquesta locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22217','fiesta','Fiestas del Santo Ángel Custodio','Patronal / Etnográfica. Se celebra en Octubre. Festejos que destacan por la magnífica conservación de su Dance de Sena, una representación folclórica con mudanzas de palos y dichos de gran arraigo comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22218','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Festejos tradicionales de marcado carácter veraniego y familiar en una localidad de baja demografía en Los Monegros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22230','fiesta','Fiestas de San Salvador','Patronal / Etnográfica. Se celebra en Agosto. Festejos en la entrada del Parque Nacional de Ordesa que destacan etnográficamente por el "Repatán" y las danzas tradicionales torlanas ejecutadas con trajes antiguos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22248','fiesta','Fiestas de San Miguel','Patronal. Se celebra en Septiembre. Festejos locales del llano oscense con reparto de tortas bendecidas, sesiones de baile para el vecindario y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90284','fiesta','Fiestas de San Agustín','Patronal. Se celebra en Agosto. Festejos estivales tradicionales en la comarca de Gúdar-Javalambre, sustentados en comidas populares y actividades infantiles para el retorno veraniego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90285','fiesta','Fiestas de la Virgen del Castillo','Patronal / Romería. Se celebra en Septiembre. Pequeña festividad vecinal en la comarca del Jiloca, centrada en la procesión tradicional a la ermita y una jornada de convivencia local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90286','fiesta','Fiesta del Santísimo Misterio','Etnográfica / Religiosa. Se celebra en Agosto. Declarada Fiesta de Interés Turístico de Aragón. Destaca a nivel autonómico por sus espectaculares alfombras de serrín teñido que tapizan las calles del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90287','fiesta','Fiestas de San Pedro San Pablo y Santa Ana','Patronal. Se celebra en Julio. Festejos patronales tradicionales de la comarca de la Comunidad de Teruel, con campeonatos de naipes, misas y orquestas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14001','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre. Celebraciones locales en AndorraSierra de Arcos, estructuradas en torno a verbenas en la plaza, pasacalles y tradicionales ritos religiosos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90288','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Pequeñas fiestas de verano de carácter estrictamente familiar y vecinal en el valle del Jiloca, enfocadas en comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90874','fiesta','Fiestas de la Virgen de la Vega','Patronal / Etnográfica. Se celebra en Septiembre. Destacan en la provincia por sus históricas representaciones de "Moros y Cristianos" y el tradicional dance de palos con dichos al estilo turolense.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44018','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre. Celebración puramente local y de carácter otoñal, fundamentada en misas tradicionales y una pequeña sesión de baile para el vecindario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44019','fiesta','Fiestas de los Santos Fabián y Sebastián','Patronal. Se celebra en Agosto. Festejos estivales de carácter familiar en la Sierra de Albarracín, centrados en bailes públicos y campeonatos de juegos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44032','fiesta','Fiestas de San Nicolás de Bari','Patronal. Se celebra en Agosto. Festejos rurales mínimos en un municipio de muy baja demografía en el Jiloca, limitados a ritos religiosos y cena comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44056','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Festejos del Jiloca que cuentan con desfiles populares, alta participación de peñas y actividades lúdicas muy concurridas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44059','fiesta','Fiestas de la Virgen del Loreto','Patronal / Taurina. Se celebra en Agosto. Festejos mayores de gran relevancia en el Maestrazgo turolense, caracterizados por sus tradicionales exhibiciones taurinas de toros embolados y cerriles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44125','fiesta','Fiestas de San Miguel','Patronal. Se celebra en Agosto. Celebración veraniega a la sombra de su castillo medieval, con actividades recreativas, campeonatos de naipes y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44230','fiesta','Fiestas de San Joaquín y Santa Ana','Patronal. Se celebra en Agosto. Festejos de arraigo en el Bajo Aragón que destacan por sus tradicionales pasacalles, campeonatos de guiñote y cenas populares en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44236','fiesta','Fiestas de la Virgen del Tremedal','Patronal / Gastronómica. Se celebra en Septiembre. Festejos de fuerte arraigo en el Maestrazgo que ponen en valor sus dances tradicionales, rondas joteras y la degustación de su célebre queso artesanal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44237','fiesta','Semana Santa de Urrea de Gaén','Religiosa / Etnográfica. Se celebra en Marzo / Abril. Como parte inseparable de la Ruta del Tambor y el Bombo, cuenta con la declaración de Fiesta de Interés Turístico Internacional de forma agrupada, atrayendo masivo turismo regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44238','fiesta','Fiestas en Honor a la Natividad de Nuestra Señora','Patronal / Cultural. Se celebra en Septiembre. Grandes fiestas mayores de la capital de las Cuencas Mineras, con un potente recinto de peñas, desfiles de carrozas, grandes conciertos y espectáculos taurinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44249','fiesta','Fiestas de la Santísima Trinidad','Patronal. Se celebra en Junio. Pequeñas fiestas rurales de baja densidad demográfica en la Sierra de Albarracín, centradas en la convivencia vecinal y ritos litúrgicos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44262','fiesta','Fiestas de la Virgen del Loreto','Patronal / Etnográfica. Se celebra en Agosto. Festejos del Maestrazgo con tradicionales rondas, procesión a la ermita de la virgen y actividades culturales que dinamizan su conjunto histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90130','fiesta','Fiestas de la Virgen del Rosario','Patronal / Enológica. Se celebra en Septiembre. Festejos tradicionales muy ligados a la vendimia de la D.O.P. Cariñena, caracterizados por el reparto de vino local de las bodegas, tradicionales rondas joteras y gran participación vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90153','fiesta','Fiestas del Santísimo Misterio','Patronal / Religiosa. Se celebra en Septiembre. Festividad de fuerte arraigo litúrgico y de tradición milagrosa en la Comunidad de Calatayud, con solemnes procesiones al templo mudéjar, canto de albadas y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50106','fiesta','Fiestas de San Bernabé','Patronal. Se celebra en Junio. Festejos locales al abrigo de sus cuevas mitológicas, con procesión tradicional al santo, actividades de hermandad vecinal y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50110','fiesta','Fiestas de la Virgen de la Peña','Patronal. Se celebra en Agosto. Festejos de retorno estival en la Sierra de Algairén, caracterizados por pasacalles, tradicionales misas y verbenas públicas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50116','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Septiembre. Celebración de escala estrictamente local en la cuenca del Jiloca, basada en ritos litúrgicos tradicionales y comidas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50128','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Pequeños festejos rurales en la comarca de las Cinco Villas, centrados en el reencuentro estival de familias, comidas comunitarias y música local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50149','fiesta','Fiestas de San Cristóbal','Patronal. Se celebra en Agosto. Pequeña festividad vecinal de baja demografía en el Campo de Daroca, centrada en el reencuentro de veraneantes con actos litúrgicos mínimos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50150','fiesta','Fiestas de San Francisco de Asís y San Roque','Patronal / Taurina. Se celebra en Agosto y Octubre. Festejos de arraigo local en Valdejalón, destacados por sus encierros, tradicionales comidas en las bodegas y música nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50170','fiesta','Fiestas de la Virgen del Rosario','Patronal / Etnográfica. Se celebra en Julio. Festejos tradicionales en el desierto monegrino que conservan rondas de jotas, encendido de hogueras y cenas populares de hermandad en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50171','fiesta','Fiestas en Honor a San Fausto','Patronal. Se celebra en Agosto. Celebración de carácter familiar y estival junto al embalse homónimo, orientada al reencuentro vecinal con orquestas y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50172','fiesta','Fiestas de San Pedro y San Pablo','Patronal. Se celebra en Agosto. Festejos fronterizos trasladados al mes estival para asegurar el reencuentro de familias, con comidas comunitarias y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05005','fiesta','Fiesta de San Antonio de Padua y Fiesta del Pastor en Enol','Patronal / Etnográfica / Romería. Se celebra en Junio y Julio. La Fiesta del Pastor en los Lagos de Covadonga está declarada de Interés Turístico Nacional por sus ancestrales ritos, competiciones de hacheros y la misa en la Vega de Enol.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33032','fiesta','Descanso Ecológico del Nalón / Fiestas de Nuestra Señora del Otero','Etnográfica / Acuática / Patronal. Se celebra en Agosto. Declarada Fiesta de Interés Turístico del Principado de Asturias. Multitudinario desfile acuático y humorístico por el cauce del río Nalón que atrae a miles de jóvenes de toda la región.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33077','fiesta','Fiestas de San Pedro en Oneta','Patronal. Se celebra en Junio. Festejos rurales de arraigo familiar y local junto a su entorno de cascadas naturales, con comidas comunitarias de hermandad y orquesta regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33078','fiesta','Feria del Puerto de Marabio','Feria de Sector / Romería. Se celebra en Octubre. Celebración ganadera tradicional en el puerto de montaña que, pese a la extrema despoblación del concejo, reúne a los pastores de la comarca con ritos tradicionales mínimos). Hemos completado al 100% todos los concejos del Principado de Asturias. ¿Procedemos a abrir la siguiente Comunidad Autónoma según el estricto orden alfabético que corresponde a Canarias (comenzando por la provincia de Las Palmas)?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38039','fiesta','Fiestas Patronales en Honor a Santa Úrsula y la Virgen del Rosario','Patronal / Gastronómica / Romería. Se celebra en Octubre. Festejos de arraigo tradicional en el norte de la isla que coinciden con la apertura de los tradicionales "guachinches" y bodegas locales, sumando una vistosa romería folclórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39021','fiesta','Fiestas de Nuestra Señora del Carmen en Villayuso','Patronal. Se celebra en Julio. Festejos de escala estrictamente local en un municipio rural de baja demografía, con procesión religiosa, pandereteras locales y comidas compartidas entre los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39023','fiesta','Fiestas de San Ginés y la Fiesta de la Salve','Patronal / Marinera. Se celebra en Agosto. Festejos de rango comarcal muy populares en el estuario del Asón, caracterizados por regatas de traineras, degustaciones de bonito, grandes verbenas y juegos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39051','fiesta','Feria del Queso Artesano de Pesquera','Gastronómica / Feria de Sector. Se celebra en Agosto. Hito gastronómico provincial de alta raigambre que congrega a miles de amantes del queso artesanal de Cantabria en este pequeño pueblo montañés.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39091','fiesta','Fiestas de San Antonio en Treceño','Patronal / Romería. Se celebra en Junio. Celebración de arraigo tradicional en las medianías occidentales, caracterizada por la procesión solemne, jotas montañesas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28030','fiesta','Festa Major de Sant Pere','Patronal / Etnográfica. Se celebra en Junio. Festejos de notable arraigo en la comarca del Baix Llobregat, caracterizados por el tradicional pasacalles de gegants, correfocs a cargo de las colles locales y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90875','fiesta','Festa Major de Sant Andreu','Patronal. Se celebra en Noviembre. Celebración de escala estrictamente local en un municipio de muy baja demografía en la Alta Segarra, basada en ritos religiosos tradicionales, teatro local y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90876','fiesta','Festa Major de Sant Joan','Patronal / Romería. Se celebra en Junio. Festejos estivales en los límites del Parque Natural del Montseny, que combinan el encendido de las hogueras de San Juan con la tradicional subida a la ermita y bailes de sardanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08007','fiesta','Festa de la Verema d''Alella y Festa Major de Sant Feliu','Enológica / Gastronómica / Patronal. Se celebra en Agosto (Patronal) y Septiembre (Vendimia). Declarada Fiesta de Interés Turístico. Su Fiesta de la Vendimia es un hito de gran empaque comarcal y regional dedicado a la promoción de los vinos de la D.O. Alella, con pisado popular de uva y ferias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44020','fiesta','Festa Major de San Cosme y San Damián y Fira del Llutonenc','Patronal / Feria Etnográfica. Se celebra en Septiembre (Fiestas) y Mayo (Fira). Festejos tradicionales en la comarca del Lluçanès que ponen en valor su singular patrimonio de forja artística mediante demostraciones en vivo, mercados artesanos y bailes folclóricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90877','fiesta','Festa Major de Sant Genís','Patronal / Etnográfica. Se celebra en Agosto. Festejos tradicionales de retorno veraniego, caracterizados por el pasacalles de la colla de gegants, el baile de bastoners y animadas verbenas nocturnas en la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08001','fiesta','Festa de Sant Zenon y Fiestas de San Roque','Patronal / Marinera / Etnográfica. Se celebra en Julio (Sant Zenon) y Agosto (Sant Roc). Festejos de rango comarcal de alta raigambre marinera en el Maresme, célebres por la espectacular cercavila de gegants, el ancestral canto de los Macips que bendicen con agua a los vecinos y correfocs.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90558','fiesta','Festa Major de Sant Martí','Patronal / Gastronómica. Se celebra en Noviembre. Festejos de fuerte arraigo en el interior del Maresme, destacados por la tradicional muestra gastronómica del Relleno —manzana rellena de carne típica de la festividad—, bailes de sardanas y pasacalles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90559','fiesta','Festa Major de Sant Llorenç','Patronal. Se celebra en Agosto. Mínimos festejos vecinales en una zona rural de la Anoia marcada por núcleos dispersos, limitados a actos litúrgicos tradicionales, una comida de hermandad y música de orquesta pequeña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90878','fiesta','Festa Major de L''Arboç','Patronal / Etnográfica. Se celebra en Agosto. Declarada Fiesta de Interés Turístico Nacional de Cataluña. Hito folclórico monumental famoso por la espectacularidad de su L''Carretillada del Ball de Diables y el altísimo nivel técnico de sus castells.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90879','fiesta','Festa Major d''Artés y Fira de l''Atans','Patronal / Enológica. Se celebra en Septiembre. Festejos de arraigo tradicional en el Bages que combinan pasacalles de cultura popular con la promoción de sus cavas y vinos de la D.O. Pla de Bages mediante catas y ferias urbanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90561','fiesta','Festa del Segar i el Batre y Festa Major de Sant Martí','Etnográfica / Tradicional / Patronal. Se celebra en Julio (Segar) y Noviembre (Patronal). Su fiesta del Segar y el Batre destaca a nivel provincial por la fiel recreación etnográfica de las antiguas labores agrícolas tradicionales de la siega a mano, atrayendo a numeroso público.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90562','fiesta','Festa Major de Sant Joan y Fira dels Matons','Patronal / Gastronómica. Se celebra en Septiembre. Festejos locales que giran en torno a la cultura popular del Bages, con correfocs, cercaviles de gegants y mercados dedicados a la promoción de sus quesos y embutidos artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90563','fiesta','Festa Major de Sant Pere','Patronal / Enológica. Se celebra en Junio. Celebración de marcado ambiente vecinal en el corazón del Penedès, basada en comidas populares bajo los emparrados, pasacalles tradicionales y degustación de vinos y cavas de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90024','fiesta','Festes de Maig (Cremada del Dimoni)','Patronal / Etnográfica / Pirotécnica. Se celebra en Mayo. Declarada Fiesta de Interés Turístico por la Generalitat. Espectacular hito etnográfico masivo donde miles de personas se congregan en la playa para presenciar la quema de una monumental figura de demonio, acompañada de pirotecnia y correfocs.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08904','fiesta','Festa Major de Badia','Cultural / Urbana. Se celebra en Junio. Festejos de ámbito estrictamente local y urbano condicionados por su reciente creación como municipio, fundamentados en conciertos masivos, actividades asociativas y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08002','fiesta','Festes de la Fia-Faia','Etnográfica / Rito del Fuego / Solsticio. Se celebra en Diciembre (Nochebuena). Declarada Fiesta de Interés Turístico Nacional de Cataluña y Patrimonio Inmaterial de la Humanidad por la UNESCO de forma agrupada. Rito ancestral del fuego donde los vecinos descienden de la montaña con antorchas de paja.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90564','fiesta','Festa Major de la Mare de Déu de l''Ajuda','Patronal. Se celebra en Septiembre. Festejos patronales tradicionales de la comarca de Osona centrados en Els Hostalets de Balenyà, con pasacalles de gegants, sardanas y actividades infantiles para el vecindario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90565','fiesta','Festa dels Traginers de Balsareny','Etnográfica / Tradicional / Animal. Se celebra en Febrero. Declarada Fiesta de Interés Turístico Nacional. Histórico e inmenso desfile de caballerías engalanadas que rinde homenaje a los antiguos arrieros, con la bendición de San Antonio, carreras tradicionales de burros y folklore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08252','fiesta','Festa Major de Barberà','Cultural / Metropolitana. Se celebra en Julio. Festejos de rango comarcal muy consolidados en el cinturón barcelonés, caracterizados por un potente programa de conciertos al aire libre, feria de entidades, correfocs y castellers.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','fiesta','Festes de la Mercè','Patronal / Etnográfica / Macrofestival. Se celebra en Septiembre. Declarada Fiesta de Interés Turístico Internacional. Macrofestejo global con un colosal despliegue cultural: el monumental Piromusical de Montjuïc, la gran Cavalcada de la Mercè, el Correfoc de la Via Laietana y exhibiciones de castells históricas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90566','fiesta','Festa Major de Sant Jaume','Patronal / Romería. Se celebra en Julio. Festejos tradicionales en el entorno del Parque Natural del Garraf, destacados por su procesión solemne, encendido de hogueras populares, bailes de diablos locales y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90567','fiesta','Festa Major de Sant Salvador','Patronal. Se celebra en Agosto. Mínima expresión festiva debido a la baja demografía del municipio en los confines de la Anoia, limitada a una misa solemne, campeonatos de cartas vecinales y una pequeña verbena de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08005','fiesta','La Patum de Berga','Etnográfica / Religiosa / Rito del Fuego. Se celebra en Mayo / Junio (Corpus Christi) *. Declarada Obra Maestra del Patrimonio Oral e Inmaterial de la Humanidad por la UNESCO. Máximo hito etnográfico catalán, celebración masiva global única en torno al fuego y las danzas místicas del Àliga, los Plens, los Gegants y los Guites al son del tambor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90568','fiesta','Festa Major de Sant Pere y Sant Vicenç','Patronal. Se celebra en Junio y Julio. Festejos de arraigo puramente local en el Vallès Oriental que unifican las costumbres de ambos núcleos tradicionales mediante pasacalles populares, cenas de hermandad y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90569','fiesta','Festa Major del Roser','Patronal / Tradicional. Se celebra en Agosto. Festejos veraniegos en el Alt Berguedà dinamizados por el turismo rural, centrados en bailes tradicionales en la plaza mayor empedrada, teatro local y actividades infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90570','fiesta','Festa del Timbaler del Bruc y Festa Major de la Mare de Déu de Montserrat','Recreación Histórica / Patronal. Se celebra en Junio (Timbaler) y Agosto (Patronal). Su recreación histórica de la batalla contra las tropas napoleónicas posee gran relevancia provincial, rememorando la mítica leyenda del tamborilero mediante desfiles de época y trabucaires.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90571','fiesta','Festa Major de Sant Martí','Patronal. Se celebra en Noviembre. Pequeña festividad rural condicionada por la baja demografía del macizo del Montseny, estructurada sobre una misa tradicional, cantos folclóricos y un almuerzo comunitario entre sus masías.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90880','fiesta','Festa Major de Sant Salvador','Patronal. Se celebra en Agosto. Celebración estivales que reúnen a los habitantes de las numerosas urbanizaciones de su disperso término municipal en torno a cenas populares al aire libre y sesiones lúdicas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08029','fiesta','Festa Major de Sant Feliu y Festa de les Bruixes','Patronal / Cultural / Etnográfica. Se celebra en Agosto. Festejos costeros en el Maresme que integran la mítica feria de las brujas inspirada en las leyendas de su castillo medieval, sumando correfocs, habaneras en la playa y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08030','fiesta','Mostra Gastronòmica de Cabrils y Festa Major de Santa Creu','Gastronómica / Patronal. Se celebra en Agosto. Gran cita gastronómica de rango provincial que atrae a miles de personas de toda la costa para degustar las elaboraciones de los restauradores locales, arropada por conciertos masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08031','fiesta','Festa Major de Calaf y Mercat de Calaf','Patronal / Tradicional. Se celebra en Septiembre. Festejos tradicionales de la Alta Segarra que destacan por el histórico arraigo de sus ferias y mercados, acompañados de pasacalles de gigantes, bailes folclóricos tradicionales de bastoners y teatro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08034','fiesta','Festa Major de Sant Vicenç','Patronal. Se celebra en Enero y Septiembre. Festejos tradicionales del Moianès con pasacalles de la colla de gegants local, competiciones lúdicas de cartas tradicionales y verbenas familiares en el polideportivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90025','fiesta','Festa Major de la Mare de Déu del Remei','Patronal / Marinera. Se celebra en Septiembre. Festejos de arraigo local y costero potenciados por el turismo de balneario, con conciertos al aire libre junto al paseo marítimo, habaneras con ron quemado y correfocs de diablos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08033','fiesta','Festa Major i L''Escaldàrium (Festa del Foc i de l''Aigua)','Etnográfica / Rito del Fuego / Termal. Se celebra en Julio (Escaldàrium) y Octubre (Patronal). Declarada Fiesta de Interés Turístico Regional. Célebre a nivel autonómico por el Escaldàrium, un espectacular hito de fuegos y agua termal hirviendo donde los asistentes bailan bajo las chispas al compás de música en directo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08007','fiesta','Festa de Sant Quirze i Santa Julita y Fira de Calella i l''Alt Maresme','Patronal / Feria de Sector / Cultural. Se celebra en Junio y Septiembre. Festejos de gran rango comarcal y turístico; su inmensa feria multisectorial de septiembre atrae a miles de visitantes de toda Cataluña combinando artesanía internacional y folklore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08036','fiesta','Festa Major de Santa Fe','Patronal. Se celebra en Septiembre. Pequeña celebración rural que congrega a los núcleos históricos de su término municipal de baja demografía, limitada a una misa solemne y vermut vecinal de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08037','fiesta','Festa Major de Sant Martí','Patronal. Se celebra en Septiembre. Festejos tradicionales de la Plana de Vic con desfiles populares, muestras de teatro aficionado local, cantos de jotas y sardanas interpretadas por coblas de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08038','fiesta','Festa Major de Callús y les Caramelles de Callús','Patronal / Etnográfica / Pascua. Se celebra en Abril (Caramelles) y Septiembre (Patronal). Destaca a nivel de la comarca del Bages por la magnífica e histórica conservación de sus cantos de caramelles de Pascua, interpretados con vestimentas tradicionales por las calles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08039','fiesta','Festa Major de Sant Joan','Patronal. Se celebra en Agosto. Pequeños festejos estivales en las laderas del Montseny con marcado acento vecinal, orientados a juegos infantiles tradicionales de plaza, cenas al aire libre y orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08041','fiesta','Festa Major de Canovelles','Cultural / Urbana. Se celebra en Julio. Festejos urbanos del área metropolitana con amplia participación de peñas y entidades culturales locales, caracterizados por correfocs, comidas populares y grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08043','fiesta','Fira de Santa Llúcia y Festa Major de Santa Magdalena','Feria Tradicional / Patronal. Se celebra en Julio (Patronal) y Diciembre (Fira). Su espectacular feria navideña de Santa Llúcia es un reclamo masivo provincial, transformando el núcleo histórico en un inmenso mercado tradicional de temática invernal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08044','fiesta','Festa Major de Capellades','Patronal / Etnográfica. Se celebra en Agosto. Festejos tradicionales de la Anoia muy vinculados a la identidad de sus históricos molinos papeleros, combinando correfocs, pasacalles folclóricos de gigantes y verbenas públicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08045','fiesta','Festa Major de Sant Martí','Patronal. Se celebra en Noviembre. Mínimos festejos rurales distribuidos entre las masías de este escarpado municipio del Berguedà, centrados en un almuerzo vecinal compartido y oficios litúrgicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08046','fiesta','Festa Major de Cardedeu y Fira de Nadal i del Torró Artesà','Patronal / Gastronómica / Feria. Se celebra en Agosto (Patronal) y Diciembre (Fira). Festejos de gran peso comarcal en el Vallès Oriental, célebres por su vistoso pasacalles de la colla de gigantes, encierros simulados de fuego, castellers y su consolidada feria de turrón artesano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08009','fiesta','Festa Major de Cardona (Corre de Bous de Cardona)','Patronal / Taurina / Etnográfica. Se celebra en Septiembre. Declarada Fiesta de Interés Turístico Nacional de Cataluña. Singular festejo taurino tradicional —el único que conserva la suelta y encierro de bueyes en el casco urbano de la provincia de Barcelona— integrado en su monumental plaza medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08048','fiesta','Festa Major de Sant Raul i de la Mare de Déu de Collbàs','Patronal / Etnográfica. Se celebra en Julio y Septiembre. Festejos patronales de arraigo estrictamente local en la comarca de Anoia, fundamentados en el tradicional repique de campanas, pasacalles infantiles y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90572','fiesta','Festa Major de Casserres y l''Aplec de Sant Pau de Casserres','Patronal / Romería. Se celebra en Agosto y Enero. Celebración de escala local en el Berguedà que mantiene vivas las tradiciones del interior catalán con pasacalles de gigantes, sardanas en la plaza y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08057','fiesta','Festa Major de Sant Vicenç','Patronal. Se celebra en Agosto. Mínima expresión festiva de carácter vecinal debido a la escasa población de este municipio rural del alto Berguedà, limitada a una misa solemne y un vermut popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90881','fiesta','Concurs Internacional de Gos d''Atura de Castellar de n''Hug','Etnográfica / Tradicional. Se celebra en Agosto. Declarada Fiesta de Interés Turístico Nacional. Hito etnográfico multitudinario en el Pirineo que congrega a pastores de toda Europa para competir con sus perros de pastoreo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08050','fiesta','Festa del Pi de les Tres Branques','Etnográfica / Tradicional / Cultural. Se celebra en Julio. Hito etnográfico e identitario de primer orden en la comarca del Berguedà, celebrado alrededor del emblemático y centenario pino de tres ramas, con música folclórica y discursos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08051','fiesta','Festa Major de Castellar y Mostra de Oficis Tradicionals','Patronal / Cultural. Se celebra en Septiembre. Festejos de rango comarcal consolidados con un potente programa lúdico, correfocs masivos, pasacalles de gigantes y cabezudos y el tradicional volteo de campanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08053','fiesta','Festa Major de Sant Cristòfol y Ball de Gitanes de Castellbell','Patronal / Etnográfica. Se celebra en Agosto. Festejos a la sombra de Montserrat que destacan por la conservación y espectacular ejecución de su tradicional Ball de Gitanes, un elemento del folclore local recuperado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08054','fiesta','Festa Major de l''Aigua i de la Llum','Patronal / Cultural. Se celebra en Agosto. Festejos con notable dinamismo y afluencia, caracterizados por el tradicional reparto de agua bendecida, potentes correfocs, conciertos masivos y fuerte implicación de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08055','fiesta','Festa Major de Santa Margarida','Patronal. Se celebra en Agosto. Celebración de ámbito estrictamente local y de carácter familiar en el Moianès, centrada en el reencuentro de veraneantes, campeonatos de naipes y pequeñas orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08056','fiesta','Festes del Mar y Fiesta Mayor de Castelldefels','Patronal / Marinera / Histórica. Se celebra en Julio y Diciembre. Las Festes del Mar están declaradas de gran empaque comarcal y costero, célebres por la espectacular recreación histórica del desembarco pirata en la playa, con participación masiva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08058','fiesta','Festa Major de Sant Pere de Castellet','Patronal / Histórica. Se celebra en Junio. Festejos veraniegos de carácter local junto al marco monumental de su castillo medieval y el embalse de Foix, con comidas populares y cantadas de habaneras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08059','fiesta','Festa Major de Sant Pere','Patronal. Se celebra en Junio. Pequeña celebración vecinal condicionada por la baja demografía y dispersión de masías en el Bages, vertebrada en torno a la santa misa y verbenas lúdicas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08060','fiesta','Festa Major del Roser','Patronal. Se celebra en Mayo. Festejos tradicionales de carácter familiar limitados al municipio debido a la escasa población, centrados en actos religiosos tradicionales y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08061','fiesta','Festa Major de Sant Miquel','Patronal. Se celebra en Mayo y Agosto. Festejos patronales con competiciones deportivas locales, sesiones de baile en la plaza del ayuntamiento y tradicionales procesiones litúrgicas para el vecindario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08062','fiesta','Festa Major de Sant Andreu','Patronal. Se celebra en Septiembre. Celebración puramente vecinal en los núcleos residenciales del término, sustentada en ritos religiosos tradicionales, juegos infantiles y cenas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08063','fiesta','Festa Major de Sant Vicenç','Patronal. Se celebra en Enero y Agosto. Festejos locales que complementan las misas tradicionales y pasacalles con actividades lúdicas veraniegas y verbenas muy concurridas por los habitantes de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08064','fiesta','Festa Major y Dansa de Castellterçol','Patronal / Etnográfica. Se celebra en Agosto. Hito etnográfico de gran renombre provincial célebre por la antiquísima y solemne "Dansa de Castellterçol" y el "Ball del Ciri", ejecutados con trajes de gala del siglo XVIII.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08065','fiesta','Festa Major del Marge y de Sant Sadurní','Patronal / Enológica. Se celebra en Agosto. Festejos tradicionales de la zona vitivinícola del Penedès, caracterizados por rondas populares, degustación de cavas artesanales locales y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08066','fiesta','Festa Major de Sant Isidre','Patronal. Se celebra en Mayo. Festejos de primavera de arraigo local, consistentes en bendiciones de campos tradicionales, pasacalles infantiles y bailes públicos en el local social.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08067','fiesta','Festa del Pi de Centelles (Sant Esteve)','Etnográfica / Tradicional / Pirotécnica. Se celebra en Diciembre. Declarada Fiesta de Interés Turístico de Cataluña. Hito etnográfico absoluto donde los "galejadors" disparan trabucos mientras asaltan el bosque para talar y ofrendar un pino a la iglesia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90573','fiesta','Festa Major de Sant Jordi de Cercs','Patronal. Se celebra en Abril y Agosto. Festejos patronales tradicionales marcados por el reencuentro veraniego en los antiguos núcleos mineros, con cantos de coros tradicionales y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08266','fiesta','Festes de Sant Martí (Festa Major de Tardor) i del Roser de Maig','Patronal / Cultural / Etnográfica. Se celebra en Mayo y Noviembre. Grandes fiestas de esta populosa ciudad metropolitana, caracterizadas por un potente programa de conciertos, castellers, pasacalles de gigantes y activos correfocs.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08068','fiesta','Festa Major de Sant Esteve','Patronal / Cultural. Se celebra en Agosto. Festejos con amplio respaldo vecinal en el Baix Llobregat, con correfocs de diablos locales, campeonatos deportivos tradicionales y verbenas nocturnas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08069','fiesta','Festa Major de Sant Corneli','Patronal / Etnográfica. Se celebra en Septiembre. Festejos de arraigo tradicional al pie de las cuevas de Montserrat, que atraen a visitantes de la comarca a sus pasacalles de gigantes, sardanas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08070','fiesta','Festa Major de la Mare de Déu dels Socors','Patronal. Se celebra en Agosto. Festejos estivales tradicionales basados en la hermandad vecinal, ritos religiosos tradicionales, juegos para niños y orquestas reducidas en la plaza de la iglesia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08071','fiesta','Festa Major de Copons *','Patronal *. Se celebra en Agosto *. Celebración de ámbito estrictamente local que mantiene el sabor de su pasado comercial, estructurada con verbenas al aire libre y comidas populares de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08072','fiesta','Pessebre Vivent de Corbera y Festa Major de Santa Magdalena','Teatral / Etnográfica / Patronal. Se celebra en Diciembre/Enero (Pessebre) y Julio (Festa Major). Su Pessebre Vivent está declarado de gran relevancia etnográfica autonómica, siendo el primer pesebre viviente de Cataluña, con representaciones masivas que atraen a miles de visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08073','fiesta','Festes del Corpus de Cornellà','Patronal / Cultural / Etnográfica. Se celebra en Mayo / Junio. Grandes fiestas mayores de la comarca con un masivo despliegue de cultura popular que incluye la mítica "Trobada de Gegants", correfocs de primer nivel y conciertos públicos masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08074','fiesta','Festa Major de Santa Maria y Festa de la Vendimia','Patronal / Gastronómica / Costera. Se celebra en Agosto y Septiembre. Festejos costeros con notable arraigo que combinan pasacalles folclóricos de castellers y gigantes con la tradicional pisada de uva comarcal del Garraf.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08075','fiesta','Festa Major de Dosrius y de Canyamars','Patronal. Se celebra en Agosto y Septiembre. Festejos tradicionales del interior del Maresme que dinamizan sus núcleos con pasacalles populares, correfocs de diablos locales y cenas comunitarias al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08076','fiesta','La Passió d''Esparreguera y Festa Major de Santa Eulàlia','Teatral / Religiosa / Etnográfica. Se celebra en Marzo / Abril (La Passió) y Febrero/ Julio (Fiestas). Su colosal representación de "La Passió" involucra de forma masiva a todo el municipio y posee un valor histórico y etnográfico singular reconocido a nivel nacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08077','fiesta','Festes de Sant Mateu','Patronal / Cultural / Etnográfica. Se celebra en Septiembre. Festejos mayores de rango metropolitano con amplia tradición popular, célebres por su "Cercavila de Gegants", correfocs espectaculares, conciertos y ferias de artesanía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08078','fiesta','Festa Major de Sant Climent','Patronal. Se celebra en Noviembre. Mínimos festejos rurales condicionados por el declive demográfico y la dispersión rural en el Berguedà, limitados a la santa misa tradicional y encuentro vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08011','fiesta','Festa Major del Roser y Fira de Sant Jaume','Patronal / Feria Tradicional. Se celebra en Mayo y Julio. Festejos locales alrededor de su monasterio románico, con tradicionales misas solemnes, mercado de productos artesanos de la comarca y sardanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08134','fiesta','Festa Major de Sant Rafael','Patronal. Se celebra en Octubre. Festejos de otoño de marcado carácter vecinal en el valle del Congost, consistentes en pasacalles musicales, juegos para niños y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08080','fiesta','Festa Major de Santa Cecília','Patronal. Se celebra en Noviembre. Pequeña celebración rural que unifica la escasa población de este antiguo núcleo minero pirenaico en torno a actos religiosos y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90574','fiesta','Festa Major de Sant Cebrià','Patronal. Se celebra en Septiembre. Festejos de ámbito estrictamente local con baja densidad de población, centrados en el reencuentro de vecinos en la plaza mayor con pequeñas orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08081','fiesta','Aplec de Sant Marçal del Montseny','Romería / Tradicional. Se celebra en Junio. Concurrida romería tradicional en pleno Parque Natural del Montseny, arraigada entre los habitantes de la sierra con misas solemnes y bailes de sardanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08084','fiesta','Festa Major de Fonollosa i de Camps','Patronal / Etnográfica. Se celebra en Agosto y Septiembre. Festejos locales que conservan ritos tradicionales agrícolas de la comarca del Bages, acompañados de comidas populares y verbenas en las plazas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08085','fiesta','Festa Major de Guardiola de Font-rubí','Patronal / Enológica. Se celebra en Agosto. Festejos veraniegos que dinamizan el municipio gracias al arraigo del cultivo del vino y el cava, combinando pasacalles folclóricos con catas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90575','fiesta','Festa Major de Santa Maria de Gaià','Patronal. Se celebra en Agosto. Mínimos festejos vecinales en una zona rural de baja demografía del norte de la provincia, limitados a ritos litúrgicos tradicionales y encuentros familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08087','fiesta','Festa Major de la Mare de Déu del Castell','Patronal / Romería. Se celebra en Septiembre. Pequeña festividad local estructurada en torno a la romería a la ermita románica fortificada y comidas de hermandad entre los escasos vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08088','fiesta','Festa del Corpus de la Garriga y Festa Major de Sant Esteve','Etnográfica / Floral / Patronal. Se celebra en Junio (Corpus) y Agosto (Festa Major). Declarada Fiesta de Interés Turístico de Cataluña. Su festividad del Corpus destaca de forma monumental por cubrir las calles con espectaculares y masivas alfombras de claveles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08089','fiesta','Festa Major de Sant Pere y Festa de l''Espàrrec de Gavà','Patronal / Gastronómica / Cultural. Se celebra en Abril (Espàrrec) y Junio (Sant Pere). Festejos de rango comarcal muy populares; su histórica feria agrícola de la fira del espárrago destaca provincialmente por sus espectaculares composiciones de hortalizas artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08091','fiesta','Festa Major de Sant Pere y Festa de Santa Llúcia','Patronal / Tradicional. Se celebra en Agosto y Diciembre. Festejos que destacan en el Alt Penedès por el reparto tradicional de la "Escudella de Santa Llúcia", cocinada de forma artesanal en ollas de barro en plena calle.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08092','fiesta','Festa Major de Gironella y el Ball de l''Almorratxa','Patronal / Etnográfica. Se celebra en Agosto. Celebración con gran arraigo comarcal e histórico en el Berguedà por la magnífica ejecución del ancestral "Ball de l''Almorratxa", una danza catalogada de alto valor folclórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08093','fiesta','Festa Major del Roser de Gisclareny','Patronal. Se celebra en Octubre. Mínima expresión festiva de carácter estrictamente familiar en el municipio menos poblado de toda Cataluña, centrada en una misa tradicional y vermut vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08094','fiesta','Festa Major de Sant Cristòfol','Patronal / Enológica. Se celebra en Julio. Festejos de arraigo local tradicionales en la comarca del vino, estructurados con castellers populares, pasacalles de gigantes de la comarca y verbenas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08095','fiesta','Festa Major de Sant Martí','Patronal. Se celebra en Agosto *. Festejos veraniegos mínimos condicionados por la despoblación a la sombra de su castillo histórico, basados en comidas de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08096','fiesta','Festa Major de Granollers (Festa de Blancs i Blaus)','Etnográfica / Cultural / Civil. Se celebra en Agosto. Declarada Fiesta de Interés Turístico de Cataluña. Macrofestejo regional masivo célebre por la espectacular rivalidad pacífica entre los bandos de "Blancs" y "Blaus", que compiten en pruebas tradicionales e inundan la ciudad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08097','fiesta','Festa Major de Sant Vicenç','Patronal. Se celebra en Enero y Agosto. Festejos locales tradicionales a los pies del Montseny orientados a las actividades familiares de verano, con comidas populares en el bosque y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08101','fiesta','Festes de Primavera de L''Hospitalet','Cultural / Etnográfica / Urbana. Se celebra en Abril. Macrocelebración de la segunda ciudad de la provincia, caracterizada por un monumental despliegue de cultura catalana con correfocs masivos, castells, desfiles de bestias de fuego y grandes conciertos públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08102','fiesta','Fira de Reis d''Igualada y Festa Major de Sant Bartomeu','Feria Tradicional / Patronal / Etnográfica. Se celebra en Enero (Reis) y Agosto (Festa Major). Su histórica e inmensa cabalgata y feria de Reyes es la más antigua de Cataluña, declarada Fiesta de Interés Turístico por su extraordinario valor identitario y masiva afluencia regional). Hemos completado al 100% todos los municipios de la provincia de Barcelona desde la letra C hasta la I de forma rigurosa y exhaustiva. ¿Procedemos a abrir el siguiente bloque, correspondiente a la provincia de Burgos (siguiendo el orden de las provincias que restan por completar de la lista general.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08103','fiesta','Festa Major de Sant Tirs y Festa de Sant Isidre','Patronal / Tradicional. Se celebra en Enero y Mayo. Festejos patronales de arraigo local en la Anoia, caracterizados por la tradicional bendición de tractores, reparto de pan y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08104','fiesta','Festa Major de La Llacuna y Aplec del Castell','Patronal / Romería / Etnográfica. Se celebra en Agosto. Festejos estivales de marcado arraigo comarcal, célebres por su vistoso "Ball de Diables", pasacalles de gigantes y el tradicional almuerzo popular en el castillo medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08105','fiesta','Festa Major de La Llagosta','Patronal / Cultural. Se celebra en Septiembre. Festejos mayores de esta localidad del Vallès Oriental, caracterizados por el correfoc de la colla local, torneos deportivos de peñas y conciertos públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90576','fiesta','Festa Major de Lliçà d''Amunt','Patronal / Cultural. Se celebra en Septiembre. Festejos tradicionales de rango comarcal muy populares, dotados de pasacalles, encuentros de castellers, muestras gastronómicas y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08108','fiesta','Festa Major de Lliçà de Vall','Patronal. Se celebra en Julio. Celebración estivales con amplia participación vecinal, destacando sus habaneras con ron quemado, actividades infantiles y sesiones de orquesta nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08106','fiesta','Festa Major de Llinars','Patronal / Etnográfica. Se celebra en Septiembre. Festejos de fuerte arraigo en el Vallès, caracterizados por la activa competición festiva entre los grupos locales de "Ginjolers" y "Banyuts", con correfocs masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90577','fiesta','Festa Major de Santa Maria de Lluçà','Patronal / Romería. Se celebra en Agosto. Pequeña celebración rural que aprovecha el entorno monumental de su histórico monasterio románico, limitada a ritos litúrgicos tradicionales y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08012','fiesta','Festa Major de Sant Roc y Festes de Santa Susanna','Patronal / Costera / Cultural. Se celebra en Agosto. Grandes festejos de verano de enorme concurrencia turística y costera, caracterizados por su espectacular castillo de fuegos artificiales en la playa, correfocs y habaneras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08111','fiesta','Festa Major de Sant Vicenç','Patronal. Se celebra en Enero. Mínima expresión festiva de carácter estrictamente familiar e invernal en Osona, debido a la dispersión rural de sus masías y baja población.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08013','fiesta','Festa Major de Manlleu y la Festa del Serpent','Patronal / Etnográfica / Mitológica. Se celebra en Agosto. Declarada Fiesta de Interés de la comarca y la región. Hito etnográfico masivo célebre por la teatralización callejera nocturna de la leyenda del Serpent, con pirotecnia y música propia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08113','fiesta','Festa Major de Manresa (La Mostra de Correfoc) i Festa de la Llum','Patronal / Histórica / Etnográfica. Se celebra en Febrero (Llum) y Agosto (Festa Major). Declaradas de gran interés regional. La Mostra de Correfoc es uno de los espectáculos pirotécnicos tradicionales más importantes, masivos y depurados de Cataluña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08242','fiesta','Festa de Sant Bartomeu y Fiesta del Mató','Patronal / Gastronómica. Se celebra en Agosto y Octubre. Festejos locales al pie de Montserrat que promocionan de forma artesanal su famoso requesón "Mató de Montserrat", arropados por folclore local y sardanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08115','fiesta','Festa Major de Martorell y Fira de Primavera','Patronal / Cultural / Feria Tradicional. Se celebra en Abril (Fira) y Agosto (Festa Major). Festejos mayores de rango comarcal, con amplio despliegue de gigantes, cabezudos, castellers locales en el Pont del Diable y potentes espectáculos musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08115','fiesta','Festa Major de Martorelles','Patronal. Se celebra en Septiembre. Festejos patronales tradicionales del Vallès Baix, con pasacalles populares, correfocs infantiles, comidas vecinales y sesiones de baile en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90882','fiesta','Festa Major de Les Masies de Roda','Patronal. Se celebra en Julio. Celebración puramente vecinal y rural condicionada por la dispersión de la población, basada en la santa misa tradicional y bailes de sociedad en el centro cívico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90883','fiesta','Festa Major de Sant Tomàs y Festa de Sant Martí','Patronal / Romería. Se celebra en Septiembre. Festejos locales tradicionales con romerías a las ermitas del término, pasacalles tradicionales con gigantes y comidas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08118','fiesta','Festa Major de Sant Pere del Masnou','Patronal / Marinera / Costera. Se celebra en Junio. Festejos costeros de gran peso comarcal, célebres por su tradicional traca kilométrica por las calles marineras, correfocs de diablos, conciertos públicos y habaneras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08119','fiesta','Festa Major de Masquefa y Festa del Raïm','Patronal / Enológica / Etnográfica. Se celebra en Julio y Septiembre. Festejos que destacan en la Anoia por su tradicional pisada de uva artesanal, pasacalles folclóricos de gigantes, diablos locales y verbenas estivales multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08120','fiesta','Festa Major de Sant Sebastià','Patronal / Etnográfica. Se celebra en Enero. Destacan provincialmente por las espectaculares e históricas "Festes de Sant Sebastià", donde se realiza la tradicional bajada del pino y la plantada del árbol en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08121','fiesta','Les Santes (Festa Major de Mataró)','Patronal / Etnográfica / Cultural. Se celebra en Julio. Declarada Fiesta de Interés Patrimonial de Cataluña. Macrofestejo masivo regional de primer orden, famoso por la "Nit de Bojos", la comparsa de figuras tradicionales de la familia Robafaves y castellers.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08122','fiesta','Festa Major de Sant Joan de Mediona','Patronal / Enológica. Se celebra en Julio. Festejos tradicionales de la comarca del Alt Penedès, basados en castellers populares, muestras de cerveza artesana local y verbenas familiares al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90578','fiesta','Festa Major de Moià y la Festa de l''Arbre i de la Fruita','Patronal / Etnográfica / Histórica. Se celebra en Agosto. Festejos de la capital del Moianès con gran valor etnográfico por la histórica Festa de l''Arbre —fundada en 1904—, pasacalles folclóricos de gigantes y bailes de bastons.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08123','fiesta','Fira de la Candelera y Festa Major de Sant Miquel','Feria Tradicional / Patronal / Etnográfica. Se celebra en Febrero (Candelera) y Septiembre (Sant Miquel). Su inmensa Fira de la Candelera —desde 1851— está declarada de gran relieve regional por su masiva afluencia y mercado de plantones, agricultura e identidad agraria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08124','fiesta','Festa Major de Mollet (Festa de Moros y Torrats)','Civil / Etnográfica / Cultural. Se celebra en Agosto. Festejos de gran calado comarcal, célebres por la divertida rivalidad festiva urbana entre las colles de "Moros" y "Torrats", que compiten en pruebas y llenan las verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08128','fiesta','Festa Major de Sant Feliu','Patronal. Se celebra en Agosto. Festejos tradicionales de carácter vecinal en el Moianès, estructurados sobre verbenas en la plaza mayor, juegos de cartas aragoneses catalanes y actividades infantiles locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08127','fiesta','Festa dels Romeus y Festa Major de Sant Sadurní','Recreación Histórica / Etnográfica / Patronal. Se celebra en Enero (Romeus) y Noviembre (Sadurní). La Festa dels Romeus recrea con gran fidelidad el pasado renacentista del municipio como parada de peregrinos hacia el monasterio de Montserrat, atrayendo a numeroso público comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08125','fiesta','Festa Major de Montcada','Patronal / Cultural. Se celebra en Mayo / Junio. Festejos del área metropolitana con notable participación, destacados por sus correfocs de diablos, desfiles populares de gigantes, castellers y macroconciertos públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08130','fiesta','Festa Major de Montclar y Fira de Reis','Patronal / Feria Tradicional. Se celebra en Enero y Agosto. Pequeña celebración en su plaza mayor medieval del Berguedà, de marcado ambiente rural y vecinal adaptado a su reducida demografía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08131','fiesta','Festa Major de Montesquiu','Patronal / Cultural. Se celebra en Septiembre. Festejos tradicionales junto al parque del castillo, consistentes en pasacalles de gigantes de la comarca, bailes de sardanas y verbenas familiares en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08126','fiesta','Festa Major de Sant Joan del Montgat','Patronal / Costera. Se celebra en Junio. Festejos costeros caracterizados por el tradicional encendido de la hoguera en la arena de la playa, comidas populares de pescadores, correfocs y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08132','fiesta','Festa Major de Montmajor y Fiesta del Mercado del Set bolet','Patronal / Feria Micológica. Se celebra en Septiembre y Octubre. Festejos de otoño orientados a la promoción micológica y su singular Museo de las Setas, arropados por comidas comunitarias de hermandad y folclore local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08133','fiesta','Festa Major de Montmaneu y Festa de la Caldera','Patronal / Gastronómica / Tradicional. Se celebra en Febrero (Caldera) y Septiembre (Festa Major). Destaca por la histórica Festa de la Caldera en época de carnaval, un tradicional reparto de sopa comunitaria cocinada con leña en plena plaza pública.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08135','fiesta','Festa Major de Montmeló (Festa de Melons y Cremauts)','Civil / Cultural / Etnográfica. Se celebra en Junio. Festejos de rango comarcal muy populares, célebres por la animada rivalidad entre las agrupaciones locales de "Melons" y "Cremauts", con correfocs multitudinarios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08136','fiesta','Festa Major de Montornès (Cremafocs)','Patronal / Etnográfica / Pirotécnica. Se celebra en Septiembre. Festejos destacados en el Vallès por la espectacularidad de su "Cremafocs", un correfoc de gran tradición pirotécnica coordinado por los diablos de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08137','fiesta','Festa Major de Sant Marçal y Festa d''en Serrallonga','Patronal / Tradicional / Teatral. Se celebra en Junio y Agosto. Festejos tradicionales de alta montaña pasiega catalana en el parque natural, con pasacalles que recuerdan al mítico bandolero, sardanas y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08139','fiesta','Festa Major de Sant Martí de Mura','Patronal / Etnográfica. Se celebra en Noviembre. Festejos locales tradicionales que visten de gala su preservado trazado medieval, consistentes en ritos religiosos tradicionales, jotas locales catalanas y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08140','fiesta','Monacalia (Fira de l''Abat) i Festa Major de Navarcles','Recreación Histórica / Feria Etnográfica / Patronal. Se celebra en Febrero (Monacalia) y Agosto (Festa Major). Su fira medieval de Monacalia posee rango comarcal destacado, recreando la histórica relación feudal del pueblo con el cercano Monasterio de Sant Benet de Bages.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08141','fiesta','Festa Major de Navàs y la Fira de Tardor','Patronal / Feria Tradicional / Etnográfica. Se celebra en Agosto y Octubre. Festejos de arraigo tradicional en el alto Llobregat, célebres por los bailes tradicionales de sus gigantes, muestras agrícolas de otoño y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90579','fiesta','Festa Major de Sant Martí y l''Aplec de Taravil','Patronal / Romería. Se celebra en Noviembre. Festejos rurales mínimos en un municipio de montaña de baja demografía, articulados en torno a la santa misa tradicional y una comida comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08143','fiesta','Festa Major de Sant Pere de Òdena','Patronal. Se celebra en Junio. Festejos tradicionales de la Anoia con pasacalles folclóricos de la colla local, competiciones lúdicas vecinales y bailes de orquesta públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08145','fiesta','Aplec d''Olèrdola y Festa Major de Sant Miquel','Romería / Histórica / Patronal. Se celebra en Junio y Octubre. Festividades celebradas en torno a su histórico conjunto arqueológico amurallado, aunando fervor mariano de la comarca, sardanas y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08146','fiesta','Festa Major de Sant Joan y de Sant Bartomeu','Patronal. Se celebra en Julio y Agosto. Festejos tradicionales en el macizo del Garraf orientados a las actividades familiares de verano, con comidas populares y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08147','fiesta','La Passió d''Olesa y Festa Major de Santa Oliva','Teatral / Religiosa / Etnográfica. Se celebra en Marzo / Abril (La Passió) y Junio (Santa Oliva). Su monumental e histórica representación teatral de "La Passió" involucra de forma masiva a todo el municipio y posee la declaración de Interés Turístico Nacional por su excelencia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08148','fiesta','Festa Major de Sant Pere y de la Mare de Déu del Garraf','Patronal. Se celebra en Julio y Noviembre. Festejos locales en un entorno residencial del parque natural, basados en ritos religiosos tradicionales, juegos infantiles tradicionales y verbenas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08149','fiesta','Fira d''en Serrallonga de Olost i Festa Major','Feria Etnográfica / Recreación Histórica / Patronal. Se celebra en Agosto y Noviembre (Fira). Gran valor etnográfico e histórico comarcal por su feria barroca dedicada al bandolero Serrallonga, con trabucaires, asaltos de época y mercado tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08150','fiesta','Festa Major de Sant Genís y Feria de la Patata de Orís','Patronal / Gastronómica. Se celebra en Agosto y Octubre. Festejos de otoño que ponen en valor el cultivo tradicional de la patata local en el llano, con mercado tradicional artesano y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08151','fiesta','Festa Major de Sant Andreu','Patronal. Se celebra en Noviembre. Celebración de escala local en el Lluçanès de carácter rural, estructurada en torno a ritos religiosos tradicionales y sesiones de orquesta en el centro cívico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08164','fiesta','Festa Major de Sant Genís','Patronal / Enológica. Se celebra en Agosto. Festejos tradicionales rodeados de viñedos del Penedès, consistentes en pasacalles con gigantes de la zona, degustaciones de vino nuevo y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08155','fiesta','Festa Major de Palafolls y Festa de Santa Maria','Patronal / Cultural. Se celebra en Septiembre. Festejos de arraigo local tradicionales en la frontera de la costa, caracterizados por sus pasacalles de la colla de gigantes local, correfocs de diablos y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08156','fiesta','Festa Major de Palau y Mercat Medieval de la Danza','Patronal / Feria Etnográfica. Se celebra en Agosto *. Festejos de rango comarcal consolidados con un potente programa lúdico que incluye el "Ball de la Post" tradicional, correfocs y mercados medievales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08157','fiesta','Festa Major de Sant Eulàlia y de Sant Jaume','Patronal / Cultural. Se celebra en Febrero y Julio. Festejos patronales con amplia participación del Baix Llobregat, con pasacalles populares de diablos de la comarca, castellers y orquestas en el patio del castillo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08905','fiesta','Festa Major de Santa Maria de la Palma','Patronal. Se celebra en Agosto. Celebración de ámbito estrictamente local de carácter familiar e infantil, fundamentada en comidas populares, habaneras y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08158','fiesta','Festa Major de la Mare de Déu de la Salut y Fiesta de la Cereza','Patronal / Gastronómica. Se celebra en Julio (Festa) y Junio (Cereza). Festejos locales tradicionales muy populares en el Llobregat por su fira tradicional de la cereza de alta raigambre artesanal, complementada con folklore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08159','fiesta','Festa Major de Parets (Festa de la Pedra del Diable)','Patronal / Cultural / Etnográfica. Se celebra en Julio. Festejos comarcales consolidados, célebres por la escenificación mitológica de la leyenda de la Piedra del Diablo, correfocs espectaculares y conciertos masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08160','fiesta','Festa Major de Sant Pere y la Festa de la Candelera (Cavallets)','Patronal / Etnográfica / Ecuestre. Se celebra en Junio (Sant Pere) y Febrero (Candelera). Festejos del Lluçanès que destacan regionalmente por las históricas carreras de caballos de la Candelera y los bailes folclóricos tradicionales de sus carrozas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08161','fiesta','Festa Major de Piera y el Santo Cristo','Patronal / Cultural. Se celebra en Septiembre. Grandes fiestas de rango comarcal en la Anoia, famosas por sus multitudinarios correfocs con bestias de fuego, desfiles populares de gigantes y castellers locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08016','fiesta','Festa Major de Pineda de Mar','Patronal / Costera / Cultural. Se celebra en Agosto. Grandes festejos de verano de masiva concurrencia turística comarcal, con barracas de peñas en el paseo marítimo, correfocs de diablos y castells.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08164','fiesta','Festa Major del Pla del Penedès','Patronal / Enológica. Se celebra en Julio. Festejos tradicionales de la zona vitivinícola del cava, caracterizados por pasacalles folclóricos de castellers comarcales y comidas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08165','fiesta','Festa Major de la Mare de Déu de la Llet y l''Aplec del Castell','Patronal / Histórica / Romería. Se celebra en Mayo y Septiembre. Festejos locales tradicionales que incluyen la concurrida procesión al imponente castillo fortificado de Claramunt, aunando fe, sardanas e identidad comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08166','fiesta','Festa Major de la Pobla de Lillet y el Ball del Ciri','Patronal / Etnográfica. Se celebra en Octubre. Festejos del alto Berguedà que destacan provincialmente por la solemne e histórica ejecución de su tradicional "Ball del Ciri", una joya catalogada del folclore catalán.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08167','fiesta','Festa Major de Polinyà','Patronal. Se celebra en Julio. Festejos patronales con competiciones deportivas locales, pasacalles tradicionales con la colla local de gigantes y animadas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08182','fiesta','Festa Major del Pont de Vilomara','Patronal / Cultural. Se celebra en Julio. Festejos veraniegos de carácter local en el Bages, basados en correfocs infantiles, tradicionales misas cántabras catalanas y cenas populares al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08168','fiesta','Festa Major de Pontons','Patronal / Enológica. Se celebra en Julio. Pequeña celebración veraniega y familiar en el municipio más alto del Alt Penedès, con comidas comunitarias y muestras de vinos de montaña locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08169','fiesta','Festa Major del Prat y Fira Avícola de la Raça Prat','Patronal / Gastronómica / Feria de Sector. Se celebra en Septiembre (Festa) y Diciembre (Fira). Su fira sectorial del pollo "Potablava" posee rango regional absoluto y alta raigambre, promocionando de forma masiva este producto con I.G.P. y la cocina comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08230','fiesta','Festa Major de Premià de Dalt (Sant Pere)','Patronal / Cultural. Se celebra en Junio. Festejos tradicionales de las medianías del Maresme con pasacalles populares, correfocs de diablos de la zona y cenas de hermandad al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08172','fiesta','Festa Major de Premià (Festa dels Pirates)','Etnográfica / Recreación Histórica / Costera. Se celebra en Julio. Declarada de gran relieve regional y turístico. Espectacular hito etnográfico masivo donde se escenifica el desembarco pirata berberisco en la playa y la toma de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90580','fiesta','Festa Major de Puigdàlber','Patronal. Se celebra en Noviembre. Mínimos festejos de ámbito puramente vecinal en el municipio con menor extensión territorial de Cataluña, limitados a ritos litúrgicos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08175','fiesta','Festa de la Corrida de Puig-reig y Festa Major','Etnográfica / Ecuestre / Patronal. Se celebra en Enero (Corrida) y Mayo (Festa Major). Su histórica fiesta ecuestre de "La Corrida" posee rango comarcal de alta raigambre en el Berguedà, con carreras tradicionales de caballos, burros y desfiles de carros de arrieros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08176','fiesta','Festa Major de Pujalt','Patronal. Se celebra en Agosto. Pequeñas fiestas estivales de marcado ambiente familiar en sus núcleos de origen medieval, con comidas de hermandad y música de orquesta reducida.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08179','fiesta','Festa Major de Rellinars','Patronal. Se celebra en Julio. Festejos patronales de arraigo estrictamente local en el Vallès Occidental, caracterizados por el retorno estival de familias, caminatas populares por el entorno natural, cenas vecinales y verbenas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08180','fiesta','Festa Major de Ripollet','Patronal / Cultural. Se celebra en Agosto. Festejos de rango comarcal consolidados con un potente programa lúdico, correfocs de diablos locales, bailes de gigantes y cabezudos, y el tradicional mercado de artesanía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08181','fiesta','Festa Major de La Roca, de Santa Agnès de Malanyanes i de Torrelles','Patronal / Cultural. Se celebra en Septiembre. Festejos que unifican las tradiciones de los distintos núcleos del término municipal con pasacalles populares, correfocs de diablos y cenas de hermandad al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08184','fiesta','Festa Major de Sant Pere de Rubí','Patronal / Etnográfica / Cultural. Se celebra en Junio. Festejos de rango comarcal muy populares, célebres por la tradicional "Ball de Gitanes" masivo en la plaza de la Vila, potentes correfocs, castellers y grandes conciertos públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08187','fiesta','Festa Major de Sabadell y Salut de Sabadell','Patronal / Cultural / Etnográfica. Se celebra en Septiembre (Festa Major) y Mayo (La Salut). Grandes fiestas de una de las cocapitales del Vallès Occidental, caracterizadas por un monumental despliegue de cultura catalana con el pasacalles de "Gegants", castells y correfocs multitudinarios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08188','fiesta','Festa Major de Sant Andreu de Sagàs','Patronal. Se celebra en Noviembre. Mínima expresión festiva de carácter vecinal debido a la escasa población de este municipio rural del Berguedà, limitada a una misa solemne y un vermut popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08190','fiesta','Festa Major de Saldes','Patronal / Romería. Se celebra en Agosto. Celebración de escala local al pie del Pedraforca que mantiene vivas las tradiciones del Pirineo catalán con pasacalles de gigantes, sardanas en la plaza y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90581','fiesta','Festa de les Enramades de Sallent','Etnográfica / Floral / Tradicional. Se celebra en Junio. Declarada Fiesta de Interés Turístico de Cataluña. Hito monumental de arte efímero donde los vecinos decoran de forma artesanal las calles del pueblo con intrincados tapices y guirnaldas temáticas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08194','fiesta','Festa Major de Sant Adrià','Patronal / Cultural. Se celebra en Septiembre. Festejos de ámbito periurbano con gran afluencia, caracterizados por festivales de música al aire libre, actividades para peñas locales y desfiles de gigantes por las calles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08195','fiesta','Festa Major de Sant Agustí','Patronal. Se celebra en Agosto. Pequeña celebración de invierno de marcado carácter vecinal y familiar debido a la baja demografía del Lluçanès, limitada a misas tradicionales y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08196','fiesta','Festa Major de Sant Andreu','Patronal / Cultural. Se celebra en Septiembre. Festejos mayores de rango metropolitano con amplia tradición popular, célebres por su "Cercavila de Gegants", correfocs de gran espectacularidad, conciertos y actividades infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08197','fiesta','Festa Major de la Minerva i de Sant Andreu','Patronal / Gastronómica. Se celebra en Julio y Noviembre. Festejos costeros en el Maresme que combinan pasacalles folclóricos de gigantes y diablos con la tradicional fiesta gastronómica dedicada a la promoción de la "Coca de Llavaneres".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08198','fiesta','Festa Major de Sant Antoni','Patronal. Se celebra en Agosto. Festejos tradicionales al pie del Montseny que dinamizan el núcleo con pasacalles populares de gigantes locales, bailes de sardanas y cenas vecinales al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08199','fiesta','Festa Major de Sant Bartomeu','Patronal. Se celebra en Agosto. Festejos veraniegos que complementan las tradicionales misas solemnes y pasacalles con actividades recreativas para los jóvenes y verbenas muy concurridas por el vecindario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90678','fiesta','Festa Major de Sant Boi y Fira de la Puríssima','Patronal / Feria Tradicional / Cultural. Se celebra en Mayo (Festa Major) y Diciembre (Fira). Su histórica e inmensa Fira de la Puríssima es una de las ferias tradicionales más antiguas de la comarca, declarada de gran raigambre y masiva afluencia regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90582','fiesta','Festa Major de Sant Boi','Patronal. Se celebra en Agosto. Celebración de ámbito estrictamente local y de carácter familiar en el Lluçanès, centrada en el reencuentro de veraneantes, campeonatos de cartas y pequeñas orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90884','fiesta','Festa Major de Sant Cebrià y Festa de la Maduixa','Patronal / Gastronómica. Se celebra en Septiembre y Mayo. Festejos tradicionales del interior del Maresme que giran en torno a la promoción agrícola de su fresa local, acompañados de música de parrandas canarias tradicionales y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08202','fiesta','Festa Major de Sant Celoni y Ball de Gitanes','Patronal / Etnográfica / Cultural. Se celebra en Septiembre y Febrero (Gitanes). Destaca en el Baix Montseny por el extraordinario arraigo de su multitudinario "Ball de Gitanes" en Carnaval, hito folclórico catalogado de alta raigambre provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08204','fiesta','Festa de la Cirera y Festa Major de Sant Climent','Gastronómica / Patronal / Etnográfica. Se celebra en Mayo y Noviembre. Festejos que destacan en el Baix Llobregat por la histórica exposición y concurso-venta de sus famosas cerezas locales, arropados por castellers y pasacalles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08205','fiesta','Festa Major de Sant Pere y l''Aplec de Sant Medir','Patronal / Romería / Cultural. Se celebra en Junio (Sant Pere) y Marzo (Sant Medir). Festejos mayores con un gran despliegue de cultura popular que incluye el tradicional "Ball de Piles", castellers de primer nivel, correfocs y grandes conciertos públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08206','fiesta','Festa Major de Sant Cugat Sesgarrigues','Patronal. Se celebra en Julio. Celebración puramente vecinal en la comarca del vino del Penedès, sustentada en ritos religiosos tradicionales, juegos infantiles y cenas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08210','fiesta','Festa Major de Sant Feliu','Patronal / Cultural. Se celebra en Septiembre. Festejos locales tradicionales en el Vallès Oriental que cuentan con pasacalles de gigantes de la comarca, sardanas y verbenas de verano bien secundadas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08211','fiesta','Festes de la Tardor (Sant Rarimi) y Fira de la Tofona de Sant Feliu','Patronal / Etnográfica / Cultural. Se celebra en Octubre. Festejos de gran personalidad comarcal en la capital de la comarca, célebres por su "Seguici Popular", el desfile de la mítica colla de gigantes y espectaculares correfocs.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08212','fiesta','Fira de les Bruixes de Sant Feliu Sasserra','Etnográfica / Recreación Histórica. Se celebra en Noviembre (Todos los Santos). Gran reclamo a nivel provincial sustentado en la teatralización de los históricos juicios por brujería del siglo XVII, inundando el pueblo de pasacalles esotéricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90584','fiesta','Festa Major de Sant Fost *','Patronal *. Se celebra en Septiembre *. Festejos tradicionales en el Vallès Oriental, caracterizados por romerías familiares, partidas de bolos tradicionales aragoneses y actividades lúdicas infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08213','fiesta','Festa de l''Arròs de Sant Fruitós de Bages','Gastronómica / Etnográfica / Tradicional. Se celebra en Febrero (Domingo de Carnaval). Hito gastronómico provincial de alta raigambre que congrega a miles de personas para cocinar y degustar de forma masiva arroz en calderas de hierro al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08020','fiesta','Festa Major de Sant Hipòlit','Patronal. Se celebra en Septiembre. Celebración de carácter tradicional y vecinal en Osona, estructurada en torno a ritos religiosos tradicionales, pasacalles infantiles y verbenas de peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08193','fiesta','Festa Major de Sant Iscle y Festa del Bolet','Patronal / Gastronómica. Se celebra en Noviembre. Festejos de otoño que giran en torno a la recogida tradicional y degustación de setas del Montnegre, combinados con actos litúrgicos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08216','fiesta','Festa Major de Sant Jaume','Patronal. Se celebra en Julio. Festejos mínimos en el segundo municipio menos poblado de la provincia, limitados a la liturgia tradicional en su joya de iglesia románica y una comida de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90585','fiesta','Festa Major de Sant Joan y Fira de l''Embarrat','Patronal / Recreación Histórica. Se celebra en Junio (Festa Major) y Octubre (Fira). Festejos que combinan la tradición local con la espectacular feria de recreación histórica de la vida textil e industrial del siglo XIX junto al río Cardener.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08217','fiesta','Festa Major de Sant Joan Despí','Patronal / Cultural. Se celebra en Junio. Festejos de rango comarcal integrados en la zona metropolitana, con un cuidado programa de actuaciones folclóricas catalanas, correfocs y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08903','fiesta','Festa de la Fia-Faia de Sant Julià de Cerdanyola','Etnográfica / Tradicional / Fuego. Se celebra en Diciembre (Nochebuena). Declarada Fiesta de Interés Turístico de Cataluña de forma agrupada. Ancestral rito de fuego navideño donde los vecinos descienden de la montaña con antorchas de hierba.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08220','fiesta','Caramelles de Sant Julià de Vilatorta','Etnográfica / Cantos Tradicionales. Se celebra en Abril (Pascua). Hito folclórico de primer nivel en Osona, célebre por la antiquísima y documentada tradición de sus cantos de caramelles con indumentaria tradicional catalana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08221','fiesta','Festes de Sant Just y de Sant Just i Pastor','Patronal / Cultural. Se celebra en Agosto. Festejos tradicionales que incluyen las famosas carreras de carricoches de cojinetes, pasacalles de gigantes de la zona, sardanas y conciertos en los parques.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08222','fiesta','Festa Major de Sant Llorenç','Patronal / Enológica. Se celebra en Agosto. Festejos tradicionales del Alt Penedès basados en el reencuentro estival, comidas populares en las bodegas locales y competiciones lúdicas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08223','fiesta','Festa Major de Sant Llorenç y de la Mare de Déu dels Àngels','Patronal. Se celebra en Agosto. Festejos de arraigo local tradicionales en el parque natural de Sant Llorenç del Munt, con pasacalles de gigantes de la comarca, correfocs y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90586','fiesta','Festa Major de Sant Martí','Patronal. Se celebra en Noviembre. Pequeña celebración de invierno de marcado ambiente familiar e infantil dirigida estrictamente a la escasa población rural de este núcleo de Osona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08224','fiesta','Festa Major de Sant Martí','Patronal. Se celebra en Noviembre. Celebración puramente vecinal condicionada por la dispersión geográfica del término, estructurada en torno a ritos religiosos tradicionales y verbenas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08226','fiesta','Festival de Llegendes de Catalunya (FesLleCat) y Festa Major','Cultural / Etnográfica / Patronal. Se celebra en Julio (Festival) y Noviembre (Patronal). Su singular festival de leyendas posee rango provincial y convierte el pueblo medieval en un gran escenario de cuentacuentos y mitología tradicional catalana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08227','fiesta','Festa Major de Sant Martí Sarroca','Patronal / Enológica. Se celebra en Julio. Festejos junto al conjunto monumental del castillo e iglesia románica, caracterizados por pasacalles de gigantes de la comarca, castellers del Penedès y degustaciones de vino.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90679','fiesta','Festa Major de Sant Martí','Patronal. Se celebra en Septiembre. Festejos locales de carácter tradicional en la alta Anoia, basados en juegos infantiles tradicionales, comidas de hermandad y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08229','fiesta','Festa Major de Sant Mateu','Patronal. Se celebra en Septiembre. Pequeñas fiestas de arraigo vecinal debido a la extrema dispersión de masías, estructuradas en torno a actos religiosos y comidas compartidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90587','fiesta','Festa Major de Sant Pere y de Sant Pau','Patronal / Etnográfica / Cultural. Se celebra en Enero y Junio. Festejos de gran arraigo comarcal en el Garraf, célebres por la espectacularidad y cantidad de sus bailes populares tradicionales: bastons, cercolets, diablos y gigantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08233','fiesta','Festa Major de Sant Pere y de la Mare de Déu de la Tosca','Patronal / Romería. Se celebra en Junio. Festejos locales que incluyen la romería tradicional al santuario mariano de la Tosca, uniendo fe, pasacalles tradicionales y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08234','fiesta','Festa Major de Sant Pere y de Sant Elies','Patronal / Romería. Se celebra en Junio. Celebración de arraigo tradicional en el Vallès Oriental con romerías a la ermita de montaña, actuaciones folclóricas catalanas y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90885','fiesta','Festa Major de Sant Pere y Festival de Música','Patronal / Cultural. Se celebra en Junio. Festejos estivales en un entorno medieval muy bien conservado, que complementan los ritos religiosos tradicionales con conciertos de música de cámara.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08235','fiesta','Festa Major de Sant Jaume y de Sant Pau','Patronal / Marinera. Se celebra en Enero y Julio. Festejos costeros con notable arraigo que combinan la espectacular "Fira de la Maduixa", pasacalles de gigantes de la comarca frente al mar y la tradicional quema de fuegos artificiales en la playa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08236','fiesta','Festa Major de Sant Quintí y Festa del Most','Patronal / Etnográfica / Enológica. Se celebra en Noviembre. Destaca en el Alt Penedès por el hito tradicional de su "Festa del Most", con pisada de uva comarcal tradicional, pasacalles de diablos folclóricos locales y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90886','fiesta','Festa Major de Sant Quirze y de Santa Maria','Patronal. Se celebra en Junio. Festejos de rango local a orillas del Ter, destacados por las regatas humorísticas de barcas tradicionales, cantadas de habaneras y bailes de sardanas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08238','fiesta','Festa Major de Sant Quirze y Mostra de Cuina Tradicional','Patronal / Cultural. Se celebra en Septiembre. Festejos de notable dinamismo comarcal en el Vallès Occidental, caracterizados por su concurrido pasacalles de gigantes, activos correfocs con bestias de fuego locales y un potente tejido asociativo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90887','fiesta','Festa Major de Sant Quirze Safaja','Patronal. Se celebra en Agosto. Festejos tradicionales de marcado carácter veraniego y familiar en el Moianès, condicionados por su baja demografía, sustentados en comidas populares y verbenas lúdicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08240','fiesta','Fires i Festes de Sant Sadurní (Festa de la Fil·loxera)','Enológica / Etnográfica / Cultural. Se celebra en Septiembre. Declarada Fiesta de Interés Turístico del Principado. Espectacular y multitudinario hito etnográfico donde destaca el desfile pirotécnico y de fuego amarillo de la Filoxera, que conmemora la victoria vitivinícola sobre la plaga.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90680','fiesta','Festa Major de Sant Salvador y del Roser','Patronal. Se celebra en Agosto. Festejos de arraigo local tradicionales en la comarca del Bages, caracterizados por campeonatos deportivos locales, tradicionales misas solemnes y bailes populares nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08262','fiesta','Festa Major de Sant Vicenç y el Ball de Gitanes de Castellet','Patronal / Etnográfica. Se celebra en Enero y Julio. Festejos de relevancia local que destacan por la espectacular ejecución de su histórico Ball de Gitanes, un elemento folclórico tradicional de alta raigambre comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08264','fiesta','Festa Major de Sant Vicenç (Festa Major de Hivern) y de Sant Antoni','Patronal. Se celebra en Enero y Agosto. Celebración costera de la comarca del Maresme con notable concurrencia, sustentada en pasacalles populares de gigantes, sardanas en la plaza mayor y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08265','fiesta','Festa Major de Sant Vicenç de Torelló','Patronal. Se celebra en Septiembre. Festejos tradicionales del valle del Ges en Osona, basados en el reencuentro vecinal, comidas de hermandad, gigantes y pequeñas orquestas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08263','fiesta','Auto Sacramental de la Setmana Santa y Festa Major d''Estiu','Religiosa / Teatral / Patronal. Se celebra en Marzo / Abril (Semana Santa) y Julio (Festa Major). Su procesión y representación de la Pasión en catalán posee un alto valor histórico y etnográfico provincial, atrayendo a numerosos visitantes por el realismo de sus pasos vivientes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08244','fiesta','Festa Major de Santa Coloma y la Festa de la Cirera','Patronal / Gastronómica. Se celebra en Mayo (Cirera) y Agosto (Festa Major). Festejos de fuerte arraigo comarcal que ponen en valor la identidad de la Colonia Güell mediante mercados modernistas artesanales y la tradicional muestra de la cereza local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08245','fiesta','Festa Major d''Estiu y Festa Major de Sota','Patronal / Cultural / Urbana. Se celebra en Septiembre. Grandes fiestas mayores de rango metropolitano con un masivo programa lúdico que inunda la ciudad con correfocs multitudinarios, castellers, pasacalles de gigantes y macroconciertos públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08246','fiesta','Festa Major de Santa Eugènia y els Tonis de Santa Eugènia','Patronal / Etnográfica. Se celebra en Enero (Tonis) y Septiembre (Festa Major). Destaca por la celebración tradicional de "Els Tonis", hito etnográfico de Osona con una vistosa cabalgata de carros tradicionales labradores y la bendición de animales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08250','fiesta','Festa Major de Santa Margarida','Patronal / Cultural. Se celebra en Julio. Festejos tradicionales de la cuenca de Òdena con desfiles de peñas juveniles, activos correfocs de diablos locales y verbenas multitudinarias en el casco urbano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90588','fiesta','Festa Major de Santa Margarida y el Ball de Diables dels Monjos','Patronal / Etnográfica. Se celebra en Julio. Festejos del Alt Penedès que destacan por su rico e histórico folclore de fuego, la exhibición de castellers locales y los pasacalles de gigantes y cabezudos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08253','fiesta','Festa Major de Santa Maria de Besora','Patronal. Se celebra en Agosto. Pequeños festejos tradicionales de alta montaña y marcado carácter familiar en el límite con el Ripollès, basados en comidas populares de hermandad y música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08255','fiesta','Festa Major de Santa Maria de Martorelles','Patronal. Se celebra en Julio. Celebración de escala estrictamente local en las faldas de la cordillera Litoral, vertebrada sobre comidas vecinales al aire libre y sesiones de orquesta nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08255','fiesta','Festa Major de Santa Maria de Merlès','Patronal. Se celebra en Agosto. Pequeña celebración vecinal con núcleos de población muy dispersos en el Berguedà oriental, centrada en ritos religiosos tradicionales y un vermut popular comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08257','fiesta','Festa Major de Santa Maria de Miralles','Patronal. Se celebra en Agosto. Mínimos festejos rurales condicionados por la baja demografía en la Anoia, limitados a la santa misa en la iglesia románica tradicional y una comida de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08258','fiesta','Festa Major de Santa Maria d''Oló','Patronal. Se celebra en Agosto. Festejos tradicionales de la comarca del Moianès, caracterizados por pasacalles populares, bailes de sardanas en la plaza de la iglesia y verbenas lúdicas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08259','fiesta','Festa Major de la Mare de Déu del Remei','Patronal / Etnográfica. Se celebra en Octubre. Festejos de arraigo tradicional al pie del Montseny, destacados por su procesión folclórica, el tradicional Ball de Gitanes local recuperado y correfocs de diablos de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08260','fiesta','Festa Major de Santa Perpètua y la Fira de Primavera','Patronal / Cultural. Se celebra en Agosto. Festejos de rango comarcal muy consolidados en el Vallès, con un potente programa lúdico que incluye conciertos masivos, desfiles folclóricos, gigantes y castellers.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08261','fiesta','Festa Major de Santa Susanna','Patronal / Costera. Se celebra en Agosto. Festejos costeros del Maresme potenciados por la población turística veraniega, articulados sobre verbenas masivas, cantadas de habaneras y actividades infantiles locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90589','fiesta','Festa Major de Santpedor y Fira de Sant Miquel','Patronal / Feria Tradicional. Se celebra en Junio (Festa Major) y Septiembre (Fira). Festejos de relevancia comarcal en el Bages; su feria tradicional medieval destaca provincialmente por sus muestras de oficios tradicionales artesanales y folclore local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90590','fiesta','Festa Major de Sentmenat','Patronal / Cultural. Se celebra en Septiembre. Fiestas patronales tradicionales del Vallès Occidental, caracterizadas por el desfile de gigantes y cabezudos, pasacalles pirotécnicos de diablos y orquestas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08269','fiesta','Festa de la Cendra i de la tòfona de Seva y Festa Major de Santa Maria','Gastronómica / Patronal. Se celebra en Agosto (Patronal) y Enero (Tòfona) *. Su feria gastronómica invernal dedicada a la trufa negra del Montseny posee un notable arraigo provincial, atrayendo a numeroso público y mercados gourmet.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08023','fiesta','Festa Major de Sant Bartomeu i Santa Tecla','Patronal / Etnográfica / Pirotécnica. Se celebra en Agosto y Septiembre. Declarada Fiesta de Interés Turístico Nacional. Máximo hito del folclore costero de Cataluña, célebre por la espectacular exhibición de sus ancestrales balls populars (moixiganga, gitanas) y su colosal castillo de fuegos artificiales marítimo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08271','fiesta','Festa Major de Sant Martí de Sobremunt','Patronal. Se celebra en Noviembre. Mínimos festejos rurales en una de las zonas menos pobladas de Osona, limitados a actos religiosos tradicionales, campeonatos de guiñote y comidas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08272','fiesta','Festa Major de Sant Pere de Sora','Patronal. Se celebra en Junio. Festejos de ámbito puramente local y de carácter familiar en el norte de la provincia, sustentados en la santa misa tradicional y una cena comunitaria para los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08273','fiesta','Festa Major de Sant Pau d''Ordal y Festa del Préssec','Patronal / Gastronómica / Enológica. Se celebra en Julio (Préssec) y Septiembre (Patronal). Festejos tradicionales que promueven los productos locales del Penedès mediante el mercado de su afamado melocotón de viña y catas artesanales de vino y cava.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08274','fiesta','Caramelles de Súria y Festa Major de Súria','Etnográfica / Musical / Patronal. Se celebra en Marzo / Abril (Pascua) y Julio (Festa Major). Declarada Fiesta de Interés Turístico de Cataluña. El mayor y más importante hito de caramelles de Cataluña, donde cientos de cantaires e históricos trabucaires inundan el pueblo de música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08276','fiesta','Festa Major de Santa Maria de Tagamanent','Patronal / Romería. Se celebra en Septiembre. Festejos que combinan la romería tradicional a la iglesia románica situada en lo alto del cerro del Montseny con pequeñas comidas vecinales e infantiles locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08277','fiesta','Festa Major de Santa Maria de Talamanca','Patronal / Histórica. Se celebra en Agosto. Festejos estivales a la sombra de su castillo medieval, caracterizados por el reencuentro veraniego de familias vinculadas al pueblo, misas tradicionales y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08278','fiesta','Festa d''en Toca-Sons y Festa Major de Taradell','Etnográfica / Recreación Histórica / Patronal. Se celebra en Agosto. Destaca provincialmente por la singular Fiesta de Toca-Sons, hito etnográfico donde se recrea de forma masiva el asalto y juicio del mítico bandolero catalán en un ambiente con trabucos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90591','fiesta','Festa Major de Sant Esteve de Tavèrnoles','Patronal. Se celebra en Agosto. Festejos tradicionales de marcado carácter rural en el entorno de las Guilleries, basados en el regreso estival, bailes de sardanas de plaza y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08024','fiesta','Festa Major de Sant Cristòfol de Tavertet','Patronal. Se celebra en Julio. Aunque la villa atrae turismo paisajístico constante en sus riscos, sus fiestas mayores mantienen un sabor puramente vecinal y comarcal con pasacalles infantiles y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90592','fiesta','Festa Major de Sant Martí y Fiesta del Vino del Maresme','Patronal / Enológica. Se celebra en Noviembre. Festejos tradicionales de la cordillera Litoral que conservan el tradicional pasacalles de gigantes local, bailes públicos y catas de vinos tradicionales de la DO Alella.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90593','fiesta','Festa Major de Terrassa y Fira Modernista de Terrassa','Patronal / Cultural / Recreación Histórica. Se celebra en Mayo (Fira) y Julio (Festa Major). Su Fira Modernista está declarada de Interés Turístico de Cataluña, hito masivo regional que transforma el centro de la cocapital con recreaciones de época, patrimonio industrial y folclore catalán.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08282','fiesta','Festa Major de Sant Cebrià y de San Antonio','Patronal / Cultural. Se celebra en Septiembre. Festejos de arraigo local tradicionales en el Maresme meridional, consistentes en pasacalles de su colla de gigantes, correfocs de diablos locales y verbenas de noche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08283','fiesta','Festa Major de Sant Andreu y de la Mare de Déu de la Salut','Patronal / Romería. Se celebra en Noviembre. Celebración de la llanura de Vic con tradicionales pasacalles, romería a la ermita románica del castillo histórico y una activa participación vecinal en el pabellón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08284','fiesta','Festa Major de Sant Bartomeu y Fira del Mercado del Ramo','Patronal / Feria Ganadera Tradicional. Se celebra en Agosto. Festejos de rango comarcal muy arraigados en el Alt Maresme, célebres por su histórica feria tradicional de campo, correfocs masivos y un potente ambiente de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08025','fiesta','Carnaval de Terra Endins y Festa Major de Torelló','Etnográfica / Carnaval / Patronal. Se celebra en Febrero (Carnaval) y Julio (Festa Major). Su Carnaval de Terra Endins posee rango e impacto masivo a nivel de toda Cataluña, famoso por el rito etnográfico del "Pullassu", desfiles satíricos multitudinarios y gran ambiente juvenil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08286','fiesta','Festa Major de Sant Joan y de la Virgen del Castillo','Patronal. Se celebra en Junio. Festejos que unifican las tradiciones de sus núcleos residenciales alrededor de su castillo fortificado tradicional, con verbenas al aire libre y juegos para niños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08287','fiesta','Festa Major de Torrelavit','Patronal / Enológica. Se celebra en Agosto. Festejos veraniegos de carácter local en la cuenca del Riudebitlles, sustentados sobre el cultivo vitivinícola tradicional del Penedès, con comidas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08288','fiesta','Festa Major de Sant Genís y l''Aplec de Foix','Patronal / Romería. Se celebra en Agosto. Festejos estivales tradicionales que incluyen la concurrida romería al Santuario de la Mare de Déu de Foix, aunando devoción comarcal y folklore de la tierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08289','fiesta','Festa Major de Sant Martí y Festa de la Cirera','Patronal / Gastronómica. Se celebra en Junio (Cirera) y Noviembre (Sant Martí). Festejos de notable peso comarcal, famosos por la muestra y concurso-exposición de la cereza local tradicional, arropados por castellers populares de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08290','fiesta','Festa Major de Santa Maria y la Festa del Serral','Patronal. Se celebra en Agosto. Festejos de escala estrictamente local en las colinas del Vallès, con tradicionales misas solemnes, comidas de hermandad vecinal y sesiones de baile públicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08291','fiesta','Festa Major de Vacarisses (Festa de la Vaca)','Patronal / Etnográfica. Se celebra en Mayo y Agosto. Destacan por el singular hito tradicional de la "Festa de la Vaca", donde se realiza una comida comunitaria en recuerdo de antiguas leyendas locales, con bailes tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08292','fiesta','Festa Major del Roser (Festa de les Garlandes)','Patronal / Etnográfica. Se celebra en Mayo. Festejos de gran arraigo local tradicionales por la Fiesta de las Guirnaldas, donde las solteras del pueblo (pabordesses) bailan danzas tradicionales en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08293','fiesta','Festa Major de Sant Miquel de Vallcebre','Patronal. Se celebra en Septiembre *. Festejos rurales tradicionales en el alto Berguedà, orientados a la convivencia comunitaria de los vecinos, con ritos religiosos tradicionales mínimos y música local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08294','fiesta','Festa Major de Sant Andreu y la Festa de la Sopa','Patronal / Gastronómica. Se celebra en Noviembre. Festejos tradicionales del interior del Montnegre que destacan por la preparación vecinal masiva de la sopa tradicional caliente para combatir el frío invernal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08295','fiesta','Festa Major de Sant Mateu','Patronal / Cultural. Se celebra en Septiembre. Festejos de arraigo local tradicionales en el Baix Llobregat con pasacalles de gigantes de la zona, potentes correfocs de diablos locales y verbenas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08296','fiesta','Festa Major de Sant Vicenç y de San Miguel','Patronal. Se celebra en Enero y Septiembre. Festejos estivales trasladados de época para asegurar la concurrencia de la población residencial, basados en torneos lúdicos y sesiones de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08297','fiesta','Festa Major de Sant Miquel de Veciana','Patronal. Se celebra en Septiembre. Mínimos festejos rurales distribuidos entre los caseríos y pequeños núcleos dispersos de la alta Anoia, centrados en comidas familiares y ritos religiosos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08026','fiesta','Festa Major de Sant Miquel dels Sants y el Mercat del Ram de Vic','Patronal / Feria Ganadera Tradicional / Etnográfica. Se celebra en Marzo / Abril (Mercat) y Julio (Patronal). Su Mercat del Ram está declarado Fiesta de Interés Turístico por su extraordinario valor identitario como eje agrícola de Osona, reuniendo exhibiciones folclóricas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08299','fiesta','Festa Major de Sant Joan de Vilada','Patronal. Se celebra en Junio. Festejos tradicionales veraniegos en el Prepirineo a orillas de la Baells, orientados a la reunión familiar con comidas de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08301','fiesta','Festa Major de Viladecans (Festa de la Mare de Déu de Sales)','Patronal / Cultural / Etnográfica. Se celebra en Septiembre. Grandes fiestas de rango comarcal muy populares, célebres por su festival de teatro callejero, masiva "Trobada de Gegants" tradicionales, castells y conciertos públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08300','fiesta','Festa Major de Sant Martí de Viladecavalls','Patronal / Cultural. Se celebra en Julio. Festejos de marcado ambiente vecinal y familiar en el Vallès Occidental, con pasacalles tradicionales de gigantes, cenas populares en las calles y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08305','fiesta','Festa Major de Vilafranca del Penedès (Sant Fèlix)','Patronal / Etnográfica / Castelleras. Se celebra en Agosto / Septiembre. Declarada Fiesta de Interés Turístico Nacional. Considerada la "Festa Major de les Festes Majors" en Cataluña por la impresionante pureza de sus balls populars y su mítica e histórica diada castellera mundial de Sant Fèlix.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08306','fiesta','Festa Major de la Mare de Déu de l''Assumpció','Patronal. Se celebra en Agosto. Pequeñas fiestas de arraigo puramente local al pie del Montnegre, estructuradas sobre actos religiosos tradicionales y cenas de hermandad para el vecindario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08303','fiesta','Festa Major de Santa Maria de Vilanova de Sau','Patronal. Se celebra en Agosto. Festejos veraniegos de carácter local vinculados al entorno del embalse de Sau, orientados a comidas populares en el bosque y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90594','fiesta','Festa Major de Vilanova del Camí (Sant Hilari)','Patronal / Cultural. Se celebra en Septiembre. Festejos de fuerte arraigo en el entorno urbano de la Anoia con desfiles tradicionales de peñas, pasacalles infantiles de gigantes y conciertos masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08902','fiesta','Festa Major de Vilanova del Vallès','Patronal. Se celebra en Agosto. Festejos estivales muy dinamizados por las asociaciones del municipio, con pasacalles pirotécnicos de diablos tradicionales locales y cenas al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90026','fiesta','Carnaval de Vilanova i la Geltrú i Festa Major de les Neus','Etnográfica / Carnaval / Patronal. Se celebra en Febrero (Carnaval) y Agosto (Festa Major). Su Carnaval está declarado de Interés Turístico Nacional, hito etnográfico masivo global célebre por las mítica "Les Comparses" donde toneladas de caramelos cubren las calles en batallas pacíficas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08214','fiesta','Festa Major de Sants Genís i Iscle y Festa dels Sants Màrtirs','Patronal / Etnográfica. Se celebra en Agosto. Festejos del interior del Maresme que conservan de forma magnífica sus pasacalles tradicionales de gigantes históricos locales y correfocs de diablos de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08219','fiesta','Festa Major de Sant Joan de Vilassar de Mar','Patronal / Costera / Etnográfica. Se celebra en Junio. Festejos costeros de gran peso comarcal, célebres por la colosal "Arribada del Penjat", pasacalles tradicionales marineros, correfocs de diablos y orquestas masivas en la playa). Hemos completado al 100% de forma exhaustiva todos los municipios de la provincia de Barcelona, cerrando los bloques pendientes desde la letra S hasta la Z. ¿Procedemos a abrir la siguiente provincia según el orden oficial para dejar lista la base de datos de esta Comunidad, que correspondería a la provincia de Girona?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90681','fiesta','Festa Major de Santa Maria y Festa de l''Esquellot','Patronal / Etnográfica. Se celebra en Agosto. Festejos patronales de arraigo estrictamente local en el Alt Empordà, marcados por el retorno estival, bailes de sardanas en la plaza y una alta participación vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90063','fiesta','Festa Major de Sant Joan y Festa de la Mel','Patronal / Gastronómica. Se celebra en Junio (Sant Joan) y Octubre (Mel). Festejos de escala local en el Gironès; su feria gastronómica de la miel destaca comarcalmente por la promoción de la apicultura tradicional y los mercados artesanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90595','fiesta','Festa Major de Sant Pere de Bassegoda','Patronal / Romería. Se celebra en Junio. Pequeña celebración rural condicionada por la baja demografía en la Alta Garrotxa, centrada en una misa tradicional en el entorno románico y comidas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90596','fiesta','Festa Major de Sant Pere de Alp y Fiesta de la Nieve','Patronal / Deportiva. Se celebra en Junio y Diciembre. Festejos estivales tradicionales en la Cerdanya que se combinan con actividades promocionales de deportes de invierno en las estaciones de esquí locales de su término municipal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90597','fiesta','Festa Major d''Amer y la Dansa del Roser (Festa de la Mare de Déu del Roser)','Patronal / Etnográfica. Se celebra en Agosto. Hito etnográfico de gran renombre provincial célebre por la solemne y singular "Dansa del Roser", un baile tradicional en espiral ejecutado de forma masiva en su plaza porticada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90598','fiesta','Festa Major d''Anglès','Patronal / Cultural. Se celebra en Agosto. Festejos de arraigo local tradicionales en la comarca de la Selva, caracterizados por pasacalles de su colla de gegants, correfocs nocturnos de diablos de la zona y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90599','fiesta','Les Enramades d''Arbúcies (Festa de les Enramades)','Etnográfica / Floral / Tradicional. Se celebra en Junio. Declarada Fiesta de Interés Turístico del Principado. Espectacular y multitudinario hito etnográfico donde los vecinos cubren las calles con alfombras monumentales de flores naturales y hojas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90600','fiesta','Festa Major de la Mare de Déu del Guilar','Patronal / Romería. Se celebra en Septiembre. Festejos de la comarca de la Garrotxa, caracterizados por la romería a la ermita románica tradicional de Santa Maria, bailes de sardanas en la plaza y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90601','fiesta','Festa Major de Sant Martí','Patronal. Se celebra en Noviembre. Celebración puramente vecinal en el llano de la comarca del Empordà, fundamentada en actos religiosos tradicionales, campeonatos de cartas locales y pequeñas orquestas en el pabellón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90602','fiesta','Festa Major de Sant Esteve','Patronal. Se celebra en Diciembre. Festejos tradicionales invernales al pie de las ruinas de su encomienda de los templarios, consistentes en misas solemnes, comidas comunitarias y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90603','fiesta','Festes de Sant Martirià (Festa Major de Banyoles)','Patronal / Etnográfica / Cultural. Se celebra en Octubre. Grandes fiestas de la capital del Pla de l''Estany, célebres por su extraordinario valor folclórico de música tradicional, desfiles de cabezudos, castellers masivos y regatas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90604','fiesta','Pessebre Vivent de Bàscara y Festa Major de Sant Vicenç','Teatral / Etnográfica / Patronal. Se celebra en Diciembre/Enero (Pessebre) y Enero (Patronal). Su espectacular Pessebre Vivent está declarado de gran relevancia etnográfica en el Principado, escenificado de forma masiva en los acantilados y cuevas a orillas del río Fluvià.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18001','fiesta','Fira d''Indians de Begur y Festa Major de Sant Pere','Recreación Histórica / Etnográfica / Costera. Se celebra en Septiembre (Indians) y Junio (Sant Pere). Declarada Fiesta de Interés Turístico en el ámbito autonómico. Gran festival que transforma las calles coloniales vistiendo a miles de asistentes de blanco, con música cubana y habaneras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90605','fiesta','Festa Major de Sant Joan y la representación del Bandoler Tocabens','Patronal / Teatral / Histórica. Se celebra en Junio y Agosto. Festejos tradicionales de arraigo local que giran en torno al marco monumental de su castillo palacio condal, incluyendo representaciones de teatro en la calle sobre leyendas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18002','fiesta','Fira Medieval de Besalú y Festa de Sant Vicenç','Recreación Histórica / Etnográfica / Cultural. Se celebra en Septiembre (Fira) y Enero (Patronal). Gran hito de recreación a nivel regional; transforma el inmenso conjunto histórico y su puente medieval con abanderados, mercados artesanales de oficios tradicionales y torneos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90606','fiesta','Festa Major de Sant Llorenç y Fira de l''Embotit d''Amer i de Bescanó','Patronal / Gastronómica. Se celebra en Agosto (Patronal) y Marzo (Fira). Festejos que combinan la cultura popular con una consolidada feria gastronómica comarcal dedicada al embutido artesanal de la tierra, atrayendo a numeroso público.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90607','fiesta','Festa Major de Sant Corneli y Sant Cebrià','Patronal. Se celebra en Septiembre. Mínimos festejos rurales en las proximidades del embalse de Boadella, limitados a actos litúrgicos tradicionales en la plaza de la iglesia, comidas vecinales de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90033','fiesta','Festa Major de Santa Anna y Concurs Internacional de Focs Artificials de la Costa Brava','Patronal / Costera / Pirotécnica. Se celebra en Julio. Declarado hito pirotécnico masivo de enorme impacto en toda Cataluña. Atrae de forma internacional a cientos de miles de espectadores a las playas para ver el espectáculo de fuegos de artificio sobre Sa Palomera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17029','fiesta','Festa Major de Sant Martí de Boadella','Patronal. Se celebra en Noviembre. Festejos de escala estrictamente local a orillas del río Muga, condicionados por la baja demografía del término, basados en verbenas de plaza y ritos litúrgicos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90608','fiesta','Festa Major de Santa Cecília','Patronal. Se celebra en Noviembre. Festejos tradicionales de la comarca de la Cerdanya de marcado carácter invernal y familiar, orientados a juegos de cartas locales, misas solemnes y cenas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90609','fiesta','Festa Major de Sant Esteve','Patronal / Cultural. Se celebra en Septiembre. Festejos de arraigo local tradicionales en la comarca del Gironès, caracterizados por pasacalles populares, bailes de sardanas en la plaza de la iglesia y orquestas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17026','fiesta','Festa Major de Sant Andreu','Patronal. Se celebra en Noviembre. Celebración de ámbito estrictamente local que mantiene las costumbres familiares del llano de la comarca del Empordà, estructurada en torno a comidas vecinales y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17027','fiesta','Festa de l''Olla de Breda (Fira de la Terrissa) y Festa Major de Santa Anna','Etnográfica / Feria de Sector / Patronal. Se celebra en Septiembre (Fira) y Julio (Patronal). Festejos de rango comarcal de alta raigambre dedicados a ensalzar su histórico patrimonio y tradición alfarera y de cerámica artesanal artesana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17028','fiesta','Fira de la Avellana de Brunyola y Festa Major de Sant Fruitós','Gastronómica / Feria Tradicional / Patronal. Se celebra en Octubre (Fira) y Agosto (Patronal) *. Su feria de la avellana posee un notable arraigo comarcal e insular provincial en la Selva, destacando por las muestras agrícolas, degustaciones populares y folclore local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17031','fiesta','Festa Major de Sant Martí de Cabanelles','Patronal. Se celebra en Noviembre. Mínimos festejos de arraigo rural distribuidos entre los caseríos y pequeños núcleos dispersos de su término, centrados en comidas familiares y ritos religiosos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12033','fiesta','Festa Major de Sant Vicenç','Patronal. Se celebra en Enero. Pequeñas fiestas de marcado carácter vecinal y familiar en el llano del Alt Empordà, limitadas a bailes populares de orquesta nocturna en el local social.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17032','fiesta','Festa Major de la Mare de Déu de l''Esperança y de Sant Sebastià','Patronal / Marinera / Etnográfica. Se celebra en Diciembre (Esperança) y Enero (Sebastià). Destaca comarcalmente por la espectacular procesión de Sant Sebastià, donde los marineros y vecinos suben a pie a la ermita de las cumbres coloniales cantando coplas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17033','fiesta','Festa de l''Aigua i de Sant Maurici','Patronal / Cultural / Etnográfica. Se celebra en Septiembre. Festejos de rango comarcal muy consolidados en torno a su patrimonio de aguas termales, caracterizados por conciertos, correfocs locales y desfiles folclóricos de gigantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17034','fiesta','Festa del Vi Nou de Calonge y Festa Major de les Neus','Enológica / Patronal / Gastronómica. Se celebra en Noviembre (Vi Nou) y Agosto (Patronal). Festejos que combinan la cultura costera con el arraigo de su festival de bodegas artesanales del Baix Empordà, abriendo bodegas tradicionales al público de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17035','fiesta','Festa Major de Sant Vicenç de Camós','Patronal. Se celebra en Enero. Celebración de escala estrictamente local en las medianías del Pla de l''Estany, vertebrada sobre comidas vecinales al aire libre y ritos litúrgicos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90888','fiesta','Fira Comarcal de la Primavera de Campllong y Festa Major de Sant Quirze','Feria Agrícola / Tradicional / Patronal. Se celebra en Abril (Fira) y Agosto (Patronal). Su gran feria ganadera tradicional y de maquinaria agrícola de primavera posee rango comarcal de alta raigambre, atrayendo a numerosos visitantes provinciales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18004','fiesta','Festa Major de Sant Patllari y Processó de la Puríssima Sang','Patronal / Religiosa / Etnográfica. Se celebra en Junio. Grandes fiestas del Pirineo con gran calado histórico e identidad en el Ripollès, célebres por el tradicional pasacalles de gigantes de la comarca, bailes de sardanas de plaza y correfocs.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17040','fiesta','Festa Major de Sant Vicenç','Patronal. Se celebra en Enero. Festejos tradicionales de carácter rural y vecinal a los pies de las colinas volcánicas del Gironès, basados en verbenas de plaza y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17041','fiesta','Festa Major de Sant Esteve','Patronal. Se celebra en Diciembre. Pequeña celebración vecinal condicionada por la baja demografía en la zona de la Albera fronteriza, limitada a ritos religiosos tradicionales y un vermut popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17042','fiesta','Festa Major de Santa Àgueda y Feria del Vino del Empordà','Patronal / Enológica. Se celebra en Febrero y Septiembre. Festejos de arraigo local tradicionales en la comarca del vino, estructurados con muestras de cooperativas locales de la DO Empordà, comidas y verbenas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17044','fiesta','Festa Major del Suro y de Santa Tecla','Etnográfica / Feria de Sector / Patronal. Se celebra en Mayo y Junio. Festejos de rango comarcal consolidados dedicados a ensalzar su histórico patrimonio industrial del corcho tradicional, con muestras de artesanos locales y folklore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17046','fiesta','Festa Major de Castellfollit (Festa del Roser)','Patronal / Etnográfica. Se celebra en Septiembre. Aunque la villa atrae turismo masivo internacional por su espectacular acantilado de basalto, sus fiestas mayores mantienen un sabor tradicional comarcal con desfiles de gegants.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90889','fiesta','Festival Medieval Terra de Trobadors y Festa Major de Sant Llorenç','Recreación Histórica / Etnográfica / Cultural. Se celebra en Septiembre (Festival) y Agosto (Patronal). Declarada Fiesta de Interés Turístico de Cataluña. Macrofestejo regional masivo que transforma por completo la histórica capital medieval del condado de Empúries con música de trovadores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90035','fiesta','Carnaval de Platja d''Aro y Festa Major de Platja d''Aro','Carnaval / Costera / Cultural. Se celebra en Febrero (Carnaval) y Agosto (Patronal). Su espectacular Carnaval de la Costa Brava posee rango e impacto masivo de gran afluencia a nivel de toda la comunidad autónoma, célebre por su Gran Desfile de carrozas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17049','fiesta','Festa Major de Celrà (Sant Feliu)','Patronal / Cultural. Se celebra en Septiembre. Fiestas patronales tradicionales del Gironès, caracterizadas por pasacalles de su colla de gegants, correfocs de diablos locales con bestias de fuego y orquestas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17050','fiesta','Festa Major de Sant Silvestre','Patronal. Se celebra en Diciembre. Festejos invernales tradicionales de carácter vecinal a orillas del río Ter, basados en ritos litúrgicos tradicionales, pasacalles locales y bailes en el local multiusos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17051','fiesta','Festa Major de Sant Martí de Cistella','Patronal. Se celebra en Noviembre. Mínimos festejos vecinales en una zona rural de baja demografía del Alt Empordà, limitados a una misa tradicional en el templo románico y comidas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17054','fiesta','Festa Major de Sant Miquel','Patronal / Costera. Se celebra en Septiembre. Festejos tradicionales de marcado carácter veraniego e identitario en la costa septentrional de la Costa Brava, con cantadas de habaneras, verbenas de plaza y juegos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17055','fiesta','Festa Major de Santa Maria de Colomers','Patronal. Se celebra en Agosto. Pequeña celebración de marcado ambiente vecinal y familiar en el Baix Empordà, centrada en comidas comunitarias de hermandad al aire libre y música nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90890','fiesta','Festa Major de Sant Julià i Santa Basilissa','Patronal. Se celebra en Octubre. Festejos tradicionales locales que integran pasacalles populares infantiles, tradicionales actos litúrgicos solemnes y bailes públicos para los vecinos del núcleo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17056','fiesta','Festa del Pi de Cornellà del Terri (Festa de Maig)','Etnográfica / Tradicional / Folclórica. Se celebra en Abril / Mayo (Lunes de Pascua). Declarada Fiesta de Interés Turístico de Cataluña. Hito etnográfico absoluto donde los jóvenes talan y enraman un pino monumental en la plaza mayor para bailar el Ball del Cornut.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17058','fiesta','Fira del Jou d''Abelles de Crespià (Fira de la Mel)','Gastronómica / Feria Tradicional. Se celebra en Febrero. Su histórica feria tradicional invernal de la miel posee un arraigo comarcal de alta raigambre en el Pla de l''Estany, reuniendo mercados artesanos y folklore local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90891','fiesta','Festa Major de Monells y Festa de Sant Joan de Cruïlles','Patronal / Etnográfica. Se celebra en Agosto. Festejos de gran sabor tradicional en el Baix Empordà que unifican la identidad de sus tres núcleos históricos, destacando los pasacalles de gigantes y cabezudos y las sardanas en sus monumentales plazas medievales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17060','fiesta','Festa Major de Sant Esteve de Darnius','Patronal. Se celebra en Diciembre. Festejos invernales de marcado carácter vecinal y familiar en el Alt Empordà, articulados en torno a ritos religiosos tradicionales, comidas populares de hermandad y música local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17061','fiesta','Festa Major de Sant Llorenç de Das','Patronal. Se celebra en Agosto. Pequeña celebración de verano en el entorno rural de la Cerdanya, sustentada en el reencuentro de veraneantes de segundas residencias, juegos infantiles y cenas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18006','fiesta','Festa de la Sal de L''Escala y Festa Major de Santa Màxima','Etnográfica / Marinera / Gastronómica. Se celebra en Septiembre (Festa de la Sal). La Festa de la Sal posee un gran empaque y trascendencia regional, recreando de forma masiva los antiguos oficios de salazón de la anchoa, la llegada de barcos de vela tradicionales y danzas marineras ancestrales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17064','fiesta','Fira de l''Oli i de l''Olivera de Espolla','Gastronómica / Feria Tradicional. Se celebra en Enero. Festejos del Alt Empordà con notable raigambre provincial, célebres por la promoción comercial de sus aceites locales con denominación, el tradicional concurso de sopladores de huesos de oliva y canciones tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17065','fiesta','Fira de la de la Calabassa de Esponellà y Festa Major de Sant Cebrià','Gastronómica / Feria Ganadera Tradicional. Se celebra en Octubre. Festejos tradicionales de la comarca del Pla de l''Estany que combinan la espectacular muestra y concurso de calabazas gigantes artesanales con música folclórica en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90892','fiesta','Festa Major de Sant Martí','Patronal. Se celebra en Noviembre. Celebración de ámbito estrictamente local y de carácter vecinal, estructurada sobre la santa misa tradicional en su iglesia fortificada histórica y un vermut popular comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17066','fiesta','Fires i Festes de Santa Creu de Figueres','Patronal / Cultural / Desfile. Se celebra en Mayo. Grandes fiestas mayores de la capital del Alt Empordà, caracterizadas por un potente programa lúdico que incluye conciertos masivos, pasacalles de su histórica colla de gigantes tradicionales, ferias del libro y del juguete artesanal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90893','fiesta','Festa Major de Sant Cebrià de Flaçà','Patronal. Se celebra en Septiembre. Festejos tradicionales de carácter familiar en la comarca del Gironès, consistentes en pasacalles musicales con gigantes de la comarca, campeonatos de cartas y orquestas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17068','fiesta','Festa Major de Sant Romà de Foixà','Patronal. Se celebra en Noviembre. Mínimos festejos rurales condicionados por la baja demografía y la dispersión de masías, limitados a la liturgia tradicional en la iglesia románica histórica y comidas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17070','fiesta','Festa Major de Sant Martí de Fontanilles','Patronal. Se celebra en Noviembre. Pequeña celebración vecinal con un programa lúdico y religioso mínimo adaptado a la escasa población de este núcleo del interior del Baix Empordà.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17069','fiesta','Festa Major de Queixans y Urtx','Patronal. Se celebra en Agosto. Festejos estivales unificados que dinamizan los pequeños caseríos del municipio pirenaico en torno al regreso de familias vinculadas al pueblo, con verbenas y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17071','fiesta','Festa Major de Sant Feliu de Fontcoberta','Patronal. Se celebra en Agosto. Festejos veraniegos marcados por la hermandad vecinal, con tradicionales misas solemnes, comidas populares al aire libre y música de orquesta regional para los habitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17902','fiesta','Festa de la de la Carbonera de Forallac y Festa Major del Roser','Etnográfica / Recreación Histórica / Patronal. Se celebra en Octubre (Carbonera). Destaca provincialmente por la singular Fiesta de la Carbonera, hito etnográfico donde se enciende una pira tradicional de madera en pleno bosque para fabricar carbón vegetal artesanal durante dos semanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17073','fiesta','Festa Major de Sant Cugat y la Festa del Trenet','Patronal / Cultural. Se celebra en Julio. Festejos patronales tradicionales del Gironès, muy dinamizados por su histórica afición al maquetismo ferroviario, sumando pasacalles de gigantes de la comarca y verbenas lúdicas en la campa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17074','fiesta','Festa Major de Sant Julià de Fortià','Patronal. Se celebra en Enero y Septiembre. Celebración de escala estrictamente local en el llano de la comarca, vertebrada sobre comidas populares de hermandad vecinal, música tradicional y actividades para niños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17075','fiesta','Festa Major de Sant Miquel de Garrigàs','Patronal. Se celebra en Septiembre. Pequeñas fiestas de arraigo puramente local con ritos religiosos tradicionales, campeonatos de guiñote y orquestas reducidas dirigidas a la población local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17076','fiesta','Festa Major de Sant Sadurní de Garrigoles','Patronal. Se celebra en Noviembre. Festejos mínimos celebrados en época otoñal de carácter estrictamente familiar debido a la escasa población de este municipio rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17077','fiesta','Festa Major de la de la Mare de Déu de l''Assumpció','Patronal / Enológica. Se celebra en Agosto. Festejos tradicionales de la zona vitivinícola de la DO Empordà, caracterizados por pasacalles de cooperativa, catas populares de vinos locales y verbenas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17078','fiesta','Festa Major de Sant Coloma de Ger','Patronal. Se celebra en Diciembre. Celebración puramente invernal y local en el Pirineo cerdanyolés, sustentada en ritos litúrgicos tradicionales, campeonatos de naipes y cenas comunitarias en el local social.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18005','fiesta','Fires i Festes de Sant Narcís de Girona','Patronal / Etnográfica / Cultural. Se celebra en Octubre / Noviembre. Declarada Fiesta de Interés Turístico Nacional. Macrocelebración de enorme impacto en toda Cataluña, célebre por la procesión de las moscas de Sant Narcís, gigantes monumentales, espectaculares castellers y conciertos públicos masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17081','fiesta','Festa Major de la Mare de Déu del Remei','Patronal. Se celebra en Octubre. Pequeña festividad local del Baix Empordà que congrega a los habitantes en torno a una misa solemne tradicional, bailes de sardanas en la plaza y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17082','fiesta','Festa Major de Guils de Cerdanya y la Festa de l''Aplec de Fontanera','Patronal / Romería. Se celebra en Mayo y Agosto. Festejos de montaña que incluyen la romería tradicional a las praderías de alta montaña, complementada con el regreso estival, bailes de plaza y música de acordeón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17083','fiesta','Festa Major d''Hostalric y la Fira Medieval d''Hostalric','Feria Tradicional / Recreación Histórica / Patronal. Se celebra en Julio (Festa Major) y Marzo / Abril (Fira) *. Su feria medieval medieval posee rango comarcal de alta popularidad, transformando por completo su imponente recinto fortificado histórico con espectáculos de época y mercados artesanales). Hemos completado al 100% todos los municipios de la provincia de Girona hasta la letra I de forma rigurosa, siguiendo el orden alfabético estricto. ¿Deseas continuar con el Siguiente Bloque de la provincia de Girona (Letras de la J en adelante.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17085','fiesta','Festa Major de Sant Antoni Abat','Patronal. Se celebra en Agosto. Festejos estivales de arraigo local tradicionales en la comarca del Baix Empordà, basados en actividades familiares, comidas populares junto al río Ter y bailes en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17086','fiesta','Festa Major de la de la Mare de Déu de l''Assumpció','Patronal / Cultural. Se celebra en Agosto. Festejos fronterizos con notable dinamismo, caracterizados por el pasacalles de gigantes de la comarca, correfocs de diablos locales de la Albera y conciertos públicos en el pabellón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17087','fiesta','Festa Major de Sant Pere de Juià','Patronal. Se celebra en Septiembre. Pequeña celebración rural que unifica la escasa población de este núcleo del Gironès en torno a ritos religiosos tradicionales, bailes de sardanas de plaza y un vermut popular comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17088','fiesta','Fira del Formatge Artesà de Lladó y Festa Major de Sant Feliu','Gastronómica / Feria Tradicional. Se celebra en Septiembre. Su feria gastronómica del queso artesanal posee un notable arraigo provincial en el Alt Empordà, atrayendo a numeroso público para degustaciones y mercados tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17089','fiesta','Festa Major de Llagostera y la Fira del Bolet','Patronal / Gastronómica / Feria Tradicional. Se celebra en Mayo (Festa Major) y Octubre (Fira). Festejos de rango comarcal muy consolidados en el Gironès; su feria otoñal de setas destaca provincialmente por sus muestras culinarias, mercados y pasacalles tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17090','fiesta','Festa Major de Sant Cristòfol de Llambilles','Patronal. Se celebra en Julio. Celebración de ámbito estrictamente local vertebrada sobre la bendición tradicional de vehículos, juegos infantiles, comidas populares de hermandad vecinal y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90610','fiesta','Festa Major de Sant Vicenç y la Festa de la Mare de Déu del Carme','Patronal / Marinera. Se celebra en Enero y Julio. Festejos costeros de gran arraigo en el Alt Empordà, célebres por la tradicional procesión marítima de la Virgen del Carmen arropada por barcos de pescadores y verbenas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18008','fiesta','Festa Major del Roser de Llívia y la Festa de la Transhumància','Patronal / Etnográfica. Se celebra en Mayo y Octubre. Aunque la villa atrae constante turismo en su enclave histórico en los Pirineos, sus fiestas mantienen una alta identidad con el baile de las cintas y la bienvenida tradicional ganadera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17095','fiesta','Festa Major de Santa Cristina (Ball de Plaça)','Patronal / Marinera / Etnográfica. Se celebra en Julio. Declarada Fiesta de Interés Turístico del Principado. Espectacular hito etnográfico masivo en la Costa Brava con la histórica procesión marítima hasta la ermita y el ancestral Ball de les Almorratxes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17097','fiesta','Festa Major de Sant Esteve de Madremanya','Patronal. Se celebra en Agosto. Festejos tradicionales de marcado carácter veraniego y familiar en las Gavarres, condicionados por su baja demografía, sustentados en comidas populares y música local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17098','fiesta','Festa Major de Sant Vicenç de Maià','Patronal. Se celebra en Enero y Septiembre. Pequeños festejos tradicionales de la comarca de la Garrotxa, basados en la hermandad vecinal, ritos religiosos tradicionales, juegos para niños y orquestas reducidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17100','fiesta','Festa Major de la Mare de Déu de l''Assumpció','Patronal. Se celebra en Agosto. Mínimos festejos vecinales en una zona rural de baja demografía del Alt Empordà, limitados a ritos litúrgicos tradicionales en la iglesia de San Martín y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17102','fiesta','Festa Major de Sant Martí de Maçanet','Patronal. Se celebra en Noviembre. Festejos tradicionales del Pirineo ampurdanés caracterizados por el regreso estival de familias vinculadas al pueblo, misas tradicionales, competiciones locales y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17103','fiesta','Festa Major de Sant Llorenç y la Fira de pagès y artesans','Patronal / Feria Tradicional. Se celebra en Agosto (Festa Major) y Noviembre (Fira). Festejos de arraigo tradicional en la Selva, caracterizados por el desfile de gigantes de la comarca, activos correfocs pirotécnicos de diablos locales y cenas comunitarias al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17099','fiesta','Festa Major de Sant Serni de Meranges','Patronal. Se celebra en Noviembre. Mínima expresión festiva de carácter estrictamente familiar en el municipio más alto del Pirineo gerundense, centrada en una misa tradicional y vermut vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17106','fiesta','Festa Major de Sant Tomàs','Patronal. Se celebra en Noviembre. Pequeña celebración vecinal con un programa lúdico y religioso mínimo adaptado a la escasa población de este núcleo agrícola del interior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17107','fiesta','Festa Major de Santa Cecília de Molló','Patronal. Se celebra en Noviembre. Festejos locales tradicionales en el valle de Camprodon alrededor de su monumental iglesia románica de Santa Cecilia, con sardanas y comidas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17110','fiesta','Festa Major de Sant Esteve de Montras','Patronal. Se celebra en Agosto. Festejos locales tradicionales del Baix Empordà orientados a las actividades familiares de verano, con comidas populares en el local social y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17111','fiesta','Festa Major de Sant Antoni Abat de Navata','Patronal. Se celebra en Enero y Julio. Festejos veraniegos que dinamizan el municipio ampurdanés combinando la santa misa tradicional y pasacalles folclóricos con verbenas de plaza muy concurridas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17112','fiesta','Festa Major de Santa Bàrbara (Festa de la Mineria)','Patronal / Etnográfica / Recreación. Se celebra en Diciembre. Festejos tradicionales marcados por el recuerdo histórico de sus antiguas minas de carbón del Ripollès, con cantos de coros tradicionales y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17114','fiesta','Festes del Tura de Olot','Patronal / Etnográfica / Cultural. Se celebra en Septiembre. Declarada Fiesta de Interés Turístico de Cataluña. Hito absoluto de la cultura popular de la Garrotxa, famosa por el místico Ball de Gegants, Nens i Cabeçuts y espectaculares correfocs.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17115','fiesta','Festa Major de Sant Nicolau de Ordis','Patronal. Se celebra en Diciembre. Pequeñas fiestas de arraigo puramente local con ritos religiosos tradicionales, campeonatos de naipes y orquestas reducidas dirigidas a la población.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17116','fiesta','Festa Major de Sant Pere de Osor y la de la Mare de Déu del Coll','Patronal / Romería. Se celebra en Junio y Septiembre. Festejos tradicionales en las Guilleries que combinan la romería al santuario montañoso con pasacalles de gigantes de la comarca y verbenas lúdicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17117','fiesta','Festes de Primavera de Palafrugell (Carrousel Costa Brava) *','Cultural / Desfile / Carnaval *. Se celebra en Mayo *. Declarada Fiesta de Interés Turístico de Cataluña. Su monumental desfile de carrozas del "Carrousel" destaca de forma provincial por su espectacularidad y masiva afluencia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17118','fiesta','Festa Major de Palamós y la de la Mare de Déu del Carme','Patronal / Marinera / Gastronómica. Se celebra en Junio y Julio. Grandes fiestas costeras del Baix Empordà muy populares, célebres por su procesión marítima de barcos tradicionales, cantadas de habaneras y degustación masiva de su cotizada gamba.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17119','fiesta','Festa Major de Santa Eulàlia','Patronal. Se celebra en Diciembre. Mínimos festejos rurales en el llano del Alt Empordà por la baja demografía, limitados a la santa misa tradicional en la iglesia románica y una comida de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17121','fiesta','Festa Major de Sant Pere de Palausator','Patronal / Histórica. Se celebra en Julio. Festejos tradicionales que visten de fiesta su recinto amurallado medieval, con pasacalles de gigantes de la comarca, bailes de sardanas en la plaza y orquestas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17120','fiesta','Festa Major de Sant Joan de Palausaverdera','Patronal. Se celebra en Agosto. Celebración de ámbito estrictamente local a las faldas de la sierra de Rodes, con tradicionales misas solemnes, comidas de hermandad vecinal y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17123','fiesta','Festa Major de Palol de Revardit y de Sant Martí','Patronal. Se celebra en Noviembre. Pequeñas fiestas estivales trasladadas de época de carácter familiar en el Pla de l''Estany, limitadas a bailes de plaza y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17124','fiesta','Festa Major de Pals (Sant Roc) y Fira de l''Arròs','Patronal / Gastronómica / Histórica. Se celebra en Agosto. Festejos que dinamizan su célebre recinto gótico medieval mediante la siembra tradicional de arroz y la tradicional muestra de cocina arrocera local con parrandas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17125','fiesta','Festa Major de Sant Esteve de Pardines','Patronal. Se celebra en Agosto. Celebración de escala local en el valle del Segadell del alto Pirineo, sustentada en ritos religiosos tradicionales, juegos de cucaña tradicionales y cenas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90894','fiesta','Festa Major de Sant Feliu de Parlavà','Patronal. Se celebra en Agosto. Festejos veraniegos tradicionales basados en la vecindad del Baix Empordà, con misas tradicionales, campeonatos de cartas y orquestas en la pista.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17128','fiesta','Festa Major de Sant Martí de Pau','Patronal / Enológica. Se celebra en Noviembre. Festejos de arraigo local tradicionales por las cosechas de viñedos y olivares del Alt Empordà, estructurados con comidas populares y bailes públicos nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90895','fiesta','Festa Major de Marzà (Sant Isidre)','Patronal. Se celebra en Mayo. Festejos rurales mínimos en una de las zonas menos pobladas de la comarca, centrados en el reencuentro familiar y religioso tradicional del vecindario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17130','fiesta','Festa Major de Sant Isidor de La Pera y Púbol','Patronal / Cultural. Se celebra en Mayo y Agosto. Festejos que unifican las tradiciones de sus núcleos medievales cerca del Castillo de Púbol, con pasacalles infantiles, gigantes de la comarca y verbenas de noche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17132','fiesta','Festa Major de Sant Martí y Festes de Sant Roc','Patronal / Cultural. Se celebra en Agosto y Noviembre. Aunque la villa recibe turismo musical internacional de élite por su festival, sus fiestas mayores mantienen un sabor puramente vecinal y comarcal con gigantes y sardanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17134','fiesta','Festa Major de Sant Vicenç de Planoles','Patronal. Se celebra en Septiembre. Festejos tradicionales de montaña de marcado carácter rural en el valle de Ribes, basados en el regreso estival, bailes tradicionales de plaza y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17135','fiesta','Festa Major de Sant Sebastià de Pont de Molins','Patronal. Se celebra en Enero y Septiembre. Festejos locales tradicionales a orillas del río Muga, caracterizados por campeonatos deportivos locales, tradicionales misas solemnes y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17136','fiesta','Festa Major de Sant Martí de Pontós','Patronal. Se celebra en Noviembre. Pequeña celebración vecinal condicionada por la baja demografía en el interior del Alt Empordà, vertebrada sobre la santa misa y verbenas de plaza locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17137','fiesta','Festa Major de Porqueres (Sant Galderic)','Patronal / Cultural. Se celebra en Mayo. Festejos de arraigo tradicional junto al lago de Banyoles, destacados por su procesión folclórica, el tradicional Ball del Drac local y correfocs de diablos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17138','fiesta','Festa Major de la de la Mare de Déu de la Mercè','Patronal / Marinera. Se celebra en Septiembre. Festejos fronterizos y costeros que combinan cantadas de habaneras en la playa, tradicionales pasacalles, fuegos artificiales y verbenas populares masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90036','fiesta','Festa de la de la Mare de Déu del Carme','Patronal / Marinera. Se celebra en Julio. Festejos costeros en el cabo de Creus muy populares, célebres por la procesión marítima nocturna de barcos tradicionales pescadores y orquestas estivales masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18012','fiesta','Festa de l''Estany de Puigcerdà y Festa del Roser','Cultural / Desfile / Etnográfica. Se celebra en Agosto. Declarada Fiesta de Interés Turístico. Gran desfile de carrozas monumentales de la capital de la Cerdanya que culmina con fuegos artificiales mágicos sobre su célebre lago histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17142','fiesta','Fira del del Terrissaire de Quart y Festa Major de Santa Margarida','Feria Etnográfica / Patronal. Se celebra en Mayo (Fira) y Julio (Festa Major). Su feria de alfarería posee un gran arraigo provincial, poniendo en valor el histórico oficio artesanal tradicional de la cerámica negra local con mercados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17043','fiesta','Festa Major de Sant Just i Sant Pastor de Queralbs','Patronal / Romería / Alta Montaña. Se celebra en Agosto y Septiembre. Festejos pirenaicos que combinan la romería tradicional al Santuario de Núria con bailes de sardanas en sus plazas empedradas de montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17143','fiesta','Festa Major de Sant Julià de Rabós','Patronal. Se celebra en Noviembre. Festejos rurales mínimos en las faldas de la Albera por la extrema baja demografía, centrados en la santa misa tradicional y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17144','fiesta','Festa Major de Sant Vicenç de Regencós','Patronal. Se celebra en Septiembre. Festejos tradicionales de marcado carácter vecinal en el Baix Empordà, basados en verbenas de plaza de la iglesia de San Vicente, sardanas y actividades para niños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17145','fiesta','Festa Major de Ribes de Freser y la Festa de la de la Mel','Patronal / Feria de Sector / Etnográfica. Se celebra en Agosto. Festejos de notable arraigo en el valle del Ripollès, potenciados por el turismo pirenaico y caracterizados por su tradicional feria apícola artesanal, pasacalles de gigantes de la comarca y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17146','fiesta','Festa Major de Sant Martí de Riells','Patronal. Se celebra en Noviembre. Festejos tradicionales de marcado carácter local en las faldas del Montseny, basados en verbenas familiares, la tradicional castañada vecinal y ritos religiosos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17147','fiesta','Festa Major de Ripoll (Festa de Sant Eudald) y la Festa de la de la Llana i el Casament Pagès','Patronal / Etnográfica / Tradicional. Se celebra en Mayo. La Festa de la Llana está declarada de gran empaque comarcal e hito etnográfico regional, recreando de forma masiva el esquilado tradicional de ovejas y una auténtica boda campesina del siglo XVIII.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17148','fiesta','Festa Major de Sant Martí de Riudarenes','Patronal. Se celebra en Noviembre. Celebración de escala local en la comarca de la Selva, sustentada en ritos religiosos tradicionales, pasacalles de gigantes de la comarca y bailes públicos nocturnos en el local social.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17150','fiesta','Festa Major de Sant Llop y la Fira del Porc','Patronal / Gastronómica. Se celebra en Septiembre (Festa Major) y Octubre (Fira). Festejos que combinan sus actos patronales tradicionales con su feria sectorial dedicada a los productos derivados del cerdo, con notable arraigo y degustaciones comarcales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17151','fiesta','Festa Major de Sant Mamet de Riumors','Patronal. Se celebra en Septiembre. Mínima expresión festiva de carácter vecinal debido a la escasa población de este municipio rural del Alt Empordà, limitada a una misa solemne tradicional y un vermut popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18014','fiesta','Carnaval de Roses y Festa Major de la de la Mare de Déu de la de la Salut','Carnaval / Patronal / Costera. Se celebra en Febrero (Carnaval) y Agosto (Festa Major). Su Carnaval posee rango e impacto masivo a nivel de toda la provincia, famoso por sus multitudinarias e históricas rúas de carrozas y disfraces satíricos a lo largo del paseo marítimo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17153','fiesta','Festa Major de Sant Llorenç de Rupià','Patronal. Se celebra en Agosto. Celebración de ámbito estrictamente local y de carácter familiar en el Baix Empordà, centrada en el reencuentro estival, bailes de sardanas en la plaza medieval y pequeñas orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17154','fiesta','Festa Major de Sant Martí de Sales','Patronal. Se celebra en Noviembre. Festejos tradicionales de carácter familiar limitados al municipio debido a la extrema baja demografía del núcleo rural de la Garrotxa, centrados en actos religiosos tradicionales mínimos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17157','fiesta','Festa Major de Sant Andreu Salou','Patronal. Se celebra en Noviembre. Mínimos festejos vecinales condicionados por ser uno de los municipios con menor población de la provincia, basados en una comida de hermandad y ritos tradicionales religiosos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17183','fiesta','Festa Major de Sant Aniol y l''Aplec de Finestres','Patronal / Romería. Se celebra en Octubre. Pequeña celebración vecinal con núcleos de población muy dispersos, vertebrada en torno a la romería tradicional a la ermita románica y comidas comunitarias locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90896','fiesta','Festa Major de Sant Climent y la Fira de la de la Garriga d''Empordà','Patronal / Feria Tradicional. Se celebra en Noviembre. Festejos de otoño de arraigo local, consistentes en pasacalles musicales, muestras de aceites y productos artesanales locales y bailes públicos en el pabellón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17159','fiesta','Festa Major de Sant Feliu de Buixalleu','Patronal. Se celebra en Agosto. Celebración puramente vecinal en los diferentes núcleos residenciales y masías dispersas del término, sustentada en comidas populares y pequeñas verbenas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17160','fiesta','Festa Major de Sant Feliu de Guíxols','Patronal / Costera / Cultural. Se celebra en Agosto. Grandes festejos de verano de enorme concurrencia turística en la Costa Brava, con un amplio recinto ferial, pasacalles de gigantes tradicionales, fuegos artificiales marítimos y conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17161','fiesta','Festa Major de Sant Feliu de Pallerols y el Ball de Cavallins','Patronal / Etnográfica. Se celebra en Mayo (Pascua de Pentecostés). Destaca provincialmente por el singular y antiquísimo Ball de Cavallins, Mulassa i Gegants, hito etnográfico de la Garrotxa catalogado de alto valor folclórico tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17162','fiesta','Festa Major de Sant Ferriol y l''Aplec del Santuari','Patronal / Romería. Se celebra en Septiembre. Pequeña festividad local estructurada en torno a la romería tradicional a su histórico santuario forestal, uniendo fe comarcal mínima y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17163','fiesta','Festa Major de Sant Gregori y la Fira del Pa i la Xocolata','Patronal / Gastronómica. Se celebra en Julio (Festa Major) y Noviembre (Fira). Festejos tradicionales del Gironès que dinamizan el municipio con pasacalles populares, verbenas de verano y una concurrida feria gastronómica artesanal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17164','fiesta','Via Crucis Vivent de Sant Hilari Sacalm y Festa Major de Joanet','Religiosa / Teatral / Etnográfica. Se celebra en Marzo / Abril (Semana Santa) y Agosto (Festa Major). Declarada Fiesta de Interés Turístico de Cataluña. Su Via Crucis está considerado un hito etnográfico de primer nivel por el sobrecogedor realismo de las representaciones vivientes en las calles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17165','fiesta','Festa Major de Sant Jaume de Llierca','Patronal. Se celebra en Julio. Festejos locales tradicionales orientados a las actividades familiares de verano, con tradicionales misas solemnes, comidas populares en la plaza y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08021','fiesta','Festa Major del del Santíssim Misteri y el Ball de de Pabordes','Patronal / Etnográfica / Histórica. Se celebra en Septiembre. Hito etnográfico de gran renombre provincial célebre por la antiquísima y solemne ejecución del Ball de Pabordes, una joya del folclore tradicional de Cataluña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17168','fiesta','Festa Major de Sant Joan de Mollet','Patronal. Se celebra en Agosto. Pequeñas fiestas estivales de marcado ambiente familiar e infantil dirigidas estrictamente a la población local del término municipal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17185','fiesta','Festa Major de Sant Joan les Fonts y la Mostra de oficis tradicionals','Patronal / Cultural. Se celebra en Junio. Festejos de arraigo tradicional en la zona volcánica de la Garrotxa con pasacalles de gigantes de la comarca, correfocs locales y comidas de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17166','fiesta','Festa Major de Sant Jordi Desvalls','Patronal. Se celebra en Abril y Agosto. Festejos tradicionales junto al río Ter basados en el reencuentro estival, comidas de hermandad vecinal, juegos para niños y pequeñas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17169','fiesta','Festa Major de Sant Julià de Ramis i de Medinyà','Patronal / Cultural. Se celebra en Septiembre *. Festejos locales que unifican las tradiciones de sus núcleos de población históricos con pasacalles populares, bailes de sardanas de plaza y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17903','fiesta','Festa Major de Bonmatí y de Sant Julià','Patronal. Se celebra en Julio. Festejos de carácter local trasladados a la época estival para asegurar la concurrencia, basados en torneos deportivos tradicionales y sesiones de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17171','fiesta','Festa Major de Sant Llorenç y la Festa del del Trull','Patronal / Feria Tradicional. Se celebra en Agosto. Festejos veraniegos en este espectacular casco fortificado tradicional del Alt Empordà, destacando por su muestra artesanal de elaboración de aceites y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90897','fiesta','Festa Major de Sant Martí de Llémena','Patronal. Se celebra en Noviembre. Pequeña celebración de invierno de marcado carácter vecinal y familiar en el valle de Llémena, limitada a misas tradicionales y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17173','fiesta','Festa Major de Sant Martí Vell','Patronal. Se celebra en Noviembre. Mínimos festejos rurales distribuidos entre el pequeño núcleo histórico y las masías dispersas del Gironès, centrados en la santa misa tradicional y encuentro vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17174','fiesta','Festa Major de Sant Miquel de Campmajor','Patronal. Se celebra en Septiembre. Pequeños festejos tradicionales de marcado carácter rural en el Pla de l''Estany, basados en la convivencia comunitaria, jotas y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17175','fiesta','Festa Major de Sant Miquel de Fluvià','Patronal. Se celebra en Septiembre. Festejos locales tradicionales en torno a su monumental monasterio románico, con tradicionales misas solemnes, pasacalles infantiles y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17176','fiesta','Festa Major de Sant Mori','Patronal. Se celebra en Agosto. Mínimos festejos de arraigo puramente local en el Alt Empordà condicionados por la baja demografía, centrados en comidas familiares de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17177','fiesta','Festa Major de Sant Pau y la Festa del del Remei','Patronal / Romería. Se celebra en Agosto y Septiembre. Festejos tradicionales del Ripollès que combinan romerías familiares por su histórica vía romana con verbenas estivales en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17178','fiesta','Festa Major de Sant Pere Pescador','Patronal / Costera / Deportiva. Se celebra en Junio. Festejos costeros del golfo de Roses potenciados por el turismo internacional de camping y los eventos de windsurf tradicionales, con verbenas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17180','fiesta','Festa Major de Santa Coloma y la Festa de la de la Ratafia','Patronal / Gastronómica / Etnográfica. Se celebra en Septiembre (Festa Major) y Noviembre (Ratafia). Su fiesta dedicada a la ratafia artesanal posee gran relevancia comarcal e hito de Cataluña, reuniendo concursos tradicionales de destilación de licores de hierbas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17181','fiesta','Festa Major de Santa Cristina d''Aro','Patronal / Costera. Se celebra en Julio. Festejos del Empordà meridional con notable afluencia turística veraniega, articulados sobre pasacalles tradicionales de gigantes, correfocs y grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90898','fiesta','Festa Major de Santa Llogaia d''Àlguema','Patronal. Se celebra en Septiembre. Pequeñas fiestas rurales de ámbito vecinal y baja demografía en el llano de la comarca, con un programa lúdico mínimo adaptado al vecindario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17184','fiesta','Fira de Sant Antoni (Festa del del Fesol) y Festa Major de Santa Pau','Gastronómica / Feria Tradicional / Patronal. Se celebra en Enero (Fesol) y Agosto (Festa Major). Su feria gastronómica invernal dedicada al judión local (fesol) posee un notable arraigo provincial, atrayendo a numeroso público al marco monumental medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17186','fiesta','Festa Major de Sarrià de Ter','Patronal / Cultural. Se celebra en Septiembre. Fiestas patronales tradicionales del cinturón urbano de Girona, caracterizadas por el desfile de gigantes tradicionales de la colla local, correfocs y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17187','fiesta','Festa Major de Camallera y Saus','Patronal. Se celebra en Agosto. Festejos unificados de carácter estival que dinamizan sus tres núcleos históricos mediante comidas populares en las plazas, juegos infantiles y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17190','fiesta','Festa Major de Serinyà y la Fira del del Roser','Patronal / Feria Tradicional. Se celebra en Noviembre. Celebración tradicional del Pla de l''Estany con muestras artesanales tradicionales de oficios antiguos de la comarca, bailes de sardanas y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17191','fiesta','Festa Major de Sant Iscle de Serra de Daró','Patronal. Se celebra en Noviembre. Festejos otoñales mínimos en el llano del Baix Empordà debido a la baja demografía, centrados en el reencuentro familiar y litúrgico tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18015','fiesta','Festa Major de Sant Miquel de Setcases y la Fira del del Bolet','Patronal / Gastronómica. Se celebra en Septiembre (Festa Major) y Octubre (Fira). Festejos pirenaicos de alta montaña condicionados por el retorno estival y su feria artesanal micológica otoñal, con música tradicional de acordeón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17193','fiesta','Festa Major de Santa Maria de Sils y la Fiesta de la de la Cuina de Sils','Patronal / Gastronómica. Se celebra en Septiembre. Festejos que destacan provincialmente por la muestra tradicional de su mítica asociación culinaria, que recupera recetas históricas de la comarca de la Selva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17194','fiesta','Festa Major de Susqueda','Patronal. Se celebra en Agosto. Mínima expresión festiva de carácter estrictamente vecinal en un municipio de extrema baja demografía por el embalse, limitada a una misa tradicional y vermut.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17196','fiesta','Fira de la de la Cirera de Terrades y Festa Major de Sant Llorenç','Gastronómica / Patronal. Se celebra en Junio (Cirera) y Agosto (Festa Major). Festejos tradicionales que promueven su cultivo frutal histórico mediante el mercado artesanal de la cereza local, arropados por folclore aragonés y catalán.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17197','fiesta','Festa Major de Sant Vicenç de Torrent','Patronal. Se celebra en Agosto. Pequeños festejos estivales en este pequeño núcleo del interior de la comarca, basados en cenas populares tradicionales de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17199','fiesta','Festa Major de Sant Genís de Torroella','Patronal / Etnográfica / Cultural. Se celebra en Agosto. Festejos de gran arraigo comarcal, renombrados por la magnífica ejecución de su histórica colla de gigantes tradicionales, correfocs de primer nivel y su festival musical.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17198','fiesta','Festa Major de Sant Pere de Torroella','Patronal. Se celebra en Junio. Pequeña celebración veraniega de carácter vecinal y familiar cerca del río Fluvià, centrada en comidas de hermandad y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17200','fiesta','Festa Major de Tortellà y la Fira de la de la Quaresma','Patronal / Feria Tradicional. Se celebra en Agosto (Festa Major) y Marzo / Abril (Fira) *. Festejos tradicionales de la comarca de la Garrotxa que recuerdan su histórico pasado artesanal de la cuchillería de madera con muestras tradicionales de oficios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90899','fiesta','Festa Major de Sant Cristófol de Toses','Patronal. Se celebra en Julio. Festejos de alta montaña en el Pirineo del Ripollès, basados en ritos religiosos tradicionales religiosos en su iglesia románica y comidas colectivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18017','fiesta','Festa del del Pelegrí de Tossa y Festa Major de Sant Pere','Romería / Etnográfica / Marinera. Se celebra en Enero (Pelegrí) y Junio (Festa Major). Declarada de gran relieve autonómico por la mítica e histórica romería de "El Pelegrí", hito etnográfico masivo e invernal que camina hasta el santuario de Santa Coloma.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17203','fiesta','Festa Major de Sant Bartomeu de Ultramort','Patronal. Se celebra en Agosto. Mínimos festejos de ámbito puramente local y de extrema baja demografía en el Empordà, estructurados en torno a actos religiosos tradicionales y cenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17206','fiesta','Festa Major de Sant Climent de Urús','Patronal. Se celebra en Noviembre. Pequeños festejos tradicionales de carácter familiar en la Cerdanya, adaptados a la comunidad de montaña con comidas populares y orquesta local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90900','fiesta','Festa Major de Sant Martí de la de la Vajol','Patronal. Se celebra en Noviembre. Festejos rurales mínimos en la frontera pirenaica del Alt Empordà debido a la baja demografía, centrados en la convivencia de los vecinos residentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17208','fiesta','Fira del del Farro de la de la Vall de Bianya y Festa Major del del Roser','Gastronómica / Feria Tradicional / Patronal. Se celebra en Febrero (Farro). Festejos que promueven su patrimonio agrícola tradicional mediante la feria del "farro" (harina de maíz tradicional de la comarca de la Garrotxa), arropados por folclore local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17207','fiesta','Festa Major del del Mallol y del del Roser de Joanetes','Patronal / Etnográfica. Se celebra en Agosto. Festejos unificados de su espectacular valle que conservan bailes de gigantes tradicionales locales, muestras artesanales y correfocs de diablos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17209','fiesta','Festa Major de Sant Mateu de Vallllobrega','Patronal. Se celebra en Septiembre. Festejos locales tradicionales a los pies de las Gavarres, orientados a las actividades vecinales de final de verano, con comidas de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17210','fiesta','Festa Major de Sant Miquel de Ventalló y la Fira de l''Oli','Patronal / Feria Tradicional. Se celebra en Septiembre. Festejos locales que promueven los productos locales del Empordà mediante el mercado de su aceite tradicional, con habaneras y orquestas de noche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17211','fiesta','Processó de Verges (Dansa de la de la Mort) y Festa Major de Sant Julià','Religiosa / Teatral / Etnográfica. Se celebra en Marzo / Abril (Jueves Santo). Declarada Fiesta de Interés Turístico de Cataluña. Hito etnográfico medieval único en el mundo, famoso por la escalofriante "Danza de la Muerte" donde esqueletos bailan al son de un tambor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17212','fiesta','Festa Major de Sant Hilari de Vidrà','Patronal. Se celebra en Septiembre. Pequeña celebración rural que unifica la escasa población de este aislado y espectacular enclave prepirenaico en torno a comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17213','fiesta','Festa del del Ranxo de Vidreres y Festa Major de Sant Iscle','Gastronómica / Etnográfica / Patronal. Se celebra en Febrero (Ranxo) y Septiembre (Festa Major). Destaca provincialmente por el multitudinario y masivo Ranxo de Vidreres, hito etnográfico de carnaval donde se cocinan grandes ollas de cocido tradicional en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17214','fiesta','Festa Major de Santa Maria de Vilabertran y la Fira de la de la Cirera','Patronal / Romería. Se celebra en Agosto. Festejos tradicionales del Alt Empordà junto a su imponente canónica románica, con muestras artesanales tradicionales locales, jotas y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17215','fiesta','Festa Major de Sant Menna de Vilablareix','Patronal. Se celebra en Noviembre. Festejos locales de carácter local en el entorno periurbano de Girona, basados en pasacalles infantiles de gigantes de la zona y sesiones de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17216','fiesta','Festa Major de Sant Vicenç de Viladasens','Patronal. Se celebra en Enero. Mínimos festejos rurales en el límite norte del Gironès, limitados a actos religiosos tradicionales litúrgicos y un vermut vecinal de hermandad local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17217','fiesta','Festa Major de Sant Joan de Viladamat','Patronal. Se celebra en Junio. Pequeñas fiestas de marcado ambiente familiar cerca de las ruinas de Empúries, estructuradas sobre actos religiosos tradicionales y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17218','fiesta','Festa Major de Sant Joan de Vilademuls','Patronal. Se celebra en Junio. Festejos que unifican las tradiciones de sus numerosos núcleos residenciales y masías de la comarca, con comidas populares y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17220','fiesta','Ball de de Bruixes de Viladrau y Festa Major de San Martín','Etnográfica / Recreación Histórica / Teatral. Se celebra en Octubre (Bruixes). Gran valor etnográfico regional desarrollado en la noche de Todos los Santos, con una espectacular escenificación teatral de fuego y música que recuerda la quema histórica de brujas del Montseny.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17221','fiesta','Festa Major de San Cebrián de Vilafant','Patronal / Cultural. Se celebra en Septiembre. Festejos de fuerte arraigo en el entorno urbano de Figueres con desfiles tradicionales de carrozas de peñas, gigantes de la comarca y conciertos masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17223','fiesta','Festa Major de Sant Feliu de Vilajuïga y de San Roque','Patronal / Enológica. Se celebra en Agosto. Festejos estivales tradicionales basados en la cultura del vino de la DO Empordà, con pasacalles, catas populares locales y orquestas de noche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17224','fiesta','Festa Major de Sant Martí y l''Aplec de la Mare de Déu del Catllar','Patronal / Romería. Se celebra en Noviembre (San Martí) y Julio (Aplec). Festejos de montaña en el Valle de Camprodon que reúnen a los vecinos en la romería tradicional a la ermita del Catllar, combinando fervor rural, sardanas y música tradicional de acordeón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17225','fiesta','Festa Major de Sant Esteve','Patronal. Se celebra en Diciembre. Festejos invernales de marcado arraigo vecinal en el Alt Empordà, estructurados en torno a ritos religiosos tradicionales, comidas populares de hermandad y sesiones lúdicas en el local social.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17226','fiesta','Festa Major de Sant Vicenç','Patronal. Se celebra en Enero. Celebración puramente local y de carácter vecinal, sustentada en la misa tradicional, competiciones lúdicas infantiles y pequeñas verbenas nocturnas organizadas para el municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17227','fiesta','Festa Major de Sant Gil','Patronal / Enológica. Se celebra en Septiembre. Pequeña festividad veraniega en la Sierra de la Albera vinculada al cultivo tradicional de la viña de la DO Empordà, con comidas comunitarias al aire libre y música de parrandas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17228','fiesta','Festa Major de Sant Salvador y Taravaus','Patronal. Se celebra en Agosto. Festejos tradicionales de carácter familiar e infantil que unifican las costumbres de sus núcleos residenciales mediante verbenas de plaza y juegos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17230','fiesta','Festa de la de la Ceba de Vila-sacra y Festa Major de Sant Esteve','Gastronómica / Feria Tradicional / Patronal. Se celebra en Marzo (Ceba) y Septiembre (Festa Major). Festejos con notable raigambre en el Alt Empordà, destacados por la feria tradicional dedicada a la cebolla, con degustaciones populares, concursos artesanales y folclore local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17222','fiesta','Festa Major de Sant Julià','Patronal. Se celebra en Septiembre. Pequeñas fiestas de arraigo puramente local con ritos religiosos tradicionales, campeonatos de cartas y orquestas reducidas adaptadas a la baja demografía del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90901','fiesta','Fira de la de la Llet de Vilobí y Festa Major de Santa Margarida','Feria de Sector / Tradicional / Patronal. Se celebra en Noviembre (Llet) y Julio (Festa Major). Festejos de rango comarcal muy consolidados en la comarca de la Selva; su feria dedicada al sector lácteo destaca provincialmente por sus concursos de ganado tradicional y exposiciones artesanales.','inventario_fiestas_pdf');
